#define MAX_EVENTS 64
#define CONTAINERS_PREFIX "/v1/containers/"
#define DNS_SERVERS_PREFIX "/v1/dns/servers/"
#define LDAP_SERVERS_PREFIX "/v1/ldap/servers/"
#define LDAP_GROUPS_PREFIX "/v1/ldap/groups/"
#define LDAP_USERS_PREFIX "/v1/ldap/users/"
#define NTP_SERVERS_PREFIX "/v1/ntp/servers/"
#define SYSLOG_TARGETS_PREFIX "/v1/syslog/targets/"
#define PROCESSES_PREFIX "/v1/system/processes/"
#define SYSCTL_PREFIX "/v1/system/sysctl/" /* ADR-0160 */
#define KMOD_PREFIX "/v1/system/kmod/" /* ADR-0159 */
#define KMODCONFIG_PREFIX "/v1/system/kmod-config/" /* ADR-0159 */
#define PKI_CERTS_PREFIX "/v1/pki/certs/"
/*
  * The parent cgroup every workload this daemon starts lives under --
  * containers and package builds alike (ADR-0165). Defined here rather
  * than beside its first user because GET /v1/system/stats reports its
  * memory too (#279), and that handler sits well above.
  */
#define CGROUP_WORKLOAD_PARENT "cix-workload"

#define PKG_PREFIX "/v1/pkg/"
#define PKG_RECIPES_PREFIX "/v1/pkg/recipes/"
#define IMAGES_PREFIX "/v1/images/"
#define IMAGE_RECIPES_PREFIX "/v1/images/recipes/"
#define DEVICEMAPS_PREFIX "/v1/devicemaps/"
#define STORAGE_ROLES_PREFIX "/v1/storage-roles/"
#define STORAGE_PREFIX "/v1/storage/"

enum conn_kind {
	CONN_LISTENER,
	CONN_LISTENER_TLS, /* the HTTPS listener (Part 0.5) -- same accept4()
	                     * loop as CONN_LISTENER, distinguished only by
	                     * whether accept_loop() wraps the accepted fd in
	                     * a fresh SSL* before registering it */
	CONN_CLIENT,
	CONN_CONTAINER,
	CONN_PKG_FETCH,
	CONN_PKG_BUILDENV, /* #238: a forked build-environment composition */
	CONN_PKG_BUILD_OUTPUT,  /* pkg.c's build-output capture pipe, drained incrementally
	                          * as the container runs rather than once at exit (ADR-0087) */
	CONN_CONTAINER_INIT,    /* ADR-0260: one container's cix-init report socket -- service state */
	CONN_STOP_ESCALATE_TIMER, /* ADR-0260: SIGKILL if a SIGTERM'd container has not stopped in its grace */
	CONN_CONTAINER_OUTPUT,  /* an ordinary container's own stdout/stderr capture pipe --
	                          * always present since transparent container-log capture
	                          * landed (every container, not just capture_output=true
	                          * ones), drained incrementally into logstore.c (source
	                          * "container") exactly like CONN_PKG_BUILD_OUTPUT drains
	                          * into pkg.c's build-output buffer -- the same ADR-0087
	                          * discipline, a different destination. POST /v1/containers'
	                          * own "capture_output" opt-in now controls only whether
	                          * the SAME bytes are ALSO mirrored into this container's
	                          * own registry_entry->captured_output tail. */
	CONN_BOOTROOT_ASSEMBLE, /* server-side mkbootroot invocation (ADR-0057) */
	CONN_ISO_OUTPUT,        /* mkinstalleriso's own captured stdout/stderr (ADR-0064) */
	CONN_BOOTROOT_OUTPUT,   /* mkbootroot's own captured stdout/stderr, drained
	                          * incrementally exactly like CONN_PKG_BUILD_OUTPUT (ADR-0087) */
	CONN_ISO_ASSEMBLE,      /* server-side mkinstalleriso invocation (ADR-0064) */
	CONN_ARTIFACT_EXPORT,      /* issue #126: tar of an image's rootfs into the artifact dir */
	CONN_ARTIFACT_PUSH,     /* issue #129: curl child publishing a fresh build to the artifact server */
	CONN_ISO_PUBLISH,       /* ADR-0220: curl child publishing an installer ISO (or its signature) */
	CONN_BOOTSTRAP_FETCH,   /* pkg/bootstrap's own toolchain_url curl fetch (ADR-0065) */
	CONN_KERNEL_RELEASES_FETCH, /* kernel.org releases.json curl fetch (issue #65) */
	CONN_PKG_SYNC_FETCH,    /* pkg sync's own repo-archive curl fetch (ADR-0121) */
	CONN_DISK_FORMAT,       /* disk format+mount job (multi-disk management Phase C) */
	CONN_STORAGE_MIGRATE,   /* state/rebuildable/log-storage migration job (ADR-0141 Phase 2) */
	CONN_CONTAINER_STORAGE_MIGRATE, /* one container's own overlay-storage migration job (ADR-0142 Section 4) */
	CONN_PING,              /* GET/POST /v1/system/ping -- the raw ICMP socket half */
	CONN_PING_TIMER,        /* same job's paired timeout -- see ping_job_teardown() */
	CONN_NTP_PERIODIC_TIMER, /* permanent, re-arms itself -- fires ntp_sync_start() periodically (task #751) */
	CONN_BUILD_STALL_TIMER,  /* permanent, re-arms itself -- reports in-flight builds that have gone quiet */
	CONN_BOOT_CONFIRM_TIMER, /* ADR-0256: re-checks a boot that could not confirm, then falls back */
	CONN_SCHEDULER_TIMER,    /* ADR-0257: permanent, re-arms to the next due job */
	CONN_NTP_SYNC,           /* one in-flight SNTP sync attempt's own UDP socket */
	CONN_NTP_SYNC_TIMER,     /* same job's per-candidate timeout -- see ntp_job_teardown() */
	/*
	 * Issue #81 server health. The probe is a NON-BLOCKING connect()
	 * driven by this same reactor -- a blocking probe would stall the
	 * whole control plane on an unreachable server, which is exactly the
	 * failure ADR-0180 exists to prevent.
	 */
	CONN_SERVERHEALTH_TIMER, /* permanent, re-arms itself -- fires one probe sweep per interval */
	CONN_SERVERHEALTH_PROBE, /* one in-flight TCP probe's own socket */
	CONN_RESTART_TIMER,
	CONN_ROLLING_RESTART_TIMER, /* jittered live-restart onto a newer rolling image
	                              * version (ADR-0124/Part 5) -- distinct from
	                              * CONN_RESTART_TIMER: that one only ever fires
	                              * after a container has already exited (crash
	                              * respawn); this one fires against a still-live
	                              * container, which needs an explicit stop first
	                              * -- see handle_rolling_restart_timer_event(). */
	CONN_BIND_IP_CLEANUP, /* deferred rtnl_addr_del_ipv4() of a superseded/cleared
	                        * bind_ip (ADR-0068) -- see arm_bind_ip_cleanup_timer() */
	CONN_CONSOLE_SHELL,
	CONN_CONSOLE_RESPAWN_TIMER,
	CONN_CONSOLE_WS,        /* GET /v1/containers/{name}/console -- client-facing WebSocket half */
	CONN_CONSOLE_PTY,       /* same session's other half -- the exec'd shell's pty master fd */
	/*
	 * ADR-0278 (#368): a piece of work running in a forked helper, its
	 * pidfd watched so the reactor learns when it finishes.
	 *
	 * The daemon already had this shape in three separate places --
	 * procfuse_start(), the build containers, diskformat.c -- each with
	 * its own fork, its own conn kind and its own completion handler.
	 * A fourth hand-rolled copy is how a fifth happens, so this is the
	 * one implementation the rest use.
	 */
	CONN_HELPER,
	CONN_CONSOLE_EXEC_REAP, /* pidfd for the console session's exec'd process, watched ONLY so
	                          * that reaping it never blocks the reactor (#399). exec.c's own
	                          * comment claimed this watch already existed; it did not, and the
	                          * blocking waitpid() that stood in for it is the bug. */
	CONN_PKG_BUILD_LOG_WS,  /* GET /v1/pkg/build/log -- live-tail of the in-flight build's own
	                          * output pipe (task #676), a one-way relay of CONN_PKG_BUILD_OUTPUT's
	                          * existing capture, not an exec/PTY session like CONN_CONSOLE_WS */
	CONN_KMSG,              /* /dev/kmsg -- feeds real kernel dmesg lines into the consolidated log store */
	CONN_UEVENT,            /* NETLINK_KOBJECT_UEVENT multicast socket (ADR-0161 Phase C) -- real
	                          * kernel hotplug add/remove events, modeled on CONN_KMSG's own async
	                          * registration shape, not rtnetlink.c's synchronous open/request/close one */
	/*
	 * A conn already torn down mid-batch (console_session_teardown()
	 * below) but not yet free()'d -- see g_pending_free's own comment
	 * for why the free is deferred. The event loop skips these
	 * immediately rather than dispatching on any of their other,
	 * already-invalid fields.
	 */
	CONN_DEAD
};

struct conn {
	enum conn_kind kind;
	int fd;
	SSL *ssl; /* CONN_CLIENT only, and only when accepted on the HTTPS
	           * listener -- NULL for every plain-HTTP connection (the
	           * overwhelming majority). Non-NULL but !SSL_is_init_
	           * finished() means the TLS handshake is still in
	           * progress; see handle_client_event(). */
	struct http_conn http;                 /* CONN_CLIENT only */
	char peer_ip[CONNTHROTTLE_IP_MAX];      /* CONN_CLIENT only -- captured at accept4() time */
	struct registry_entry *entry;           /* CONN_CONTAINER / CONN_CONTAINER_OUTPUT */
	/*
	 * CONN_CONTAINER_OUTPUT only: partial-line accumulation for the
	 * always-on container-log-capture forward into logstore (transparent
	 * log aggregation) -- independent of entry->captured_output's own
	 * raw-byte accumulation (which stays byte-oriented, unchanged,
	 * gated on entry->capture_requested). A line longer than this
	 * buffer is flushed to logstore as-is at the boundary rather than
	 * grown unboundedly -- the same "generous but bounded" posture
	 * every other capture buffer in this daemon already has.
	 */
	char output_line_buf[1024];             /* CONN_CONTAINER_OUTPUT only */
	int output_line_len;                    /* CONN_CONTAINER_OUTPUT only */
	int service_index;                      /* CONN_CONTAINER_OUTPUT only: which service's pipe, -1 = cix-init's own stdio */
	time_t escalate_started_at;             /* CONN_STOP_ESCALATE_TIMER only: the incarnation it was armed for */
	pid_t pkg_fetch_pid;                    /* CONN_PKG_FETCH / CONN_BOOTROOT_ASSEMBLE / CONN_ISO_ASSEMBLE / CONN_BOOTSTRAP_FETCH / CONN_DISK_FORMAT / CONN_STORAGE_MIGRATE / CONN_CONTAINER_STORAGE_MIGRATE / CONN_CONSOLE_EXEC_REAP */
	int pkg_chain_idx;                      /* CONN_PKG_FETCH / CONN_PKG_BUILD_OUTPUT / CONN_PKG_BUILD_LOG_WS -- ADR-0157 Phase 2: which g_chains[] slot this conn belongs to */
	/* CONN_HELPER (ADR-0278): what to call when the helper exits, and
	 * with what. The context is an opaque pointer the caller owns --
	 * this layer never frees it, because only the caller knows whether
	 * it is heap, static, or an index dressed up as a pointer. */
	void (*helper_done)(int exit_status, void *ctx);
	void *helper_ctx;
	const char *helper_what; /* for the log line when it fails -- a literal, never freed */
	enum storage_kind storage_migrate_kind; /* CONN_STORAGE_MIGRATE only */
	char container_storage_migrate_name[REGISTRY_NAME_MAX]; /* CONN_CONTAINER_STORAGE_MIGRATE only */
	char restart_name[REGISTRY_NAME_MAX];   /* CONN_RESTART_TIMER only */
	/* CONN_SERVERHEALTH_PROBE only -- which registered server this
	 * in-flight probe is for, so its result can be attributed when the
	 * socket becomes writable (or the sweep times it out). */
	char probe_kind[SERVERHEALTH_KIND_MAX];
	char probe_container[REGISTRY_NAME_MAX];
	char probe_desc[SERVERHEALTH_PROBE_MAX];
	time_t probe_started_at;
	/*
	 * The address this listener is actually bound to (#454). Listener
	 * conns only.
	 *
	 * Both rebind functions short-circuit when asked to rebind to where
	 * they already are, because binding the same tuple twice is a real
	 * EADDRINUSE that SO_REUSEADDR does not help with. They used to
	 * make that comparison against the SHARED global g_bind_addr, which
	 * is wrong for two independent reasons and was wrong in both at
	 * once on the management-network path: the handler passes
	 * g_bind_addr itself, making the test strcmp(x, x) and therefore
	 * always true; and rebind_listener() has already overwritten
	 * g_bind_addr with the new address by the time the https rebind is
	 * attempted. So the https listener was never rebound by a
	 * management address change, and stayed bound to an address that
	 * had just been removed from the interface -- measured on
	 * 192.168.15.95 (2026-09-13): after a live .103 -> .95 move,
	 * http answered 200 on the new address and https answered nothing
	 * on either, until the next reboot rebound both from net.conf.
	 *
	 * A listener's own bound address is a property of that listener,
	 * so it lives on the listener.
	 */
	char listen_addr[64];                   /* listener conns only */
	int listen_port;                        /* listener conns only */
	char cleanup_ifname[NETWORK_NAME_MAX];  /* CONN_BIND_IP_CLEANUP only */
	uint32_t cleanup_addr_be;               /* CONN_BIND_IP_CLEANUP only */
	int cleanup_prefix_len;                 /* CONN_BIND_IP_CLEANUP only */
	pid_t console_pid;                      /* CONN_CONSOLE_SHELL only */
	char console_tty[32];                   /* CONN_CONSOLE_SHELL / CONN_CONSOLE_RESPAWN_TIMER */
	struct console_exec_session *exec_session; /* CONN_CONSOLE_WS / CONN_CONSOLE_PTY only -- shared by both halves of one session */
	struct ws_conn ws;                      /* CONN_CONSOLE_WS / CONN_PKG_BUILD_LOG_WS -- incremental client-frame parser */
	/*
	 * CONN_CLIENT only -- a response the peer has not finished reading
	 * (#237).
	 *
	 * Responses used to be written straight to the socket with the fd
	 * put back into blocking mode, inside the single event loop. That
	 * made the whole control plane hostage to the slowest reader
	 * attached to it: one client asking for GET /v1/pkg (1.8 MB on a
	 * real host) and then not reading held every other request off for
	 * as long as it liked, with no authentication needed. Measured:
	 * health went from 7 ms to a hard timeout for exactly as long as
	 * such a client was attached, and recovered in 14 ms the moment it
	 * closed.
	 *
	 * So the response is built into out_buf and drained across EPOLLOUT
	 * events instead. out_progress_at is the last time bytes actually
	 * moved, which is what the write deadline is measured from -- a
	 * peer reading slowly but genuinely is not the same as one that has
	 * stopped, and only the latter should lose its connection.
	 */
	char *out_buf;
	size_t out_len;
	size_t out_sent;
	time_t out_progress_at;
	struct conn *out_next;                  /* g_out_pending list linkage */
};

/*
 * One exec-console session's shared state, referenced by both its own
 * conns (the client-facing WS half and the pty-master half) so either
 * side noticing the other has gone away can tear down the whole pair.
 * The first time this daemon has needed two independently-epoll-
 * registered fds to represent one logical session -- see
 * console_session_teardown() and g_pending_free below for the real
 * hazard that shape introduces and how it's handled.
 */
/*
 * Terminal input that the pty master would not take yet (#294).
 *
 * The master is O_NONBLOCK, so a write can return EAGAIN the moment the
 * slave's input buffer is full -- a shell that has stopped reading, a
 * paste larger than the buffer, a program in a tight loop. Before that
 * flag the write simply blocked, which on a single-threaded daemon
 * stopped the entire control plane, so this buffer is what makes the
 * non-blocking master safe rather than a way to lose a keystroke.
 *
 * 64 KiB is far beyond any real terminal input burst. A session that
 * manages to exceed it has a slave that is not consuming at all, and is
 * torn down with that said plainly rather than silently truncated.
 */
#define CONSOLE_PTY_OUT_MAX 65536

struct console_exec_session {
	struct conn *ws_conn;
	struct conn *pty_conn;
	/*
	 * #331: the CONN_CONSOLE_EXEC_REAP watching this session's exec'd
	 * process, so the two can clear each other.
	 *
	 * The reap conn learns the process has exited; the session is what
	 * a client is waiting on. Without the link the daemon knew the
	 * process was gone and told nobody -- measured in a selftest where
	 * the exec'd program (one that never exits on its own) was absent
	 * from the container 31 seconds into a session that had answered
	 * 101, with the client still waiting for a first byte.
	 */
	struct conn *reap_conn;
	pid_t exec_pid;
	int torn_down;
	unsigned char pty_out[CONSOLE_PTY_OUT_MAX];
	size_t pty_out_len;
};

/* Defined with the rest of the console pty handling, below; declared
 * here because the websocket read path above it is what feeds it. */
static int console_pty_write(struct console_exec_session *sess, const unsigned char *buf, size_t len);

/*
 * What to do once the event loop actually stops -- reachable via
 * SIGTERM/SIGINT (unchanged, defaults to a graceful poweroff rather
 * than the bare `return 0` that, as PID 1, the kernel treats as "init
 * exited" and panics on) or the new /v1/system/{shutdown,reboot}
 * endpoints below. Only ever acted on when running --init-mode (real
 * PID 1) -- see main()'s own post-loop handling; a dev/test cixd
 * (no --init-mode, e.g. every test/*.c invocation) just exits normally
 * regardless of this value, exactly as it always has.
 */
enum shutdown_action { SHUTDOWN_ACTION_POWEROFF, SHUTDOWN_ACTION_REBOOT };

static int g_epfd;
static struct conn g_listener_conn;
static struct conn g_kmsg_conn;
static struct conn g_uevent_conn;
static struct conn g_https_listener_conn; /* .fd == -1 when HTTPS is disabled */
static SSL_CTX *g_tls_ctx;                 /* NULL when HTTPS is disabled */
static const char *g_web_root;
static volatile sig_atomic_t g_stop;
static volatile sig_atomic_t g_shutdown_action = SHUTDOWN_ACTION_POWEROFF;

/*
 * ADR-0256: the uplink this box was configured to use, when
 * bootstrap_management_network() could not attach it.
 *
 * Issue #133 was right that a missing uplink must never kill PID 1, and
 * that is unchanged -- cixd still comes up and still serves on the
 * management bridge. What was wrong is what happened NEXT: the boot was
 * confirmed anyway, on the grounds that a socket was bound. A box that
 * nobody on the network can reach had spent its A/B fallback on the
 * slot that cannot serve them.
 */
static char g_uplink_unattached[64];
/*
 * Non-empty when cixd could not bind the box's chosen management
 * address, holding the address it wanted. The daemon keeps running --
 * the loopback listeners below are unconditional -- so this is not a
 * fallback state to recover from, it is a fact to report: the box is up
 * and nothing off this machine can reach it.
 *
 * Same role g_uplink_unattached plays for a missing NIC (ADR-0256), and
 * used for the same decision: a boot in this state must not be
 * confirmed as a good A/B slot on the strength of having bound a socket.
 */
static char g_bind_unavailable[64];

/*
 * 127.0.0.1 is ALWAYS bound, in addition to whatever address the box was
 * given. Asked for directly by the owner, after an address change left a
 * box bound to nothing:
 *
 *   "the simple fix is to always bind to 127.0.0.1 and to bind to
 *    another address based on what was chosen for the box. this way a
 *    failure of this sort can never happen."
 *
 * cixd is PID 1 and there is no other shell on the box: the only local
 * surface is the interactive cixctl that cixd itself forks onto the
 * consoles (spawn_console_shell(), /dev/tty0 and /dev/ttyS0), and that
 * cixctl talks to cixd over TCP like any other client. So the console is
 * only ever as available as cixd's most reliable listener -- and until
 * now its target was the management address, which means every console
 * session was one address change away from breaking. It broke.
 *
 * These are never rebound and never stopped by a remote reconfiguration:
 * PUT /system/daemon-config (ports) and PUT/DELETE /system/management-
 * address (the off-box address, ADR-0287) move or stop the off-box
 * listeners only. An operator cannot turn the local surface off by
 * reconfiguring the remote one, which is the entire point. (Reset,
 * DELETE /system/management-address, does bring the loopback pair down
 * -- but only because the main listeners then serve loopback directly,
 * so 127.0.0.1 never stops answering.)
 *
 * Skipped when the chosen address IS loopback (an install with no
 * management network), because then the pair above already is it.
 */
static struct conn g_lo_listener_conn;
static struct conn g_lo_https_listener_conn;


/*
 * conns torn down mid-batch are queued here instead of free()'d
 * immediately. A single cix_epoll_wait() call can report BOTH halves of
 * one console session's fd pair as ready in the same batch; freeing
 * the first one processed would leave the second event's own `struct
 * conn *` dangling for the rest of that same batch's for-loop. Drained
 * (actually freed) once the whole batch has been dispatched -- see the
 * main loop below. Sized to MAX_EVENTS since a batch can never report
 * more events than that, and console_session_teardown() is itself
 * idempotent (guarded by torn_down), so it can never queue more than
 * one free per conn regardless of how many events reference it.
 */
#define MAX_PENDING_FREE MAX_EVENTS
static struct conn *g_pending_free[MAX_PENDING_FREE];
static int g_pending_free_count;

static void queue_conn_free(struct conn *cc)
{
	if (g_pending_free_count < MAX_PENDING_FREE)
		g_pending_free[g_pending_free_count++] = cc;
	else
		free(cc); /* unreachable per MAX_PENDING_FREE's own bound -- fail safe rather than leak */
}

static void drain_pending_free(void)
{
	int i;

	for (i = 0; i < g_pending_free_count; i++)
		free(g_pending_free[i]);
	g_pending_free_count = 0;
}

/*
 * Kills (if still running -- SIGKILL is a harmless no-op/ESRCH if the
 * shell already exited on its own) and reaps the exec'd process, tears
 * down both fds/epoll registrations, and queues both conns for
 * deferred free. Safe to call from either side (the WS client
 * disconnecting, or the pty hitting EOF/EIO because the shell exited)
 * and safe to call twice (torn_down guards against it).
 */
static void console_session_teardown(struct console_exec_session *sess)
{
	if (sess->torn_down)
		return;
	sess->torn_down = 1;
	/* #331: the reap conn outlives this struct -- it is freed by its own
	 * pidfd event, which may never come for a process that is still
	 * running. Drop its back-pointer so it cannot reach a session that
	 * is being freed. */
	if (sess->reap_conn != NULL) {
		sess->reap_conn->exec_session = NULL;
		sess->reap_conn = NULL;
	}

	/*
	 * Signal, never wait (#399, and ADR-0180's rule applied to the
	 * second place that broke it).
	 *
	 * This used to be kill() followed by waitpid(pid, NULL, 0), on the
	 * reasoning that SIGKILL is instant. It is not: a task in
	 * uninterruptible D-state only ever PENDS a SIGKILL, so the wait is
	 * unbounded -- and this is a single-threaded epoll loop, so an
	 * unbounded wait here is a total control-plane outage for as long
	 * as it lasts. ADR-0180 established exactly this for container
	 * delete after it froze a real host twice; the console path kept
	 * the old shape because exec.c's comment said the grandchild was
	 * "reaped via pidfd, the same convention every other child it
	 * tracks already uses". No such registration existed, so this
	 * blocking wait WAS the reaper, on a long-lived process, on the
	 * reactor.
	 *
	 * The child is now watched by its own pidfd from the moment the
	 * session is built (register_console_exec_reap()), so the reap
	 * happens when the process actually dies, off this path entirely.
	 * Measured signature this closes: wchan "do_wait" with no request
	 * in flight -- three times on 192.168.15.95 on 2026-09-10/11, the
	 * last for 366 seconds, ending only in a hand reset.
	 */
	kill(sess->exec_pid, SIGKILL);

	cix_epoll_ctl(g_epfd, EPOLL_CTL_DEL, sess->ws_conn->fd, NULL);
	if (sess->ws_conn->ssl != NULL) {
		tls_unregister(sess->ws_conn->fd);
		SSL_free(sess->ws_conn->ssl);
	}
	close(sess->ws_conn->fd);
	ws_conn_free(&sess->ws_conn->ws);
	sess->ws_conn->kind = CONN_DEAD;
	queue_conn_free(sess->ws_conn);

	cix_epoll_ctl(g_epfd, EPOLL_CTL_DEL, sess->pty_conn->fd, NULL);
	close(sess->pty_conn->fd);
	sess->pty_conn->kind = CONN_DEAD;
	queue_conn_free(sess->pty_conn);

	free(sess);
}
/*
 * This boot's own slot and bind address, set once from argv in main()
 * -- previously plain locals, read only by confirm_boot()'s call site
 * and a diagnostic print. Promoted here (same file-scope-static
 * precedent as g_epfd) so handle_system_update() below can also reach
 * them: it needs g_slot to compute the *inactive* slot, and g_bind_addr
 * to embed the same address into the fresh loader entry it writes for
 * that slot. NULL/unset (g_slot) means this isn't a real --init-mode
 * boot -- handle_system_update() rejects the request rather than
 * guessing at an "inactive" slot that doesn't meaningfully exist.
 *
 * g_port joins them for the same reason (Phase 19): spawn_console_shell()
 * and its respawn-timer path need the real listening port to hand
 * cixctl a --port= that actually reaches this daemon, and both are
 * called from places that don't otherwise have it in scope.
 */
static const char *g_slot;
static const char *g_bind_addr;
/* Backing storage for g_bind_addr when it's derived from the
 * management network's own address (Part 0.5) rather than taken directly
 * from argv's --bind= -- g_bind_addr has to remain valid for the rest
 * of the process's life, so this can't be a stack buffer. */
static char g_bind_addr_buf[INET_ADDRSTRLEN];
static int g_port;

/*
 * Real freshness tracking for the async cix bootroot assembly
 * (spawn_cix_bootroot_assembly()/handle_bootroot_assemble_event(),
 * ADR-0057) -- closes task #737's own gap: `pkg hostbuild cix
 * --deploy` used to treat "cixd-root.squashfs exists" as "this
 * hostbuild round's own artifact is ready," but that file is a leftover
 * from whichever assembly last succeeded, not necessarily the one this
 * round's own hostbuild triggered -- a stale file from an earlier round
 * would be silently redeployed while the real new assembly was still
 * running. g_bootroot_assembly_started increments once per attempt
 * (right before the fork in spawn_cix_bootroot_assembly());
 * g_bootroot_assembly_completed is only ever set to that attempt's own
 * generation number on a *real, confirmed success*
 * (handle_bootroot_assemble_event(), WIFEXITED && WEXITSTATUS==0) --
 * never bumped on failure, so a client that captured a baseline before
 * triggering a new hostbuild can tell "a newer assembly than the one I
 * already knew about actually finished" from "the last one is still the
 * only one that ever succeeded." g_bootroot_assembly_running covers the
 * third state (attempted but not yet resolved either way) so a client
 * polling this can also tell "still working" from "gave up, that
 * attempt failed" instead of spinning forever on a failure. Reported via
 * GET /system/boot (handle_system_boot() below) -- not a new resource of
 * its own, since this is squarely "state about the currently/most-
 * recently-assembled boot image," the same subject that endpoint already
 * owns; keeping it there (rather than folding it into pkg.c's own
 * generic pkg_get_one() JSON) keeps pkg.c fully agnostic to what any
 * hostbuild name *means*, exactly the separation ADR-0057's own "cix"
 * special-case comment in this file already established.
 */
static long g_bootroot_assembly_started;
static long g_bootroot_assembly_completed;
static int g_bootroot_assembly_running;

static void on_signal(int sig)
{
	(void)sig;
	g_stop = 1;
}

static int ensure_dir(const char *path)
{
	if (mkdir(path, 0755) != 0 && errno != EEXIST) {
		perror(path);
		return -1;
	}
	return 0;
}

static int mount_or_fail(const char *source, const char *target, const char *fstype,
                          unsigned long flags)
{
	if (mount(source, target, fstype, flags, NULL) != 0) {
		perror(target);
		return -1;
	}
	return 0;
}

/*
 * Only reached with --init-mode, i.e. cixd running as PID 1 on a bare
 * kernel boot with no initramfs (Phase 11) -- nothing else has mounted
 * /proc, /sys, or cgroup2 yet. devtmpfs is populated by the kernel itself
 * (CONFIG_DEVTMPFS_MOUNT) before init ever runs, so /dev needs no mount
 * here. Same proc mount flags mountns_pivot() already uses for each
 * container's own /proc (src/mountns.c) -- one already-correct flag set,
 * not a second one invented.
 *
 * BASE_DIR is the real cix-containers partition (CONTAINERS_DEVICE) --
 * everything a running daemon persists (images/, containers/,
 * networks.json, dns_records.json, pki_certs.json, pkg_installed.json)
 * genuinely survives a real reboot, not just a plain daemon restart
 * within the same still-running kernel. Falls back to a tmpfs at the
 * same mount point when that device doesn't exist (parts 1/2's own
 * throwaway 2/3-partition test disks): a real, deliberate exception
 * for "not a real installed system," same posture as CONFIG_DEVICE's
 * own non-fatal mount below, not a bug in that fallback path. This
 * was originally meant to land in Phase 11 part 3 (the installer
 * already formats and names this partition for exactly this purpose)
 * but the swap itself never actually happened until now -- see
 * ADR-0018.
 */

/*
 * Part 3 (bare-metal-readiness plan, ADR-0061): loads a curated,
 * boot-critical module list via the real, freshly-staged
 * /usr/bin/modprobe (kmod.recipe, staged onto this control-plane
 * squashfs by mkbootroot.c's own kmod_bin_dir argument) -- run before
 * bootstrap_management_network() below, not after: that function
 * attaches a *named* physical interface (net.conf's own --interface=),
 * which the kernel must have already detected as a real netdev by
 * then, and on real hardware that detection only happens once the
 * matching driver is loaded. The storage controller that might hold
 * root is never in this list -- see image/kernel/qemu-part1.config's
 * own comment on why that has to stay built directly into the kernel
 * instead, never a module.
 *
 * Best-effort per module, same "a real machine this project has never
 * seen before might simply not have this exact hardware" posture
 * cgroup_enable_controllers() already established for an unrelated
 * optional capability -- covers several different vendors' NIC
 * chipsets in one list, no single real machine has all of them, so a
 * missing driver here is the overwhelmingly common, expected case, not
 * a real error worth failing boot over (or even logging on every
 * single boot). A --data-dir= test invocation never reaches this at
 * all (init_mode is false), so it never needs a real /usr/bin/modprobe
 * to exist.
 */
static void load_boot_modules(void)
{
	/*
	 * The NIC list comes from bootmodules.h, shared with cix-install,
	 * which needs the identical set before it lists interfaces for an
	 * operator to choose from. A second copy here would fail in the
	 * worst way if it drifted: the installer offering a NIC this
	 * daemon cannot bring up, or this daemon finding one the installer
	 * never let anyone choose.
	 *
	 * ehci-hcd and usb-storage USED to be appended here. Both are
	 * built into the kernel as of #429 -- they had to be, since a
	 * module cannot be loaded before root is mounted and there is no
	 * initramfs -- so modprobing them is now a no-op against a
	 * built-in driver. Dropped rather than left to fail harmlessly:
	 * a list that names things it does not need is a list nobody
	 * trusts.
	 */
	static const char *const boot_modules[] = CIX_NIC_MODULES;
	size_t i;

	for (i = 0; i < sizeof(boot_modules) / sizeof(boot_modules[0]); i++) {
		/*
		 * kmod_load(), not a second hand-rolled fork+execve of
		 * modprobe. This loop used to be one, which made two places
		 * in this platform that know how to run modprobe and how to
		 * spell its path -- and only one of them would have been
		 * found by anyone changing that.
		 *
		 * Return value deliberately unchecked, and output deliberately
		 * discarded: see the function-level comment above for why "no
		 * such hardware present" is not an error here. That is a
		 * choice about THIS list, not about kmod_load(), which now
		 * reports its reason everywhere the answer matters.
		 */
		(void)kmod_load(boot_modules[i], NULL, NULL, 0);
	}
}

/*
 * ADR-0160: applies every persisted GET/PUT /v1/system/sysctl/{key}
 * entry at boot. Runs after load_boot_modules() (a net.* sysctl could
 * plausibly depend on a just-loaded NIC driver's own /proc/sys nodes
 * existing) but before bootstrap_management_network() below -- a
 * net.* sysctl can affect how that bootstrap itself behaves (e.g.
 * net.ipv4.ip_forward), so it needs to already be applied by then.
 * Best-effort per key, matching load_boot_modules()'s own posture: a
 * key that fails (e.g. a kernel built without the feature it
 * controls, so its /proc/sys node doesn't exist at all) is logged and
 * skipped, never a reason to fail boot.
 */
static void apply_one_configured_sysctl(const char *key, const char *value, void *ctx)
{
	(void)ctx;
	if (container_net_apply_sysctl(key, value) != 0)
		fprintf(stderr, "apply_configured_sysctls: %s=%s failed: %s\n", key, value,
		        strerror(errno));
}

static void apply_configured_sysctls(void)
{
	sysctlconfig_foreach(apply_one_configured_sysctl, NULL);
}

/*
 * ADR-0159 Phase A: the REST-managed autoload counterpart to
 * load_boot_modules() above -- runs last of the four (after
 * bootstrap_management_network(), not before it): operator-configured
 * autoload is the least boot-critical of the four steps, and a
 * container-usable driver loaded slightly later than the management
 * network is fine, unlike load_boot_modules()'s own hardware-detection
 * list, which genuinely must precede that bootstrap. Best-effort per
 * module, same posture as load_boot_modules(): a module an operator
 * configured for autoload but that fails to load (hardware not
 * present, or never actually got built) is logged and skipped, never a
 * reason to fail boot.
 */
static void load_one_configured_module(const char *name, const char *options, void *ctx)
{
	char tool_out[256];

	(void)ctx;
	/*
	 * modprobe's own words, and to the log store rather than stderr.
	 * This ran at boot, so stderr goes nowhere an operator can read
	 * (#132) -- an autoload that silently did not happen was
	 * indistinguishable from one never configured.
	 */
	if (kmod_load(name, options, tool_out, sizeof(tool_out)) != 0) {
		size_t i;

		for (i = 0; tool_out[i] != '\0'; i++) {
			if (tool_out[i] == '\n' || tool_out[i] == '\r')
				tool_out[i] = ' ';
		}
		logstore_write("cixd", "error", "kmod autoload: %s failed: %s", name,
		               tool_out[0] != '\0' ? tool_out : "modprobe said nothing about why");
	}
}

static void load_configured_modules(void)
{
	kmodconfig_foreach_autoload(load_one_configured_module, NULL);
}

/*
 * Bootstraps cixd's off-box management address (ADR-0287, superseding
 * Part 0.5's is_management model). The management address is a single
 * persisted value in daemon_config; the network it lives in and that
 * network's `management` flag are DERIVED from it. This function runs
 * once at boot and establishes three things in priority order:
 *
 *   1. A persisted address (daemon_config_management_address()) -- a
 *      new-model box, or one whose legacy bind_ip daemon_config's own
 *      load already migrated -- is reapplied to its network's bridge
 *      (#436: the persisted address is reapplied at every boot) and
 *      becomes g_bind_addr.
 *   2. Otherwise, a legacy "is_management" network's address (captured
 *      by network_init's load) is migrated once into daemon_config.
 *   3. Otherwise, on a genuinely fresh install, net.conf's IP seeds the
 *      first network AND the management address. After the first boot
 *      net.conf no longer decides the address -- only the default route
 *      below still reads it.
 *
 * A missing/incomplete net.conf with no persisted address is not an
 * error (return 0): parts 1/2's test disks never write one, and a
 * deliberate loopback-only install is ordinary -- 127.0.0.1 stays the
 * only surface, which is a normal, inert boot rather than a failure.
 *
 * The upstream default route (net.conf's "gateway=") is a separate
 * concept (ADR-0067) and is still applied from net.conf at every boot;
 * operators change it afterwards via /system/routes, not here.
 */
static int bootstrap_management_network(void)
{
	char ip[64], upstream_gateway[64], iface[IFNAMSIZ];
	int prefix = 0;
	struct in_addr addr, gw, subnet;
	char subnet_str[INET_ADDRSTRLEN];
	uint32_t mask;
	struct network_def *net;
	enum network_error nerr;
	int rtfd;
	const char *persisted;
	int have_netconf;
	char mgmt_addr[INET_ADDRSTRLEN] = "";

	have_netconf = netconf_parse(NET_CONF_PATH, ip, sizeof(ip), &prefix, upstream_gateway,
	                             sizeof(upstream_gateway), iface, sizeof(iface)) == 0;

	/* (1) persisted single truth, else (2) legacy migration. */
	persisted = daemon_config_management_address();
	if (persisted == NULL) {
		uint32_t legacy_be;

		if (network_legacy_management_address(&legacy_be)) {
			struct in_addr la;

			la.s_addr = legacy_be;
			if (inet_ntop(AF_INET, &la, mgmt_addr, sizeof(mgmt_addr)) != NULL &&
			    daemon_config_set_management_address(mgmt_addr) == DAEMON_CONFIG_OK)
				persisted = daemon_config_management_address();
		}
	}
	if (persisted != NULL)
		snprintf(mgmt_addr, sizeof(mgmt_addr), "%s", persisted);

	/* (3) fresh install: net.conf seeds the first network + address. */
	if (persisted == NULL) {
		if (!have_netconf)
			return 0; /* loopback-only: an ordinary, inert boot */
		if (inet_pton(AF_INET, ip, &addr) != 1) {
			fprintf(stderr, "bootstrap_management_network: invalid ip %s\n", ip);
			return -1;
		}
		if (prefix < 8 || prefix > 30) {
			fprintf(stderr, "bootstrap_management_network: invalid prefix %d\n", prefix);
			return -1;
		}
		mask = (uint32_t)0xFFFFFFFFu << (32 - prefix);
		subnet.s_addr = htonl(ntohl(addr.s_addr) & mask);
		if (inet_ntop(AF_INET, &subnet, subnet_str, sizeof(subnet_str)) == NULL) {
			perror("bootstrap_management_network: inet_ntop");
			return -1;
		}
		net = network_find(MGMT_NETWORK_NAME);
		if (net == NULL) {
			nerr = network_create(MGMT_NETWORK_NAME, subnet_str, prefix, ip, NULL, NULL, &net);
			if (nerr != NETWORK_OK) {
				fprintf(stderr, "bootstrap_management_network: network_create failed (%d)\n",
				        (int)nerr);
				return -1;
			}
			nerr = network_attach_interface(MGMT_NETWORK_NAME, iface, 0);
			if (nerr != NETWORK_OK) {
				/*
				 * Issue #133: a missing uplink NIC must never kill the
				 * box (PID 1 exiting is a kernel panic). The bridge and
				 * its address already exist, so cixd can still bind and
				 * serve the console shell. Degraded and reachable beats
				 * dead: log precisely (ADR-0256: remembered, so the
				 * deploy stage does not confirm this boot as healthy),
				 * keep booting.
				 */
				char known[256];
				DIR *nd = opendir("/sys/class/net");
				size_t off = 0;

				known[0] = '\0';
				if (nd != NULL) {
					struct dirent *ne;

					while ((ne = readdir(nd)) != NULL) {
						if (ne->d_name[0] == '.')
							continue;
						off += (size_t)snprintf(known + off, sizeof(known) - off, "%s%s",
						                        off > 0 ? " " : "", ne->d_name);
						if (off >= sizeof(known) - 1)
							break;
					}
					closedir(nd);
				}
				snprintf(g_uplink_unattached, sizeof(g_uplink_unattached), "%s", iface);
				fprintf(stderr,
				        "bootstrap_management_network: cannot attach uplink \"%s\" (error %d) -- "
				        "interfaces present: [%s]. Continuing WITHOUT an uplink: the API is only "
				        "reachable on this machine itself; use the console shell to run "
				        "\"network attach-interface\" once the cause is fixed.\n",
				        iface, (int)nerr, known[0] != '\0' ? known : "none");
				logstore_write("cixd", "error",
				                "management network has NO uplink: attaching \"%s\" failed (error "
				                "%d); interfaces present: [%s]",
				                iface, (int)nerr, known[0] != '\0' ? known : "none");
			}
		}
		snprintf(mgmt_addr, sizeof(mgmt_addr), "%s", ip);
		if (daemon_config_set_management_address(mgmt_addr) != DAEMON_CONFIG_OK) {
			fprintf(stderr, "bootstrap_management_network: could not persist management address\n");
			return -1;
		}
	}

	/*
	 * Set network.c's runtime derivation and reapply the address to its
	 * network's bridge (#436; idempotent via EEXIST). The network exists
	 * here -- just created (fresh), reloaded by network_init (reapply),
	 * or the legacy-flag network (migration).
	 */
	nerr = network_set_management_address(mgmt_addr);
	if (nerr != NETWORK_OK) {
		/*
		 * The persisted address belongs to no current network (its
		 * network was deleted out of band). Degraded, not fatal: log
		 * and stay loopback-only rather than panicking as PID 1.
		 */
		fprintf(stderr,
		        "bootstrap_management_network: management address %s is in no known network "
		        "(error %d) -- staying loopback-only\n",
		        mgmt_addr, (int)nerr);
		logstore_write("cixd", "error",
		                "management address %s is in no known network -- cixd is loopback-only "
		                "until an address that matches a network is set",
		                mgmt_addr);
		return 0;
	}
	net = network_find_management();
	if (net != NULL) {
		struct in_addr ma;

		if (inet_pton(AF_INET, mgmt_addr, &ma) == 1) {
			rtfd = rtnl_open();
			if (rtfd >= 0) {
				(void)rtnl_addr_add_ipv4(rtfd, net->name, ma.s_addr, net->prefix_len); /* EEXIST ok */
				rtnl_close(rtfd);
			}
		}
	}

	snprintf(g_bind_addr_buf, sizeof(g_bind_addr_buf), "%s", mgmt_addr);
	g_bind_addr = g_bind_addr_buf;

	/*
	 * Upstream default route from net.conf's gateway -- a separate
	 * concept from the management address (ADR-0067/0287), still read
	 * from net.conf at every boot. Absent gateway = no default route (a
	 * subnet-only install). A PRESENT but malformed gateway stays an
	 * error: it is a typo in a value someone meant.
	 */
	if (have_netconf && upstream_gateway[0] != '\0') {
		if (inet_pton(AF_INET, upstream_gateway, &gw) != 1) {
			fprintf(stderr, "bootstrap_management_network: invalid gateway %s\n", upstream_gateway);
			return -1;
		}
		rtfd = rtnl_open();
		if (rtfd < 0) {
			perror("rtnl_open");
			return -1;
		}
		if (rtnl_route_add_default_ipv4(rtfd, gw.s_addr) != 0) {
			perror("bootstrap_management_network: default route");
			rtnl_close(rtfd);
			return -1;
		}
		rtnl_close(rtfd);
	}

	printf("init-mode: management address %s on network %s%s\n", mgmt_addr,
	       net != NULL ? net->name : "(none)",
	       (have_netconf && upstream_gateway[0] != '\0') ? "" : " (no default route)");
	fflush(stdout);
	return 0;
}

/*
 * Find the platform's own partitions by the labels cix-install wrote,
 * instead of by a device path compiled into this binary (#305).
 *
 * These five were "/dev/vda1".."/dev/vda5" for the platform's whole
 * life, and the comments above each of them said so honestly: a fixed
 * QEMU virtio-blk layout, with a real lookup deferred until hardware
 * needed one. Hardware needed one. Moving the same disk from virtio to
 * SATA renames it to sda, and a fully-installed, perfectly good system
 * then panics in a reboot loop -- the loader still says root=/dev/vda2,
 * the kernel finds sda1..sda5, and nothing in the box can reconcile
 * them. Measured on 192.168.15.95 when the owner changed the disk
 * configuration deliberately to find out whether the platform coped.
 *
 * The names have always been on the disk: cix-install.c's own sfdisk
 * script writes name="cix-esp" and the other four, and every one of
 * them survives whatever the kernel decides to call the device this
 * boot. partlabel_find() reads them straight out of the GPT.
 *
 * A label that resolves to nothing leaves its device empty rather than
 * falling back to a guess. The mounts below already treat a missing
 * partition as "not a real installed system" -- a throwaway test disk
 * has no cix-config -- so an empty string reaches mount(2), fails, and
 * takes exactly the path the absent-device case always took. What is
 * new is that it says so: on a real box stderr is the serial console,
 * which is the one place someone watching a boot can actually read.
 */
/*
 * A platform partition that turned up on a disk other than the one / is
 * on. Not an error -- partlabel_find() falls back to every disk exactly
 * so a machine in that shape still boots -- but it is not the layout
 * cix-install writes, so it is said out loud on the console instead of
 * being left for someone to infer from a device name months later.
 */
static void warn_if_off_root_disk(const char *label, const char *device)
{
	char parent[64];
	const char *base;

	if (PLATFORM_ROOT_DISK[0] == '\0' || device[0] == '\0')
		return;
	base = strrchr(device, '/');
	base = (base != NULL) ? base + 1 : device;
	partlabel_parent_name(base, parent, sizeof(parent));
	if (strcmp(parent, PLATFORM_ROOT_DISK) != 0)
		fprintf(stderr, "cix: warning: %s is on disk %s, not on the root disk %s\n", label,
		        parent, PLATFORM_ROOT_DISK);
}

static void resolve_platform_devices(void)
{
	static const struct {
		const char *label;
		char *out;
		size_t size;
	} map[] = {
		{ "cix-esp", ESP_DEVICE, sizeof(ESP_DEVICE) },
		{ "cix-root-a", ROOT_A_DEVICE, sizeof(ROOT_A_DEVICE) },
		{ "cix-root-b", ROOT_B_DEVICE, sizeof(ROOT_B_DEVICE) },
		{ "cix-config", CONFIG_DEVICE, sizeof(CONFIG_DEVICE) },
		{ "cix-containers", CONTAINERS_DEVICE, sizeof(CONTAINERS_DEVICE) },
	};
	size_t i;

	/*
	 * Which disk to believe when a label is not unique (#427). Printed
	 * as well as used: it is the one line that makes the five below
	 * auditable on a real boot, and a serial console is where someone
	 * watching a boot can actually read it.
	 */
	if (partlabel_root_disk(PLATFORM_ROOT_DISK, sizeof(PLATFORM_ROOT_DISK)) == 0)
		fprintf(stderr,
		        "cix: the running root is on disk %s -- platform labels resolve there first\n",
		        PLATFORM_ROOT_DISK);
	else
		fprintf(stderr, "cix: the running root's disk is unknown -- platform labels resolve "
		                "across every disk\n");

	for (i = 0; i < sizeof(map) / sizeof(map[0]); i++) {
		if (partlabel_find(map[i].label, map[i].out, map[i].size) == 0) {
			fprintf(stderr, "cix: %s is %s\n", map[i].label, map[i].out);
			warn_if_off_root_disk(map[i].label, map[i].out);
			continue;
		}
		map[i].out[0] = '\0';
		fprintf(stderr, "cix: no partition labelled %s on any disk\n", map[i].label);
	}
}

static int boot_init(void)
{
	int rtfd;

	if (mount_or_fail("proc", "/proc", "proc", MS_NOSUID | MS_NODEV | MS_NOEXEC) != 0)
		return -1;
	if (mount_or_fail("sysfs", "/sys", "sysfs", MS_NOSUID | MS_NODEV | MS_NOEXEC) != 0)
		return -1;
	if (mount_or_fail("cgroup2", "/sys/fs/cgroup", "cgroup2", 0) != 0)
		return -1;
	/*
	 * Resolve the platform's own partitions before anything mounts
	 * one (#305). Needs /sys, mounted immediately above; /dev is
	 * already populated because the kernel mounts devtmpfs itself
	 * (CONFIG_DEVTMPFS_MOUNT=y in image/kernel/qemu-part1.config),
	 * so this runs before any of our own /dev work and does not
	 * depend on it.
	 */
	resolve_platform_devices();

	/*
	 * efivarfs (issue #154). sysfs above provides /sys/firmware/efi,
	 * but EFI variables live in a SEPARATE filesystem mounted at
	 * .../efivars -- without this that directory is simply empty, and
	 * every attempt to read or write a variable fails against a
	 * read-only sysfs. POST /v1/system/boot-next would then be dead on
	 * exactly the real EFI hardware it exists for, while passing every
	 * test against a simulated directory.
	 *
	 * Deliberately NOT mount_or_fail(): a BIOS/CSM machine, or a
	 * kernel without CONFIG_EFIVAR_FS, legitimately has no efivarfs
	 * and must still boot. The endpoint reports "not writable here"
	 * in that case, which is the honest answer rather than a dead
	 * host.
	 */
	if (mount("efivarfs", "/sys/firmware/efi/efivars", "efivarfs",
	           MS_NOSUID | MS_NODEV | MS_NOEXEC, NULL) != 0 &&
	    errno != EBUSY /* already mounted */) {
		logstore_write("cixd", "info",
		                "efivarfs not mounted (%s) -- boot-slot selection via EFI variables "
		                "is unavailable on this machine",
		                strerror(errno));
	}
	/*
	 * task #764: cixd's own exec_into_container() (daemon/src/exec.c,
	 * the console/exec feature, ADR pending #426) calls posix_openpt()
	 * and then open()s the slave device ptsname_r() hands back --
	 * that slave path only resolves to a real device node once the
	 * devpts filesystem is actually mounted at /dev/pts. devtmpfs
	 * auto-populates /dev/ptmx (CONFIG_DEVTMPFS_MOUNT) so posix_openpt()
	 * itself always succeeds regardless, which is exactly what made
	 * this gap so easy to miss: only the SECOND step (opening the
	 * slave) ever fails, with a generic ENOENT that gave no hint it
	 * was devpts-shaped until task #764's own diagnostic surfacing
	 * made "No such file or directory" visible at all. cix-install.c's
	 * own early_mounts() has mounted devpts since ADR-0042/task #406 --
	 * but that binary only ever runs during one-time disk installation,
	 * never during cixd's own real boot_init() (--init-mode, a bare
	 * kernel with no initramfs) on an already-installed box, which is
	 * exactly why every console/exec attempt against 192.168.15.95
	 * failed with a bare 500 while the same code path passed cleanly
	 * in every dev-sandbox/QEMU test harness run (those inherit an
	 * already-mounted /dev/pts from their own outer environment,
	 * never exercising this gap). Same mount options as
	 * cix-install.c's own copy, for the same reason (ptmxmode=0666
	 * -- devpts's own ptmx alias needs to be world-writable for
	 * posix_openpt() to work as any non-root exec'd process would
	 * expect, even though everything in this project currently execs
	 * as root).
	 */
	if (mkdir("/dev/pts", 0755) != 0 && errno != EEXIST) {
		perror("/dev/pts");
		return -1;
	}
	if (mount("devpts", "/dev/pts", "devpts", MS_NOSUID | MS_NOEXEC,
	          "mode=0620,ptmxmode=0666") != 0) {
		perror("mount devpts");
		return -1;
	}
	/* ADR-0207 phase 4: btrfs is the install default for this
	 * partition; ext4 is what every not-yet-migrated box still has.
	 * Tried in that order -- mount(2) needs the type named, and
	 * probing the superblock here would be a second copy of what the
	 * kernel's own mount rejection already tells us for free. The
	 * ext4 branch retires with the rest of ext4 once btrfs has run
	 * production (the ADR's staged retirement), leaving one type
	 * again. */
	if (mount(CONTAINERS_DEVICE, g_base_dir, "btrfs", MS_NOSUID | MS_NODEV, NULL) != 0 &&
	    mount(CONTAINERS_DEVICE, g_base_dir, "ext4", MS_NOSUID | MS_NODEV, NULL) != 0 &&
	    mount_or_fail("tmpfs", g_base_dir, "tmpfs", MS_NOSUID | MS_NODEV) != 0)
		return -1;
	/*
	 * ADR-0141 fix (found live, 192.168.15.95): must run here, not just
	 * from main()'s own later call below boot_init()'s return -- the
	 * resolv.conf open+bind-mount immediately below this comment (and
	 * any future boot_init() step touching a grouped-layout path) reads
	 * RESOLV_CONF_PATH/STATE_DIR/REBUILDABLE_DIR *before* main() ever
	 * gets a chance to migrate an old-flat-layout box's real content
	 * into them. Confirmed the hard way: on this box's first boot after
	 * the STATE_DIR/REBUILDABLE_DIR grouping shipped, boot_init()'s own
	 * O_CREAT (no O_TRUNC) opened a brand-new, empty RESOLV_CONF_PATH
	 * (nothing had migrated there yet) and bind-mounted /etc/resolv.conf
	 * onto *that* inode; main()'s later migrate_flat_layout_to_grouped()
	 * then rename(2)'d the box's real, historical resolv.conf into the
	 * same path -- which only repoints the directory entry, not the
	 * already-bind-mounted inode -- leaving /etc/resolv.conf silently,
	 * permanently empty (every GET/PUT /v1/system/resolv still worked
	 * correctly, since resolv.c operates on the path, not the stale
	 * mount) until a second reboot, by which point nothing was left to
	 * migrate and the race couldn't recur. Calling it here, before any
	 * grouped-path use in this function, closes the race outright.
	 * Idempotent (a no-op once already-migrated) -- main()'s own call
	 * right after boot_init() returns stays in place, unchanged, for
	 * the non-init-mode (test/dev) path that never reaches this
	 * function at all.
	 */
	migrate_flat_layout_to_grouped();
	migrate_diskroles_out_of_state_dir();
	/*
	 * ADR-0076: the host's own outbound DNS resolver config.
	 * RESOLV_CONF_PATH (STATE_DIR/resolv.conf) is real, persisted
	 * state -- ordinary create-if-missing (O_CREAT, no O_TRUNC, so a
	 * real reboot never wipes an operator-configured resolver) rather
	 * than resolv_init()'s own later, read-only load, since that
	 * doesn't run until well after this mount needs the file to
	 * already exist. Bind-mounted onto /etc/resolv.conf (a real,
	 * empty placeholder file already staged in the control-plane
	 * squashfs, mkbootroot.c) so cixd's own curl/openssl/etc.
	 * subprocesses -- and every future host-level tool -- resolve
	 * against whatever an operator sets via PUT /v1/system/resolv,
	 * with zero further wiring needed per tool. Best-effort: a
	 * failure here leaves the host with no outbound DNS, exactly
	 * today's status quo, not a boot-blocking condition.
	 */
	{
		int rfd;

	/*
	 * The config partition is mounted HERE, before anything reads or
	 * writes a path under it.
	 *
	 * It used to be mounted after the /etc/resolv.conf setup below,
	 * which was harmless only while STATE_DIR lived on the containers
	 * partition. Once state moved to /config (ADR-0232), that ordering
	 * created STATE_DIR and resolv.conf on the ROOT filesystem's bare
	 * /config mountpoint, bind-mounted that inode onto
	 * /etc/resolv.conf, and then mounted the real partition over the
	 * top -- shadowing the file the mount still pointed at. The daemon
	 * reported the right nameservers, PUT /v1/system/resolv wrote them
	 * to the right path, and the host could not resolve a hostname,
	 * which is issue #138 again by a different route.
	 *
	 * Still deliberately non-fatal -- see CONFIG_DEVICE's own comment.
	 * Left mounted (not unmounted here): bootstrap_management_network()
	 * reads net.conf from it later in main().
	 */
	if (mount(CONFIG_DEVICE, CONFIG_DIR, "btrfs", 0, NULL) != 0)
		mount(CONFIG_DEVICE, CONFIG_DIR, "ext4", 0, NULL);

	/*
	 * Issue #138: STATE_DIR must exist before the file inside it
	 * can be created. On an UPGRADED box it always did, because
	 * migrate_flat_layout_to_grouped() above made it while moving
	 * real state in -- but that function returns early precisely
	 * when there is nothing to migrate, which is every FRESH
	 * install. So the create failed ENOENT, the bind mount failed
	 * ENOENT, and PUT /v1/system/resolv wrote to a path nothing
	 * reads: a freshly installed host could never resolve a
	 * hostname, no matter what an operator configured, while an
	 * older migrated one worked fine. That asymmetry is what made
	 * this look like anything other than what it was.
	 */
	if (persist_mkdir_p(STATE_DIR) != 0)
			fprintf(stderr, "%s: cannot create state dir for resolv.conf: %s\n", STATE_DIR,
			        strerror(errno));

		rfd = open(RESOLV_CONF_PATH, O_CREAT | O_WRONLY, 0644);
		if (rfd >= 0)
			close(rfd);
		else
			fprintf(stderr, "%s: cannot create: %s\n", RESOLV_CONF_PATH, strerror(errno));

		/*
		 * Loud, not silent. This failing means the host has no
		 * outbound DNS at all, and every symptom of it appears far
		 * away (a package source that will not fetch, a repo sync that
		 * fails with curl exit 6) with nothing pointing back here.
		 * perror() alone put it on a console nobody was reading; it
		 * now also reaches the log store, which is the only place a
		 * shell-less installed host can be asked what went wrong.
		 */
		if (mount(RESOLV_CONF_PATH, "/etc/resolv.conf", NULL, MS_BIND, NULL) != 0) {
			perror("/etc/resolv.conf bind mount");
			logstore_write("cixd", "error",
			                "/etc/resolv.conf bind mount FAILED (%s): this host cannot resolve "
			                "hostnames, and PUT /v1/system/resolv will have no effect. Every "
			                "outbound fetch must use a literal IP until this is fixed.",
			                strerror(errno));
		}
	}
	/* Needed to reach the loader entry confirm_boot() renames once this
	 * boot proves healthy (Phase 11 part 2) -- writable, not read-only
	 * like the root mounts, since that rename is a real write. */
	if (mount_or_fail(ESP_DEVICE, ESP_DIR, "vfat", MS_NOSUID | MS_NODEV | MS_NOEXEC) != 0)
		return -1;

	/*
	 * A tmpfs for the mountpoints of attached disks, so nothing writes
	 * them to the root slot.
	 *
	 * A mountpoint is pure runtime state: it exists to have a
	 * filesystem grafted onto it and is meaningless across a reboot.
	 * Writing those directories onto the root would work today --
	 * cix-install's loader entry mounts the slot `rw` -- and would be
	 * wrong the day the A/B roots become genuinely read-only, which is
	 * the design they exist to serve. A tmpfs is correct under both.
	 *
	 * Deliberately non-fatal, like the CONFIG_DEVICE mount above: if
	 * this fails the daemon still starts and persist_mkdir_p() creates
	 * an ordinary directory instead. A disk mountpoint is not worth
	 * refusing a boot over.
	 */
	if (mount("tmpfs", DISKS_MOUNT_DIR, "tmpfs", MS_NOSUID | MS_NODEV, "mode=0755") != 0)
		fprintf(stderr,
		        "boot_init: tmpfs for %s unavailable (%s) -- disk mountpoints will be "
		        "ordinary directories on the root slot\n",
		        DISKS_MOUNT_DIR, strerror(errno));

	/*
	 * A fresh kernel boot brings lo up as a device but leaves it
	 * administratively down (no IFF_UP) -- DEFAULT_BIND's bind() to
	 * 127.0.0.1 fails with EADDRNOTAVAIL until something sets it up.
	 * Reuses rtnl_link_set_up() (netplane/), the same primitive every
	 * container's own network setup already calls -- not a second,
	 * ioctl-based way to change link state.
	 */
	rtfd = rtnl_open();
	if (rtfd < 0) {
		perror("rtnl_open");
		return -1;
	}
	if (rtnl_link_set_up(rtfd, "lo") != 0) {
		perror("rtnl_link_set_up lo");
		rtnl_close(rtfd);
		return -1;
	}
	rtnl_close(rtfd);

	return 0;
}

/*
 * Renames whichever loader entry on the ESP matches this boot's slot
 * (cix-<slot>[+<tries-left>[-<tries-done>]].conf) down to the bare
 * cix-<slot>.conf, stripping systemd-boot's own Automatic Boot
 * Assessment counter suffix -- a plain rename(2), not a bootctl
 * subprocess call, the same hand-rolled-daemon posture ADR-0007/
 * ADR-0014 already established. Called only once this boot has actually
 * reached a healthy, serving state (main()'s own call site, right
 * before the reactor loop starts) -- "about to serve traffic" is the
 * honest definition of healthy this confirms.
 */
static int confirm_boot(const char *slot)
{
	char entry_name[ESP_ENTRY_NAME_MAX];
	char oldpath[PATH_MAX];
	char newpath[PATH_MAX];

	/*
	 * Which entry to confirm is esp.c's business -- it already owns
	 * loader-entry naming, and this used to duplicate that knowledge
	 * here, wrongly: it took whichever entry readdir() returned first.
	 * After an update the ESP legitimately holds both
	 * `cix-<slot>.conf` and `cix-<slot>+N.conf`, so hitting the bare
	 * one first made this a no-op while the real entry's counter kept
	 * ticking down -- an update that booted and passed every health
	 * check, silently undone two reboots later. Seen on a real host
	 * after a successful cutover (cix-a.conf and cix-a+2-1.conf side
	 * by side).
	 */
	if (!esp_entry_to_confirm(g_esp_entries_dir, slot, entry_name, sizeof(entry_name))) {
		fprintf(stderr, "confirm_boot: no loader entry found for slot %s\n", slot);
		return -1;
	}

	snprintf(oldpath, sizeof(oldpath), "%s/%s", g_esp_entries_dir, entry_name);
	snprintf(newpath, sizeof(newpath), "%s/cix-%s.conf", g_esp_entries_dir, slot);
	if (strcmp(oldpath, newpath) == 0)
		return 0; /* already confirmed (no counter suffix) -- nothing to do */
	/* rename(2) replaces any stale confirmed entry of the same name,
	 * which is exactly what should happen to the previous cycle's. */
	if (rename(oldpath, newpath) != 0) {
		perror("confirm_boot rename");
		return -1;
	}
	return 0;
}

static int name_is_valid(const char *name)
{
	return simple_name_is_valid(name, REGISTRY_NAME_MAX);
}





static void handle_health(int fd)
{
	struct json_writer w;

	jw_init(&w);
	jw_obj_open(&w);
	jw_key(&w, "status");
	jw_str(&w, "ok");
	/*
	 * #370: whether write authentication is actually in force. Here,
	 * on the one endpoint every client and monitor already polls,
	 * because the failure this closes is that an OPEN control plane
	 * and a secured one were indistinguishable -- this host answered
	 * unauthenticated writes for four days and nothing anywhere said so.
	 *
	 * `status` deliberately stays "ok". A fresh install has no admin
	 * user by design and would otherwise report unhealthy forever,
	 * which teaches operators to ignore the field; and this project's
	 * own deploy tooling polls health for liveness, where "is the
	 * daemon up" and "is it authenticating" are different questions.
	 * So: a separate field, always present, never a status change.
	 *
	 * Not withheld from unauthenticated callers, deliberately. One
	 * unauthenticated POST already reveals it, so hiding it would
	 * protect nobody while keeping it from the operator who needs it.
	 */
	jw_key(&w, "auth_gating_active");
	jw_bool(&w, hostauth_gating_active());
	jw_obj_close(&w);
	respond_json(fd, 200, "OK", &w);
	jw_free(&w);
}

/*
 * Build/slot/kernel identity -- split out of handle_health() (ADR-0077)
 * so the liveness poll every client runs every few seconds stays the
 * single-field response it always should have been, while this
 * lower-frequency identity check gets a real home of its own.
 */
static void handle_system_boot(int fd)
{
	struct json_writer w;
	struct utsname uts;

	jw_init(&w);
	jw_obj_open(&w);
	jw_key(&w, "build_version");
	jw_str(&w, CIX_BUILD_VERSION);
	jw_key(&w, "build_time");
	jw_str(&w, CIX_BUILD_TIME);
	jw_key(&w, "slot");
	if (g_slot != NULL)
		jw_str(&w, g_slot);
	else
		jw_null(&w);
	jw_key(&w, "kernel_version");
	if (uname(&uts) == 0)
		jw_str(&w, uts.release);
	else
		jw_null(&w);
	/*
	 * What each platform partition resolved to THIS BOOT (#305).
	 *
	 * resolve_platform_devices() reads these out of the GPT by label,
	 * so a disk that comes back as sda instead of vda changes every
	 * one of these strings and nothing else. Until this field existed
	 * the result was visible only on stderr -- the serial console on
	 * an installed box, which is precisely what nobody has to hand
	 * when a controller changes underneath a machine. The log store is
	 * not an option for it either: these are resolved before anything
	 * is mounted, and the store lives on the very partition being
	 * resolved.
	 *
	 * Empty strings are the normal answer for a dev daemon that is not
	 * an installed system, and the thing to look at on one that is.
	 */
	jw_key(&w, "platform_devices");
	jw_obj_open(&w);
	jw_key(&w, "esp");
	jw_str(&w, ESP_DEVICE);
	jw_key(&w, "root_a");
	jw_str(&w, ROOT_A_DEVICE);
	jw_key(&w, "root_b");
	jw_str(&w, ROOT_B_DEVICE);
	jw_key(&w, "config");
	jw_str(&w, CONFIG_DEVICE);
	jw_key(&w, "containers");
	jw_str(&w, CONTAINERS_DEVICE);
	/*
	 * The disk the five above were resolved on (#427), "" when the
	 * running root is not on a block device. Reported because it is
	 * the tie-break itself: five device paths look identically
	 * plausible whether or not they came off the right disk.
	 */
	jw_key(&w, "root_disk");
	jw_str(&w, PLATFORM_ROOT_DISK);
	jw_obj_close(&w);
	/*
	 * Real freshness signal for `pkg hostbuild cix --deploy`
	 * (task #737, ADR-0058-follow-on comment in
	 * g_bootroot_assembly_started's own doc comment above): a client
	 * that captured bootroot_assembly_completed_generation *before*
	 * triggering a new hostbuild round can wait here for it to advance
	 * past that baseline rather than trusting "cixd-root.squashfs
	 * exists" (which is also true of a stale file left by an earlier,
	 * unrelated round).
	 */
	/*
	 * Assembly state used to be reported here and has MOVED to
	 * GET /v1/system/assembly (#182, ADR-0230).
	 *
	 * This endpoint's subject is what BOOTED. Assembly is what is being
	 * BUILT, and it had no endpoint of its own at all, so its progress
	 * arrived as two generation counters on a neighbour that happened
	 * to know about it. An operator watching a deploy had to know that
	 * assembly is a side effect of a hostbuild named "cix" and is
	 * observed somewhere else entirely.
	 *
	 * Moved rather than duplicated, per this project's no-compatibility-
	 * shim posture; its one consumer (cixctl's deploy wait) moved in the
	 * same change.
	 */
	jw_obj_close(&w);
	respond_json(fd, 200, "OK", &w);
	jw_free(&w);
}

/* Both just record what main()'s own post-loop cleanup should do once
 * the event loop actually stops (g_stop=1) -- responding here, before
 * that happens, so the client sees a real reply rather than the
 * connection simply dropping mid-shutdown. */
static void handle_shutdown(int fd)
{
	struct json_writer w;

	g_shutdown_action = SHUTDOWN_ACTION_POWEROFF;
	g_stop = 1;

	jw_init(&w);
	jw_obj_open(&w);
	jw_key(&w, "status");
	jw_str(&w, "shutting down");
	jw_obj_close(&w);
	respond_json(fd, 202, "Accepted", &w);
	jw_free(&w);
}

/* ---- Issue #63: factory reset ---- */

/*
 * Returning a box to its just-installed state, without reinstalling.
 *
 * The mechanism is deliberately a SENTINEL plus a reboot, rather than
 * wiping state and carrying on. Two reasons, and both are correctness
 * rather than taste:
 *
 * - The daemon holds most of this state in memory and rewrites its
 *   files on any change. Deleting them underneath a running daemon is a
 *   race it usually loses -- the next container event, health probe or
 *   config touch writes the file straight back, and the reset silently
 *   half-happens.
 * - It is crash-safe. Once the sentinel is written the reset WILL
 *   happen, on this boot or the next one. A reset that got as far as
 *   "the operator was told yes" and then evaporated because the reboot
 *   did not complete is the worst possible outcome for an operation
 *   whose entire purpose is being sure of the starting state.
 *
 * The wipe itself runs at startup before any subsystem loads, so
 * nothing has read the old state yet and nothing can write it back.
 */
#define FACTORY_RESET_SENTINEL "FACTORY-RESET"

static void factory_reset_sentinel_path(char *out, size_t out_size)
{
	snprintf(out, out_size, "%s/%s", g_base_dir, FACTORY_RESET_SENTINEL);
}

/*
 * Wipes every operator-owned tree back to first-boot empty. Called at
 * startup only, before boot_subsystem_init() reads anything.
 *
 * What is deliberately NOT touched: the OS itself. The two root slots,
 * the kernel, the ESP and the install-time config partition all live
 * outside this base directory, so a reset returns the box to how
 * cix-install left it rather than to nothing.
 *
 * What IS destroyed, and worth naming because it is the part that
 * cannot be undone: volumes and everything in them. A just-installed
 * box has no volumes, so a reset that kept them would not be a reset --
 * but this is the one category here that is genuinely irreplaceable
 * workload data rather than regenerable platform state.
 */
static void factory_reset_apply_if_pending(void)
{
	char sentinel[PATH_MAX];
	struct stat st;
	const char *trees[] = { "state", "containers", "rebuildable", "logs", "volumes" };
	size_t i;

	factory_reset_sentinel_path(sentinel, sizeof(sentinel));
	if (stat(sentinel, &st) != 0)
		return;

	fprintf(stderr, "factory reset: wiping all operator state back to first-boot defaults\n");
	for (i = 0; i < sizeof(trees) / sizeof(trees[0]); i++) {
		char path[PATH_MAX];

		snprintf(path, sizeof(path), "%s/%s", g_base_dir, trees[i]);
		/*
		 * "disks" holds the mountpoints of role-assigned disks, not
		 * their contents -- removing the directory does not touch the
		 * filesystems themselves, which is right: a factory reset
		 * forgets which disks were assigned what, it does not reformat
		 * hardware behind the operator's back.
		 */
		persist_remove_tree(path);
		fprintf(stderr, "factory reset: removed %s\n", path);
	}
	/*
	 * The mountpoint directory is removed by its real path rather than
	 * as a child of the data directory, because it is no longer one.
	 * Still only mountpoints, never their contents: this runs before
	 * diskformat_remount_present_role_disks(), so every directory
	 * under it is empty at this moment. A factory reset forgets which
	 * disks were assigned what; it does not reformat hardware.
	 */
	persist_remove_tree(DISKS_MOUNT_DIR);
	fprintf(stderr, "factory reset: removed %s\n", DISKS_MOUNT_DIR);
	unlink(sentinel);
	fprintf(stderr, "factory reset: complete -- this boot starts from install defaults\n");
}

/*
 * POST /v1/system/factory-reset
 *
 * The most destructive endpoint this platform has, so the confirmation
 * is the instance's own name typed back -- not a boolean. A boolean can
 * be sent by a client that misunderstood what it was calling; a name
 * can only be sent by something that looked it up first.
 */
static void handle_factory_reset(int fd, const char *body, size_t body_len)
{
	struct json_value *root;
	const char *confirm;
	const char *instance = siteconfig_instance_name();
	char sentinel[PATH_MAX];
	int sfd;
	struct json_writer w;

	root = json_parse(body, body_len);
	if (root == NULL || root->type != JSON_OBJECT) {
		json_free(root);
		respond_error(fd, 400, "Bad Request", "invalid JSON body");
		return;
	}
	confirm = json_as_string(json_object_get(root, "confirm"));
	if (instance == NULL || instance[0] == '\0')
		instance = "cix";
	if (confirm == NULL || strcmp(confirm, instance) != 0) {
		json_free(root);
		respond_error(fd, 400, "Bad Request",
		              "confirm must be this install's own instance name (GET /v1/system/site) -- "
		              "this destroys every container, image, volume and all their data, and "
		              "cannot be undone");
		return;
	}
	json_free(root);

	factory_reset_sentinel_path(sentinel, sizeof(sentinel));
	sfd = open(sentinel, O_WRONLY | O_CREAT | O_TRUNC | O_CLOEXEC, 0600);
	if (sfd < 0) {
		respond_error(fd, 500, "Internal Server Error", "could not arm the factory reset");
		return;
	}
	close(sfd);
	/*
	 * Logged before the reboot, not after: the log store is one of the
	 * things about to be wiped, so this line exists to reach whatever
	 * is forwarding logs off the box, and to be the last thing in the
	 * local store if nothing is.
	 */
	logstore_write("system", "warn",
	               "FACTORY RESET armed -- rebooting, and all operator state will be wiped on the "
	               "next boot");

	g_shutdown_action = SHUTDOWN_ACTION_REBOOT;
	g_stop = 1;

	jw_init(&w);
	jw_obj_open(&w);
	jw_key(&w, "status");
	jw_str(&w, "factory reset armed -- rebooting");
	jw_key(&w, "wipes");
	jw_arr_open(&w);
	jw_str(&w, "containers and their storage");
	jw_str(&w, "images and every version of them");
	jw_str(&w, "volumes AND ALL DATA IN THEM");
	jw_str(&w, "networks, routes, DNS, PKI, LDAP, NTP, syslog registrations");
	jw_str(&w, "package install state, recipes, build cache and artifacts");
	jw_str(&w, "the consolidated log store");
	jw_arr_close(&w);
	jw_key(&w, "keeps");
	jw_arr_open(&w);
	jw_str(&w, "the installed OS itself (both root slots, kernel, ESP, install config)");
	jw_str(&w, "the contents of any role-assigned disk -- roles are forgotten, disks are not reformatted");
	jw_arr_close(&w);
	jw_obj_close(&w);
	respond_json(fd, 202, "Accepted", &w);
	jw_free(&w);
}

static void handle_reboot(int fd)
{
	struct json_writer w;

	g_shutdown_action = SHUTDOWN_ACTION_REBOOT;
	g_stop = 1;

	jw_init(&w);
	jw_obj_open(&w);
	jw_key(&w, "status");
	jw_str(&w, "rebooting");
	jw_obj_close(&w);
	respond_json(fd, 202, "Accepted", &w);
	jw_free(&w);
}

/*
 * Tries-left counter for a freshly-staged update's own loader entry --
 * matches cix-install.c's own ROOT_A_TRIES value (3), the same
 * Automatic Boot Assessment convention applied uniformly to any fresh
 * slot, not just the very first install.
 */
#define ROOT_UPDATE_TRIES 3

/*
 * Writes the whole content of src_path onto dst device_path, raw --
 * mirrors cix-install.c's own copy_file()/write_whole_file_to_
 * device() shape (plain open/read/write loop, no byte-offset math,
 * since device_path is a real partition block device here too, not
 * test/test_disk_image.c's flat-file-at-an-offset case). device_path
 * already exists as a block device, so unlike copy_file()'s
 * O_CREAT|O_TRUNC destination, this opens it O_WRONLY only. Kept as
 * its own small static rather than shared across the daemon/installer
 * binaries -- genuinely trivial, and the two binaries share no common
 * library today (the daemon can't link test/test_image_fixture.c,
 * which is test-scoped).
 */
/*
 * Copies every byte of src_fd onto dst_fd, then fsync()s dst_fd before
 * returning success -- without that, these bytes can still be sitting
 * in the page cache, not yet flushed through to the underlying device/
 * filesystem, when do_system_update() reports 200 back to the caller.
 * The whole point of this feature is a trustworthy "the new image is
 * safely on the inactive slot" signal; a crash/power-loss between that
 * response and an eventual background writeback could otherwise
 * silently lose it. Shared by write_file_to_device() (a raw partition
 * device) and write_file_to_esp() (a regular file on the already-
 * mounted ESP) -- callers own opening/closing both fds, since the
 * right open() flags genuinely differ between the two (a device
 * already exists; an ESP file may not).
 */
static int copy_bytes(int src_fd, int dst_fd)
{
	char buf[65536];
	ssize_t n;

	while ((n = read(src_fd, buf, sizeof(buf))) > 0) {
		if (write(dst_fd, buf, (size_t)n) != n) {
			perror("write");
			return -1;
		}
	}
	if (n < 0) {
		perror("read");
		return -1;
	}
	if (fsync(dst_fd) != 0) {
		perror("fsync");
		return -1;
	}
	return 0;
}

/* device_path already exists as a block device -- O_WRONLY only, no
 * O_CREAT (unlike write_file_to_esp() below). */
static int write_file_to_device(const char *src_path, const char *device_path)
{
	int src, dst, rc;

	src = open(src_path, O_RDONLY);
	if (src < 0) {
		perror(src_path);
		return -1;
	}
	dst = open(device_path, O_WRONLY);
	if (dst < 0) {
		perror(device_path);
		close(src);
		return -1;
	}
	rc = copy_bytes(src, dst);
	close(src);
	close(dst);
	return rc;
}

/* esp_path is a plain file on the already-mounted ESP -- it may not
 * exist yet (first time this slot's kernel file is ever written) or
 * may already exist (overwriting a prior update), so O_CREAT|O_TRUNC,
 * unlike write_file_to_device()'s existing-device case above. */
static int write_file_to_esp(const char *src_path, const char *esp_path)
{
	int src, dst, rc;

	src = open(src_path, O_RDONLY);
	if (src < 0) {
		perror(src_path);
		return -1;
	}
	dst = open(esp_path, O_CREAT | O_TRUNC | O_WRONLY, 0644);
	if (dst < 0) {
		perror(esp_path);
		close(src);
		return -1;
	}
	rc = copy_bytes(src, dst);
	close(src);
	close(dst);
	return rc;
}

/*
 * Pure (no fd) core of POST /v1/system/update -- writes a fresh
 * control-plane squashfs and/or a fresh kernel onto whichever slot
 * ISN'T this boot's own (g_slot), then stages a fresh systemd-boot
 * loader entry for it with its own Automatic Boot Assessment
 * tries-left counter -- the same "write to the inactive slot, let the
 * existing boot-counter/confirm_boot() machinery decide whether it
 * sticks" shape ADR-0014 already established for the very first
 * install, now reachable on an already-running system too (see
 * docs/adr/0031, docs/adr/0032). Split out from handle_system_update()
 * the same way create_container_from_body() is split from
 * handle_create() -- so test/test_boot_update.c's --test-update-
 * image=/--test-update-kernel= self-test (main(), no live HTTP round
 * trip needed) can exercise the exact same real device/ESP-write and
 * loader-entry logic a live request would, inside a real QEMU guest
 * with a real virtio-blk disk attached, without needing the daemon to
 * also be its own HTTP client.
 *
 * image_path/kernel_path are local paths the operator has already
 * transferred the new files to (e.g. scp) -- no upload/streaming HTTP
 * machinery is added here; see ADR-0031 for why. Independent and both
 * optional (at least one required): a cixd security fix needs no
 * new kernel, and new hardware support needs no new root.
 *
 * Deliberately does NOT reboot -- update and reboot stay two separate,
 * composable actions (ADR-0031). The operator (or a script) calls the
 * existing POST /v1/system/reboot separately once ready to cut over;
 * confirm_boot()/the boot counter, both entirely unchanged, decide
 * whether the fresh slot sticks.
 *
 * Returns the HTTP status this operation resolves to (200 on success);
 * *out_slot/*out_updated_root/*out_updated_kernel are filled in only
 * on success, *out_errmsg only otherwise.
 */
static int do_system_update(const char *body, size_t body_len, char *out_slot,
                             size_t out_slot_size, int *out_updated_root, int *out_updated_kernel,
                             char *out_errmsg, size_t out_errmsg_size)
{
	struct json_value *root;
	const char *image_path;
	const char *kernel_path;
	const char *inactive_slot;
	const char *device;
	char root_partuuid[64];
	const char *active_device;
	char active_kernel_path[PATH_MAX];
	int src;
	unsigned char magic4[4];
	unsigned char magic2[2];
	char kernel_dest[PATH_MAX];
	char entry_path[PATH_MAX];
	char entry_conf[512];

	if (g_slot == NULL) {
		snprintf(out_errmsg, out_errmsg_size,
		         "this daemon has no --slot=, there is no inactive slot to update");
		return 400;
	}
	if (strcmp(g_slot, "a") == 0) {
		inactive_slot = "b";
		device = ROOT_B_DEVICE;
		active_device = ROOT_A_DEVICE;
	} else if (strcmp(g_slot, "b") == 0) {
		inactive_slot = "a";
		device = ROOT_A_DEVICE;
		active_device = ROOT_B_DEVICE;
	} else {
		snprintf(out_errmsg, out_errmsg_size, "unrecognized --slot=, expected \"a\" or \"b\"");
		return 400;
	}
	snprintf(kernel_dest, sizeof(kernel_dest), "%s/cix-bzImage-%s", ESP_DIR, inactive_slot);
	snprintf(active_kernel_path, sizeof(active_kernel_path), "%s/cix-bzImage-%s", ESP_DIR, g_slot);

	root = json_parse(body, body_len);
	if (root == NULL) {
		snprintf(out_errmsg, out_errmsg_size, "invalid JSON body");
		return 400;
	}
	image_path = json_as_string(json_object_get(root, "image_path"));
	kernel_path = json_as_string(json_object_get(root, "kernel_path"));
	if ((image_path == NULL || image_path[0] == '\0') &&
	    (kernel_path == NULL || kernel_path[0] == '\0')) {
		json_free(root);
		snprintf(out_errmsg, out_errmsg_size, "image_path and/or kernel_path required");
		return 400;
	}
	/*
	 * ADR-0095: the real footgun this project's own guides have
	 * documented and worked around by hand ever since ADR-0031/
	 * ADR-0032 first split image_path/kernel_path apart -- a one-sided
	 * update used to leave the OTHER file in the inactive slot exactly
	 * as stale as it was from whenever that slot was last written,
	 * silently pairing (say) a brand-new kernel with a root squashfs
	 * from three updates ago. Closed by auto-copying the omitted half
	 * forward from the ACTIVE slot's own currently-running copy --
	 * already-booted, already-verified-good by definition, and the
	 * exact thing an operator supplying only one path actually wants
	 * paired with it. This is pure default-filling: an explicitly
	 * supplied image_path/kernel_path is used exactly as given, this
	 * only ever substitutes for one that's missing.
	 */
	if (image_path == NULL || image_path[0] == '\0')
		image_path = NULL; /* copy from active_device below */
	if (kernel_path == NULL || kernel_path[0] == '\0')
		kernel_path = NULL; /* copy from active_kernel_path below */

	/* Cheap, real safety checks before touching the inactive slot at
	 * all: squashfs's own on-disk magic ("hsqs", the little-endian
	 * bytes of 0x73717368) and a bzImage's own on-disk magic (the x86
	 * boot-sector signature 0x55 0xAA at offset 0x1FE, and "HdrS" --
	 * struct setup_header's own magic -- at offset 0x202, the same
	 * check bootloaders use) each turn a wrong path by mistake into a
	 * clean 400 instead of silently overwriting the inactive slot with
	 * garbage. Both files are fully validated before either is
	 * written, so a bad kernel_path never leaves a real image_path
	 * partially applied. */
	if (image_path != NULL && image_path[0] != '\0') {
		src = open(image_path, O_RDONLY);
		if (src < 0) {
			json_free(root);
			snprintf(out_errmsg, out_errmsg_size,
			         "image_path does not exist or is not readable");
			return 400;
		}
		if (read(src, magic4, 4) != 4 || memcmp(magic4, "hsqs", 4) != 0) {
			close(src);
			json_free(root);
			snprintf(out_errmsg, out_errmsg_size, "image_path is not a squashfs image");
			return 400;
		}
		close(src);
	}
	if (kernel_path != NULL && kernel_path[0] != '\0') {
		src = open(kernel_path, O_RDONLY);
		if (src < 0) {
			json_free(root);
			snprintf(out_errmsg, out_errmsg_size,
			         "kernel_path does not exist or is not readable");
			return 400;
		}
		if (lseek(src, 0x1FE, SEEK_SET) != 0x1FE || read(src, magic2, 2) != 2 ||
		    magic2[0] != 0x55 || magic2[1] != 0xAA || lseek(src, 0x202, SEEK_SET) != 0x202 ||
		    read(src, magic4, 4) != 4 || memcmp(magic4, "HdrS", 4) != 0) {
			close(src);
			json_free(root);
			snprintf(out_errmsg, out_errmsg_size, "kernel_path is not a valid bzImage");
			return 400;
		}
		close(src);
	}

	/*
	 * write_file_to_device()'s own copy_bytes() loop reads until read()
	 * returns 0 -- true at end-of-file for a plain file, equally true
	 * at a block device's own real capacity for a raw device node, so
	 * active_device works as a src_path here with no separate device-
	 * to-device copy primitive needed.
	 */
	if (write_file_to_device(image_path != NULL ? image_path : active_device, device) != 0) {
		json_free(root);
		snprintf(out_errmsg, out_errmsg_size,
		         image_path != NULL ? "failed to write image to inactive slot"
		                             : "failed to copy the active slot's own root forward");
		return 500;
	}
	if (write_file_to_esp(kernel_path != NULL ? kernel_path : active_kernel_path, kernel_dest) !=
	    0) {
		json_free(root);
		snprintf(out_errmsg, out_errmsg_size,
		         kernel_path != NULL ? "failed to write kernel to inactive slot"
		                              : "failed to copy the active slot's own kernel forward");
		return 500;
	}

	/*
	 * One entry per slot. Any other entry for this slot is removed
	 * first, because a slot with two entries cannot be rolled back
	 * reliably.
	 *
	 * Seen on 192.168.15.95 after a bad update: the ESP held both
	 * cix-b+0-3.conf (this update's entry, its three boot attempts
	 * spent) and cix-b.conf (the same slot, left over from an earlier
	 * update after a successful boot stripped its counter). An entry
	 * with no counter is never considered expired -- that is what
	 * "confirmed good" means -- so the failed slot stayed permanently
	 * bootable through its own stale entry, and which slot won came
	 * down to how the two versions happened to compare. Automatic Boot
	 * Assessment cannot mean anything while a second, un-counted door
	 * into the same root is still open.
	 */
	{
		DIR *ed = opendir(g_esp_entries_dir);
		struct dirent *de;
		char prefix[64];

		snprintf(prefix, sizeof(prefix), "cix-%s", inactive_slot);
		if (ed != NULL) {
			while ((de = readdir(ed)) != NULL) {
				char stale[PATH_MAX];
				size_t nlen = strlen(de->d_name);
				size_t plen = strlen(prefix);

				if (nlen <= 5 || strcmp(de->d_name + nlen - 5, ".conf") != 0)
					continue;
				if (strncmp(de->d_name, prefix, plen) != 0)
					continue;
				/* Same slot only: "cix-b" must not match "cix-b2".
				 * What follows the slot is either the counter or
				 * nothing at all. */
				if (de->d_name[plen] != '+' && de->d_name[plen] != '.')
					continue;
				snprintf(stale, sizeof(stale), "%s/%s", g_esp_entries_dir, de->d_name);
				if (unlink(stale) == 0)
					logstore_write("cixd", "info",
					               "esp: removed a previous boot entry for slot %s: %s",
					               inactive_slot, de->d_name);
			}
			closedir(ed);
		}
	}

	snprintf(entry_path, sizeof(entry_path), "%s/cix-%s+%d.conf", g_esp_entries_dir,
	         inactive_slot, ROOT_UPDATE_TRIES);
	/* version is this boot's own current timestamp -- always higher
	 * than whatever's already on disk, so systemd-boot sorts this
	 * entry first, with no need to parse the existing entry's own
	 * version back out first. linux always references this slot's own
	 * cix-bzImage-<slot> (pre-staged for both slots at install
	 * time, ADR-0032) -- whether or not kernel_path was given this
	 * call, that file already exists and is exactly what should boot. */
	{
		/* Issue #24: the console portion comes from the operator's own
		 * configuration rather than being fixed here. Everything else
		 * on this line -- root=, rw, init= and the daemon's own
		 * arguments -- stays this function's business: those decide
		 * whether the machine boots at all, not what it displays.
		 *
		 * panic=10 is what makes Automatic Boot Assessment work
		 * unattended. A panicking kernel HALTS; it does not reboot. So
		 * a slot that dies during boot consumes one try and then just
		 * sits there, and the counter only drains if somebody power-
		 * cycles the machine. That is exactly what happened on
		 * 192.168.15.95 after a bad update: the counter worked
		 * perfectly, 3 -> 0 across three resets, and every one of
		 * those resets was a human at the box.
		 *
		 * A Cix host has no console and no BMC by assumption -- that
		 * is why ADR-0212 exists at all -- so "an operator power-cycles
		 * it" is not a recovery path, it is an outage. Ten seconds is
		 * long enough for a serial capture to be read and short enough
		 * that three failed attempts cost well under a minute. */
		char console_opts[512];

		bootconsole_render(console_opts, sizeof(console_opts));
		/*
		 * The entry names the root by PARTUUID, not by the device
		 * path this daemon happens to see it at (#305). `device`
		 * below is still the path -- writing the squashfs needs one
		 * -- but a boot entry outlives this boot, and the name the
		 * kernel gives a disk does not. A compiled-in /dev/vda2 in
		 * exactly this line is what turned a healthy install into a
		 * panic loop when its disk moved from virtio to SATA.
		 */
		if (partlabel_uuid_for_device(device, root_partuuid, sizeof(root_partuuid)) != 0) {
			logstore_write("cixd", "error",
			                "could not read the PARTUUID of %s -- refusing to write a boot "
			                "entry naming a device path that may not survive a reboot",
			                device);
			return -1;
		}
		snprintf(entry_conf, sizeof(entry_conf),
		         "title Cix (%s)\n"
		         "sort-key cix\n"
		         "version %ld\n"
		         "linux /cix-bzImage-%s\n"
		         /*
		          * cixd is init (ADR-0247).
		          *
		          * ADR-0246 tried a supervisor above it, and the box
		          * disproved it: cix-init came up as pid 1, spawned
		          * the worker, answered its out-of-band status port
		          * and restarted the worker on demand -- and the
		          * worker could not come up a SECOND time, because the
		          * whole --init-mode startup path assumes a fresh
		          * kernel (not merely boot_init()'s mounts, but
		          * diskrole_init(), network_init() and a dozen
		          * boot_subsystem_init() calls besides). The restarted
		          * worker wedged before creating its listener, so the
		          * recovery mechanism produced a worse outage than the
		          * failure it existed to recover from.
		          *
		          * A restart path that cannot restart is worse than
		          * none, because it invites the kill. The defence is
		          * that the reactor does not block in the first place,
		          * which test_blocking_waits enforces per file.
		          */
		         /*
		          * No --bind= (#443). The management address belongs to
		          * net.conf, which boot_init() reads and which the
		          * listener now binds (ADR-0284). Writing it here too
		          * made it a second copy of one fact, read from the
		          * wrong one: a management-address change updated
		          * net.conf and the registry, this entry kept the old
		          * address, and the next boot bound an address that was
		          * gone. There is no override to preserve -- cix-boot
		          * has no edit-at-menu, so a cmdline copy was never
		          * something an operator could reach for, and a box
		          * whose net.conf is wrong now comes up on loopback
		          * with a working console shell instead of needing one.
		          * The --bind= FLAG stays, for test and dev invocations
		          * that have no net.conf at all.
		          */
		         "options %s%sroot=PARTUUID=%s rw panic=10 init=/bin/cixd -- --init-mode "
		         "--slot=%s\n",
		         inactive_slot[0] == 'a' ? "A" : "B", (long)time(NULL), inactive_slot,
		         console_opts, console_opts[0] != '\0' ? " " : "", root_partuuid,
		         inactive_slot);
	}

	{
		int efd = open(entry_path, O_CREAT | O_TRUNC | O_WRONLY, 0644);
		size_t len = strlen(entry_conf);

		/* fsync() for the same reason write_file_to_device()/write_
		 * file_to_esp() do -- this file is the ONLY thing that makes
		 * the just-written image/kernel bootable at all; it needs to
		 * be durable too, not still sitting in the page cache when
		 * this call returns. */
		if (efd < 0 || write(efd, entry_conf, len) != (ssize_t)len || fsync(efd) != 0) {
			if (efd >= 0)
				close(efd);
			json_free(root);
			snprintf(out_errmsg, out_errmsg_size, "failed to write loader entry");
			return 500;
		}
		close(efd);
	}

	json_free(root);
	snprintf(out_slot, out_slot_size, "%s", inactive_slot);
	/*
	 * Both are always written now (ADR-0095) -- an omitted half is
	 * auto-filled from the active slot's own running copy rather than
	 * left stale, so both genuinely are fresh content in the inactive
	 * slot regardless of which one(s) the caller actually supplied.
	 */
	*out_updated_root = 1;
	*out_updated_kernel = 1;
	return 200;
}

/*
 * Issue #141: fetch an update image by URL, verify it, and hand back a
 * local path do_system_update() can use unchanged.
 *
 * Synchronous on purpose, unlike pkg bootstrap's async toolchain fetch.
 * An update image is ~10 MB on a LAN, not 1.4 GB, and the caller is an
 * operator waiting on a single deliberate action -- an async job with
 * its own polling endpoint would be more machinery than the problem
 * has. If that stops being true (a slow WAN, a much larger image), the
 * async pattern already exists next door to copy.
 *
 * The checksum is required, not optional: this writes a boot slot, and
 * an image that arrives truncated or wrong would be discovered at the
 * next reboot, which is the worst possible time.
 */
static int fetch_update_image(const char *url, const char *sha256, char *out_path,
                              size_t out_path_size, char *err, size_t err_size)
{
	char *argv[16];
	char url_buf[PKG_URL_MAX];
	pid_t pid;
	int status;
	char got[128];

	if (sha256 == NULL || strlen(sha256) != 64) {
		snprintf(err, err_size,
		         "image_sha256 is required with image_url and must be 64 hex characters -- "
		         "this writes a boot slot, so an unverified image is not accepted");
		return -1;
	}
	snprintf(url_buf, sizeof(url_buf), "%s", url);
	snprintf(out_path, out_path_size, "%s", SYSTEM_UPDATE_FETCH_PATH);
	unlink(out_path);

	/*
	 * #285: this one runs on the EVENT LOOP, which makes its guards a
	 * different question from every other curl here.
	 *
	 * The rest are forked job children -- an unbounded fetch stalls
	 * that job and nothing else. This is called straight from the
	 * POST /v1/system/update handler and waited on with waitpid(), so
	 * a peer that accepts the connection and then says nothing does
	 * not stall a job, it stalls the whole control plane, for as long
	 * as it likes, from one unauthenticated-shaped API call. Nothing
	 * about the "synchronous on purpose" reasoning above is wrong; it
	 * reasoned about SIZE (~10 MB on a LAN) and not about a peer that
	 * never answers.
	 *
	 * So the retry count comes down as well. The shared guards bound
	 * one attempt at roughly 20s of connect plus 60s of silence, and
	 * --retry multiplies that: eight attempts is ten minutes of dead
	 * control plane, which is not a bound worth having. Two attempts
	 * is one real retry for a transient blip and a worst case of a
	 * few minutes.
	 *
	 * That is a bound, not a fix. A synchronous fetch on the event
	 * loop is still a control-plane pause for however long a genuinely
	 * slow transfer takes, and the async pattern this function's own
	 * comment points at next door remains the real answer if update
	 * images stop being small and local.
	 */
	argv[0] = (char *)PKG_CURL_BIN;
	argv[1] = "-fsSL";
	argv[2] = "--connect-timeout";
	argv[3] = PKG_CURL_CONNECT_TIMEOUT;
	argv[4] = "--speed-limit";
	argv[5] = PKG_CURL_SPEED_LIMIT;
	argv[6] = "--speed-time";
	argv[7] = PKG_CURL_SPEED_TIME;
	argv[8] = "--retry";
	argv[9] = "2";
	argv[10] = "-o";
	argv[11] = out_path;
	argv[12] = url_buf;
	argv[13] = NULL;

	pid = fork();
	if (pid < 0) {
		snprintf(err, err_size, "fork failed: %s", strerror(errno));
		return -1;
	}
	if (pid == 0) {
		execve(PKG_CURL_BIN, argv, environ);
		_exit(127);
	}
	if (waitpid(pid, &status, 0) != pid || !WIFEXITED(status) || WEXITSTATUS(status) != 0) {
		snprintf(err, err_size, "could not fetch image_url (curl exit %d)",
		         WIFEXITED(status) ? WEXITSTATUS(status) : -1);
		unlink(out_path);
		return -1;
	}
	if (pkg_run_capture_sha256(out_path, got, sizeof(got)) != 0) {
		snprintf(err, err_size, "could not checksum the fetched image");
		unlink(out_path);
		return -1;
	}
	if (strcasecmp(got, sha256) != 0) {
		snprintf(err, err_size, "fetched image does not match image_sha256 (got %s)", got);
		unlink(out_path);
		return -1;
	}
	return 0;
}

/* Defined with the dispatch code below; the deploy gate here needs to
 * name who was refused (ADR-0271/ADR-0273). */
static const char *audit_who(void);

static void handle_system_update(int fd, const char *body, size_t body_len)
{
	char slot[8];
	char errmsg[256];
	int status;
	int updated_root, updated_kernel;
	struct json_writer w;
	char fetched_body[PKG_URL_MAX + 512];
	char fetched_path[PATH_MAX];
	const char *use_body = body;
	size_t use_body_len = body_len;

	/*
	 * Issue #141: image_url is rewritten into the image_path
	 * do_system_update() already understands, rather than teaching that
	 * function a second way to be given an image. One code path stages
	 * a slot; this just decides what file it stages from.
	 */
	{
		struct json_value *root = (body != NULL && body_len > 0) ? json_parse(body, body_len) : NULL;

		if (root != NULL) {
			const char *url = json_as_string(json_object_get(root, "image_url"));
			const char *sha = json_as_string(json_object_get(root, "image_sha256"));
			const char *kpath = json_as_string(json_object_get(root, "kernel_path"));

			if (url != NULL && url[0] != '\0') {
				if (fetch_update_image(url, sha, fetched_path, sizeof(fetched_path), errmsg,
				                        sizeof(errmsg)) != 0) {
					json_free(root);
					respond_error(fd, 400, "Bad Request", errmsg);
					return;
				}
				if (kpath != NULL && kpath[0] != '\0')
					snprintf(fetched_body, sizeof(fetched_body),
					         "{\"image_path\":\"%s\",\"kernel_path\":\"%s\"}", fetched_path,
					         kpath);
				else
					snprintf(fetched_body, sizeof(fetched_body), "{\"image_path\":\"%s\"}",
					         fetched_path);
				use_body = fetched_body;
				use_body_len = strlen(fetched_body);
				logstore_write("cixd", "info",
				                "system update: fetched and verified an image from %s", url);
			}
			json_free(root);
		}
	}

	/*
	 * ADR-0273: the deploy gate.
	 *
	 * Checked here, after image_url has been rewritten into an
	 * image_path, so the target an operator is asked to approve is the
	 * one that would actually be written -- approving a URL and
	 * staging a file would be two different things wearing one name.
	 *
	 * Refused rather than queued: this is one synchronous request with
	 * nothing behind it, so there is no queue to wait in. The refusal
	 * names the exact target, because an operator cannot approve what
	 * the error does not tell them.
	 */
	if (pkg_gate_enabled("deploy")) {
		struct json_value *gr = json_parse(use_body, use_body_len);
		const char *ipath = gr != NULL ? json_as_string(json_object_get(gr, "image_path")) : NULL;
		char target[256];

		snprintf(target, sizeof(target), "%s", ipath != NULL ? ipath : "");
		json_free(gr);
		if (target[0] == '\0') {
			respond_error(fd, 400, "Bad Request",
			              "the deploy gate is on and this request names no image_path to "
			              "approve");
			return;
		}
		if (!pkg_approval_take_deploy(target)) {
			char msg[512];

			snprintf(msg, sizeof(msg),
			         "the deploy gate is on and \"%s\" is not approved -- "
			         "POST /v1/pipeline/approve {\"gate\":\"deploy\",\"target\":\"%s\"} "
			         "first. Nothing has been written to a boot slot",
			         target, target);
			logstore_write("audit", "warn", "%s system update HELD by the deploy gate: %s",
			                audit_who(), target);
			respond_error(fd, 409, "Conflict", msg);
			return;
		}
	}

	status = do_system_update(use_body, use_body_len, slot, sizeof(slot), &updated_root,
	                           &updated_kernel, errmsg, sizeof(errmsg));
	if (status != 200) {
		respond_error(fd, status, http_status_text(status), errmsg);
		return;
	}

	jw_init(&w);
	jw_obj_open(&w);
	jw_key(&w, "status");
	jw_str(&w, "staged");
	jw_key(&w, "slot");
	jw_str(&w, slot);
	jw_key(&w, "updated");
	jw_arr_open(&w);
	if (updated_root)
		jw_str(&w, "root");
	if (updated_kernel)
		jw_str(&w, "kernel");
	jw_arr_close(&w);
	jw_obj_close(&w);
	respond_json(fd, 200, "OK", &w);
	jw_free(&w);
}

/*
 * Pure (no fd) core of GET /v1/system/backup -- bundles platform
 * *configuration* state (what containers/networks/DNS records/
 * packages should exist, plus this install's own site config), not
 * workload data or image content, and never PKI (see docs/adr/0033).
 * Each file is read via the existing
 * persist_read_file() (daemon/src/persist.c) exactly as-is and
 * embedded as an escaped JSON string, the same "raw content as a JSON
 * string" shape ConfigFile.content already uses -- not a second,
 * raw-JSON-embedding mechanism. persist_read_file() already treats a
 * missing file as valid-empty (ENOENT -> 0-length), so a fresh system
 * with e.g. no DNS records yet needs no special-casing here.
 *
 * container_defs alone is already a complete reconstruction source:
 * ADR-0025 persists a container's entire raw create request verbatim
 * (including devices/interfaces/files/sysctls), so nothing here needs
 * its own separate per-feature export logic.
 *
 * Always succeeds (200) -- reading local state files cannot fail in a
 * way that should reject the request the way a bad squashfs/kernel
 * path can for /system/update; an individual unreadable recipe file
 * is skipped, not fatal to the whole bundle.
 */
static void do_system_backup(struct json_writer *w)
{
	char *buf;
	size_t len;
	DIR *d;
	struct dirent *de;

	jw_init(w);
	jw_obj_open(w);
	jw_key(w, "version");
	jw_int(w, 1);
	/*
	 * #415: this bundle names what it does not carry. Hardcoded false
	 * and that is the point -- the PKI is deliberately not here (this is
	 * offered to the dashboard as a download, and a file that sometimes
	 * contains the root CA private key is the wrong thing to hand
	 * around), but a backup that silently omits the trust root READS as
	 * complete, and an operator finds out otherwise at the reinstall
	 * they needed it for. POST /pki/export is the other half.
	 */
	jw_key(w, "pki_included");
	jw_bool(w, 0);

	jw_key(w, "container_defs");
	if (persist_read_file(CONTAINER_DEFS_STATE_PATH, &buf, &len) == 0 && buf != NULL) {
		jw_str(w, buf);
		free(buf);
	} else {
		jw_str(w, "");
	}

	jw_key(w, "networks");
	if (persist_read_file(NETWORKS_STATE_PATH, &buf, &len) == 0 && buf != NULL) {
		jw_str(w, buf);
		free(buf);
	} else {
		jw_str(w, "");
	}

	jw_key(w, "dns_records");
	if (persist_read_file(DNS_RECORDS_STATE_PATH, &buf, &len) == 0 && buf != NULL) {
		jw_str(w, buf);
		free(buf);
	} else {
		jw_str(w, "");
	}

	jw_key(w, "pkg_installed");
	if (persist_read_file(PKG_INSTALLED_STATE_PATH, &buf, &len) == 0 && buf != NULL) {
		jw_str(w, buf);
		free(buf);
	} else {
		jw_str(w, "");
	}

	/*
	 * Issue #88: the volume REGISTRY -- which volumes exist and where
	 * they are placed. That is configuration, so it belongs here; a
	 * volume's contents are workload data and deliberately stay out,
	 * the same boundary ADR-0033 draws for image content.
	 *
	 * This is not optional polish. container_defs reference volumes by
	 * name, and a container naming an unknown volume is a hard 400 by
	 * design (ADR-0183) -- so a bundle carrying the defs but not the
	 * registry restores onto a box where every container with a volume
	 * fails to start, which is a broken restore rather than a partial
	 * one. Restoring recreates the volumes empty; refilling them is the
	 * operator's own concern, exactly as it is for image content.
	 */
	jw_key(w, "volumes");
	if (persist_read_file(VOLUMES_STATE_PATH, &buf, &len) == 0 && buf != NULL) {
		jw_str(w, buf);
		free(buf);
	} else {
		jw_str(w, "");
	}

	jw_key(w, "site_config");
	if (persist_read_file(SITE_CONFIG_PATH, &buf, &len) == 0 && buf != NULL) {
		jw_str(w, buf);
		free(buf);
	} else {
		jw_str(w, "");
	}

	/* Every recipe version on disk, not just currently-installed
	 * packages -- they're cheap, and the operator may want them all
	 * preserved. ADR-0107's version-keyed layout (<name>/<version>/
	 * build.sh, ADR-0120's filename) needs a two-level directory walk,
	 * not the flat single-level opendir() this used before that
	 * migration landed -- that old code silently stopped matching
	 * anything the moment recipes moved to per-name subdirectories
	 * (every entry in PKG_RECIPES_DIR became a directory, none ending
	 * in ".recipe"), so backups have included zero recipes since.
	 * Each entry's key is "<name>/<version>" (never ambiguous, since a
	 * bare package name never itself contains '/') -- do_system_
	 * restore() below splits on the same separator to reconstruct the
	 * exact on-disk path. */
	jw_key(w, "pkg_recipes");
	jw_obj_open(w);
	d = opendir(PKG_RECIPES_DIR);
	if (d != NULL) {
		while ((de = readdir(d)) != NULL) {
			char name_dir[PATH_MAX];
			DIR *vd;
			struct dirent *vde;

			if (de->d_name[0] == '.')
				continue;
			snprintf(name_dir, sizeof(name_dir), "%s/%s", PKG_RECIPES_DIR, de->d_name);
			vd = opendir(name_dir);
			if (vd == NULL)
				continue;
			while ((vde = readdir(vd)) != NULL) {
				char script_path[PATH_MAX];
				char key[512];
				struct stat st;

				if (vde->d_name[0] == '.')
					continue;
				snprintf(script_path, sizeof(script_path), "%s/%s/build.sh", name_dir,
				         vde->d_name);
				if (stat(script_path, &st) != 0 || !S_ISREG(st.st_mode))
					continue;
				if (persist_read_file(script_path, &buf, &len) != 0 || buf == NULL)
					continue;
				snprintf(key, sizeof(key), "%s/%s", de->d_name, vde->d_name);
				jw_key(w, key);
				jw_str(w, buf);
				free(buf);
			}
			closedir(vd);
		}
		closedir(d);
	}
	jw_obj_close(w);

	jw_obj_close(w);
}

static void handle_system_backup(int fd)
{
	struct json_writer w;

	do_system_backup(&w);
	respond_json(fd, 200, "OK", &w);
	jw_free(&w);
}



/*
 * Writes str (a JSON-string field's own already-validated content,
 * e.g. a whole container_defs.json) to path via the existing
 * persist_atomic_write() (daemon/src/persist.c) -- same atomic-
 * rewrite safety every other state file in this codebase already
 * gets, no new write primitive introduced for restore.
 */
static int restore_write_field(const char *path, const char *str)
{
	return persist_atomic_write(path, str, strlen(str));
}

/*
 * Pure (no fd) core of POST /v1/system/restore -- the reverse of
 * do_system_backup(): takes the identical bundle shape and writes each
 * field back to its own real path. Every embedded field is validated
 * BEFORE any file is written (container_defs/networks/dns_records/
 * pkg_installed must each themselves parse as valid JSON; pkg_recipes
 * must be an object of string values) -- one malformed field must
 * never leave the others half-applied, the same "validate everything,
 * then write" discipline do_system_update() already established.
 *
 * Deliberately does NOT reboot or hot-reload anything -- network_
 * init()/dns_init()/pkg_init()/containerdef_init() all run once at
 * daemon startup, so restored state only takes effect on the next
 * boot, via boot-time logic (containerdef_autostart_all() in
 * particular) that already exists and is already tested. This
 * function's whole job is "the files are now correct"; the operator
 * calls the pre-existing POST /system/reboot separately once ready,
 * the same "write, don't reboot, caller decides when to cut over"
 * shape /system/update already established (ADR-0031).
 *
 * Returns the HTTP status this operation resolves to (200 on
 * success); *out_errmsg is filled in only otherwise.
 */
/* True if v is a string whose own content is either empty or itself
 * valid JSON -- used to validate each of restore's JSON-file fields
 * before any of them are written. */
static int json_string_field_is_valid(const struct json_value *v)
{
	const char *s;
	struct json_value *check;

	s = json_as_string(v);
	if (s == NULL)
		return 0;
	if (s[0] == '\0')
		return 1;
	check = json_parse(s, strlen(s));
	if (check == NULL)
		return 0;
	json_free(check);
	return 1;
}

static int do_system_restore(const char *body, size_t body_len, char *out_errmsg,
                              size_t out_errmsg_size)
{
	struct json_value *root;
	const struct json_value *jcontainer_defs, *jnetworks, *jdns_records, *jpkg_installed;
	const struct json_value *jpkg_recipes, *jsite_config, *jvolumes;
	size_t i;
	int have_any = 0;

	root = json_parse(body, body_len);
	if (root == NULL) {
		snprintf(out_errmsg, out_errmsg_size, "invalid JSON body");
		return 400;
	}

	jcontainer_defs = json_object_get(root, "container_defs");
	jnetworks = json_object_get(root, "networks");
	jdns_records = json_object_get(root, "dns_records");
	jpkg_installed = json_object_get(root, "pkg_installed");
	jpkg_recipes = json_object_get(root, "pkg_recipes");
	jsite_config = json_object_get(root, "site_config");
	jvolumes = json_object_get(root, "volumes"); /* issue #88 */

	/* Each present field must be a string whose own content is valid
	 * JSON -- checked for every field before any file is touched. */
	if (jcontainer_defs != NULL) {
		have_any = 1;
		if (!json_string_field_is_valid(jcontainer_defs)) {
			json_free(root);
			snprintf(out_errmsg, out_errmsg_size, "container_defs is not valid JSON");
			return 400;
		}
	}
	if (jnetworks != NULL) {
		have_any = 1;
		if (!json_string_field_is_valid(jnetworks)) {
			json_free(root);
			snprintf(out_errmsg, out_errmsg_size, "networks is not valid JSON");
			return 400;
		}
	}
	if (jdns_records != NULL) {
		have_any = 1;
		if (!json_string_field_is_valid(jdns_records)) {
			json_free(root);
			snprintf(out_errmsg, out_errmsg_size, "dns_records is not valid JSON");
			return 400;
		}
	}
	if (jpkg_installed != NULL) {
		have_any = 1;
		if (!json_string_field_is_valid(jpkg_installed)) {
			json_free(root);
			snprintf(out_errmsg, out_errmsg_size, "pkg_installed is not valid JSON");
			return 400;
		}
	}
	if (jpkg_recipes != NULL) {
		have_any = 1;
		if (jpkg_recipes->type != JSON_OBJECT) {
			json_free(root);
			snprintf(out_errmsg, out_errmsg_size, "pkg_recipes must be an object");
			return 400;
		}
		for (i = 0; i < jpkg_recipes->u.object.count; i++) {
			const char *key = jpkg_recipes->u.object.keys[i];
			const char *slash = strchr(key, '/');

			if (json_as_string(jpkg_recipes->u.object.values[i]) == NULL) {
				json_free(root);
				snprintf(out_errmsg, out_errmsg_size,
				         "pkg_recipes.%s is not a string", key);
				return 400;
			}
			/* ADR-0120: each key is "<name>/<version>" (do_system_
			 * backup()'s own emitted shape) -- a bare package name
			 * never itself contains '/', so a single separator with
			 * non-empty content on both sides is both necessary and
			 * sufficient here. */
			if (slash == NULL || slash == key || slash[1] == '\0') {
				json_free(root);
				snprintf(out_errmsg, out_errmsg_size,
				         "pkg_recipes key %s is not in <name>/<version> form", key);
				return 400;
			}
		}
	}
	if (jsite_config != NULL) {
		have_any = 1;
		if (!json_string_field_is_valid(jsite_config)) {
			json_free(root);
			snprintf(out_errmsg, out_errmsg_size, "site_config is not valid JSON");
			return 400;
		}
	}
	if (jvolumes != NULL) {
		have_any = 1;
		if (!json_string_field_is_valid(jvolumes)) {
			json_free(root);
			snprintf(out_errmsg, out_errmsg_size, "volumes is not valid JSON");
			return 400;
		}
	}

	if (!have_any) {
		json_free(root);
		snprintf(out_errmsg, out_errmsg_size,
		         "at least one of container_defs/networks/dns_records/pkg_installed/pkg_recipes/"
		         "site_config/volumes required");
		return 400;
	}

	/* Every field validated -- now write. */
	if (jcontainer_defs != NULL &&
	    restore_write_field(CONTAINER_DEFS_STATE_PATH, json_as_string(jcontainer_defs)) != 0) {
		json_free(root);
		snprintf(out_errmsg, out_errmsg_size, "failed to write container_defs.json");
		return 500;
	}
	if (jnetworks != NULL &&
	    restore_write_field(NETWORKS_STATE_PATH, json_as_string(jnetworks)) != 0) {
		json_free(root);
		snprintf(out_errmsg, out_errmsg_size, "failed to write networks.json");
		return 500;
	}
	if (jdns_records != NULL &&
	    restore_write_field(DNS_RECORDS_STATE_PATH, json_as_string(jdns_records)) != 0) {
		json_free(root);
		snprintf(out_errmsg, out_errmsg_size, "failed to write dns_records.json");
		return 500;
	}
	if (jpkg_installed != NULL &&
	    restore_write_field(PKG_INSTALLED_STATE_PATH, json_as_string(jpkg_installed)) != 0) {
		json_free(root);
		snprintf(out_errmsg, out_errmsg_size, "failed to write pkg_installed.json");
		return 500;
	}
	if (jsite_config != NULL &&
	    restore_write_field(SITE_CONFIG_PATH, json_as_string(jsite_config)) != 0) {
		json_free(root);
		snprintf(out_errmsg, out_errmsg_size, "failed to write site_config.json");
		return 500;
	}
	if (jvolumes != NULL &&
	    restore_write_field(VOLUMES_STATE_PATH, json_as_string(jvolumes)) != 0) {
		json_free(root);
		snprintf(out_errmsg, out_errmsg_size, "failed to write volumes.json");
		return 500;
	}
	if (jpkg_recipes != NULL) {
		if (persist_mkdir_p(PKG_RECIPES_DIR) != 0) {
			json_free(root);
			snprintf(out_errmsg, out_errmsg_size, "failed to create recipes directory");
			return 500;
		}
		for (i = 0; i < jpkg_recipes->u.object.count; i++) {
			const char *key = jpkg_recipes->u.object.keys[i];
			const char *slash = strchr(key, '/');
			char version_dir[PATH_MAX];
			char path[PATH_MAX];

			/* Already validated above (key is "<name>/<version>",
			 * slash guaranteed non-NULL and interior) -- rebuilds the
			 * exact <name>/<version>/build.sh path do_system_backup()
			 * read this same content from (ADR-0120). */
			snprintf(version_dir, sizeof(version_dir), "%s/%.*s/%s", PKG_RECIPES_DIR,
			         (int)(slash - key), key, slash + 1);
			if (persist_mkdir_p(version_dir) != 0) {
				json_free(root);
				snprintf(out_errmsg, out_errmsg_size, "failed to create recipe directory for %s",
				         key);
				return 500;
			}
			snprintf(path, sizeof(path), "%s/build.sh", version_dir);
			if (restore_write_field(path, json_as_string(jpkg_recipes->u.object.values[i])) !=
			    0) {
				json_free(root);
				snprintf(out_errmsg, out_errmsg_size, "failed to write recipe %s", key);
				return 500;
			}
		}
	}

	json_free(root);
	return 200;
}

static void handle_system_restore(int fd, const char *body, size_t body_len)
{
	char errmsg[256];
	int status;
	struct json_writer w;

	status = do_system_restore(body, body_len, errmsg, sizeof(errmsg));
	if (status != 200) {
		respond_error(fd, status, http_status_text(status), errmsg);
		return;
	}

	jw_init(&w);
	jw_obj_open(&w);
	jw_key(&w, "status");
	jw_str(&w, "restored");
	jw_obj_close(&w);
	respond_json(fd, 200, "OK", &w);
	jw_free(&w);
}



/*
 * Auto-maintains a single DNS record for this install's own qualified
 * FQDN, pointed at the daemon's own --bind= address (ADR-0053) -- the
 * "reflects back" design: not a second, independently-editable
 * record, this record's own name simply tracks whatever the FQDN
 * currently is, the same relationship reissue_host_pki_cert() already
 * has with the PKI leaf above.
 *
 * Only meaningful when --bind= is a real, specific address the
 * operator explicitly chose: "0.0.0.0" (bind-everywhere) and
 * "127.0.0.1" (loopback-only, unreachable from anywhere else) have no
 * single correct IP to publish, so both are a deliberate no-op here,
 * never a guess.
 *
 * g_last_instance_dns_name tracks what this function itself last
 * registered, in-process only (not persisted) -- enough to delete the
 * old name before creating the new one when the FQDN changes while
 * the daemon keeps running (the actual, tested scenario). A rename
 * that happens to straddle a daemon restart with no PUT ever
 * registering the "old" name in this process's own lifetime is a
 * real, narrow, accepted gap (see ADR-0053's own Consequences), not
 * solved here.
 */
static char g_last_instance_dns_name[DNS_NAME_MAX];

static void reconcile_instance_dns_record(void)
{
	char fqdn[SITECONFIG_NAME_MAX * 3];
	struct in_addr addr;
	struct dns_record *rec;
	enum dns_error derr;

	if (strcmp(g_bind_addr, "0.0.0.0") == 0 || strcmp(g_bind_addr, "127.0.0.1") == 0)
		return;
	if (inet_pton(AF_INET, g_bind_addr, &addr) != 1)
		return;

	siteconfig_host_fqdn(fqdn, sizeof(fqdn));
	if (!dns_name_is_valid(fqdn)) {
		fprintf(stderr,
		        "instance DNS record: composed FQDN '%s' is not a valid DNS name, skipping\n",
		        fqdn);
		return;
	}

	if (g_last_instance_dns_name[0] != '\0' && strcmp(g_last_instance_dns_name, fqdn) != 0)
		dns_record_delete(g_last_instance_dns_name);
	dns_record_delete(fqdn); /* in case this exact name is already registered (idempotent re-call) */

	/* "__host" owner sentinel, same reasoning as reissue_host_pki_cert()
	 * above -- never a real container name, so this record's own
	 * ownership can't collide with one. */
	derr = dns_record_create(fqdn, addr.s_addr, "__host", &rec);
	if (derr != DNS_OK) {
		fprintf(stderr, "instance DNS record: could not (re)create %s (err=%d)\n", fqdn,
		        (int)derr);
		return;
	}
	snprintf(g_last_instance_dns_name, sizeof(g_last_instance_dns_name), "%s", fqdn);
}

/*
 * GET/PUT /v1/system/site (ADR-0046): this install's own declared
 * site_name/domain_suffix, a real convenience for client tooling to
 * suggest a default FQDN with, never enforced by anything on the
 * daemon side -- see siteconfig.h's own comment for the full
 * rationale. GET always 200s (siteconfig_init() already applied
 * defaults at startup; there is no "not configured yet" state the way
 * PKI's bootstrap-gated resources have).
 */
static void handle_site_get(int fd)
{
	struct json_writer w;

	jw_init(&w);
	siteconfig_write_json(&w);
	respond_json(fd, 200, "OK", &w);
	jw_free(&w);
}

static void handle_site_put(int fd, const char *body, size_t body_len)
{
	struct json_value *root;
	const char *instance_name, *site_name, *domain_suffix;
	enum siteconfig_error serr;
	struct json_writer w;

	root = json_parse(body, body_len);
	if (root == NULL) {
		respond_error(fd, 400, "Bad Request", "invalid JSON body");
		return;
	}
	instance_name = json_as_string(json_object_get(root, "instance_name"));
	site_name = json_as_string(json_object_get(root, "site_name"));
	domain_suffix = json_as_string(json_object_get(root, "domain_suffix"));
	if (instance_name == NULL) {
		json_free(root);
		respond_error(fd, 400, "Bad Request", "instance_name is required");
		return;
	}
	if (domain_suffix == NULL) {
		json_free(root);
		respond_error(fd, 400, "Bad Request", "domain_suffix is required");
		return;
	}

	serr = siteconfig_set(instance_name, site_name, domain_suffix);
	json_free(root);

	if (serr != SITECONFIG_OK) {
		switch (serr) {
		case SITECONFIG_ERR_INVALID_INSTANCE_NAME:
			respond_error(fd, 400, "Bad Request", "invalid instance_name");
			break;
		case SITECONFIG_ERR_INVALID_SITE_NAME:
			respond_error(fd, 400, "Bad Request", "invalid site_name");
			break;
		case SITECONFIG_ERR_INVALID_DOMAIN_SUFFIX:
			respond_error(fd, 400, "Bad Request", "invalid domain_suffix");
			break;
		case SITECONFIG_ERR_PERSIST_FAILED:
		default:
			respond_error(fd, 500, "Internal Server Error", "could not persist site config");
			break;
		}
		return;
	}

	reissue_host_pki_cert();
	reconcile_instance_dns_record();

	jw_init(&w);
	siteconfig_write_json(&w);
	respond_json(fd, 200, "OK", &w);
	jw_free(&w);
}

/*
 * Builds a fresh SSL_CTX from the PKI subsystem's already-issued
 * "host" leaf certificate (PKI_CERTS_DIR/host.{crt,key}, reissue_host_
 * pki_cert()) -- reusing that existing cert-issuance path rather than
 * inventing a second one, per Part 0.5's design. Returns NULL (with a
 * diagnostic already printed) if the CA hasn't been bootstrapped yet,
 * or the host cert/key can't be loaded/don't match -- HTTPS simply
 * isn't available yet in that case, exactly the same "not configured"
 * posture other PKI-gated resources in this daemon already have.
 *
 * ADR-0136: when an intermediate CA is bootstrapped, host.crt (like
 * every leaf pki_cert_create() issues) is signed BY the intermediate,
 * but is itself still just the one leaf certificate on disk --
 * SSL_CTX_use_certificate_file() below loads exactly that one
 * certificate and nothing past it, even if the file had more (it
 * doesn't parse a chain the way SSL_CTX_use_certificate_chain_file()
 * would). Confirmed live: a client trusting only the root CA can
 * never validate leaf->intermediate->root with just the leaf in hand
 * -- it needs the intermediate cert as part of the handshake too.
 * pki_intermediate_cert_pem() + SSL_CTX_add_extra_chain_cert() below
 * add it explicitly, the OpenSSL-idiomatic way to extend an
 * already-loaded leaf's own chain without touching host.crt itself
 * (which pki_cert_deliver()'s own, separate leaf+intermediate
 * chain-building for pki_issue-delivered container certs already
 * assumes is leaf-only -- changing that here would double the
 * intermediate there).
 */
static SSL_CTX *create_tls_ctx(void)
{
	SSL_CTX *ctx;
	char crt_path[PATH_MAX], key_path[PATH_MAX];

	if (!pki_ca_bootstrapped()) {
		fprintf(stderr, "create_tls_ctx: PKI not bootstrapped yet -- no host cert to serve HTTPS with\n");
		return NULL;
	}
	snprintf(crt_path, sizeof(crt_path), "%s/host.crt", PKI_CERTS_DIR);
	snprintf(key_path, sizeof(key_path), "%s/host.key", PKI_CERTS_DIR);

	ctx = SSL_CTX_new(TLS_server_method());
	if (ctx == NULL) {
		ERR_print_errors_fp(stderr);
		return NULL;
	}
	if (SSL_CTX_use_certificate_file(ctx, crt_path, SSL_FILETYPE_PEM) != 1 ||
	    SSL_CTX_use_PrivateKey_file(ctx, key_path, SSL_FILETYPE_PEM) != 1 ||
	    SSL_CTX_check_private_key(ctx) != 1) {
		ERR_print_errors_fp(stderr);
		SSL_CTX_free(ctx);
		return NULL;
	}

	{
		char *intermediate_pem = NULL;
		size_t intermediate_len = 0;
		int r = pki_intermediate_cert_pem(&intermediate_pem, &intermediate_len);

		if (r < 0) {
			fprintf(stderr, "create_tls_ctx: could not read the intermediate CA cert\n");
			SSL_CTX_free(ctx);
			return NULL;
		}
		if (r == 1) {
			BIO *bio = BIO_new_mem_buf(intermediate_pem, (int)intermediate_len);
			X509 *intermediate_x509 = bio != NULL ? PEM_read_bio_X509(bio, NULL, NULL, NULL) : NULL;

			if (bio != NULL)
				BIO_free(bio);
			free(intermediate_pem);
			if (intermediate_x509 == NULL) {
				fprintf(stderr, "create_tls_ctx: could not parse the intermediate CA cert\n");
				SSL_CTX_free(ctx);
				return NULL;
			}
			/* Ownership transfers to ctx on success -- never X509_free()
			 * this one ourselves. */
			if (SSL_CTX_add_extra_chain_cert(ctx, intermediate_x509) != 1) {
				ERR_print_errors_fp(stderr);
				X509_free(intermediate_x509);
				SSL_CTX_free(ctx);
				return NULL;
			}
		}
	}

	return ctx;
}

/*
 * Creates, binds, and listens a real TCP socket at bind_addr:port --
 * the one source of truth for that sequence, shared by main()'s own
 * initial bind and rebind_listener()'s live-rebind path below (Part
 * 0.5). SOCK_NONBLOCK/SOCK_CLOEXEC for the same reason every other fd
 * this daemon holds open is CLOEXEC -- see main()'s own comment at its
 * call site. Returns a ready-to-epoll fd, or -1 (already logged) on
 * any failure -- never partially bound.
 */
static int create_listen_socket(const char *bind_addr, int port)
{
	int fd;
	int opt = 1;
	struct sockaddr_in addr;

	fd = socket(AF_INET, SOCK_STREAM | SOCK_NONBLOCK | SOCK_CLOEXEC, 0);
	if (fd < 0) {
		perror("socket");
		return -1;
	}
	setsockopt(fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));

	memset(&addr, 0, sizeof(addr));
	addr.sin_family = AF_INET;
	addr.sin_port = htons((uint16_t)port);
	if (inet_pton(AF_INET, bind_addr, &addr.sin_addr) != 1) {
		fprintf(stderr, "create_listen_socket: invalid bind address %s\n", bind_addr);
		close(fd);
		return -1;
	}

	if (bind(fd, (struct sockaddr *)&addr, sizeof(addr)) != 0) {
		perror("create_listen_socket: bind");
		close(fd);
		return -1;
	}
	if (listen(fd, 128) != 0) {
		perror("create_listen_socket: listen");
		close(fd);
		return -1;
	}
	return fd;
}

/*
 * Live listen-socket rebind (Part 0.5) -- cixd is real PID 1 under
 * --init-mode (confirmed: image/src/cix-install.c's loader entry
 * uses "init=/bin/cixd"), so there is no "restart the daemon" to
 * pick up a new bind address or port; this closes the old listening
 * socket and opens a new one in-process instead. Already-accept()ed
 * connections (a separate fd from the listening socket) are completely
 * unaffected -- the request that triggered this rebind (e.g. PUT
 * /v1/system/daemon-config) finishes normally over its own connection.
 *
 * Ordering matters: the new socket is created and added to epoll
 * *before* the old one is torn down, so any failure rolls back to the
 * still-working old listener -- this daemon must never be left with
 * zero listeners, even transiently. A no-op (new == current) is
 * detected up front rather than relying on SO_REUSEADDR semantics for
 * an identical rebind.
 */
/*
 * Move ONE listener to a new address:port. The only implementation
 * (#454).
 *
 * There used to be two of these, byte-identical apart from which conn
 * they touched and which global they compared against -- and the
 * comparison is the whole bug. Both short-circuited on
 *
 *     strcmp(new_addr, g_bind_addr) == 0 && new_port == <that global>
 *
 * against a SHARED global rather than against the listener's own state.
 * On the management-address path that is wrong twice over: the caller
 * passes g_bind_addr itself, making the test strcmp(x, x) and therefore
 * always true; and the http rebind has already overwritten g_bind_addr
 * with the new address before the https rebind is attempted. So the
 * https listener was never rebound by a management address change. It
 * stayed bound to an address that had just been removed from the
 * interface, and only the next reboot -- which binds both from net.conf
 * -- repaired it. Measured on 192.168.15.95, 2026-09-13: after a live
 * .103 -> .95 move, http answered 200 on the new address and https
 * answered nothing on either.
 *
 * The short-circuit itself is load-bearing and stays: binding the same
 * tuple a second time while the existing listener is still open on it
 * fails with EADDRINUSE, and SO_REUSEADDR does not help (that covers a
 * TIME_WAIT teardown, not two simultaneously-open listeners). It just
 * has to be asked of the listener being moved, which is the only thing
 * that knows where it actually is.
 *
 * `what` names the listener in the log line and nothing else.
 */
static int rebind_listener_conn(struct conn *c, const char *what, const char *new_addr,
                                 int new_port)
{
	int new_fd;
	int old_fd;
	struct cix_epoll_event ev;

	if (strcmp(new_addr, c->listen_addr) == 0 && new_port == c->listen_port)
		return 0;

	new_fd = create_listen_socket(new_addr, new_port);
	if (new_fd < 0)
		return -1;

	old_fd = c->fd;
	c->fd = new_fd;
	memset(&ev, 0, sizeof(ev));
	ev.events = EPOLLIN;
	ev.data.ptr = c;
	if (cix_epoll_ctl(g_epfd, EPOLL_CTL_ADD, new_fd, &ev) != 0) {
		perror("rebind_listener_conn: epoll_ctl ADD");
		c->fd = old_fd;
		close(new_fd);
		return -1;
	}

	cix_epoll_ctl(g_epfd, EPOLL_CTL_DEL, old_fd, NULL);
	close(old_fd);

	snprintf(c->listen_addr, sizeof(c->listen_addr), "%s", new_addr);
	c->listen_port = new_port;

	printf("cixd rebound %s listener to %s:%d\n", what, new_addr, new_port);
	fflush(stdout);
	/*
	 * In the log store as well as on the console, for the same reason
	 * the startup "listening on ..." line exists: a console printf is
	 * unreadable from off the box, and where a daemon is listening is
	 * exactly the fact an operator needs when it has stopped answering.
	 */
	logstore_write("cixd", "info", "rebound %s listener to %s:%d", what, new_addr, new_port);
	return 0;
}

/*
 * The management HTTP listener. Also updates g_bind_addr/g_port, which
 * are the daemon's own notion of the address it is reachable on --
 * separate from where any single socket is bound, and read all over.
 */
static int rebind_listener(const char *new_bind_addr, int new_port)
{
	if (rebind_listener_conn(&g_listener_conn, "http", new_bind_addr, new_port) != 0)
		return -1;
	snprintf(g_bind_addr_buf, sizeof(g_bind_addr_buf), "%s", new_bind_addr);
	g_bind_addr = g_bind_addr_buf;
	g_port = new_port;
	return 0;
}

/* Best-effort, same "never block daemon startup" posture as every
 * other non-critical reconciliation step (cgroup_enable_io_
 * accounting(), swap_init()'s own swapon() retry) -- a test/dev
 * invocation, or a kernel with /dev/kmsg unreadable for any other
 * reason, simply never gets kernel-source log entries; every other
 * source (cixd's own diagnostics, the audit trail) is unaffected. */
/* Set while the default image's own C library install is in flight (#189). */
static int g_default_image_seed_pending;
static void report_default_image_seed_result(void);

/* Forward declaration -- defined further down beside the other reactor
 * registrations, which all sit after the startup helpers that use them. */
static void register_pkg_fetch_pidfd(pid_t pid, int pidfd, int chain_idx);
/* ADR-0278: defined next to the other pidfd handlers, used well above
 * them -- pkg.sync's completion is the first caller. */
static int helper_run(int (*work)(void *), void *work_arg, void (*done)(int, void *), void *ctx,
                      const char *what);

/* Gives the default image a C library if it has none and one can be
 * installed without building anything (#189, see pkg_seed_default_
 * image_libc()). Same "needs g_epfd, never block startup" posture as
 * the watches below: the install is asynchronous like any other, so
 * the box finishes booting and the image becomes runnable a moment
 * later rather than the daemon waiting on it.
 *
 * Silent on the ordinary path -- an image that already has a runtime
 * is the case on every boot after the first, and logging it would be
 * noise on every boot forever. */
static void start_default_image_libc_seed(void)
{
	pid_t pid;
	int pidfd, chain_idx;
	enum pkg_error perr = pkg_seed_default_image_libc(&pid, &pidfd, &chain_idx);

	if (perr == PKG_ERR_NOT_FOUND)
		return;
	if (perr != PKG_OK) {
		logstore_write("cixd", "error",
		               "could not give the default image \"%s\" a C library (%d) -- it has "
		               "none, so containers created from it will be refused until one is "
		               "installed",
		               PKG_DEFAULT_IMAGE, (int)perr);
		return;
	}
	register_pkg_fetch_pidfd(pid, pidfd, chain_idx);
	g_default_image_seed_pending = 1;
	logstore_write("cixd", "info",
	               "the default image \"%s\" had no C library -- installing %s into it",
	               PKG_DEFAULT_IMAGE, PKG_BASE_LIBC);
	/* Console too, not just the log store: this is a first boot, the
	 * log store is not reachable yet, and an operator watching a fresh
	 * install being made ready should see it happening. */
	printf("default image: no C library -- installing %s\n", PKG_BASE_LIBC);
	fflush(stdout);
}

/*
 * Says when the install above has actually landed, once.
 *
 * Called from the same place every other "a pkg job may have just
 * finished" follow-up runs, so it needs no completion hook of its own.
 * Checks the thing that actually matters -- the image can run something
 * now -- rather than a job status, which is the same reason the
 * container-create guard looks for a loader rather than a package name.
 */
static void report_default_image_seed_result(void)
{
	char version[IMAGE_VERSION_MAX];
	char rootfs[PATH_MAX];
	char loader[PATH_MAX];
	struct stat st;

	if (!g_default_image_seed_pending)
		return;
	if (image_current_version(PKG_DEFAULT_IMAGE, version, sizeof(version)) != IMAGE_OK)
		return;
	image_version_rootfs_path(PKG_DEFAULT_IMAGE, version, rootfs, sizeof(rootfs));
	snprintf(loader, sizeof(loader), "%s/%s", rootfs, PKG_IMAGE_LOADER_REL);
	if (stat(loader, &st) != 0) {
		char why[256];

		/* Still running -- unless it finished and failed, in which case
		 * saying so beats looking like a hang forever. */
		if (pkg_default_image_libc_failed(why, sizeof(why))) {
			g_default_image_seed_pending = 0;
			logstore_write("cixd", "error",
			               "default image \"%s\" has no C library: installing %s failed -- %s",
			               PKG_DEFAULT_IMAGE, PKG_BASE_LIBC, why);
			printf("default image: installing %s FAILED -- %s\n", PKG_BASE_LIBC, why);
			fflush(stdout);
		}
		return;
	}
	g_default_image_seed_pending = 0;
	/*
	 * On disk before it is announced. btrfs commits on its own schedule
	 * (~30s), and this is a first boot: the machine may well be powered
	 * off moments after being told the image is ready, and losing a
	 * freshly materialized default image to that would be the same
	 * "reported success, produced nothing" failure this project keeps
	 * having to fix. Costs one sync, once, on the only boot that does
	 * this work.
	 */
	sync();
	logstore_write("cixd", "info", "default image \"%s\" is ready -- %s installed",
	               PKG_DEFAULT_IMAGE, PKG_BASE_LIBC);
	printf("default image: ready\n");
	fflush(stdout);
}

static void start_kmsg_watch(void)
{
	struct cix_epoll_event ev;
	int fd = logstore_kmsg_fd();

	if (fd < 0)
		return;
	g_kmsg_conn.kind = CONN_KMSG;
	g_kmsg_conn.fd = fd;
	memset(&ev, 0, sizeof(ev));
	ev.events = EPOLLIN;
	ev.data.ptr = &g_kmsg_conn;
	if (cix_epoll_ctl(g_epfd, EPOLL_CTL_ADD, fd, &ev) != 0)
		g_kmsg_conn.fd = -1;
}

static void handle_kmsg_event(struct conn *cc)
{
	(void)cc;
	logstore_kmsg_readable();
}

/* Forward declarations -- real definitions live alongside the manual
 * POST/DELETE /v1/containers/{name}/devices handlers further down
 * (ADR-0161 Phase D), needed here already since Phase C's hotplug
 * reconciliation (below) is just another caller of the same live-
 * attach/detach primitives those handlers use. */
static int live_mknod_device(const struct registry_entry *e, const struct device_spec *dev);
static int live_unlink_device(const struct registry_entry *e, const char *dev_path);
static int live_attach_one_device(struct registry_entry *e, const struct discovered_device *dd,
                                   int shared);

/*
 * ADR-0161 Phase C: a persistent NETLINK_KOBJECT_UEVENT multicast
 * socket, registered with the daemon's own epoll reactor once at
 * startup -- modeled on start_kmsg_watch()'s own async-registration
 * shape (never registered with epoll before), not rtnetlink.c's
 * synchronous open/request/close one, which this genuinely isn't:
 * kernel uevents arrive whenever real hardware changes, with no
 * request/response pairing at all. Best-effort, same posture as
 * start_kmsg_watch(): a kernel/sandbox with no CAP_NET_ADMIN, or one
 * that otherwise can't bind this socket, simply never gets hotplug
 * reactions -- every other capability this daemon has is unaffected.
 */
static void start_uevent_watch(void)
{
	struct cix_epoll_event ev;
	int fd;
	struct sockaddr_nl addr;

	fd = socket(AF_NETLINK, SOCK_RAW | SOCK_CLOEXEC, NETLINK_KOBJECT_UEVENT);
	if (fd < 0)
		return;

	memset(&addr, 0, sizeof(addr));
	addr.nl_family = AF_NETLINK;
	addr.nl_groups = 1; /* kernel events multicast group */

	if (bind(fd, (struct sockaddr *)&addr, sizeof(addr)) != 0) {
		close(fd);
		return;
	}

	g_uevent_conn.kind = CONN_UEVENT;
	g_uevent_conn.fd = fd;
	memset(&ev, 0, sizeof(ev));
	ev.events = EPOLLIN;
	ev.data.ptr = &g_uevent_conn;
	if (cix_epoll_ctl(g_epfd, EPOLL_CTL_ADD, fd, &ev) != 0) {
		close(fd);
		g_uevent_conn.fd = -1;
	}
}

/*
 * ADR-0161 Phase B/C: for every running container's own pending_
 * devices[] (an "optional": true devices[] reference that didn't
 * resolve at creation time), re-attempts resolution now that a real
 * hotplug event just fired. Contention (resolved decision): if more
 * than one running container's own pending reference resolves to the
 * SAME device, neither gets it -- logged, not silently arbitrated by
 * registry scan order. A device this pass successfully grants is
 * removed from the winning container's own pending list; every other
 * pending reference (no match, or lost a contention) is left in place
 * for the next hotplug event to retry.
 */
struct pending_device_claim {
	struct registry_entry *e;
	char ref[96];
	char resolved_id[96];
};

static void reconcile_pending_device_attachments(void)
{
	char names[REGISTRY_MAX_CONTAINERS][REGISTRY_NAME_MAX];
	int ncount = registry_list_names(names, REGISTRY_MAX_CONTAINERS);
	static struct pending_device_claim claims[REGISTRY_MAX_CONTAINERS * CONTAINER_MAX_DEVICES];
	int claim_count = 0;
	int i, j;

	for (i = 0; i < ncount; i++) {
		struct registry_entry *e = registry_find(names[i]);

		if (e == NULL || !e->running || e->pending_device_count == 0)
			continue;
		for (j = 0; j < e->pending_device_count; j++) {
			const struct discovered_device *matches[1];
			int n;

			n = devicemap_resolve(e->pending_devices[j], CONTAINERS_DIR, matches, 1);
			if (n < 0)
				n = device_find_group(e->pending_devices[j], CONTAINERS_DIR, matches, 1);
			if (n <= 0 || !matches[0]->assignable)
				continue;
			if (claim_count >= (int)(sizeof(claims) / sizeof(claims[0])))
				continue;
			claims[claim_count].e = e;
			snprintf(claims[claim_count].ref, sizeof(claims[claim_count].ref), "%s",
			         e->pending_devices[j]);
			snprintf(claims[claim_count].resolved_id, sizeof(claims[claim_count].resolved_id), "%s",
			         matches[0]->id);
			claim_count++;
		}
	}

	for (i = 0; i < claim_count; i++) {
		int contenders = 0;
		const struct discovered_device *dd;

		for (j = 0; j < claim_count; j++) {
			if (strcmp(claims[i].resolved_id, claims[j].resolved_id) == 0)
				contenders++;
		}
		if (contenders > 1) {
			/* Logged once per losing claim, not once per contending
			 * pair -- a real operator-visible signal without becoming
			 * noisy for a device with many contenders. */
			logstore_write("cixd", "warning",
			                "container %s: hotplugged device %s matches \"%s\" but another "
			                "running container also claims it -- granted to neither",
			                claims[i].e->name, claims[i].resolved_id, claims[i].ref);
			continue;
		}

		dd = device_find(claims[i].resolved_id, CONTAINERS_DIR);
		if (dd == NULL)
			continue; /* raced with another unplug between resolve and here */

		/*
		 * #356: a pending grant reconciled by a hotplug event is not
		 * shared. The container named a device that did not resolve at
		 * creation time and said nothing about sharing, and silence
		 * reads as exclusive here exactly as it does on the create
		 * path. The contention rule above already refuses to hand one
		 * device to two claimants, so this is the same answer stated
		 * once more where the grant is actually recorded.
		 */
		if (live_attach_one_device(claims[i].e, dd, 0) == 0) {
			registry_clear_pending_device(claims[i].e, claims[i].ref);
			logstore_write("cixd", "info",
			                "container %s: hotplug live-attached device %s (matched \"%s\")",
			                claims[i].e->name, dd->id, claims[i].ref);
		} else {
			logstore_write("cixd", "error",
			                "container %s: hotplug live-attach of %s (matched \"%s\") failed: %s",
			                claims[i].e->name, dd->id, claims[i].ref, strerror(errno));
		}
	}
}

/*
 * ADR-0161 Phase C: symmetric unplug reaction -- for every running
 * container's own currently-granted devices[], checks whether the
 * underlying host device can still be found at all; a device whose
 * hardware just disappeared has its grant actively revoked (BPF
 * program updated, /dev node unlinked), never left in place as an
 * inert grant for hardware that no longer exists. Applies to EVERY
 * grant regardless of how it was originally made (create-time or
 * live) -- unlike the operator-facing DELETE endpoint, which refuses
 * to touch a create-time grant, a physical unplug is not an operator
 * request and revokes it either way; registry_device_live_detach()
 * itself carries no such restriction (see its own header comment).
 */
static void reconcile_live_device_revocations(void)
{
	char names[REGISTRY_MAX_CONTAINERS][REGISTRY_NAME_MAX];
	int ncount = registry_list_names(names, REGISTRY_MAX_CONTAINERS);
	int i, j;

	for (i = 0; i < ncount; i++) {
		struct registry_entry *e = registry_find(names[i]);

		if (e == NULL || !e->running)
			continue;
		/* Iterated backward: registry_device_live_detach() shifts
		 * later entries down by one on every successful removal, so a
		 * forward scan would skip the entry that just slid into the
		 * current index. */
		for (j = e->device_count - 1; j >= 0; j--) {
			char id_copy[96];
			struct registry_device_attachment removed;

			if (device_find(e->devices[j].id, CONTAINERS_DIR) != NULL)
				continue;

			snprintf(id_copy, sizeof(id_copy), "%s", e->devices[j].id);
			if (registry_device_live_detach(e, id_copy, &removed) != 0) {
				logstore_write("cixd", "error",
				                "container %s: failed to revoke unplugged device %s: %s",
				                e->name, id_copy, strerror(errno));
				continue;
			}
			live_unlink_device(e, removed.dev_path);
			logstore_write("cixd", "info",
			                "container %s: revoked grant for unplugged device %s", e->name,
			                id_copy);
		}
	}
}

/*
 * ADR-0161 Phase C: one datagram is one uevent -- a NUL-separated
 * "KEY=VALUE" list, first line the summary ("add@/devices/.../3-3"),
 * every line after it a real KEY=VALUE env var (ACTION=, SUBSYSTEM=,
 * DEVPATH=, ...). Filtered to SUBSYSTEM=usb and a whole-device DEVPATH
 * only (trailing path component containing no ':' -- the identical
 * rule device.c's own usb_name_is_device() applies to its sysfs walk,
 * inlined here rather than exported across modules for one line of
 * logic) -- an interface-level uevent for the same physical device is
 * deliberately ignored, matching the whole-device passthrough model.
 * Deliberately does NOT try to derive the specific device's own
 * stable id (vendor/product/serial) from the uevent payload itself --
 * real hardware doesn't populate those fields identically across
 * every device class, and this daemon already has a robust, fresh way
 * to discover exactly that (device.c's own sysfs walk). The uevent is
 * treated purely as a trigger ("something USB just changed, go
 * recheck"), not as a source of device identity.
 */
static void handle_uevent_event(struct conn *cc)
{
	char buf[2048];
	ssize_t n;
	int is_add = 0, is_remove = 0, is_usb = 0, is_whole_device = 0;
	size_t off;

	n = recv(cc->fd, buf, sizeof(buf) - 1, 0);
	if (n <= 0)
		return;
	buf[n] = '\0';

	for (off = 0; off < (size_t)n;) {
		const char *line = buf + off;
		size_t line_len = strlen(line);

		if (strncmp(line, "ACTION=", 7) == 0) {
			is_add = strcmp(line + 7, "add") == 0;
			is_remove = strcmp(line + 7, "remove") == 0;
		} else if (strncmp(line, "SUBSYSTEM=", 10) == 0) {
			is_usb = strcmp(line + 10, "usb") == 0;
		} else if (strncmp(line, "DEVPATH=", 8) == 0) {
			const char *base = strrchr(line + 8, '/');

			base = (base != NULL) ? base + 1 : line + 8;
			is_whole_device = strchr(base, ':') == NULL;
		}
		off += line_len + 1;
	}

	if (!is_usb || !is_whole_device || (!is_add && !is_remove))
		return;

	if (is_add)
		reconcile_pending_device_attachments();
	else
		reconcile_live_device_revocations();
}

/*
 * Takes the conn to own the socket, so the loopback listeners (always
 * present -- see cixd_main()) use this same implementation rather than a
 * second copy of it. The accept path dispatches on conn->kind, never on
 * which global it is, so an additional listener needs nothing else.
 */
static int start_http_listener(struct conn *c, const char *bind_addr, int port)
{
	struct cix_epoll_event ev;
	int fd = create_listen_socket(bind_addr, port);

	if (fd < 0)
		return -1;
	c->kind = CONN_LISTENER;
	c->fd = fd;
	memset(&ev, 0, sizeof(ev));
	ev.events = EPOLLIN;
	ev.data.ptr = c;
	if (cix_epoll_ctl(g_epfd, EPOLL_CTL_ADD, fd, &ev) != 0) {
		perror("start_http_listener: epoll_ctl ADD");
		close(fd);
		c->fd = -1;
		return -1;
	}
	/*
	 * #454: a listener records where it actually is, so a later rebind
	 * can ask IT rather than a shared global that another path may have
	 * already moved.
	 */
	snprintf(c->listen_addr, sizeof(c->listen_addr), "%s", bind_addr);
	c->listen_port = port;
	printf("cixd listening on %s:%d\n", bind_addr, port);
	fflush(stdout);
	return 0;
}

static void stop_http_listener(void)
{
	if (g_listener_conn.fd < 0)
		return;
	cix_epoll_ctl(g_epfd, EPOLL_CTL_DEL, g_listener_conn.fd, NULL);
	close(g_listener_conn.fd);
	g_listener_conn.fd = -1;
	/* #454: nowhere, not "still where it last was" -- a stale record
	 * here would make a later rebind short-circuit into doing nothing,
	 * which is the exact failure this field exists to prevent. */
	g_listener_conn.listen_addr[0] = '\0';
	g_listener_conn.listen_port = 0;
}

/*
 * The four HTTPS listener lifecycle operations (Part 0.5), mirroring
 * the plain-HTTP ones above -- start/stop/rebind, plus create_tls_ctx()
 * itself for the cert-loading half. g_tls_ctx, once successfully
 * built, is deliberately kept alive across a later stop/restart cycle
 * (stop_https_listener() only tears down the socket) -- re-enabling
 * HTTPS doesn't need to re-read the host cert off disk every time.
 */
static int start_https_listener(struct conn *c, const char *bind_addr, int port)
{
	struct cix_epoll_event ev;
	int fd;

	if (g_tls_ctx == NULL) {
		g_tls_ctx = create_tls_ctx();
		if (g_tls_ctx == NULL)
			return -1;
	}
	fd = create_listen_socket(bind_addr, port);
	if (fd < 0)
		return -1;

	c->kind = CONN_LISTENER_TLS;
	c->fd = fd;
	memset(&ev, 0, sizeof(ev));
	ev.events = EPOLLIN;
	ev.data.ptr = c;
	if (cix_epoll_ctl(g_epfd, EPOLL_CTL_ADD, fd, &ev) != 0) {
		perror("start_https_listener: epoll_ctl ADD");
		close(fd);
		c->fd = -1;
		return -1;
	}
	/* #454 -- see start_http_listener() and rebind_listener_conn(). */
	snprintf(c->listen_addr, sizeof(c->listen_addr), "%s", bind_addr);
	c->listen_port = port;
	printf("cixd listening (https) on %s:%d\n", bind_addr, port);
	fflush(stdout);
	return 0;
}

static void stop_https_listener(void)
{
	if (g_https_listener_conn.fd < 0)
		return;
	cix_epoll_ctl(g_epfd, EPOLL_CTL_DEL, g_https_listener_conn.fd, NULL);
	close(g_https_listener_conn.fd);
	g_https_listener_conn.fd = -1;
	/* #454, as in stop_http_listener(): a stopped listener is nowhere,
	 * and a stale record would make a later rebind decide it had
	 * nothing to do. */
	g_https_listener_conn.listen_addr[0] = '\0';
	g_https_listener_conn.listen_port = 0;
}

/*
 * Starts whichever listeners the config enables, at one address.
 * Returns 0 if at least one came up, -1 if none did -- the caller
 * decides whether that is fatal or a reason to fall back.
 *
 * Both are attempted even when the first fails: an HTTPS-only box (no
 * host certificate yet is the common case for HTTP-only, but the
 * reverse is a real configuration) must not be judged unreachable
 * because the listener it does not use refused to start.
 */
static int start_listeners(struct conn *http, struct conn *https, const char *addr, int port)
{
	if (daemon_config_http_enabled() && start_http_listener(http, addr, port) != 0)
		fprintf(stderr, "could not start the HTTP listener on %s:%d\n", addr, port);
	if (daemon_config_https_enabled() &&
	    start_https_listener(https, addr, daemon_config_https_port()) != 0)
		fprintf(stderr, "could not start the HTTPS listener on %s:%d\n", addr,
		        daemon_config_https_port());
	return (http->fd >= 0 || https->fd >= 0) ? 0 : -1;
}

static int rebind_https_listener(const char *new_bind_addr, int new_port)
{
	return rebind_listener_conn(&g_https_listener_conn, "https", new_bind_addr, new_port);
}

/*
 * Deferred rtnl_addr_del_ipv4() of a stale bind_ip (ADR-0068), arm'd by
 * handle_daemon_config_put() below instead of deleting synchronously --
 * a real hazard was confirmed the hard way, not assumed: when the very
 * connection carrying the PUT request that clears/replaces bind_ip has
 * that address as its own local endpoint (the common case, since an
 * operator naturally reaches the daemon at whatever it's currently
 * bound to), the response write() succeeds at the socket-buffer level
 * but the address disappearing before the kernel actually transmits it
 * leaves the client hanging forever, never receiving bytes that were
 * already "successfully" written. A short, fixed delay -- long enough
 * for a same-host TCP round trip under any real scheduler load, utterly
 * negligible for a background bridge address cleanup that has no
 * user-visible deadline -- sidesteps the whole class of problem without
 * needing to reason about exact ACK timing. Same one-shot timerfd +
 * conn shape as arm_restart_timer() (below, container restart/backoff)
 * uses -- this codebase's own existing precedent for "do something
 * shortly after, without blocking the event loop."
 */
#define BIND_IP_CLEANUP_DELAY_SECONDS 2

static void arm_bind_ip_cleanup_timer(const char *ifname, uint32_t addr_be, int prefix_len)
{
	int tfd;
	struct itimerspec its;
	struct conn *cc;
	struct cix_epoll_event ev;

	tfd = timerfd_create(CLOCK_MONOTONIC, TFD_NONBLOCK | TFD_CLOEXEC);
	if (tfd < 0) {
		perror("timerfd_create (bind_ip cleanup)");
		return;
	}

	memset(&its, 0, sizeof(its));
	its.it_value.tv_sec = BIND_IP_CLEANUP_DELAY_SECONDS;
	if (timerfd_settime(tfd, 0, &its, NULL) != 0) {
		perror("timerfd_settime (bind_ip cleanup)");
		close(tfd);
		return;
	}

	cc = calloc(1, sizeof(*cc));
	if (cc == NULL) {
		perror("malloc (bind_ip cleanup timer conn)");
		close(tfd);
		return;
	}
	cc->kind = CONN_BIND_IP_CLEANUP;
	cc->fd = tfd;
	snprintf(cc->cleanup_ifname, sizeof(cc->cleanup_ifname), "%s", ifname);
	cc->cleanup_addr_be = addr_be;
	cc->cleanup_prefix_len = prefix_len;

	memset(&ev, 0, sizeof(ev));
	ev.events = EPOLLIN;
	ev.data.ptr = cc;
	if (cix_epoll_ctl(g_epfd, EPOLL_CTL_ADD, tfd, &ev) != 0) {
		perror("epoll_ctl ADD bind_ip cleanup timer");
		close(tfd);
		free(cc);
	}
}

static void handle_bind_ip_cleanup_timer_event(struct conn *cc)
{
	uint64_t expirations;
	int rtfd;

	if (read(cc->fd, &expirations, sizeof(expirations)) < 0)
		perror("read (bind_ip cleanup timerfd)");

	cix_epoll_ctl(g_epfd, EPOLL_CTL_DEL, cc->fd, NULL);
	close(cc->fd);

	rtfd = rtnl_open();
	if (rtfd >= 0) {
		rtnl_addr_del_ipv4(rtfd, cc->cleanup_ifname, cc->cleanup_addr_be, cc->cleanup_prefix_len);
		rtnl_close(rtfd);
	}
	/* Best-effort, same as before this became a deferred timer: a
	 * failure here leaves a harmless leftover address on the bridge,
	 * never persisted or bound to by cixd itself. */

	free(cc);
}

/*
 * GET/POST /v1/system/ping (task #679-681): a real ICMP echo, backed
 * by ping.c's own raw-socket mechanics. Two fds are in flight for one
 * logical job -- the raw socket (an echo reply arriving) and a
 * timerfd (the timeout) -- whichever fires first resolves the job and
 * tears down BOTH. Same batch-safety hazard console_session_teardown()
 * already solves (both could be EPOLLIN-ready in the same epoll_wait()
 * batch): torn-down conns are marked CONN_DEAD and queued via
 * queue_conn_free(), never free()'d directly.
 */
#define PING_TIMEOUT_MS 2000

static struct conn *g_ping_sock_conn;
static struct conn *g_ping_timer_conn;

static void ping_job_teardown(void)
{
	if (g_ping_sock_conn != NULL) {
		cix_epoll_ctl(g_epfd, EPOLL_CTL_DEL, g_ping_sock_conn->fd, NULL);
		close(g_ping_sock_conn->fd);
		g_ping_sock_conn->kind = CONN_DEAD;
		queue_conn_free(g_ping_sock_conn);
		g_ping_sock_conn = NULL;
	}
	if (g_ping_timer_conn != NULL) {
		cix_epoll_ctl(g_epfd, EPOLL_CTL_DEL, g_ping_timer_conn->fd, NULL);
		close(g_ping_timer_conn->fd);
		g_ping_timer_conn->kind = CONN_DEAD;
		queue_conn_free(g_ping_timer_conn);
		g_ping_timer_conn = NULL;
	}
}

static void handle_ping_socket_event(struct conn *cc)
{
	if (ping_handle_reply(cc->fd))
		ping_job_teardown();
}

static void handle_ping_timer_event(struct conn *cc)
{
	uint64_t expirations;

	if (read(cc->fd, &expirations, sizeof(expirations)) < 0)
		perror("read (ping timerfd)");
	ping_handle_timeout();
	ping_job_teardown();
}

/* Body: {"host": "A.B.C.D"}. 202 with the job's initial (pending)
 * status; GET on the same path polls it, same "kick off + poll"
 * shape as disks format/ISO build/every other uncertain-duration job
 * in this daemon. */
static void handle_ping_post(int fd, const char *body, size_t body_len)
{
	struct json_value *root;
	const char *host_str;
	struct in_addr addr;
	int sockfd;
	enum ping_error perr;
	struct conn *sock_cc, *timer_cc;
	struct cix_epoll_event ev;
	int tfd;
	struct itimerspec its;
	struct json_writer w;

	root = json_parse(body, body_len);
	if (root == NULL) {
		respond_error(fd, 400, "Bad Request", "invalid JSON body");
		return;
	}
	host_str = json_as_string(json_object_get(root, "host"));
	if (host_str == NULL || inet_pton(AF_INET, host_str, &addr) != 1) {
		json_free(root);
		respond_error(fd, 400, "Bad Request", "host missing or not a valid IPv4 address");
		return;
	}
	json_free(root);

	perr = ping_start(addr.s_addr, &sockfd);
	if (perr == PING_ERR_BUSY) {
		respond_error(fd, 409, "Conflict", "another ping is already in flight");
		return;
	}
	if (perr != PING_OK) {
		respond_error(fd, 500, "Internal Server Error",
		              "could not send ICMP echo (raw socket failed -- CAP_NET_RAW?)");
		return;
	}

	tfd = timerfd_create(CLOCK_MONOTONIC, TFD_NONBLOCK | TFD_CLOEXEC);
	if (tfd < 0) {
		perror("timerfd_create (ping timeout)");
		close(sockfd);
		respond_error(fd, 500, "Internal Server Error", "could not arm ping timeout");
		return;
	}
	memset(&its, 0, sizeof(its));
	its.it_value.tv_sec = PING_TIMEOUT_MS / 1000;
	its.it_value.tv_nsec = (long)(PING_TIMEOUT_MS % 1000) * 1000000L;
	if (timerfd_settime(tfd, 0, &its, NULL) != 0) {
		perror("timerfd_settime (ping timeout)");
		close(tfd);
		close(sockfd);
		respond_error(fd, 500, "Internal Server Error", "could not arm ping timeout");
		return;
	}

	sock_cc = malloc(sizeof(*sock_cc));
	timer_cc = malloc(sizeof(*timer_cc));
	if (sock_cc == NULL || timer_cc == NULL) {
		perror("malloc (ping job conns)");
		free(sock_cc);
		free(timer_cc);
		close(tfd);
		close(sockfd);
		respond_error(fd, 500, "Internal Server Error", "out of memory");
		return;
	}
	sock_cc->kind = CONN_PING;
	sock_cc->fd = sockfd;
	timer_cc->kind = CONN_PING_TIMER;
	timer_cc->fd = tfd;

	memset(&ev, 0, sizeof(ev));
	ev.events = EPOLLIN;
	ev.data.ptr = sock_cc;
	if (cix_epoll_ctl(g_epfd, EPOLL_CTL_ADD, sockfd, &ev) != 0) {
		perror("epoll_ctl ADD ping socket");
		free(sock_cc);
		free(timer_cc);
		close(tfd);
		close(sockfd);
		respond_error(fd, 500, "Internal Server Error", "could not register ping socket");
		return;
	}
	ev.data.ptr = timer_cc;
	if (cix_epoll_ctl(g_epfd, EPOLL_CTL_ADD, tfd, &ev) != 0) {
		perror("epoll_ctl ADD ping timer");
		cix_epoll_ctl(g_epfd, EPOLL_CTL_DEL, sockfd, NULL);
		free(sock_cc);
		free(timer_cc);
		close(tfd);
		close(sockfd);
		respond_error(fd, 500, "Internal Server Error", "could not register ping timeout");
		return;
	}

	g_ping_sock_conn = sock_cc;
	g_ping_timer_conn = timer_cc;

	jw_init(&w);
	ping_write_json_status(&w);
	respond_json(fd, 202, "Accepted", &w);
	jw_free(&w);
}

static void handle_ping_get(int fd)
{
	struct json_writer w;

	jw_init(&w);
	ping_write_json_status(&w);
	respond_json(fd, 200, "OK", &w);
	jw_free(&w);
}

/*
 * NTP sync job (task #751-755): one in-flight SNTP attempt, mirroring
 * ping's own two-fd (socket + timeout) shape above -- the one real
 * difference is ntp.c's own candidate-retry logic means a timeout can
 * result in "move to the next candidate, re-arm the SAME timer" rather
 * than always tearing down (see arm_ntp_timeout_timer() below).
 */
#define NTP_SYNC_INTERVAL_SEC (60 * 60) /* re-sync hourly once a sync mechanism exists at all */

static struct conn *g_ntp_sync_conn;
static struct conn *g_ntp_timer_conn;
static struct conn g_ntp_periodic_conn; /* permanent -- registered once at startup */
static struct conn g_boot_confirm_conn = { .fd = -1 };
static char g_boot_confirm_slot[8];
static int g_boot_confirm_attempts;

/*
 * Twelve attempts at ten seconds. A NIC driver loading late is the
 * benign case this window exists for (the uevent watch may bring the
 * interface up seconds after boot_init ran); two minutes is long enough
 * for that and short enough that a genuinely dead slot falls back while
 * someone is still watching the console.
 */
#define BOOT_CONFIRM_RETRY_SECONDS 10
#define BOOT_CONFIRM_MAX_ATTEMPTS 12

static struct conn g_build_stall_conn;  /* permanent -- registered once at startup */

static void ntp_job_teardown(void)
{
	if (g_ntp_sync_conn != NULL) {
		cix_epoll_ctl(g_epfd, EPOLL_CTL_DEL, g_ntp_sync_conn->fd, NULL);
		close(g_ntp_sync_conn->fd);
		g_ntp_sync_conn->kind = CONN_DEAD;
		queue_conn_free(g_ntp_sync_conn);
		g_ntp_sync_conn = NULL;
	}
	if (g_ntp_timer_conn != NULL) {
		cix_epoll_ctl(g_epfd, EPOLL_CTL_DEL, g_ntp_timer_conn->fd, NULL);
		close(g_ntp_timer_conn->fd);
		g_ntp_timer_conn->kind = CONN_DEAD;
		queue_conn_free(g_ntp_timer_conn);
		g_ntp_timer_conn = NULL;
	}
}

/* Re-arms g_ntp_timer_conn's own timerfd for the next candidate --
 * reused (not recreated) across every candidate in one sync attempt,
 * unlike ping's own always-one-shot timer. */
static int arm_ntp_timeout_timer(void)
{
	struct itimerspec its;

	if (g_ntp_timer_conn == NULL)
		return -1;
	memset(&its, 0, sizeof(its));
	its.it_value.tv_sec = NTP_SYNC_TIMEOUT_MS / 1000;
	its.it_value.tv_nsec = (long)(NTP_SYNC_TIMEOUT_MS % 1000) * 1000000L;
	return timerfd_settime(g_ntp_timer_conn->fd, 0, &its, NULL);
}

static void handle_ntp_sync_socket_event(struct conn *cc)
{
	if (ntp_sync_handle_reply(cc->fd)) {
		ntp_job_teardown();
		return;
	}
	if (arm_ntp_timeout_timer() != 0) {
		perror("timerfd_settime (ntp sync re-arm)");
		ntp_job_teardown();
	}
}

static void handle_ntp_sync_timer_event(struct conn *cc)
{
	uint64_t expirations;

	if (read(cc->fd, &expirations, sizeof(expirations)) < 0)
		perror("read (ntp sync timerfd)");
	if (ntp_sync_handle_timeout(g_ntp_sync_conn != NULL ? g_ntp_sync_conn->fd : -1)) {
		ntp_job_teardown();
		return;
	}
	if (arm_ntp_timeout_timer() != 0) {
		perror("timerfd_settime (ntp sync re-arm)");
		ntp_job_teardown();
	}
}

/* Kicks off one sync attempt if none is currently in flight. Returns
 * the outcome so callers can distinguish "started" from "nothing to
 * do" -- the periodic timer (best-effort, ignores the return value:
 * NTP_START_BUSY/NTP_START_NO_CANDIDATES are the common,
 * nothing-configured-yet case, not a real error, and the next fire
 * tries again regardless) vs. the manual POST /v1/system/ntp/sync
 * trigger below, which does report it to the caller. */
static enum ntp_start_error start_ntp_sync_job(void)
{
	int sockfd;
	enum ntp_start_error serr;
	struct conn *sock_cc, *timer_cc;
	struct cix_epoll_event ev;
	int tfd;
	struct itimerspec its;

	serr = ntp_sync_start(&sockfd);
	if (serr != NTP_START_OK)
		return serr;

	tfd = timerfd_create(CLOCK_MONOTONIC, TFD_NONBLOCK | TFD_CLOEXEC);
	if (tfd < 0) {
		perror("timerfd_create (ntp sync timeout)");
		close(sockfd);
		return NTP_START_SOCKET_FAILED;
	}
	memset(&its, 0, sizeof(its));
	its.it_value.tv_sec = NTP_SYNC_TIMEOUT_MS / 1000;
	its.it_value.tv_nsec = (long)(NTP_SYNC_TIMEOUT_MS % 1000) * 1000000L;
	if (timerfd_settime(tfd, 0, &its, NULL) != 0) {
		perror("timerfd_settime (ntp sync timeout)");
		close(tfd);
		close(sockfd);
		return NTP_START_SOCKET_FAILED;
	}

	sock_cc = malloc(sizeof(*sock_cc));
	timer_cc = malloc(sizeof(*timer_cc));
	if (sock_cc == NULL || timer_cc == NULL) {
		perror("malloc (ntp sync job conns)");
		free(sock_cc);
		free(timer_cc);
		close(tfd);
		close(sockfd);
		return NTP_START_SOCKET_FAILED;
	}
	sock_cc->kind = CONN_NTP_SYNC;
	sock_cc->fd = sockfd;
	timer_cc->kind = CONN_NTP_SYNC_TIMER;
	timer_cc->fd = tfd;

	memset(&ev, 0, sizeof(ev));
	ev.events = EPOLLIN;
	ev.data.ptr = sock_cc;
	if (cix_epoll_ctl(g_epfd, EPOLL_CTL_ADD, sockfd, &ev) != 0) {
		perror("epoll_ctl ADD ntp sync socket");
		free(sock_cc);
		free(timer_cc);
		close(tfd);
		close(sockfd);
		return NTP_START_SOCKET_FAILED;
	}
	ev.data.ptr = timer_cc;
	if (cix_epoll_ctl(g_epfd, EPOLL_CTL_ADD, tfd, &ev) != 0) {
		perror("epoll_ctl ADD ntp sync timer");
		cix_epoll_ctl(g_epfd, EPOLL_CTL_DEL, sockfd, NULL);
		free(sock_cc);
		free(timer_cc);
		close(tfd);
		close(sockfd);
		return NTP_START_SOCKET_FAILED;
	}

	g_ntp_sync_conn = sock_cc;
	g_ntp_timer_conn = timer_cc;
	return NTP_START_OK;
}

/* Permanent, re-arming itself every NTP_SYNC_INTERVAL_SEC -- the
 * "schedule the next one-shot fire on completion" idiom this daemon
 * already uses everywhere else (e.g. the console-respawn timer),
 * rather than a genuinely recurring timerfd (it_interval) -- this
 * codebase has no precedent for the latter yet, and re-arming keeps
 * this consistent with every other timer here. */
static void arm_ntp_periodic_timer(void)
{
	struct itimerspec its;

	memset(&its, 0, sizeof(its));
	its.it_value.tv_sec = NTP_SYNC_INTERVAL_SEC;
	if (timerfd_settime(g_ntp_periodic_conn.fd, 0, &its, NULL) != 0)
		perror("timerfd_settime (ntp periodic re-arm)");
}

static void handle_ntp_periodic_timer_event(struct conn *cc)
{
	uint64_t expirations;

	if (read(cc->fd, &expirations, sizeof(expirations)) < 0)
		perror("read (ntp periodic timerfd)");
	start_ntp_sync_job();
	arm_ntp_periodic_timer();
}

/* Best-effort, same "never block daemon startup" posture as start_
 * kmsg_watch() above -- a timerfd_create() failure here just means no
 * automatic sync ever happens; GET/PUT /v1/system/ntp and /v1/ntp/
 * servers remain fully usable regardless. */
/* ---- Issue #81: registered-server health probing ---- */

/*
 * How often a full probe sweep runs. 30s is a deliberate middle ground:
 * fast enough that a dead directory server is noticed long before an
 * operator finishes reading a failed login, slow enough that four
 * subsystems' worth of probes never become their own load.
 */
#define SERVERHEALTH_SWEEP_SECONDS 30
/*
 * A probe that has neither connected nor been refused within this long
 * counts as failed. Kept well under the sweep interval so a sweep can
 * never overlap the previous one's stragglers.
 */
#define SERVERHEALTH_PROBE_TIMEOUT_SECONDS 5

static struct conn g_serverhealth_timer_conn;

/*
 * The one place that says what "probing" means for each kind. Adding a
 * fifth registered-server subsystem means adding a row here, nothing
 * else -- the record, the state machine and the whole REST/CLI/web
 * surface are already shared.
 *
 * port == 0 means this kind has no TCP service to connect to (NTP and
 * syslog are UDP, and a TCP connect against them would be a meaningless
 * check dressed up as a real one). Those fall back to container
 * liveness, and the record's own `probe` field reports "process" so an
 * operator can see exactly how much the verdict is worth.
 */
struct serverhealth_kind_spec {
	const char *kind;
	int port;
	/* Non-NULL when the port is not a constant: the LDAP service moves
	 * between its plaintext and TLS ports with ldap/config's own
	 * client_tls (#416), and a probe fixed at the plaintext port went
	 * on testing it after ldap-1/ldap-2 1.6.0 stopped serving it --
	 * both servers reporting "connect: Connection refused" against a
	 * door that had been deliberately closed. Consulted per sweep
	 * rather than cached, since the setting is API-changeable while
	 * the daemon runs. `port` is the fallback and stays meaningful:
	 * 0 still means "no TCP service to probe". */
	int (*port_now)(void);
	int (*list)(char out[][REGISTRY_NAME_MAX], int max);
};

static int serverhealth_list_ldap(char out[][REGISTRY_NAME_MAX], int max)
{
	return ldap_server_list_containers(out, max);
}
static int serverhealth_list_dns(char out[][REGISTRY_NAME_MAX], int max)
{
	return dns_server_list_containers(out, max);
}
static int serverhealth_list_ntp(char out[][REGISTRY_NAME_MAX], int max)
{
	return ntp_server_list_containers(out, max);
}
static int serverhealth_list_syslog(char out[][REGISTRY_NAME_MAX], int max)
{
	return syslogfwd_target_list_containers(out, max);
}

static const struct serverhealth_kind_spec g_serverhealth_kinds[] = {
	{ "ldap", HOSTAUTH_LDAP_DEFAULT_PORT, ldap_client_port, serverhealth_list_ldap },
	{ "dns", 53, NULL, serverhealth_list_dns },
	{ "ntp", 0, NULL, serverhealth_list_ntp },
	{ "syslog", 0, NULL, serverhealth_list_syslog },
};

/*
 * In-flight probes, so a sweep can time out stragglers rather than
 * leaving them to the kernel's own multi-minute TCP timeout (which would
 * let sweeps pile up on an unreachable server). Bounded by the same cap
 * as the health table itself -- there can never be more probes in flight
 * than there are registered servers.
 */
static struct conn *g_serverhealth_inflight[SERVERHEALTH_MAX];

static void serverhealth_inflight_add(struct conn *cc)
{
	int i;

	for (i = 0; i < SERVERHEALTH_MAX; i++) {
		if (g_serverhealth_inflight[i] == NULL) {
			g_serverhealth_inflight[i] = cc;
			return;
		}
	}
}

static void serverhealth_inflight_remove(struct conn *cc)
{
	int i;

	for (i = 0; i < SERVERHEALTH_MAX; i++) {
		if (g_serverhealth_inflight[i] == cc)
			g_serverhealth_inflight[i] = NULL;
	}
}

static void serverhealth_probe_teardown(struct conn *cc)
{
	serverhealth_inflight_remove(cc);
	cix_epoll_ctl(g_epfd, EPOLL_CTL_DEL, cc->fd, NULL);
	close(cc->fd);
	free(cc);
}

/* Fails every probe that has been outstanding too long -- called at the
 * start of each sweep, so a hung server is recorded as failing rather
 * than silently accumulating sockets. */
static void serverhealth_reap_stale_probes(void)
{
	time_t now = time(NULL);
	int i;

	for (i = 0; i < SERVERHEALTH_MAX; i++) {
		struct conn *cc = g_serverhealth_inflight[i];

		if (cc == NULL)
			continue;
		if (now - cc->probe_started_at < SERVERHEALTH_PROBE_TIMEOUT_SECONDS)
			continue;
		serverhealth_record_result(cc->probe_kind, cc->probe_container, cc->probe_desc, 0,
		                            "probe timed out -- no response");
		serverhealth_probe_teardown(cc);
	}
}

/*
 * Resolves a registered server container's own management IP -- the same
 * "look up the registry entry fresh, never cache" resolution
 * ldap_effective_client_uri() already does. Returns 0 if the container
 * isn't running or has no address yet, which is itself a real answer:
 * a server that isn't up cannot be serving.
 */
static int serverhealth_resolve_ip(const char *container, char *out, size_t out_size)
{
	struct registry_entry *e = registry_find(container);
	struct in_addr a;

	if (e == NULL || !e->running || e->net_count == 0 || e->nets[0].ip_be == 0)
		return 0;
	a.s_addr = e->nets[0].ip_be;
	return inet_ntop(AF_INET, &a, out, (socklen_t)out_size) != NULL;
}

/*
 * Starts one non-blocking TCP probe. The connect() is expected to return
 * EINPROGRESS; the verdict is taken later, when the reactor reports the
 * socket writable (see handle_serverhealth_probe_event()). Nothing here
 * ever blocks.
 */
static void serverhealth_start_tcp_probe(const char *kind, const char *container, const char *ip,
                                          int port)
{
	struct sockaddr_in sa;
	struct conn *cc;
	struct cix_epoll_event ev;
	char desc[SERVERHEALTH_PROBE_MAX];
	int fd;

	snprintf(desc, sizeof(desc), "tcp:%d", port);
	fd = socket(AF_INET, SOCK_STREAM | SOCK_NONBLOCK | SOCK_CLOEXEC, 0);
	if (fd < 0) {
		serverhealth_record_result(kind, container, desc, 0, "socket() failed");
		return;
	}
	memset(&sa, 0, sizeof(sa));
	sa.sin_family = AF_INET;
	sa.sin_port = htons((uint16_t)port);
	if (inet_pton(AF_INET, ip, &sa.sin_addr) != 1) {
		close(fd);
		serverhealth_record_result(kind, container, desc, 0, "bad server address");
		return;
	}
	if (connect(fd, (struct sockaddr *)&sa, sizeof(sa)) != 0 && errno != EINPROGRESS) {
		char err[SERVERHEALTH_ERROR_MAX];

		snprintf(err, sizeof(err), "connect: %s", strerror(errno));
		close(fd);
		serverhealth_record_result(kind, container, desc, 0, err);
		return;
	}
	cc = calloc(1, sizeof(*cc));
	if (cc == NULL) {
		close(fd);
		return;
	}
	memset(cc, 0, sizeof(*cc));
	cc->kind = CONN_SERVERHEALTH_PROBE;
	cc->fd = fd;
	snprintf(cc->probe_kind, sizeof(cc->probe_kind), "%s", kind);
	snprintf(cc->probe_container, sizeof(cc->probe_container), "%s", container);
	snprintf(cc->probe_desc, sizeof(cc->probe_desc), "%s", desc);
	cc->probe_started_at = time(NULL);

	memset(&ev, 0, sizeof(ev));
	ev.events = EPOLLOUT;
	ev.data.ptr = cc;
	if (cix_epoll_ctl(g_epfd, EPOLL_CTL_ADD, fd, &ev) != 0) {
		close(fd);
		free(cc);
		serverhealth_record_result(kind, container, desc, 0, "epoll registration failed");
		return;
	}
	serverhealth_inflight_add(cc);
}

/* One sweep: every registered server of every kind, probed once. */
static void serverhealth_sweep(void)
{
	size_t k;

	serverhealth_reap_stale_probes();

	for (k = 0; k < sizeof(g_serverhealth_kinds) / sizeof(g_serverhealth_kinds[0]); k++) {
		const struct serverhealth_kind_spec *spec = &g_serverhealth_kinds[k];
		char names[SERVERHEALTH_MAX][REGISTRY_NAME_MAX];
		int count = spec->list(names, SERVERHEALTH_MAX);
		int port = spec->port_now != NULL ? spec->port_now() : spec->port;
		int i;

		for (i = 0; i < count; i++) {
			char ip[INET_ADDRSTRLEN];

			if (!serverhealth_resolve_ip(names[i], ip, sizeof(ip))) {
				serverhealth_record_result(spec->kind, names[i],
				                            port > 0 ? "tcp" : "process", 0,
				                            "container is not running, or has no address");
				continue;
			}
			if (port == 0) {
				/* UDP service: the honest check available without
				 * speaking its protocol is that its container is
				 * genuinely up, and the record says exactly that. */
				serverhealth_record_result(spec->kind, names[i], "process", 1, NULL);
				continue;
			}
			serverhealth_start_tcp_probe(spec->kind, names[i], ip, port);
		}
	}
}

static void arm_serverhealth_timer(void)
{
	struct itimerspec its;

	if (g_serverhealth_timer_conn.fd < 0)
		return;
	memset(&its, 0, sizeof(its));
	its.it_value.tv_sec = SERVERHEALTH_SWEEP_SECONDS;
	if (timerfd_settime(g_serverhealth_timer_conn.fd, 0, &its, NULL) != 0)
		perror("timerfd_settime (server health sweep re-arm)");
}

/* Best-effort, same posture as every other periodic timer here: failing
 * to create it means no automatic probing, never a failed startup. */
/*
 * Issue #86: keep cixd schedulable and un-killable under overload.
 * Best-effort by design -- see the call site's own comment. Reports what
 * it could not do rather than failing silently, so a real install where
 * one of these is unexpectedly denied is visible in the log.
 */
static void protect_control_plane(void)
{
	int fd;

	/*
	 * Strongly negative nice: ordinary workloads (containers, package
	 * builds) then cannot push the daemon off the run queue no matter how
	 * much CPU they collectively demand. -20 rather than something milder
	 * because there is nothing on the box whose latency matters more than
	 * the one interface an operator has.
	 */
	errno = 0;
	if (setpriority(PRIO_PROCESS, 0, -20) != 0 && errno != 0)
		fprintf(stderr, "control plane: could not raise scheduling priority: %s\n",
		        strerror(errno));

	/*
	 * And never be the OOM killer's choice. -1000 is the strongest
	 * available "do not kill this" hint; if the daemon is the thing that
	 * dies under memory pressure, the operator loses the box rather than
	 * a workload.
	 */
	fd = open("/proc/self/oom_score_adj", O_WRONLY);
	if (fd < 0) {
		fprintf(stderr, "control plane: could not open oom_score_adj: %s\n", strerror(errno));
		return;
	}
	if (write(fd, "-1000", 5) != 5)
		fprintf(stderr, "control plane: could not set oom_score_adj: %s\n", strerror(errno));
	close(fd);
}

static void start_serverhealth_timer(void)
{
	struct cix_epoll_event ev;
	int fd = timerfd_create(CLOCK_MONOTONIC, TFD_NONBLOCK | TFD_CLOEXEC);

	g_serverhealth_timer_conn.fd = -1;
	if (fd < 0) {
		perror("timerfd_create (server health)");
		return;
	}
	g_serverhealth_timer_conn.kind = CONN_SERVERHEALTH_TIMER;
	g_serverhealth_timer_conn.fd = fd;
	memset(&ev, 0, sizeof(ev));
	ev.events = EPOLLIN;
	ev.data.ptr = &g_serverhealth_timer_conn;
	if (cix_epoll_ctl(g_epfd, EPOLL_CTL_ADD, fd, &ev) != 0) {
		close(fd);
		g_serverhealth_timer_conn.fd = -1;
		return;
	}
	arm_serverhealth_timer();
}

/*
 * The probe socket became writable: SO_ERROR carries the real verdict.
 * 0 means the server accepted a connection -- a genuine service check,
 * not a guess. ECONNREFUSED and friends mean it is listening on nothing,
 * which is exactly the "registered but not serving" state this whole
 * mechanism exists to surface.
 */
static void handle_serverhealth_probe_event(struct conn *cc)
{
	int soerr = 0;
	socklen_t len = sizeof(soerr);

	if (getsockopt(cc->fd, SOL_SOCKET, SO_ERROR, &soerr, &len) != 0)
		soerr = errno;
	if (soerr == 0) {
		serverhealth_record_result(cc->probe_kind, cc->probe_container, cc->probe_desc, 1, NULL);
	} else {
		char err[SERVERHEALTH_ERROR_MAX];

		snprintf(err, sizeof(err), "connect: %s", strerror(soerr));
		serverhealth_record_result(cc->probe_kind, cc->probe_container, cc->probe_desc, 0, err);
	}
	serverhealth_probe_teardown(cc);
}

/*
 * How often to LOOK for a stalled build, not how long a build may be
 * quiet -- both live in pkg.c now, the interval derived from the
 * threshold so the two cannot disagree. This used to be a fixed minute
 * here, which quietly put a floor under what the threshold could mean.
 */
static void arm_build_stall_timer(void)
{
	struct itimerspec its;

	memset(&its, 0, sizeof(its));
	its.it_value.tv_sec = pkg_build_stall_check_interval();
	if (timerfd_settime(g_build_stall_conn.fd, 0, &its, NULL) != 0)
		perror("timerfd_settime (build stall re-arm)");
}

/*
 * Issue #119: a container whose async teardown (ADR-0180) never
 * completes -- its pidns init wedged in the kernel reaping a process
 * that will not die -- sits in "deleting" forever, holding its build
 * slot, indistinguishable from a merely-slow teardown. Nothing here can
 * force the kernel to finish, but this makes the stuck teardown VISIBLE:
 * once a teardown has been in flight past the threshold, log it (once),
 * the same discipline pkg_check_build_stalls() applies to a quiet build.
 */
static void check_teardown_stalls(void)
{
	char names[REGISTRY_MAX_CONTAINERS][REGISTRY_NAME_MAX];
	int n = registry_list_names(names, REGISTRY_MAX_CONTAINERS);
	time_t now = time(NULL);
	int i;

	for (i = 0; i < n; i++) {
		struct registry_entry *e = registry_find(names[i]);

		if (e == NULL || e->teardown_kind == REGISTRY_TEARDOWN_NONE)
			continue;
		if (e->teardown_stall_reported)
			continue;
		if (now - e->teardown_started_at < REGISTRY_TEARDOWN_STALL_SECONDS)
			continue;
		logstore_write("cixd", "error",
		               "container %s stuck in teardown for %llds -- its pidfd has not "
		               "fired since SIGKILL, most likely a kernel pidns reap that cannot "
		               "complete; the build slot it holds will not return until the "
		               "process dies or the host reboots (issue #119)",
		               names[i], (long long)(now - e->teardown_started_at));
		e->teardown_stall_reported = 1;
	}
}

static void handle_build_stall_timer_event(struct conn *cc)
{
	uint64_t expirations;

	if (read(cc->fd, &expirations, sizeof(expirations)) < 0)
		perror("read (build stall timerfd)");
	pkg_check_build_stalls();
	check_teardown_stalls();   /* issue #119 */
	arm_build_stall_timer();
}

/*
 * ADR-0256: is this boot still on its A/B trial?
 *
 * systemd-boot's Automatic Boot Assessment keeps the remaining try
 * count in the entry's own filename, and confirm_boot() renames it away
 * once the boot is good. So a '+' in the name is the whole question:
 * present means unconfirmed and still falling back on failure, absent
 * means this slot has already been accepted.
 */
static int boot_is_unconfirmed(const char *slot)
{
	char entry_name[ESP_ENTRY_NAME_MAX];

	if (!esp_entry_to_confirm(g_esp_entries_dir, slot, entry_name, sizeof(entry_name)))
		return 0;
	return strchr(entry_name, '+') != NULL;
}

static void arm_boot_confirm_timer(void)
{
	struct itimerspec its;

	memset(&its, 0, sizeof(its));
	its.it_value.tv_sec = BOOT_CONFIRM_RETRY_SECONDS;
	if (timerfd_settime(g_boot_confirm_conn.fd, 0, &its, NULL) != 0)
		perror("timerfd_settime (boot confirm re-arm)");
}

static void stop_boot_confirm_timer(void)
{
	if (g_boot_confirm_conn.fd < 0)
		return;
	cix_epoll_ctl(g_epfd, EPOLL_CTL_DEL, g_boot_confirm_conn.fd, NULL);
	close(g_boot_confirm_conn.fd);
	g_boot_confirm_conn.fd = -1;
}

static void handle_boot_confirm_timer_event(struct conn *cc)
{
	uint64_t expirations;

	if (read(cc->fd, &expirations, sizeof(expirations)) < 0)
		perror("read (boot confirm timerfd)");
	g_boot_confirm_attempts++;

	/*
	 * The benign case this window exists for: a NIC driver that loaded
	 * after boot_init() ran, so the interface exists now and did not
	 * then. Retrying the attach is the whole check -- it succeeds
	 * exactly when the host has become reachable.
	 */
	if (network_attach_interface(MGMT_NETWORK_NAME, g_uplink_unattached, 0) == NETWORK_OK) {
		logstore_write("cixd", "info",
		                "boot confirm: uplink \"%s\" attached after %d attempt(s); "
		                "confirming slot %s",
		                g_uplink_unattached, g_boot_confirm_attempts, g_boot_confirm_slot);
		g_uplink_unattached[0] = '\0';
		if (confirm_boot(g_boot_confirm_slot) != 0)
			fprintf(stderr, "confirm_boot failed for slot %s (continuing anyway)\n",
			        g_boot_confirm_slot);
		stop_boot_confirm_timer();
		return;
	}

	if (g_boot_confirm_attempts >= BOOT_CONFIRM_MAX_ATTEMPTS) {
		/*
		 * Deliberately reboot rather than park. The entry still
		 * carries a try count, so this spends one and eventually hands
		 * the machine back to the other slot -- which is the whole
		 * point of an A/B scheme and is what a box that came up
		 * unreachable never used to do.
		 */
		logstore_write("cixd", "error",
		                "boot confirm: uplink \"%s\" still unattached after %d attempts -- "
		                "NOT confirming slot %s, rebooting to spend a boot try so the "
		                "loader can fall back to the other slot",
		                g_uplink_unattached, g_boot_confirm_attempts, g_boot_confirm_slot);
		fprintf(stderr, "boot confirm: unreachable on \"%s\" -- rebooting to fall back\n",
		        g_uplink_unattached);
		stop_boot_confirm_timer();
		g_shutdown_action = SHUTDOWN_ACTION_REBOOT;
		g_stop = 1;
		return;
	}
	arm_boot_confirm_timer();
}

static void start_boot_confirm_timer(const char *slot)
{
	struct cix_epoll_event ev;
	int fd = timerfd_create(CLOCK_MONOTONIC, TFD_NONBLOCK | TFD_CLOEXEC);

	snprintf(g_boot_confirm_slot, sizeof(g_boot_confirm_slot), "%s", slot);
	g_boot_confirm_attempts = 0;
	if (fd < 0) {
		perror("timerfd_create (boot confirm)");
		return;
	}
	g_boot_confirm_conn.kind = CONN_BOOT_CONFIRM_TIMER;
	g_boot_confirm_conn.fd = fd;
	memset(&ev, 0, sizeof(ev));
	ev.events = EPOLLIN;
	ev.data.ptr = &g_boot_confirm_conn;
	if (cix_epoll_ctl(g_epfd, EPOLL_CTL_ADD, fd, &ev) != 0) {
		close(fd);
		g_boot_confirm_conn.fd = -1;
		return;
	}
	arm_boot_confirm_timer();
}

/*
 * ADR-0256: confirming a boot means the host is REACHABLE, not that a
 * socket is bound.
 *
 * "About to serve traffic" was the old condition, and a box whose
 * configured uplink could not be attached satisfies it: the management
 * bridge and its address exist, cixd binds, and the boot was confirmed
 * -- permanently, on a slot nobody on the network can reach, with the
 * A/B fallback already spent. Now that case does not confirm; it
 * retries for a bounded window and then reboots so the loader falls
 * back.
 *
 * The guard is what keeps this safe: it applies ONLY while the boot is
 * unconfirmed. A slot that has already been accepted and whose NIC
 * fails later must never reboot itself, or a pulled cable becomes a
 * reboot loop.
 */
/*
 * Two ways a boot can be RUNNING and reachable from nowhere but itself:
 * no uplink attached (#133), or the chosen management address could not
 * be bound (2026-09-13 -- cixd keeps serving on loopback, see the
 * listener block in cixd_main()). Either way the slot must not be
 * confirmed on the strength of having bound a socket (ADR-0256).
 *
 * The guard is what keeps this safe: it applies ONLY while the boot is
 * unconfirmed. A slot that has already been accepted and whose NIC
 * fails later must never reboot itself, or a pulled cable becomes a
 * reboot loop.
 */
static void maybe_confirm_boot(const char *slot)
{
	char why[192];

	if (g_uplink_unattached[0] != '\0')
		snprintf(why, sizeof(why), "uplink \"%s\" is not attached", g_uplink_unattached);
	else if (g_bind_unavailable[0] != '\0')
		snprintf(why, sizeof(why), "the chosen management address %s could not be bound",
		          g_bind_unavailable);
	else
		why[0] = '\0';

	if (why[0] == '\0') {
		if (confirm_boot(slot) != 0)
			fprintf(stderr, "confirm_boot failed for slot %s (continuing anyway)\n", slot);
		return;
	}
	if (!boot_is_unconfirmed(slot)) {
		logstore_write("cixd", "error",
		                "%s, so this host is only reachable on itself -- slot %s was already "
		                "confirmed, so it is kept: a confirmed slot never reboots itself over "
		                "a fault it can survive",
		                why, slot);
		return;
	}
	logstore_write("cixd", "error",
	                "%s, so this boot is NOT reachable and will not be confirmed yet -- "
	                "retrying for %d seconds, then falling back to the other slot",
	                why, BOOT_CONFIRM_RETRY_SECONDS * BOOT_CONFIRM_MAX_ATTEMPTS);
	start_boot_confirm_timer(slot);
}

/* ---------- ADR-0257: one scheduler ---------- */

static struct conn g_scheduler_conn = { .fd = -1 };
static int g_scheduler_first_tick = 1;

/* Defined with the rest of the kernel.org release plumbing, far below;
 * declared here so the action that schedules it can sit beside the
 * scheduler's own timer rather than being stranded next to curl. */
static int kernel_releases_fetch_start(char *err_msg, size_t err_msg_size);

/*
 * The first registered action, and deliberately the only one in this
 * part: refreshing what upstream has published.
 *
 * ADR-0255 gave the platform a source catalogue and no way to keep its
 * inputs fresh -- kernel.org's release list only ever refreshed when
 * somebody asked by hand. This closes that, and it has no existing
 * timer of its own, so nothing can double-fire while the legacy timers
 * are still alive. The four that DO have timers (system backup, volume
 * backup, pkg sync, NTP) arrive together with the cut-over, so no
 * window exists in which a job and a legacy timer drive the same work.
 *
 * Enqueues rather than fetching inline: kernel_releases_fetch_start()
 * forks curl and watches it on this same reactor, which is what keeps
 * a scheduled refresh from blocking the control plane.
 */
static int action_refresh_upstreams(const char *params, char *reason, size_t reason_size)
{
	char err[192];

	(void)params;
	if (kernel_releases_fetch_start(err, sizeof(err)) != 0) {
		snprintf(reason, reason_size, "%s", err);
		return -1;
	}
	snprintf(reason, reason_size, "started a kernel.org release-list refresh");
	return 0;
}

/* All defined further down, next to the subsystems they belong to;
 * declared here so the actions that schedule them sit beside the
 * scheduler rather than being scattered across the file. */
static void do_backup_snapshot_now(void);
static int volumebackup_sweep_now(void);
static void register_pkg_sync_fetch_pidfd(pid_t pid, int pidfd);

/*
 * ADR-0257: the three actions that replace three periodic timers.
 *
 * Each calls an entry point that already existed and already respects
 * its own queue, so a schedule cannot start work that a manual request
 * could not. That is the whole reason actions enqueue rather than doing
 * anything themselves.
 */
static int action_system_backup(const char *params, char *reason, size_t reason_size)
{
	(void)params;
	if (!backupconfig_enabled()) {
		snprintf(reason, reason_size,
		         "system backups are disabled -- enable them in PUT /v1/system/backup-config");
		return -1;
	}
	if (backupconfig_disk() == NULL || backupconfig_disk()[0] == '\0') {
		snprintf(reason, reason_size, "no backup disk is configured");
		return -1;
	}
	do_backup_snapshot_now();
	snprintf(reason, reason_size, "wrote a system backup to %s", backupconfig_disk());
	return 0;
}

static int action_volume_backup(const char *params, char *reason, size_t reason_size)
{
	int taken;

	(void)params;
	if (!volumebackup_enabled()) {
		snprintf(reason, reason_size,
		         "volume backups are disabled -- enable them in PUT /v1/volume-backup-config");
		return -1;
	}
	taken = volumebackup_sweep_now();
	snprintf(reason, reason_size, "snapshotted %d volume(s)", taken);
	return 0;
}

static int action_pkg_sync(const char *params, char *reason, size_t reason_size)
{
	pid_t pid;
	int pidfd;
	enum pkg_error perr;

	(void)params;
	perr = pkg_sync_start(&pid, &pidfd);
	if (perr == PKG_ERR_BUSY) {
		snprintf(reason, reason_size, "a sync was already running; this one was not started");
		return -1;
	}
	if (perr == PKG_ERR_NOT_FOUND) {
		snprintf(reason, reason_size,
		         "no repo is configured -- PUT /v1/pkg/repo-config first");
		return -1;
	}
	if (perr != PKG_OK) {
		snprintf(reason, reason_size, "could not start a sync (%d)", (int)perr);
		return -1;
	}
	register_pkg_sync_fetch_pidfd(pid, pidfd);
	snprintf(reason, reason_size, "started a recipe sync");
	return 0;
}

/*
 * The one-time upgrade step ADR-0257 promised: a config file that still
 * carries an interval becomes the equivalent schedule, once, and then
 * drops the field.
 *
 * Not a compatibility shim -- it runs against what is on disk, writes a
 * real schedule, and clears the old value, so a second boot finds
 * nothing to do. A box that never had an interval set gets no schedule
 * at all, which is right: nothing was running before either.
 */
static void migrate_legacy_intervals(void)
{
	struct {
		const char *name;
		const char *action;
		int seconds;
	} jobs[3];
	char body[256];
	char err[256];
	int i, n = 0;

	if (backupconfig_legacy_interval_hours() > 0) {
		jobs[n].name = "system-backup";
		jobs[n].action = "system.backup";
		jobs[n].seconds = backupconfig_legacy_interval_hours() * 3600;
		n++;
	}
	if (volumebackup_legacy_interval_hours() > 0) {
		jobs[n].name = "volume-backup";
		jobs[n].action = "volume.backup";
		jobs[n].seconds = volumebackup_legacy_interval_hours() * 3600;
		n++;
	}
	if (pkg_repo_legacy_sync_interval_seconds() > 0) {
		jobs[n].name = "recipe-sync";
		jobs[n].action = "pkg.sync";
		jobs[n].seconds = pkg_repo_legacy_sync_interval_seconds();
		n++;
	}
	for (i = 0; i < n; i++) {
		/* Never overwrite a schedule an operator already made. */
		if (scheduler_find(jobs[i].name) != NULL)
			continue;
		snprintf(body, sizeof(body),
		         "{\"action\":\"%s\",\"schedule\":{\"every\":{\"seconds\":%d}},"
		         "\"catch_up\":true}",
		         jobs[i].action, jobs[i].seconds);
		if (scheduler_set_from_json(jobs[i].name, body, strlen(body), err, sizeof(err)) !=
		    SCHEDULE_OK) {
			logstore_write("cixd", "error",
			                "could not migrate the %s interval into a schedule: %s",
			                jobs[i].action, err);
			continue;
		}
		logstore_write("cixd", "info",
		                "migrated a %d-second %s interval into schedule \"%s\" (ADR-0257)",
		                jobs[i].seconds, jobs[i].action, jobs[i].name);
	}
	/*
	 * Cleared unconditionally, including when nothing was migrated:
	 * backupconfig and volumebackup no longer write the field at all,
	 * so the value only survives until their next save; clearing it
	 * here makes that explicit rather than incidental.
	 */
	backupconfig_clear_legacy_interval();
	volumebackup_clear_legacy_interval();
	if (pkg_repo_legacy_sync_interval_seconds() > 0)
		pkg_repo_clear_legacy_sync_interval();
}

static void arm_scheduler_timer(void)
{
	struct itimerspec its;
	long now = (long)time(NULL);
	long due = scheduler_next_due(now);
	long delay;

	/*
	 * Armed to the next due job, never to a fixed tick, but clamped:
	 * at least a second so a job that is already overdue cannot spin,
	 * and at most a minute so a wall-clock job stays accurate across a
	 * clock step (NTP moving the clock does not re-arm this timer, so
	 * a multi-hour sleep would simply be wrong afterwards).
	 */
	if (due == 0)
		delay = 60;
	else
		delay = due - now;
	if (delay < 1)
		delay = 1;
	if (delay > 60)
		delay = 60;

	memset(&its, 0, sizeof(its));
	its.it_value.tv_sec = delay;
	if (timerfd_settime(g_scheduler_conn.fd, 0, &its, NULL) != 0)
		perror("timerfd_settime (scheduler re-arm)");
}

static void handle_scheduler_timer_event(struct conn *cc)
{
	uint64_t expirations;

	if (read(cc->fd, &expirations, sizeof(expirations)) < 0)
		perror("read (scheduler timerfd)");
	scheduler_run_due((long)time(NULL), g_scheduler_first_tick);
	g_scheduler_first_tick = 0;
	arm_scheduler_timer();
}

static void start_scheduler_timer(void)
{
	struct cix_epoll_event ev;
	int fd = timerfd_create(CLOCK_MONOTONIC, TFD_NONBLOCK | TFD_CLOEXEC);

	if (fd < 0) {
		perror("timerfd_create (scheduler)");
		return;
	}
	g_scheduler_conn.kind = CONN_SCHEDULER_TIMER;
	g_scheduler_conn.fd = fd;
	memset(&ev, 0, sizeof(ev));
	ev.events = EPOLLIN;
	ev.data.ptr = &g_scheduler_conn;
	if (cix_epoll_ctl(g_epfd, EPOLL_CTL_ADD, fd, &ev) != 0) {
		close(fd);
		g_scheduler_conn.fd = -1;
		return;
	}
	arm_scheduler_timer();
}

static void start_build_stall_timer(void)
{
	struct cix_epoll_event ev;
	int fd = timerfd_create(CLOCK_MONOTONIC, TFD_NONBLOCK | TFD_CLOEXEC);

	if (fd < 0) {
		perror("timerfd_create (build stall)");
		return;
	}
	g_build_stall_conn.kind = CONN_BUILD_STALL_TIMER;
	g_build_stall_conn.fd = fd;
	memset(&ev, 0, sizeof(ev));
	ev.events = EPOLLIN;
	ev.data.ptr = &g_build_stall_conn;
	if (cix_epoll_ctl(g_epfd, EPOLL_CTL_ADD, fd, &ev) != 0) {
		close(fd);
		g_build_stall_conn.fd = -1;
		return;
	}
	arm_build_stall_timer();
}

static void start_ntp_periodic_timer(void)
{
	struct cix_epoll_event ev;
	int fd = timerfd_create(CLOCK_MONOTONIC, TFD_NONBLOCK | TFD_CLOEXEC);

	if (fd < 0) {
		perror("timerfd_create (ntp periodic)");
		return;
	}
	g_ntp_periodic_conn.kind = CONN_NTP_PERIODIC_TIMER;
	g_ntp_periodic_conn.fd = fd;
	memset(&ev, 0, sizeof(ev));
	ev.events = EPOLLIN;
	ev.data.ptr = &g_ntp_periodic_conn;
	if (cix_epoll_ctl(g_epfd, EPOLL_CTL_ADD, fd, &ev) != 0) {
		close(fd);
		g_ntp_periodic_conn.fd = -1;
		return;
	}
	arm_ntp_periodic_timer();
}

/* POST /v1/system/ntp/sync: triggers one sync attempt on demand,
 * rather than waiting for the next hourly automatic fire
 * (NTP_SYNC_INTERVAL_SEC) -- an operator who just set upstream
 * servers or registered a server container has no other way to see
 * the result without waiting up to an hour. Same v1
 * one-job-in-flight/202-Accepted-then-poll-status shape POST
 * /v1/system/ping already established; GET /v1/system/ntp/status
 * reports the outcome once it lands. */
static void handle_ntp_sync_post(int fd)
{
	enum ntp_start_error serr = start_ntp_sync_job();

	if (serr == NTP_START_BUSY) {
		respond_error(fd, 409, "Conflict", "a sync attempt is already in flight");
		return;
	}
	if (serr == NTP_START_NO_CANDIDATES) {
		respond_error(fd, 400, "Bad Request",
		              "no NTP servers configured -- set upstream (PUT /v1/system/ntp) or "
		              "register a server container (POST /v1/ntp/servers) first");
		return;
	}
	if (serr != NTP_START_OK) {
		respond_error(fd, 500, "Internal Server Error",
		              "could not start sync (socket/timer setup failed)");
		return;
	}
	http_set_blocking(fd);
	http_write_response(fd, 202, "Accepted", "application/json", "", 0);
}





/* Best-effort: a missing/malformed /proc/loadavg leaves all three at 0,
 * same "snapshot, not all-or-nothing" convention as read_net_stat(). */
static void read_loadavg(double *l1, double *l5, double *l15)
{
	FILE *f;

	*l1 = *l5 = *l15 = 0.0;
	f = fopen("/proc/loadavg", "r");
	if (f == NULL)
		return;
	fscanf(f, "%lf %lf %lf", l1, l5, l15);
	fclose(f);
}

/*
 * Host uptime, straight from /proc/uptime's own first field (seconds
 * since boot, as a float). Best-effort like read_loadavg(): an
 * unreadable /proc/uptime reports 0 rather than failing the whole
 * stats response, and 0 is distinguishable from any real answer
 * because a booted box has always been up for something.
 */
static long long read_host_uptime_seconds(void)
{
	FILE *f;
	double up = 0.0;

	f = fopen("/proc/uptime", "r");
	if (f == NULL)
		return 0;
	if (fscanf(f, "%lf", &up) != 1)
		up = 0.0;
	fclose(f);
	return (long long)up;
}

/*
 * When this daemon process itself started, stamped once at startup.
 * Deliberately separate from host uptime: they differ after a daemon
 * restart that was not a reboot (a `system/update` confirm, a crash
 * and respawn), and "the box has been up for days but the control
 * plane restarted four minutes ago" is exactly the thing an operator
 * needs to be able to see.
 */
static time_t g_daemon_started_at;

/* /proc/stat's own first "cpu" line: user/nice/system/idle/iowait/irq/
 * softirq/steal jiffies, in that fixed kernel-documented order. Raw
 * cumulative counters since boot -- callers compute their own deltas,
 * same convention as every other stats endpoint in this daemon. */
static void read_cpu_jiffies(long long *user, long long *nice, long long *system_j,
                              long long *idle, long long *iowait, long long *irq,
                              long long *softirq, long long *steal)
{
	FILE *f;
	char label[16];

	*user = *nice = *system_j = *idle = *iowait = *irq = *softirq = *steal = 0;
	f = fopen("/proc/stat", "r");
	if (f == NULL)
		return;
	if (fscanf(f, "%15s %lld %lld %lld %lld %lld %lld %lld %lld",
	           label, user, nice, system_j, idle, iowait, irq, softirq, steal) < 9) {
		*user = *nice = *system_j = *idle = *iowait = *irq = *softirq = *steal = 0;
	}
	fclose(f);
}

/* /proc/meminfo: "Key:   value kB" lines, in no guaranteed order and
 * with keys this daemon doesn't care about interspersed -- parsed as a
 * single pass matching each line's key against the wanted set, rather
 * than assuming a fixed line count/order. All values kB -> bytes. */
static void read_meminfo(long long *total, long long *free_b, long long *avail,
                          long long *buffers, long long *cached,
                          long long *swap_total, long long *swap_free)
{
	FILE *f;
	char line[256];
	char key[64];
	long long val;

	*total = *free_b = *avail = *buffers = *cached = *swap_total = *swap_free = 0;
	f = fopen("/proc/meminfo", "r");
	if (f == NULL)
		return;
	while (fgets(line, sizeof(line), f) != NULL) {
		if (sscanf(line, "%63s %lld", key, &val) != 2)
			continue;
		if (strcmp(key, "MemTotal:") == 0)
			*total = val * 1024;
		else if (strcmp(key, "MemFree:") == 0)
			*free_b = val * 1024;
		else if (strcmp(key, "MemAvailable:") == 0)
			*avail = val * 1024;
		else if (strcmp(key, "Buffers:") == 0)
			*buffers = val * 1024;
		else if (strcmp(key, "Cached:") == 0)
			*cached = val * 1024;
		else if (strcmp(key, "SwapTotal:") == 0)
			*swap_total = val * 1024;
		else if (strcmp(key, "SwapFree:") == 0)
			*swap_free = val * 1024;
	}
	fclose(f);
}

/*
 * GET /v1/system/stats: host-wide CPU/memory/disk/network load, mirroring
 * handle_container_stats()'s own conventions one level up -- nested
 * per-category objects, raw cumulative/monotonic counters only (never a
 * pre-computed rate; the client already does its own delta math for
 * container stats and does the same here). Real /proc and statvfs()
 * sources throughout, no shelling out, matching this project's own
 * syscall-first convention. Every field here is a best-effort read: a
 * missing source leaves that section zeroed rather than failing the
 * whole request, same as container stats' own network section.
 */
/*
 * GET/PUT /v1/system/daemon-config: cixd's own listen port and
 * HTTP/HTTPS exposure -- a dedicated resource, distinct from generic
 * network CRUD, since changing a field here has a real side effect (a
 * live listen-socket start/stop/rebind) that plain PUT /v1/networks/...
 * was never meant to trigger. WHERE cixd binds off-box is NOT here
 * anymore (ADR-0287): that is the single management address, GET/PUT/
 * DELETE /v1/system/management-address, and the derived `management`
 * flag on GET /networks. PUT accepts a partial body (only the fields
 * being changed).
 */
static void handle_daemon_config_get(int fd)
{
	struct json_writer w;

	jw_init(&w);
	jw_obj_open(&w);
	jw_key(&w, "port");
	jw_int(&w, g_port);
	jw_key(&w, "http_enabled");
	jw_bool(&w, g_listener_conn.fd >= 0);
	jw_key(&w, "https_enabled");
	jw_bool(&w, g_https_listener_conn.fd >= 0);
	jw_key(&w, "userns_default");
	jw_bool(&w, daemon_config_userns_default());
	jw_key(&w, "https_port");
	jw_int(&w, daemon_config_https_port());
	/* WHERE cixd binds off-box is a separate resource now (ADR-0287):
	 * GET /system/management-address. daemon-config is listeners only. */
	jw_obj_close(&w);
	respond_json(fd, 200, "OK", &w);
	jw_free(&w);
}

/*
 * GET/PUT/DELETE /v1/system/management-address (ADR-0287).
 *
 * The single truth for where cixd answers off-box. One address is
 * given; the network it lives in is DERIVED from it
 * (network_find_containing()), and that network's `management` flag is
 * derived in turn. 127.0.0.1 is always bound in addition and is never
 * part of this resource. This supersedes the old /system/management-
 * network endpoint and daemon-config's management_network/bind_ip
 * fields -- one input, not three.
 */

/*
 * Bring an arbitrary listener conn down. stop_http_listener() above is
 * hardcoded to the main HTTP conn; this is the same three steps for the
 * always-on loopback pair, which must be started or stopped as the
 * off-box address crosses to or from loopback.
 */
static void stop_listener_conn(struct conn *c)
{
	if (c->fd < 0)
		return;
	cix_epoll_ctl(g_epfd, EPOLL_CTL_DEL, c->fd, NULL);
	close(c->fd);
	c->fd = -1;
	c->listen_addr[0] = '\0';
	c->listen_port = 0;
}

static int addr_is_loopback_bind(const char *addr)
{
	return strcmp(addr, DEFAULT_BIND) == 0 || strcmp(addr, "0.0.0.0") == 0;
}

/*
 * Move cixd's off-box HTTP/HTTPS listeners to target_addr (a real
 * address, or DEFAULT_BIND for the loopback-only reset state) and keep
 * the always-on loopback pair correct across the transition. The
 * loopback pair (g_lo_*) runs only WHEN the off-box address is not
 * itself loopback -- binding 127.0.0.1 twice on one port collides
 * (EADDRINUSE, and SO_REUSEADDR does not change that) -- so crossing to
 * or from loopback starts or stops it. Returns 0, or -1 with the
 * off-box listeners left on the previous address. The HTTPS listener is
 * moved only if it is currently up; a down HTTPS listener (no cert yet)
 * is not started here.
 */
static int apply_bind_address(const char *target_addr)
{
	int was_loopback = addr_is_loopback_bind(g_bind_addr);
	int now_loopback = addr_is_loopback_bind(target_addr);

	/*
	 * Going TO loopback (reset): free 127.0.0.1 from the loopback pair
	 * BEFORE the main listeners rebind onto it, or that rebind hits
	 * EADDRINUSE -- two identical 127.0.0.1:P binds collide and
	 * SO_REUSEADDR does not help (the same rule the boot path states).
	 * stop_listener_conn() only closes the fd; g_tls_ctx is a shared
	 * global kept alive across stop/restart, so the HTTPS loopback conn
	 * needs nothing more.
	 */
	if (now_loopback && !was_loopback) {
		stop_listener_conn(&g_lo_listener_conn);
		stop_listener_conn(&g_lo_https_listener_conn);
	}

	/*
	 * Honor http_enabled/https_enabled (mirroring start_listeners()):
	 * a listener that is down because its side is disabled stays down,
	 * and re-PUTting the current address to retry a boot-time bind
	 * failure brings each enabled side back -- HTTPS soft-failing when
	 * no host cert exists yet, the same posture daemon-config uses.
	 */
	if (g_listener_conn.fd < 0) {
		if (daemon_config_http_enabled() &&
		    start_http_listener(&g_listener_conn, target_addr, g_port) != 0)
			return -1;
		snprintf(g_bind_addr_buf, sizeof(g_bind_addr_buf), "%s", target_addr);
		g_bind_addr = g_bind_addr_buf;
	} else if (rebind_listener(target_addr, g_port) != 0) {
		return -1;
	}
	if (g_https_listener_conn.fd >= 0) {
		if (rebind_https_listener(target_addr, daemon_config_https_port()) != 0)
			return -1;
	} else if (daemon_config_https_enabled() &&
	           start_https_listener(&g_https_listener_conn, target_addr,
	                                 daemon_config_https_port()) != 0) {
		fprintf(stderr,
		        "https_enabled but could not start the HTTPS listener on %s (no host cert "
		        "yet?) -- continuing without it\n",
		        target_addr);
	}

	/*
	 * Going TO a real address from loopback: the main listeners have
	 * vacated 127.0.0.1, so bring the always-on loopback pair up now.
	 */
	if (!now_loopback && was_loopback)
		(void)start_listeners(&g_lo_listener_conn, &g_lo_https_listener_conn, DEFAULT_BIND,
		                       g_port);
	return 0;
}

static void management_address_write_json(int fd)
{
	struct json_writer w;
	const char *addr = daemon_config_management_address();
	struct network_def *mgmt = network_find_management();
	int bound = addr != NULL && g_bind_unavailable[0] == '\0';

	jw_init(&w);
	jw_obj_open(&w);
	jw_key(&w, "configured");
	jw_bool(&w, addr != NULL);
	jw_key(&w, "address");
	jw_str(&w, addr != NULL ? addr : "");
	jw_key(&w, "bound");
	jw_str(&w, bound ? addr : "");
	jw_key(&w, "bind_unavailable");
	jw_str(&w, g_bind_unavailable);
	jw_key(&w, "network");
	jw_str(&w, mgmt != NULL ? mgmt->name : "");
	jw_obj_close(&w);
	respond_json(fd, 200, "OK", &w);
	jw_free(&w);
}

static void handle_management_address_get(int fd)
{
	management_address_write_json(fd);
}

static void handle_management_address_put(int fd, const char *body, size_t body_len)
{
	struct json_value *root;
	const struct json_value *jaddr;
	const char *raw;
	char addr_str[INET_ADDRSTRLEN];
	struct in_addr a;
	uint32_t addr_be, valid_be;
	struct network_def *net, *old_mgmt;
	uint32_t old_addr_be = 0;
	char old_ifname[NETWORK_NAME_MAX] = "";
	int old_prefix = 0;
	const char *cur;
	int rtfd;

	root = json_parse(body, body_len);
	if (root == NULL) {
		respond_error(fd, 400, "Bad Request", "invalid JSON body");
		return;
	}
	jaddr = json_object_get(root, "address");
	raw = jaddr != NULL ? json_as_string(jaddr) : NULL;
	if (raw == NULL) {
		json_free(root);
		respond_error(fd, 400, "Bad Request", "address must be a string");
		return;
	}
	if (snprintf(addr_str, sizeof(addr_str), "%s", raw) >= (int)sizeof(addr_str) ||
	    inet_pton(AF_INET, addr_str, &a) != 1) {
		json_free(root);
		respond_error(fd, 400, "Bad Request", "address is not a valid IPv4 address");
		return;
	}
	json_free(root);
	addr_be = a.s_addr;

	/* Loopback / unspecified are not off-box addresses -- reset to
	 * loopback-only with DELETE, don't set one here. */
	{
		uint32_t h = ntohl(addr_be);

		if ((h >> 24) == 127 || (h >> 24) == 0) {
			respond_error(fd, 400, "Bad Request",
			              "address in 0.0.0.0/8 or 127.0.0.0/8 -- reset to loopback-only with DELETE instead");
			return;
		}
	}

	net = network_find_containing(addr_be);
	if (net == NULL) {
		respond_error(fd, 400, "Bad Request",
		              "no network contains that address -- create one first");
		return;
	}
	/* A real host address within that network (not the network or
	 * broadcast address) -- the identical rule every other address on a
	 * Cix network already obeys. */
	if (network_address_str_is_valid(net, addr_str, &valid_be) != 0) {
		respond_error(fd, 400, "Bad Request",
		              "not a usable host address in its network (network or broadcast address?)");
		return;
	}

	/* Where the old address currently lives, captured before anything
	 * moves so it can be torn down from the right bridge afterwards. */
	cur = daemon_config_management_address();
	old_mgmt = network_find_management();
	if (cur != NULL && old_mgmt != NULL) {
		struct in_addr oa;

		if (inet_pton(AF_INET, cur, &oa) == 1)
			old_addr_be = oa.s_addr;
		snprintf(old_ifname, sizeof(old_ifname), "%s", old_mgmt->name);
		old_prefix = old_mgmt->prefix_len;
	}

	/* Add the address to the derived network's bridge (idempotent via
	 * NLM_F_EXCL when it is that network's own address), then rebind.
	 * Not short-circuited on "same address": re-PUTting the current
	 * address is how an operator retries a bind that failed at boot
	 * (g_bind_unavailable), and start/rebind below handles that. */
	rtfd = rtnl_open();
	if (rtfd < 0) {
		respond_error(fd, 500, "Internal Server Error", "could not open rtnetlink socket");
		return;
	}
	if (rtnl_addr_add_ipv4(rtfd, net->name, addr_be, net->prefix_len) != 0 && errno != EEXIST) {
		rtnl_close(rtfd);
		respond_error(fd, 500, "Internal Server Error",
		              "could not assign the address to its network's bridge");
		return;
	}
	rtnl_close(rtfd);

	if (apply_bind_address(addr_str) != 0) {
		respond_error(fd, 500, "Internal Server Error", "listener rebind failed");
		return;
	}
	g_bind_unavailable[0] = '\0'; /* bound for real now */

	(void)network_set_management_address(addr_str);
	if (daemon_config_set_management_address(addr_str) != DAEMON_CONFIG_OK) {
		respond_error(fd, 500, "Internal Server Error",
		              "address applied live but could not be persisted");
		return;
	}

	logstore_write("cixd", "info", "management address set to %s on network %s", addr_str,
	               net->name);
	management_address_write_json(fd);

	/*
	 * Deferred, and only now (ADR-0068): the reply may travel over the
	 * old address's own connection, and removing it synchronously would
	 * strand this client. Only when it genuinely moved to a different
	 * address on a real bridge.
	 */
	if (old_addr_be != 0 && old_addr_be != addr_be && old_ifname[0] != '\0')
		arm_bind_ip_cleanup_timer(old_ifname, old_addr_be, old_prefix);
}

static void handle_management_address_delete(int fd)
{
	const char *cur = daemon_config_management_address();
	struct network_def *old_mgmt;
	uint32_t old_addr_be = 0;
	char old_ifname[NETWORK_NAME_MAX] = "";
	int old_prefix = 0;
	int coincides_own = 0;

	if (cur == NULL) {
		management_address_write_json(fd); /* already loopback-only: 200 no-op */
		return;
	}

	old_mgmt = network_find_management();
	if (old_mgmt != NULL) {
		struct in_addr oa;

		if (inet_pton(AF_INET, cur, &oa) == 1)
			old_addr_be = oa.s_addr;
		snprintf(old_ifname, sizeof(old_ifname), "%s", old_mgmt->name);
		old_prefix = old_mgmt->prefix_len;
		/* Never delete the network's OWN address out from under it. */
		coincides_own = old_mgmt->has_address && old_mgmt->address_be == old_addr_be;
	}

	if (apply_bind_address(DEFAULT_BIND) != 0) {
		respond_error(fd, 500, "Internal Server Error", "could not drop the off-box listener");
		return;
	}
	g_bind_unavailable[0] = '\0';

	(void)network_set_management_address(NULL);
	if (daemon_config_set_management_address(NULL) != DAEMON_CONFIG_OK) {
		respond_error(fd, 500, "Internal Server Error",
		              "unbound live but could not persist the reset");
		return;
	}

	logstore_write("cixd", "info", "management address reset -- cixd is loopback-only");
	management_address_write_json(fd);

	if (old_addr_be != 0 && !coincides_own && old_ifname[0] != '\0')
		arm_bind_ip_cleanup_timer(old_ifname, old_addr_be, old_prefix);
}

static void handle_daemon_config_put(int fd, const char *body, size_t body_len)
{
	struct json_value *root;
	const struct json_value *jport, *jhttp, *jhttps, *jhttps_port;
	int new_port = g_port;
	int new_https_port = daemon_config_https_port();
	int have_https_port_req = 0;
	int want_http = daemon_config_http_enabled();
	int want_https = daemon_config_https_enabled();
	int have_http_req = 0, have_https_req = 0;
	enum daemon_config_error derr;

	root = json_parse(body, body_len);
	if (root == NULL) {
		respond_error(fd, 400, "Bad Request", "invalid JSON body");
		return;
	}

	jport = json_object_get(root, "port");
	if (jport != NULL) {
		new_port = (int)json_as_number(jport);
		if (new_port < 1 || new_port > 65535) {
			json_free(root);
			respond_error(fd, 400, "Bad Request", "port must be 1-65535");
			return;
		}
	}

	jhttps_port = json_object_get(root, "https_port");
	if (jhttps_port != NULL) {
		new_https_port = (int)json_as_number(jhttps_port);
		have_https_port_req = 1;
		if (new_https_port < 1 || new_https_port > 65535) {
			json_free(root);
			respond_error(fd, 400, "Bad Request", "https_port must be 1-65535");
			return;
		}
	}

	{
		const struct json_value *jud = json_object_get(root, "userns_default");

		if (jud != NULL) {
			if (jud->type != JSON_BOOL) {
				json_free(root);
				respond_error(fd, 400, "Bad Request", "userns_default must be a boolean");
				return;
			}
			if (daemon_config_set_userns_default(jud->u.boolean) != DAEMON_CONFIG_OK) {
				json_free(root);
				respond_error(fd, 500, "Internal Server Error",
				               "failed to persist userns_default");
				return;
			}
		}
	}

	jhttp = json_object_get(root, "http_enabled");
	if (jhttp != NULL && jhttp->type == JSON_BOOL) {
		want_http = jhttp->u.boolean;
		have_http_req = 1;
	}
	jhttps = json_object_get(root, "https_enabled");
	if (jhttps != NULL && jhttps->type == JSON_BOOL) {
		want_https = jhttps->u.boolean;
		have_https_req = 1;
	}
	json_free(root);

	if (!want_http && !want_https) {
		respond_error(fd, 400, "Bad Request", "refusing to leave both http and https disabled");
		return;
	}

	/*
	 * daemon-config never moves cixd's off-box address (ADR-0287) --
	 * that is PUT /system/management-address. Every rebind here stays on
	 * the current g_bind_addr; only the port can change. The loopback
	 * pair is likewise left where it is.
	 */
	if (want_http) {
		if (g_listener_conn.fd < 0) {
			if (start_http_listener(&g_listener_conn, g_bind_addr, new_port) != 0) {
				respond_error(fd, 500, "Internal Server Error", "could not start http listener");
				return;
			}
			g_port = new_port;
		} else if (rebind_listener(g_bind_addr, new_port) != 0) {
			respond_error(fd, 500, "Internal Server Error", "listener rebind failed");
			return;
		}
	} else if (g_listener_conn.fd >= 0) {
		stop_http_listener();
	}

	if (want_https) {
		if (g_https_listener_conn.fd < 0) {
			if (start_https_listener(&g_https_listener_conn, g_bind_addr, new_https_port) != 0) {
				if (have_https_req) {
					respond_error(fd, 500, "Internal Server Error",
					              "could not start https listener (no usable host cert yet?)");
					return;
				}
				fprintf(stderr,
				        "https_enabled (default) but could not start the HTTPS listener -- "
				        "continuing without it\n");
			}
		} else if (rebind_https_listener(g_bind_addr, new_https_port) != 0) {
			respond_error(fd, 500, "Internal Server Error", "https listener rebind failed");
			return;
		}
	} else if (g_https_listener_conn.fd >= 0) {
		stop_https_listener();
	}

	/* https_enabled persisted before http_enabled deliberately -- see
	 * daemon_config_set_http_enabled()'s own guard. */
	if (have_https_req) {
		derr = daemon_config_set_https_enabled(want_https);
		if (derr != DAEMON_CONFIG_OK) {
			respond_error(fd, 500, "Internal Server Error",
			              "listener(s) changed but could not persist https_enabled");
			return;
		}
	}
	if (have_http_req) {
		derr = daemon_config_set_http_enabled(want_http);
		if (derr != DAEMON_CONFIG_OK) {
			respond_error(fd, 500, "Internal Server Error",
			              "listener(s) changed but could not persist http_enabled");
			return;
		}
	}
	if (have_https_port_req) {
		derr = daemon_config_set_https_port(new_https_port);
		if (derr != DAEMON_CONFIG_OK) {
			respond_error(fd, 500, "Internal Server Error",
			              "listener(s) changed but could not persist https_port");
			return;
		}
	}
	derr = daemon_config_set_port(new_port);
	if (derr != DAEMON_CONFIG_OK) {
		respond_error(fd, 500, "Internal Server Error",
		              "listener rebound but could not persist port");
		return;
	}

	handle_daemon_config_get(fd);
}

/*
 * Writes one cgroup_pressure as {"some":{...},"full":{...}} -- shared
 * by cpu.pressure/io.pressure/memory.pressure in both host and
 * per-container stats, so the shape only needs defining once.
 */
static void write_pressure_json(struct json_writer *w, const struct cgroup_pressure *p)
{
	jw_key(w, "some");
	jw_obj_open(w);
	jw_key(w, "avg10");
	jw_num(w, p->some_avg10);
	jw_key(w, "avg60");
	jw_num(w, p->some_avg60);
	jw_key(w, "avg300");
	jw_num(w, p->some_avg300);
	jw_key(w, "total_usec");
	jw_int(w, p->some_total);
	jw_obj_close(w);
	jw_key(w, "full");
	jw_obj_open(w);
	jw_key(w, "avg10");
	jw_num(w, p->full_avg10);
	jw_key(w, "avg60");
	jw_num(w, p->full_avg60);
	jw_key(w, "avg300");
	jw_num(w, p->full_avg300);
	jw_key(w, "total_usec");
	jw_int(w, p->full_total);
	jw_obj_close(w);
}

static void handle_system_stats(int fd)
{
	struct json_writer w;
	double load1, load5, load15;
	long long cpu_user, cpu_nice, cpu_system, cpu_idle, cpu_iowait, cpu_irq, cpu_softirq, cpu_steal;
	long long mem_total, mem_free, mem_avail, mem_buffers, mem_cached, swap_total, swap_free;
	struct statvfs vfs;
	long long disk_total = 0, disk_free = 0, disk_avail = 0;
	struct cgroup_pressure cpu_pressure, io_pressure, mem_pressure;
	DIR *d;
	struct dirent *ent;

	read_loadavg(&load1, &load5, &load15);
	read_cpu_jiffies(&cpu_user, &cpu_nice, &cpu_system, &cpu_idle, &cpu_iowait,
	                 &cpu_irq, &cpu_softirq, &cpu_steal);
	read_meminfo(&mem_total, &mem_free, &mem_avail, &mem_buffers, &mem_cached,
	             &swap_total, &swap_free);
	if (statvfs(g_base_dir, &vfs) == 0) {
		disk_total = (long long)vfs.f_blocks * vfs.f_frsize;
		disk_free = (long long)vfs.f_bfree * vfs.f_frsize;
		disk_avail = (long long)vfs.f_bavail * vfs.f_frsize;
	}

	memset(&cpu_pressure, 0, sizeof(cpu_pressure));
	memset(&io_pressure, 0, sizeof(io_pressure));
	memset(&mem_pressure, 0, sizeof(mem_pressure));
	{
		/*
		 * Host-wide PSI lives at the cgroup v2 root, not inside any
		 * single leaf -- opened here (O_PATH, no container involved)
		 * rather than threading a root fd through from daemon init,
		 * since this is the only call site that ever needs it.
		 */
		int root_fd = open("/sys/fs/cgroup", O_PATH | O_DIRECTORY);

		if (root_fd >= 0) {
			cgroup_read_pressure(root_fd, "cpu.pressure", &cpu_pressure);
			cgroup_read_pressure(root_fd, "io.pressure", &io_pressure);
			cgroup_read_pressure(root_fd, "memory.pressure", &mem_pressure);
			close(root_fd);
		}
	}

	jw_init(&w);
	jw_obj_open(&w);

	jw_key(&w, "uptime");
	jw_obj_open(&w);
	jw_key(&w, "host_seconds");
	jw_int(&w, read_host_uptime_seconds());
	jw_key(&w, "daemon_seconds");
	jw_int(&w, (long long)(time(NULL) - g_daemon_started_at));
	jw_obj_close(&w);
	jw_key(&w, "load");
	jw_obj_open(&w);
	jw_key(&w, "load1");
	jw_num(&w, load1);
	jw_key(&w, "load5");
	jw_num(&w, load5);
	jw_key(&w, "load15");
	jw_num(&w, load15);
	jw_obj_close(&w);

	jw_key(&w, "cpu");
	jw_obj_open(&w);
	jw_key(&w, "user_jiffies");
	jw_int(&w, cpu_user);
	jw_key(&w, "nice_jiffies");
	jw_int(&w, cpu_nice);
	jw_key(&w, "system_jiffies");
	jw_int(&w, cpu_system);
	jw_key(&w, "idle_jiffies");
	jw_int(&w, cpu_idle);
	jw_key(&w, "iowait_jiffies");
	jw_int(&w, cpu_iowait);
	jw_key(&w, "irq_jiffies");
	jw_int(&w, cpu_irq);
	jw_key(&w, "softirq_jiffies");
	jw_int(&w, cpu_softirq);
	jw_key(&w, "steal_jiffies");
	jw_int(&w, cpu_steal);
	jw_key(&w, "pressure");
	jw_obj_open(&w);
	write_pressure_json(&w, &cpu_pressure);
	jw_obj_close(&w);
	jw_obj_close(&w);

	jw_key(&w, "memory");
	jw_obj_open(&w);
	jw_key(&w, "total_bytes");
	jw_int(&w, mem_total);
	jw_key(&w, "free_bytes");
	jw_int(&w, mem_free);
	jw_key(&w, "available_bytes");
	jw_int(&w, mem_avail);
	jw_key(&w, "buffers_bytes");
	jw_int(&w, mem_buffers);
	jw_key(&w, "cached_bytes");
	jw_int(&w, mem_cached);
	jw_key(&w, "swap_total_bytes");
	jw_int(&w, swap_total);
	jw_key(&w, "swap_free_bytes");
	jw_int(&w, swap_free);
	jw_key(&w, "pressure");
	jw_obj_open(&w);
	write_pressure_json(&w, &mem_pressure);
	jw_obj_close(&w);
	jw_obj_close(&w);

	/*
	 * The workload parent's own memory, beside the host's (#279).
	 *
	 * Both numbers are true at once and only one of them was ever
	 * reported, which is how a live OOM presented as a healthy,
	 * mostly-idle machine: the host had 5.88 GB available while
	 * cix-workload/cix-pkgbuild sat pinned at its 2 GiB ceiling,
	 * OOM-killing continuously. An operator watching this endpoint saw
	 * the first number and had no way to reach the second.
	 *
	 * usage_bytes against limit_bytes is the pair that answers "is
	 * something at its ceiling", and memory.pressure is what says it is
	 * hurting rather than merely close. limit_bytes is -1 when the
	 * parent is unlimited ("max"), which is the default: a null would
	 * read as "unknown" when it means "no ceiling to hit".
	 *
	 * Absent entirely rather than zeroed when the cgroup does not exist
	 * -- on a host that has never started a workload there is no
	 * ceiling to report, and zeroes there would look like a workload
	 * pinned at nothing.
	 */
	{
		char wpath[64];
		int wfd;

		snprintf(wpath, sizeof(wpath), "/sys/fs/cgroup/%s", CGROUP_WORKLOAD_PARENT);
		wfd = open(wpath, O_PATH | O_DIRECTORY);
		if (wfd >= 0) {
			long long wcur = 0, wpeak = 0, wmax = 0;
			int wcur_unlimited = 0, wpeak_unlimited = 0, wmax_unlimited = 0;
			struct cgroup_pressure wpressure;

			memset(&wpressure, 0, sizeof(wpressure));
			cgroup_read_single_value(wfd, "memory.current", &wcur, &wcur_unlimited);
			cgroup_read_single_value(wfd, "memory.peak", &wpeak, &wpeak_unlimited);
			cgroup_read_single_value(wfd, "memory.max", &wmax, &wmax_unlimited);
			cgroup_read_pressure(wfd, "memory.pressure", &wpressure);
			close(wfd);

			jw_key(&w, "workload_memory");
			jw_obj_open(&w);
			jw_key(&w, "cgroup");
			jw_str(&w, CGROUP_WORKLOAD_PARENT);
			jw_key(&w, "usage_bytes");
			jw_int(&w, wcur);
			jw_key(&w, "peak_bytes");
			jw_int(&w, wpeak);
			jw_key(&w, "limit_bytes");
			jw_int(&w, wmax_unlimited ? -1 : wmax);
			jw_key(&w, "pressure");
			jw_obj_open(&w);
			write_pressure_json(&w, &wpressure);
			jw_obj_close(&w);
			jw_obj_close(&w);
		}
	}

	jw_key(&w, "disk");
	jw_obj_open(&w);
	jw_key(&w, "total_bytes");
	jw_int(&w, disk_total);
	jw_key(&w, "free_bytes");
	jw_int(&w, disk_free);
	jw_key(&w, "avail_bytes");
	jw_int(&w, disk_avail);
	jw_key(&w, "pressure");
	jw_obj_open(&w);
	write_pressure_json(&w, &io_pressure);
	jw_obj_close(&w);
	jw_obj_close(&w);

	jw_key(&w, "networks");
	jw_arr_open(&w);
	d = opendir("/sys/class/net");
	if (d != NULL) {
		while ((ent = readdir(d)) != NULL) {
			if (ent->d_name[0] == '.')
				continue;
			jw_obj_open(&w);
			jw_key(&w, "name");
			jw_str(&w, ent->d_name);
			jw_key(&w, "rx_bytes");
			jw_int(&w, read_net_stat(ent->d_name, "rx_bytes"));
			jw_key(&w, "tx_bytes");
			jw_int(&w, read_net_stat(ent->d_name, "tx_bytes"));
			jw_key(&w, "rx_packets");
			jw_int(&w, read_net_stat(ent->d_name, "rx_packets"));
			jw_key(&w, "tx_packets");
			jw_int(&w, read_net_stat(ent->d_name, "tx_packets"));
			jw_obj_close(&w);
		}
		closedir(d);
	}
	jw_arr_close(&w);

	jw_obj_close(&w);
	respond_json(fd, 200, "OK", &w);
	jw_free(&w);
}

/* GET/DELETE /v1/system/processes (logging/web-UI epic Part 6,
 * ADR-0131): a real, direct /proc scan of every process on the box,
 * correlated to a container by hostproc.c's own ppid-chain walk. */
/*
 * GET /v1/system/server-health (issue #81) -- every registered server of
 * every kind, with its live health, whether it is in service, and how it
 * was probed.
 */
/*
 * Issue #83: health can only ever describe servers Cix KNOWS about, so
 * an unregistered one is invisible to it by construction -- which is
 * exactly how a real box ran for its whole life with DNS records that
 * resolved nothing, because dns-1/dns-2 were never registered and
 * dns_record_sync_all() only ever writes into registered servers.
 *
 * The precisely detectable version of that failure is "Cix is managing
 * state it has nowhere to deliver": records/accounts exist, zero servers
 * are registered to receive them. Reported as real warnings alongside the
 * health list. Deliberately only for the two subsystems that actually
 * PUSH managed state to their servers -- NTP and syslog have no
 * equivalent stranded state, so inventing a check for them would be
 * noise dressed up as diagnostics.
 */
static void serverhealth_write_warnings(struct json_writer *w)
{
	char names[SERVERHEALTH_MAX][REGISTRY_NAME_MAX];
	char msg[256];
	int records, servers;

	jw_arr_open(w);

	records = dns_record_count();
	servers = dns_server_list_containers(names, SERVERHEALTH_MAX);
	if (records > 0 && servers == 0) {
		snprintf(msg, sizeof(msg),
		         "%d DNS record(s) are managed but no DNS server is registered -- they are "
		         "not being served by anything. Register the container running your resolver "
		         "(POST /v1/dns/servers).",
		         records);
		jw_str(w, msg);
	}

	servers = ldap_server_list_containers(names, SERVERHEALTH_MAX);
	if (servers == 0 && (ldap_user_count() > 0 || ldap_group_count() > 0)) {
		snprintf(msg, sizeof(msg),
		         "LDAP users/groups are managed but no LDAP server is registered -- they are "
		         "not being served by anything. Register the container running your directory "
		         "(POST /v1/ldap/servers).");
		jw_str(w, msg);
	}
	jw_arr_close(w);
}

static void handle_serverhealth_list(int fd)
{
	struct json_writer w;

	jw_init(&w);
	jw_obj_open(&w);
	jw_key(&w, "servers");
	serverhealth_write_json_list(&w);
	jw_key(&w, "warnings");
	serverhealth_write_warnings(&w);
	jw_obj_close(&w);
	respond_json(fd, 200, "OK", &w);
	jw_free(&w);
}

/*
 * PUT /v1/system/server-health/{kind}/{container} -- the operator drain
 * override: {"drained": true|false}. Deliberately separate from the
 * probe's own verdict: draining is an intent ("I am doing maintenance
 * on this one"), which is why it is the one part of a health record that
 * is persisted across a daemon restart.
 */
static void handle_serverhealth_set(int fd, const char *kind, const char *container,
                                     const char *body, size_t body_len)
{
	struct json_value *root = json_parse(body, body_len);
	const struct json_value *jdrained;
	struct json_writer w;

	if (root == NULL) {
		respond_error(fd, 400, "Bad Request", "invalid JSON body");
		return;
	}
	jdrained = json_object_get(root, "drained");
	if (jdrained == NULL || jdrained->type != JSON_BOOL) {
		json_free(root);
		respond_error(fd, 400, "Bad Request", "drained (boolean) is required");
		return;
	}
	if (serverhealth_set_drained(kind, container, jdrained->u.boolean) != 0) {
		json_free(root);
		respond_error(fd, 500, "Internal Server Error", "could not record the drain state");
		return;
	}
	json_free(root);

	jw_init(&w);
	jw_obj_open(&w);
	jw_key(&w, "servers");
	serverhealth_write_json_list(&w);
	jw_obj_close(&w);
	respond_json(fd, 200, "OK", &w);
	jw_free(&w);
}

static void handle_hostproc_list(int fd)
{
	struct json_writer w;

	jw_init(&w);
	hostproc_write_json_list(&w);
	respond_json(fd, 200, "OK", &w);
	jw_free(&w);
}

static void handle_hostproc_kill(int fd, const char *pid_str)
{
	char *endptr;
	long pid;
	enum hostproc_error herr;

	pid = strtol(pid_str, &endptr, 10);
	if (*pid_str == '\0' || *endptr != '\0' || pid <= 0) {
		respond_error(fd, 400, "Bad Request", "pid must be a positive integer");
		return;
	}

	herr = hostproc_kill((pid_t)pid);
	switch (herr) {
	case HOSTPROC_OK:
		http_set_blocking(fd);
		http_write_response(fd, 204, "No Content", "application/json", "", 0);
		break;
	case HOSTPROC_ERR_NOT_FOUND:
		respond_error(fd, 404, "Not Found", "no such pid currently running");
		break;
	case HOSTPROC_ERR_FORBIDDEN:
		respond_error(fd, 400, "Bad Request",
		              "refusing to kill pid 1 or this daemon's own pid");
		break;
	case HOSTPROC_ERR_KILL_FAILED:
		respond_error(fd, 500, "Internal Server Error", "kill(2) failed");
		break;
	}
}

static void handle_list(int fd, const char *path)
{
	struct json_writer w;
	char flag[16];
	int include_internal = 0;
	int hidden = 0;

	/*
	 * #426: the platform's own containers are out by default, in on
	 * request. The filter lives here rather than in each client
	 * because API-First is absolute: a dashboard-side filter would
	 * have given the web a view `cixctl container ls` could not have,
	 * and the definition of "ours" would then exist twice.
	 *
	 * Accepts the spellings a person actually types -- 1/true/yes --
	 * and treats anything else, including a bare ?include_internal=,
	 * as false. A malformed value meaning "show me everything" would
	 * be the wrong way round for a flag whose whole purpose is to
	 * reduce what is shown.
	 */
	if (url_query_param(path, "include_internal", flag, sizeof(flag)) == 0 &&
	    (strcmp(flag, "1") == 0 || strcmp(flag, "true") == 0 || strcmp(flag, "yes") == 0))
		include_internal = 1;

	jw_init(&w);
	jw_obj_open(&w);
	jw_key(&w, "containers");
	registry_write_json_list(&w, include_internal, &hidden);
	/*
	 * How many were left out, so they do not silently vanish. An
	 * operator watching a build who cannot find __pkgbuild-0 should be
	 * told it is hidden and how to ask for it, not left to conclude
	 * the container is gone -- which is exactly the wrong conclusion
	 * to draw while debugging a build.
	 */
	jw_key(&w, "hidden_internal");
	jw_int(&w, hidden);
	jw_obj_close(&w);
	respond_json(fd, 200, "OK", &w);
	jw_free(&w);
}

static void handle_get_one(int fd, const char *name)
{
	struct registry_entry *e = registry_find(name);
	struct json_writer w;

	if (e == NULL) {
		/* Not live -- might still be a kept-but-not-running container
		 * (ADR-0045, extended by ADR-0181's persist-all), same fallback
		 * GET /v1/containers' own list already makes via
		 * containerdef_write_json_inactive_list(). */
		jw_init(&w);
		if (containerdef_write_json_inactive_one(name, &w)) {
			respond_json(fd, 200, "OK", &w);
			jw_free(&w);
			return;
		}
		jw_free(&w);
		respond_error(fd, 404, "Not Found", "no such container");
		return;
	}
	jw_init(&w);
	registry_write_json_one(e, &w);
	respond_json(fd, 200, "OK", &w);
	jw_free(&w);
}

/* ------------------------------------------------------------------ */
/* ADR-0260: cix-init -- staging the binary, wiring its transport,     */
/* reading its reports.                                                */

/*
 * Where this daemon's own cix-init lives: beside its own executable.
 * /bin/cixd finds /bin/cix-init on an installed host; a test's
 * build/cixd finds build/cix-init. One rule, no flag, and a daemon can
 * only ever stage the cix-init it shipped with.
 */
static int stage_container_bytes(const char *upperdir, const char *path, const void *content,
                                  size_t content_len, mode_t mode, uid_t owner, gid_t group,
                                  uid_t id_offset);

/*
 * Where cix-init lands INSIDE a container, as one definition.
 *
 * It is named twice -- once staging the bytes, once as argv[0] of pid
 * 1 -- and the two must agree or every container on the host fails to
 * start, so they are not allowed to be two literals that a future edit
 * could move independently.
 *
 * /sbin rather than the root directory: it is a system binary and
 * belongs where system binaries go. stage_container_bytes() runs
 * persist_mkdir_p() on the parent, so an image with no /sbin of its
 * own gets one; on an image that has a real /sbin, overlayfs merges
 * with it rather than replacing it.
 */
#define CIX_INIT_CONTAINER_PATH "/sbin/cix-init"

static const char *cix_init_source_path(void)
{
	static char path[PATH_MAX];
	static int resolved;

	if (!resolved) {
		char exe[PATH_MAX];
		ssize_t n = readlink("/proc/self/exe", exe, sizeof(exe) - 1);
		char *slash;

		if (n <= 0)
			return NULL;
		exe[n] = '\0';
		slash = strrchr(exe, '/');
		if (slash == NULL)
			return NULL;
		*slash = '\0';
		if (snprintf(path, sizeof(path), "%s/cix-init", exe) >= (int)sizeof(path))
			return NULL;
		resolved = 1;
	}
	return path;
}

/*
 * Stages cix-init into a container's tree at creation time (at
 * CIX_INIT_CONTAINER_PATH), through
 * the same helper files[] uses so the direct-rootfs and id-mapped
 * cases are inherited rather than re-derived. Not at image-seed time:
 * ADR-0155's manifest-hash dedup would discard a reseed, and a
 * container must run the cix-init its own daemon shipped with.
 */
static int stage_cix_init(const char *upperdir, uid_t id_offset, char *err, size_t err_size)
{
	const char *src = cix_init_source_path();
	int fd;
	struct stat st;
	char *buf;
	ssize_t got;
	int rc;

	if (src == NULL || (fd = open(src, O_RDONLY | O_CLOEXEC)) < 0) {
		snprintf(err, err_size, "cix-init is not beside this daemon's executable (%s)",
		         src != NULL ? src : "unresolvable");
		return -1;
	}
	if (fstat(fd, &st) != 0 || !S_ISREG(st.st_mode) || st.st_size <= 0 || st.st_size > (1 << 20)) {
		close(fd);
		snprintf(err, err_size, "cix-init at %s is not a plausible binary", src);
		return -1;
	}
	buf = malloc((size_t)st.st_size);
	if (buf == NULL) {
		close(fd);
		snprintf(err, err_size, "out of memory staging cix-init");
		return -1;
	}
	got = read(fd, buf, (size_t)st.st_size);
	close(fd);
	if (got != (ssize_t)st.st_size) {
		free(buf);
		snprintf(err, err_size, "short read of %s", src);
		return -1;
	}
	rc = stage_container_bytes(upperdir, CIX_INIT_CONTAINER_PATH, buf, (size_t)st.st_size, 0755,
	                            (uid_t)-1,
	                            (gid_t)-1, id_offset);
	free(buf);
	if (rc != 0) {
		snprintf(err, err_size, "failed to stage %s: %s", CIX_INIT_CONTAINER_PATH,
		          strerror(errno));
		return -1;
	}
	return 0;
}

/*
 * The fds a container's cix-init is handed: both ends of two
 * SOCK_SEQPACKET pairs and one pipe per service, every one of them
 * close-on-exec (the child switches its own back, src/container.c).
 * The parent's ends are non-blocking; a reactor never blocks (ADR-0247).
 */
struct init_transport {
	int ctl[2];                        /* [0] daemon, [1] cix-init */
	int rep[2];                        /* [0] daemon, [1] cix-init */
	int out[CIXINIT_MAX_SERVICES][2];  /* [0] daemon reads, [1] the service writes */
	int count;
	char argv_store[2 + CIXINIT_MAX_SERVICES][16];
	char *argv[4 + CIXINIT_MAX_SERVICES];
};

static void init_transport_init(struct init_transport *t)
{
	int k;

	memset(t, 0, sizeof(*t));
	t->ctl[0] = t->ctl[1] = t->rep[0] = t->rep[1] = -1;
	for (k = 0; k < CIXINIT_MAX_SERVICES; k++)
		t->out[k][0] = t->out[k][1] = -1;
}

static void close_if_open(int *fd)
{
	if (*fd >= 0) {
		close(*fd);
		*fd = -1;
	}
}

/* The child's ends, once the child has them (or never will). */
static void init_transport_close_child_ends(struct init_transport *t)
{
	int k;

	close_if_open(&t->ctl[1]);
	close_if_open(&t->rep[1]);
	for (k = 0; k < t->count; k++)
		close_if_open(&t->out[k][1]);
}

static void init_transport_close_all(struct init_transport *t)
{
	int k;

	init_transport_close_child_ends(t);
	close_if_open(&t->ctl[0]);
	close_if_open(&t->rep[0]);
	for (k = 0; k < t->count; k++)
		close_if_open(&t->out[k][0]);
}

/*
 * Creates the sockets and pipes, writes the table into the control
 * socket before there is a child to read it (the socket buffer is
 * sized to hold all of it), and fills spec->argv and spec->keep_fds.
 * shared_out, when >= 0, is used as every service's output fd instead
 * of a pipe per service -- the build container's shape, where the
 * build log pipe already exists and the one service writes to it.
 */
static int init_transport_open(struct init_transport *t, const struct cixinit_table *table,
                               int shared_out, struct container_spec *spec, char *err,
                               size_t err_size)
{
	int so = (int)cixinit_table_socket_bytes(table) + 4096;
	int k, argn = 0;

	init_transport_init(t);
	t->count = table->count;
	if (socketpair(AF_UNIX, SOCK_SEQPACKET | SOCK_CLOEXEC, 0, t->ctl) != 0 ||
	    socketpair(AF_UNIX, SOCK_SEQPACKET | SOCK_CLOEXEC, 0, t->rep) != 0) {
		snprintf(err, err_size, "cannot create cix-init's sockets: %s", strerror(errno));
		init_transport_close_all(t);
		return -1;
	}
	(void)setsockopt(t->ctl[0], SOL_SOCKET, SO_SNDBUF, &so, sizeof(so));
	(void)setsockopt(t->ctl[1], SOL_SOCKET, SO_RCVBUF, &so, sizeof(so));
	(void)fcntl(t->ctl[0], F_SETFL, O_NONBLOCK);
	(void)fcntl(t->rep[0], F_SETFL, O_NONBLOCK);
	if (shared_out < 0) {
		for (k = 0; k < t->count; k++) {
			if (pipe2(t->out[k], O_CLOEXEC) != 0) {
				snprintf(err, err_size, "cannot create a service output pipe: %s", strerror(errno));
				init_transport_close_all(t);
				return -1;
			}
			(void)fcntl(t->out[k][0], F_SETFL, O_NONBLOCK);
		}
	}
	if (cixinit_table_send(table, t->ctl[0]) != 0) {
		snprintf(err, err_size, "cannot hand cix-init its table: %s", strerror(errno));
		init_transport_close_all(t);
		return -1;
	}

	t->argv[argn++] = (char *)CIX_INIT_CONTAINER_PATH;
	snprintf(t->argv_store[0], sizeof(t->argv_store[0]), "%d", t->ctl[1]);
	t->argv[argn++] = t->argv_store[0];
	snprintf(t->argv_store[1], sizeof(t->argv_store[1]), "%d", t->rep[1]);
	t->argv[argn++] = t->argv_store[1];
	spec->keep_fd_count = 0;
	spec->keep_fds[spec->keep_fd_count++] = t->ctl[1];
	spec->keep_fds[spec->keep_fd_count++] = t->rep[1];
	for (k = 0; k < t->count; k++) {
		int fd = shared_out >= 0 ? shared_out : t->out[k][1];

		snprintf(t->argv_store[2 + k], sizeof(t->argv_store[2 + k]), "%d", fd);
		t->argv[argn++] = t->argv_store[2 + k];
		if (shared_out < 0 || k == 0)
			spec->keep_fds[spec->keep_fd_count++] = fd;
	}
	t->argv[argn] = NULL;
	spec->argv = t->argv;
	return 0;
}

static void container_init_log_report(struct registry_entry *entry, const struct cixinit_report *r)
{
	const char *svc = (r->service >= 0 && r->service < entry->service_count)
	                      ? entry->services[r->service].def.name
	                      : "cix-init";


	switch (r->event) {
	case CIXINIT_EV_UP:
		logstore_write_container(entry->name, "info", "cix-init up, %d service(s)", r->b);
		/*
		 * ADR-0262: and now that pid 1 is talking to us, its mount
		 * table is certainly finished -- the first moment the procfuse
		 * binds can be counted truthfully. Counting them at creation
		 * reads a mount namespace the child is still building.
		 *
		 * Reported here so the answer is in the log without anyone
		 * having to ask. A container short of its binds still runs; it
		 * reads the HOST's /proc for the files it did not get, which
		 * is a wrong answer to "how much memory do I have", not a
		 * missing feature.
		 */
		if (entry->procfuse_expected > 0) {
			int bound = registry_procfuse_bound(entry);

			if (bound == entry->procfuse_expected) {
				logstore_write_container(entry->name, "info",
				                          "procfuse: %d/%d files bound", bound,
				                          entry->procfuse_expected);
			} else if (bound < 0) {
				logstore_write_container(entry->name, "error",
				                          "procfuse: cannot read the mount table to confirm "
				                          "%d expected binds", entry->procfuse_expected);
			} else {
				logstore_write_container(entry->name, "error",
				                          "procfuse: only %d of %d files bound -- this container "
				                          "reads the host's /proc for the rest", bound,
				                          entry->procfuse_expected);
			}
		}
		break;
	case CIXINIT_EV_STARTED:
		logstore_write_container(entry->name, "info", "service %s started, pid %d", svc, r->a);
		break;
	case CIXINIT_EV_READY:
		logstore_write_container(entry->name, "info", "service %s ready%s", svc,
		                         r->a == 1 ? " (probe timed out; proceeding)" : "");
		break;
	case CIXINIT_EV_EXITED:
		logstore_write_container(entry->name, r->a == CIXINIT_EXIT_KIND_EXITED && r->b == 0 ? "info" : "warn",
		                         "service %s %s %d", svc,
		                         r->a == CIXINIT_EXIT_KIND_EXITED ? "exited with status" : "killed by signal",
		                         r->b);
		break;
	case CIXINIT_EV_RESTART_IN:
		logstore_write_container(entry->name, "warn", "service %s restarting in %ds (restart %d)", svc,
		                         r->a, r->b);
		break;
	case CIXINIT_EV_STOPPED:
		logstore_write_container(entry->name, "info", "service %s stopped by operator", svc);
		break;
	case CIXINIT_EV_FAILED:
		logstore_write_container(entry->name, "error", "service %s failed: %s (%d)", svc,
		                         r->a == CIXINIT_FAIL_PROBE ? "ready probe timed out"
		                         : r->a == CIXINIT_FAIL_ONESHOT ? "oneshot exited non-zero"
		                         : r->a == CIXINIT_FAIL_SPAWN ? "fork failed"
		                         : r->a == CIXINIT_FAIL_DEPENDENCY ? "a service it is after can never be ready"
		                         : "unknown reason",
		                         r->b);
		break;
	case CIXINIT_EV_SHUTDOWN:
		logstore_write_container(entry->name, "info", r->a == 0 ? "cix-init: shutdown begins"
		                                                        : "cix-init: shutdown complete");
		break;
	default:
		break;
	}
}

/*
 * Drains cix-init's report socket. Returns 0 while the socket is open,
 * 1 once cix-init has closed it (it only does that by exiting).
 */
static int container_init_pump(struct registry_entry *entry, int fd)
{
	for (;;) {
		struct cixinit_report r;
		ssize_t n = recv(fd, &r, sizeof(r), MSG_DONTWAIT);

		if (n < 0) {
			if (errno == EINTR)
				continue;
			return 0; /* EAGAIN: drained */
		}
		if (n == 0)
			return 1;
		if (n != (ssize_t)sizeof(r))
			continue; /* a short record cannot be interpreted */
		if (!entry->in_use || entry->init_report_fd != fd)
			continue;
		container_init_log_report(entry, &r);
		registry_apply_init_report(entry, &r);
	}
}

static void handle_container_init_event(struct conn *cc)
{
	struct registry_entry *entry = cc->entry;

	if (container_init_pump(entry, cc->fd)) {
		cix_epoll_ctl(g_epfd, EPOLL_CTL_DEL, cc->fd, NULL);
		close(cc->fd);
		if (entry->init_report_fd == cc->fd)
			entry->init_report_fd = -1;
		free(cc);
	}
}

static void register_container_init(struct registry_entry *entry)
{
	struct conn *cc;
	struct cix_epoll_event ev;

	if (entry->init_report_fd < 0)
		return;
	cc = calloc(1, sizeof(*cc));
	if (cc == NULL) {
		perror("malloc (container init reactor conn)");
		abort();
	}
	cc->kind = CONN_CONTAINER_INIT;
	cc->fd = entry->init_report_fd;
	cc->entry = entry;
	memset(&ev, 0, sizeof(ev));
	ev.events = EPOLLIN;
	ev.data.ptr = cc;
	if (cix_epoll_ctl(g_epfd, EPOLL_CTL_ADD, cc->fd, &ev) != 0) {
		perror("epoll_ctl ADD container init fd");
		abort();
	}
}

/* Sends one command to a container's cix-init. 0, or -1 with errno. */
static int container_init_command(struct registry_entry *entry, int op, int service)
{
	struct cixinit_command c;

	if (entry->init_control_fd < 0) {
		errno = ENOTCONN;
		return -1;
	}
	memset(&c, 0, sizeof(c));
	c.magic = CIXINIT_MAGIC;
	c.op = op;
	c.service = service;
	return send(entry->init_control_fd, &c, sizeof(c), MSG_DONTWAIT | MSG_NOSIGNAL) == (ssize_t)sizeof(c)
	           ? 0
	           : -1;
}

/*
 * How long a container is given to stop on its own before SIGKILL:
 * the longest declared per-service stop timeout, plus a margin for
 * cix-init to work through the graph.
 */
static int container_stop_grace_seconds(const struct registry_entry *entry)
{
	int i, grace = 10;

	for (i = 0; i < entry->service_count; i++)
		if (entry->services[i].def.stop_timeout_seconds > grace)
			grace = entry->services[i].def.stop_timeout_seconds;
	return grace + 5;
}

/*
 * Autostart's wait for a container to become ready, on the same
 * reports the reactor will consume once it runs: this is called before
 * the event loop starts, so the socket is pumped here. Returns 1 when
 * ready, 0 on timeout or when cix-init went away.
 */
static int wait_for_container_ready(struct registry_entry *entry, int timeout_seconds)
{
	time_t deadline = time(NULL) + timeout_seconds;

	while (!entry->ready) {
		struct pollfd p;
		long left = (long)(deadline - time(NULL));
		int rc;

		if (left <= 0 || entry->init_report_fd < 0)
			return entry->ready;
		p.fd = entry->init_report_fd;
		p.events = POLLIN;
		p.revents = 0;
		rc = poll(&p, 1, (int)(left * 1000 > 250 ? 250 : left * 1000));
		if (rc < 0 && errno != EINTR)
			return entry->ready;
		if (rc > 0 && container_init_pump(entry, entry->init_report_fd)) {
			/* cix-init exited; the reactor's own conn will see the EOF too. */
			return entry->ready;
		}
	}
	return 1;
}

static int container_ready_timeout_seconds(const struct registry_entry *entry)
{
	int i, t = 5;

	for (i = 0; i < entry->service_count; i++)
		if (entry->services[i].def.ready_timeout_seconds > t)
			t = entry->services[i].def.ready_timeout_seconds;
	return t + 5;
}

/*
 * ADR-0260: a stop is SIGTERM to cix-init, which stops the services in
 * reverse dependency order, and SIGKILL only if that has not finished
 * within the container's grace. This timer is the escalation.
 */
static void arm_stop_escalation_timer(struct registry_entry *entry)
{
	int tfd;
	struct itimerspec its;
	struct conn *cc;
	struct cix_epoll_event ev;

	tfd = timerfd_create(CLOCK_MONOTONIC, TFD_NONBLOCK | TFD_CLOEXEC);
	if (tfd < 0) {
		perror("timerfd_create (stop escalation)");
		return;
	}
	memset(&its, 0, sizeof(its));
	its.it_value.tv_sec = container_stop_grace_seconds(entry);
	if (timerfd_settime(tfd, 0, &its, NULL) != 0) {
		perror("timerfd_settime (stop escalation)");
		close(tfd);
		return;
	}
	cc = calloc(1, sizeof(*cc));
	if (cc == NULL) {
		perror("malloc (stop escalation timer conn)");
		close(tfd);
		return;
	}
	cc->kind = CONN_STOP_ESCALATE_TIMER;
	cc->fd = tfd;
	snprintf(cc->restart_name, sizeof(cc->restart_name), "%s", entry->name);
	cc->escalate_started_at = entry->started_at;
	memset(&ev, 0, sizeof(ev));
	ev.events = EPOLLIN;
	ev.data.ptr = cc;
	if (cix_epoll_ctl(g_epfd, EPOLL_CTL_ADD, tfd, &ev) != 0) {
		perror("epoll_ctl ADD stop escalation timer");
		close(tfd);
		free(cc);
	}
}

static void handle_stop_escalation_timer_event(struct conn *cc)
{
	uint64_t expirations;
	struct registry_entry *e;

	if (read(cc->fd, &expirations, sizeof(expirations)) < 0)
		perror("read (stop escalation timerfd)");
	cix_epoll_ctl(g_epfd, EPOLL_CTL_DEL, cc->fd, NULL);
	close(cc->fd);

	e = registry_find(cc->restart_name);
	if (e != NULL && e->in_use && e->running && e->teardown_kind != REGISTRY_TEARDOWN_NONE &&
	    e->started_at == cc->escalate_started_at) {
		logstore_write("cixd", "warn",
		               "container %s did not stop within its grace -- SIGKILL to pid 1", e->name);
		fprintf(stderr, "%s: did not stop within its grace -- SIGKILL to pid 1\n", e->name);
		sys_pidfd_send_signal(e->handle.pidfd, SIGKILL);
	}
	free(cc);
}

/*
 * ADR-0260: stopping a container is a message first and a signal
 * second, and the order is load-bearing.
 *
 * A signal is not enough on its own. pid 1 of a PID namespace is
 * SIGNAL_UNKILLABLE: the kernel DISCARDS any signal it has no handler
 * installed for -- it is not queued and not delivered later. So a
 * SIGTERM that arrives in the window between execve() and cix-init's
 * own install_signal() is simply gone, and the container then sits
 * until the SIGKILL escalation. That is not theoretical: a container
 * created and deleted a few milliseconds apart hit it every run, and
 * it was measured directly (a pidns init that installs its handler
 * 300ms late never sees the signal at all).
 *
 * CIXINIT_OP_SHUTDOWN has no such window. It waits in the control
 * socket's buffer and is read the moment cix-init reaches its loop,
 * whether that is before or after the daemon sent it. The signal stays
 * as the fallback for a cix-init that has stopped reading, and for any
 * container whose pid 1 is not cix-init at all.
 */
static void begin_container_stop(struct registry_entry *e, int teardown_kind)
{
	int grace = container_stop_grace_seconds(e);
	int told = container_init_command(e, CIXINIT_OP_SHUTDOWN, 0) == 0;

	registry_begin_kill(e, teardown_kind);
	arm_stop_escalation_timer(e);
	/*
	 * A container's stop is now a conversation with its pid 1 rather
	 * than a SIGKILL, so how long it takes is a real, variable thing an
	 * operator can be waiting on -- and until this line the only trace
	 * of it anywhere was the container's status flipping to "stopping".
	 */
	fprintf(stderr, "%s: %s -- %s, SIGKILL in %ds if it has not gone\n", e->name,
	        teardown_kind == REGISTRY_TEARDOWN_DELETE ? "deleting" : "stopping",
	        told ? "shutdown asked of cix-init, SIGTERM alongside it"
	             : "SIGTERM only (no control socket)",
	        grace);
}

static void register_container_pidfd(struct registry_entry *entry)
{
	struct conn *cc;
	struct cix_epoll_event ev;

	cc = calloc(1, sizeof(*cc));
	if (cc == NULL) {
		/*
		 * The container is already running with real resources
		 * committed; failing to register its pidfd would leave it
		 * permanently stuck reporting "running" even after it
		 * exits. Under this kind of memory pressure the daemon is
		 * already in a bad state, so fail loudly rather than carry
		 * a silently-wrong registry entry forever.
		 */
		perror("malloc (container reactor conn)");
		abort();
	}
	cc->kind = CONN_CONTAINER;
	cc->fd = entry->handle.pidfd;
	cc->entry = entry;
	entry->reactor_conn = cc;

	memset(&ev, 0, sizeof(ev));
	ev.events = EPOLLIN;
	ev.data.ptr = cc;
	if (cix_epoll_ctl(g_epfd, EPOLL_CTL_ADD, cc->fd, &ev) != 0) {
		perror("epoll_ctl ADD pidfd");
		abort();
	}
}

/*
 * Same shape as register_container_pidfd(), for a plain fork()'d
 * subprocess instead of a clone3()'d container -- Phase 10's package
 * fetch step (a `curl` subprocess) needs the exact same non-blocking
 * "tell me via epoll when this exits" treatment a container's own
 * CLONE_PIDFD-obtained pidfd already gets, via the explicit
 * sys_pidfd_open() equivalent for an already-forked pid.
 */
static void register_pkg_fetch_pidfd(pid_t pid, int pidfd, int chain_idx)
{
	struct conn *cc;
	struct cix_epoll_event ev;

	cc = calloc(1, sizeof(*cc));
	if (cc == NULL) {
		perror("malloc (pkg fetch reactor conn)");
		abort();
	}
	cc->kind = CONN_PKG_FETCH;
	cc->fd = pidfd;
	cc->pkg_fetch_pid = pid;
	cc->pkg_chain_idx = chain_idx;

	memset(&ev, 0, sizeof(ev));
	ev.events = EPOLLIN;
	ev.data.ptr = cc;
	if (cix_epoll_ctl(g_epfd, EPOLL_CTL_ADD, cc->fd, &ev) != 0) {
		perror("epoll_ctl ADD pkg fetch pidfd");
		abort();
	}
}

/*
 * The same treatment for the build-environment composition child
 * (#238). Composition is filesystem work with a clear start and end
 * that touches no daemon state until it finishes, which is exactly the
 * shape the fetch child already had -- so it gets the same fork, the
 * same pidfd, and the same "tell me via epoll when it exits" handling,
 * rather than running inline and making every other request wait.
 */
static void register_pkg_buildenv_pidfd(pid_t pid, int pidfd, int chain_idx)
{
	struct conn *cc;
	struct cix_epoll_event ev;

	cc = calloc(1, sizeof(*cc));
	if (cc == NULL) {
		perror("malloc (pkg buildenv reactor conn)");
		abort();
	}
	cc->kind = CONN_PKG_BUILDENV;
	cc->fd = pidfd;
	cc->pkg_fetch_pid = pid;
	cc->pkg_chain_idx = chain_idx;

	memset(&ev, 0, sizeof(ev));
	ev.events = EPOLLIN;
	ev.data.ptr = cc;
	if (cix_epoll_ctl(g_epfd, EPOLL_CTL_ADD, cc->fd, &ev) != 0) {
		perror("epoll_ctl ADD pkg buildenv pidfd");
		abort();
	}
}

/* Forward declaration -- defined later in this file (Part 5, ADR-0124);
 * called from try_start_queued_pkg_rebuild() below, which several
 * earlier call sites already depend on. */
static void apply_rolling_container_restarts(void);
static void apply_pending_deployments(void); /* ADR-0270 */

/*
 * ADR-0107: called at every point a completed/failed pkg job might
 * have just freed pkg.c's own single-job-in-flight slot -- tries to
 * start whatever rolling-image rebuild is queued (pkg_recipe_add()'s
 * own trigger), registering its pidfd exactly like a fresh top-level
 * install already does if one actually started. A no-op (returns
 * immediately, no epoll registration) when the queue is empty or a
 * job is somehow already running -- safe to call unconditionally
 * after every job-completion path rather than threading a "did this
 * really free the slot" condition through each call site.
 *
 * Also runs apply_rolling_container_restarts() (Part 5, ADR-0124):
 * this same "a pkg job just finished" moment is exactly when an
 * image's current_version might have just moved (a rolling rebuild
 * completing is itself one more pkg job), so it's the natural single
 * hook for reconciling any follow_rolling container against it too --
 * one call site, not two independently-triggered mechanisms.
 */
static void try_start_queued_pkg_rebuild(void)
{
	pid_t pkg_pid;
	int pkg_pidfd;
	int pkg_chain_idx;

	if (pkg_try_start_queued_rebuild(&pkg_pid, &pkg_pidfd, &pkg_chain_idx))
		register_pkg_fetch_pidfd(pkg_pid, pkg_pidfd, pkg_chain_idx);
	report_default_image_seed_result(); /* #189 -- says once when the default image became runnable */
	apply_rolling_container_restarts();
	apply_pending_deployments(); /* ADR-0270 -- same moment, same reason */
}

/*
 * ADR-0087: registers pkg.c's own build-output capture pipe (see
 * pkg_build_output_fd()) directly with epoll, watching the pipe's fd
 * itself rather than a pidfd -- the CONN_KMSG pattern (start_kmsg_
 * watch()/handle_kmsg_event()), not the pidfd-then-single-read pattern
 * every other CONN_* kind above uses. This is deliberate: the build
 * container's own exit is already tracked separately via
 * register_container_pidfd()'s own CONN_CONTAINER registration for
 * PKG_BUILD_CONTAINER_NAME; this conn's only job is draining the
 * output pipe live, as data arrives, so it never fills its 64KB
 * kernel buffer and deadlocks the still-running build. No-op if
 * output_fd is -1 (pipe2() itself failed at build-spawn time, or no
 * build is in flight).
 */
static void register_pkg_build_output(int output_fd, int chain_idx)
{
	struct conn *cc;
	struct cix_epoll_event ev;

	if (output_fd < 0)
		return;

	cc = calloc(1, sizeof(*cc));
	if (cc == NULL) {
		perror("malloc (pkg build output reactor conn)");
		abort();
	}
	cc->kind = CONN_PKG_BUILD_OUTPUT;
	cc->fd = output_fd;
	cc->pkg_chain_idx = chain_idx;

	memset(&ev, 0, sizeof(ev));
	ev.events = EPOLLIN;
	ev.data.ptr = cc;
	if (cix_epoll_ctl(g_epfd, EPOLL_CTL_ADD, cc->fd, &ev) != 0) {
		perror("epoll_ctl ADD pkg build output fd");
		abort();
	}
}

/*
 * task #676: clients live-tailing the in-flight build's own output
 * over GET /v1/pkg/build/log (try_pkg_build_log_upgrade() below) --
 * a small fixed table, same "one build in flight at a time" invariant
 * pkg.c's own module-level build state already relies on, generous
 * enough for a few operators watching the same build at once.
 */
#define PKG_BUILD_LOG_WS_MAX 4
static struct conn *g_build_log_ws_conns[PKG_BUILD_LOG_WS_MAX];
static int g_build_log_ws_conn_count;

static void build_log_ws_detach(struct conn *cc)
{
	int i;

	for (i = 0; i < g_build_log_ws_conn_count; i++) {
		if (g_build_log_ws_conns[i] != cc)
			continue;
		g_build_log_ws_conns[i] = g_build_log_ws_conns[g_build_log_ws_conn_count - 1];
		g_build_log_ws_conn_count--;
		return;
	}
}

/* Sends a chunk of newly-drained build output to every attached
 * live-tail client watching THIS chain (ADR-0157 Phase 2 -- a client
 * watching a different concurrent build must never see another
 * build's output). A write failure just detaches that one client
 * (its own next epoll event, or this immediate teardown, reflects a
 * gone-away peer) -- never lets one broken viewer affect the others
 * or the build itself, which never blocks on this at all. */
static void build_log_ws_broadcast(int chain_idx, const void *data, size_t len)
{
	int i;

	for (i = 0; i < g_build_log_ws_conn_count;) {
		struct conn *cc = g_build_log_ws_conns[i];

		if (cc->pkg_chain_idx != chain_idx) {
			i++;
			continue;
		}
		if (ws_write_frame(cc->fd, WS_OPCODE_TEXT, data, len) != 0) {
			cix_epoll_ctl(g_epfd, EPOLL_CTL_DEL, cc->fd, NULL);
			ws_conn_free(&cc->ws);
			close(cc->fd);
			g_build_log_ws_conns[i] = g_build_log_ws_conns[g_build_log_ws_conn_count - 1];
			g_build_log_ws_conn_count--;
			free(cc);
			continue;
		}
		i++;
	}
}

/* Called once THIS chain's build output pipe reaches EOF (that chain's
 * build finished, one way or another) -- tells every still-attached
 * live-tail client watching that same chain the stream is over via a
 * real WS close frame, then tears each one down. Without this a client
 * would just hang waiting for more output that will never come. Only
 * touches conns watching chain_idx -- a client attached to a different,
 * still-running concurrent build is left alone. */
static void build_log_ws_teardown_all(int chain_idx)
{
	int i;

	for (i = 0; i < g_build_log_ws_conn_count;) {
		struct conn *cc = g_build_log_ws_conns[i];

		if (cc->pkg_chain_idx != chain_idx) {
			i++;
			continue;
		}
		ws_write_frame(cc->fd, WS_OPCODE_CLOSE, NULL, 0);
		cix_epoll_ctl(g_epfd, EPOLL_CTL_DEL, cc->fd, NULL);
		ws_conn_free(&cc->ws);
		close(cc->fd);
		free(cc);
		g_build_log_ws_conns[i] = g_build_log_ws_conns[g_build_log_ws_conn_count - 1];
		g_build_log_ws_conn_count--;
	}
}

/*
 * Fires whenever pkg_build_output_fd()'s fd becomes readable --
 * drains everything currently buffered into pkg.c's own capture
 * buffer, relaying whatever was newly read to any attached live-tail
 * clients (task #676) before checking for EOF. Once
 * pkg_build_output_readable() reports EOF/error (every write end
 * closed -- the build container and all its descendants have
 * exited), tears down this conn's own epoll registration and closes
 * the fd via pkg_build_output_close(), mirroring exactly how the
 * container's own CONN_CONTAINER exit path tears itself down, and
 * tells every live-tail client the stream has ended.
 */
static void handle_pkg_build_output_event(struct conn *cc)
{
	char new_data[4096];
	int new_len = 0;
	int eof;

	eof = pkg_build_output_readable(cc->pkg_chain_idx, new_data, (int)sizeof(new_data), &new_len);
	if (new_len > 0 && g_build_log_ws_conn_count > 0)
		build_log_ws_broadcast(cc->pkg_chain_idx, new_data, (size_t)new_len);
	if (eof) {
		cix_epoll_ctl(g_epfd, EPOLL_CTL_DEL, cc->fd, NULL);
		pkg_build_output_close(cc->pkg_chain_idx);
		build_log_ws_teardown_all(cc->pkg_chain_idx);
		free(cc);
	}
}

/*
 * The ordinary-container analog of register_pkg_build_output() above --
 * registers a container's own always-present capture pipe directly
 * with epoll, watching entry->output_fd itself rather than a pidfd,
 * for exactly the same reason: draining it live, incrementally, as
 * the container runs, so it never fills its 64KB kernel buffer and
 * blocks whatever the container itself is trying to write to stdout/
 * stderr (the same ADR-0087 discipline). No-op if output_fd is < 0
 * (pipe2() itself failed at container-create time -- capture
 * unavailable, the container still runs, exactly like pkg.c's own
 * build path degrades on the same failure).
 */
static void register_container_output_fd(struct registry_entry *entry, int fd, int service_index)
{
	struct conn *cc;
	struct cix_epoll_event ev;

	if (fd < 0)
		return;

	cc = calloc(1, sizeof(*cc));
	if (cc == NULL) {
		perror("malloc (container output reactor conn)");
		abort();
	}
	memset(cc, 0, sizeof(*cc));
	cc->kind = CONN_CONTAINER_OUTPUT;
	cc->fd = fd;
	cc->entry = entry;
	cc->service_index = service_index;

	memset(&ev, 0, sizeof(ev));
	ev.events = EPOLLIN;
	ev.data.ptr = cc;
	if (cix_epoll_ctl(g_epfd, EPOLL_CTL_ADD, cc->fd, &ev) != 0) {
		perror("epoll_ctl ADD container output fd");
		abort();
	}
}

static void register_container_output(struct registry_entry *entry)
{
	register_container_output_fd(entry, entry->output_fd, -1);
}

/* Is this output conn still the one its entry knows about? */
static int container_output_conn_live(const struct conn *cc)
{
	const struct registry_entry *e = cc->entry;

	if (!e->in_use)
		return 0;
	if (cc->service_index < 0)
		return e->output_fd == cc->fd;
	return cc->service_index < e->service_count && e->services[cc->service_index].output_fd == cc->fd;
}

/*
 * Fires whenever any container's own output_fd becomes readable --
 * every container has one now (transparent log capture), not just
 * ones created with "capture_output":true. Two independent
 * destinations for the same bytes: (1) always, split into lines and
 * forwarded to logstore.c as source="container" entries (see
 * forward_container_output_to_logstore()) -- the "transparent... goes
 * to a common logging backend" mechanism; (2) only when
 * entry->capture_requested (this container's own client explicitly
 * opted in), the raw bytes are ALSO appended into
 * entry->captured_output (bounded at REGISTRY_CAPTURED_OUTPUT_MAX,
 * silently dropping anything past that -- the same "generous but
 * bounded" posture pkg.c's own build-output capture already
 * established, not a live-tail feature like CONN_PKG_BUILD_OUTPUT's WS
 * relay, just a diagnostic snapshot GET /v1/containers/{name} can
 * report). Guards entry->in_use: this registry slot could in principle
 * already have been reused by a different container by the time EOF
 * finally arrives (e.g. a very fast create/delete/create cycle racing
 * this conn's own teardown) -- skip both destinations rather than risk
 * attributing one container's output to another's slot. On EOF (every
 * copy of the pipe's write end closed
 * -- the container process and every descendant it forked have
 * exited), tears down this conn's own epoll registration and closes
 * the fd, mirroring handle_pkg_build_output_event() exactly.
 */
/*
 * Splits newly-read bytes on '\n', flushing each complete line into
 * logstore as its own "container" entry -- the transparent capture
 * this feature exists for, always running regardless of whether this
 * container's own client asked for capture_output. Partial lines
 * accumulate in cc->output_line_buf across calls (a line can span
 * multiple read()s); a line that fills the buffer with no '\n' yet is
 * flushed as-is rather than grown unboundedly, the same "generous but
 * bounded" posture entry->captured_output already has. Called with
 * flush_partial=1 at EOF so a container's final line (its very last
 * write before exit, which may have no trailing newline at all) isn't
 * silently dropped.
 *
 * Each flushed line is also fanned out to syslogfwd_send() (logging
 * epic Part 2, ADR-0127) -- a no-op unless at least one syslog forward
 * target is registered, so this costs nothing in the common case.
 */
/*
 * One complete line of a container's output: to the log store and
 * syslog forwarding, and into captured_output when capture was
 * requested -- prefixed with the service that wrote it (ADR-0260), so
 * the merged view keeps its attribution. cix-init's own lines carry
 * its name.
 */
static void container_output_line(struct conn *cc, const char *line)
{
	struct registry_entry *e = cc->entry;
	const char *svc = cc->service_index >= 0 ? e->services[cc->service_index].def.name : "cix-init";
	char tagged[1024 + CIXINIT_NAME_MAX + 4];

	snprintf(tagged, sizeof(tagged), "%s: %s", svc, line);
	logstore_write_container(e->name, "info", "%s", tagged);
	syslogfwd_send(e->name, "info", tagged);
	if (e->capture_requested) {
		size_t tl = strlen(tagged);
		int room = (int)sizeof(e->captured_output) - e->captured_output_len - 2;

		if (room > 0) {
			int take = (int)tl < room ? (int)tl : room;

			memcpy(e->captured_output + e->captured_output_len, tagged, (size_t)take);
			e->captured_output_len += take;
			e->captured_output[e->captured_output_len++] = '\n';
			e->captured_output[e->captured_output_len] = '\0';
		}
	}
}

static void forward_container_output_to_logstore(struct conn *cc, const char *data, size_t len,
                                                   int flush_partial)
{
	size_t i;

	for (i = 0; i < len; i++) {
		if (data[i] == '\n' ||
		    cc->output_line_len >= (int)sizeof(cc->output_line_buf) - 1) {
			cc->output_line_buf[cc->output_line_len] = '\0';
			if (cc->output_line_len > 0)
				container_output_line(cc, cc->output_line_buf);
			cc->output_line_len = 0;
			if (data[i] == '\n')
				continue;
		}
		cc->output_line_buf[cc->output_line_len++] = data[i];
	}

	if (flush_partial && cc->output_line_len > 0) {
		cc->output_line_buf[cc->output_line_len] = '\0';
		container_output_line(cc, cc->output_line_buf);
		cc->output_line_len = 0;
	}
}

static void handle_container_output_event(struct conn *cc)
{
	char new_data[4096];
	ssize_t n;
	int eof = 0;

	for (;;) {
		n = read(cc->fd, new_data, sizeof(new_data));
		if (n > 0) {
			if (container_output_conn_live(cc))
				forward_container_output_to_logstore(cc, new_data, (size_t)n, 0);
			if (n < (ssize_t)sizeof(new_data))
				break; /* drained everything currently buffered */
			continue;
		}
		if (n == 0) {
			eof = 1;
			break;
		}
		/* n < 0 */
		if (errno == EINTR)
			continue;
		if (errno == EAGAIN || errno == EWOULDBLOCK)
			break; /* nothing more right now, still open */
		eof = 1; /* a real read error -- treat like EOF, stop watching */
		break;
	}

	if (eof) {
		if (container_output_conn_live(cc))
			forward_container_output_to_logstore(cc, "", 0, 1);
		cix_epoll_ctl(g_epfd, EPOLL_CTL_DEL, cc->fd, NULL);
		close(cc->fd);
		if (cc->service_index < 0) {
			if (cc->entry->output_fd == cc->fd)
				cc->entry->output_fd = -1;
		} else if (cc->service_index < cc->entry->service_count &&
		           cc->entry->services[cc->service_index].output_fd == cc->fd) {
			cc->entry->services[cc->service_index].output_fd = -1;
		}
		free(cc);
	}
}

/*
 * ADR-0087: mkbootroot's own captured stdout/stderr, drained
 * incrementally via epoll exactly like pkg.c's own build-output pipe
 * above -- the identical class of bug (a single post-exit read of a
 * plain pipe deadlocks the moment cumulative output exceeds the 64KB
 * kernel buffer), just not yet observed live here since a
 * control-plane-only rebuild's own output has never been verbose
 * enough to fill it. Safe as a bare static: only one bootroot
 * assembly can ever be in flight at a time (triggered exclusively by
 * a "cix" hostbuild completing, itself serialized by pkg.c's own
 * one-job-at-a-time invariant) -- the same reasoning pkg.c's own
 * module-level build state statics already document.
 */
#define BOOTROOT_OUTPUT_CAPTURE_MAX 2000

/*
 * One captured child's output. Made a struct rather than a second set
 * of module globals because the ISO assembly needs exactly this and
 * copying it would be a parallel implementation of the same buffer --
 * and because the gap it closes has now appeared three times (#125,
 * #132, and the artifact-export stderr fix): a child fails, its own
 * account of why goes to a pipe nobody reads, and the operator gets an
 * exit status. Each instance is still safe as a bare static for the
 * same reason the original was: at most one bootroot assembly and at
 * most one ISO build can be in flight at a time, the latter enforced
 * by handle_system_iso_post()'s own 409.
 */
struct child_output {
	int rd;
	char buf[BOOTROOT_OUTPUT_CAPTURE_MAX + 1];
	int len;
};

static struct child_output g_bootroot_output = {-1, {0}, 0};

static void child_output_append(struct child_output *c, const char *data, int len)
{
	int take = (len > BOOTROOT_OUTPUT_CAPTURE_MAX) ? BOOTROOT_OUTPUT_CAPTURE_MAX : len;
	int new_total = c->len + take;

	if (new_total > BOOTROOT_OUTPUT_CAPTURE_MAX) {
		int overflow = new_total - BOOTROOT_OUTPUT_CAPTURE_MAX;

		memmove(c->buf, c->buf + overflow, c->len - overflow);
		c->len -= overflow;
	}
	memcpy(c->buf + c->len, data + (len - take), take);
	c->len += take;
}

/* Returns 1 once every write end has closed (EOF/real read error --
 * the caller should tear down its own epoll registration and call
 * child_output_close()), 0 if there may still be more to come. */
static int child_output_readable(struct child_output *c)
{
	char chunk[2048];
	ssize_t n;

	if (c->rd < 0)
		return 1;

	for (;;) {
		n = read(c->rd, chunk, sizeof(chunk));
		if (n > 0) {
			child_output_append(c, chunk, (int)n);
			continue;
		}
		if (n < 0 && (errno == EAGAIN || errno == EWOULDBLOCK))
			return 0;
		return 1;
	}
}

static void child_output_close(struct child_output *c)
{
	if (c->rd >= 0) {
		close(c->rd);
		c->rd = -1;
	}
}

/* Registers g_bootroot_output.rd with epoll -- same CONN_KMSG-style
 * direct-fd pattern as register_pkg_build_output() above, not the
 * pidfd-then-single-read shape the CONN_BOOTROOT_ASSEMBLE conn itself
 * still uses for tracking mkbootroot's own exit. No-op if the fd is
 * -1 (pipe2() failed at spawn time). */
static void register_bootroot_output(void)
{
	struct conn *cc;
	struct cix_epoll_event ev;

	if (g_bootroot_output.rd < 0)
		return;

	cc = calloc(1, sizeof(*cc));
	if (cc == NULL) {
		perror("malloc (bootroot output reactor conn)");
		abort();
	}
	cc->kind = CONN_BOOTROOT_OUTPUT;
	cc->fd = g_bootroot_output.rd;

	memset(&ev, 0, sizeof(ev));
	ev.events = EPOLLIN;
	ev.data.ptr = cc;
	if (cix_epoll_ctl(g_epfd, EPOLL_CTL_ADD, cc->fd, &ev) != 0) {
		perror("epoll_ctl ADD bootroot output fd");
		abort();
	}
}

static void handle_bootroot_output_event(struct conn *cc)
{
	if (child_output_readable(&g_bootroot_output)) {
		cix_epoll_ctl(g_epfd, EPOLL_CTL_DEL, cc->fd, NULL);
		child_output_close(&g_bootroot_output);
		free(cc);
	}
}

/*
 * mkinstalleriso's own captured output. Until this existed a failed
 * ISO build reported "mkinstalleriso failed (status 0x100)" and
 * nothing else -- the tool's own account of what went wrong went to a
 * pipe nobody created. That is the third time this exact gap has cost
 * a debugging cycle (#125, #132, and the artifact-export stderr fix),
 * and an ISO build has more ways to fail than most: it stages a dozen
 * host libraries, shells out to grub-mkrescue, xorriso, mformat and
 * sbsign, and any of them can fail for a reason only it can state.
 */
static struct child_output g_iso_output = {-1, {0}, 0};

static void register_iso_output(void)
{
	struct conn *cc;
	struct cix_epoll_event ev;

	if (g_iso_output.rd < 0)
		return;

	cc = calloc(1, sizeof(*cc));
	if (cc == NULL) {
		perror("malloc (iso output reactor conn)");
		abort();
	}
	cc->kind = CONN_ISO_OUTPUT;
	cc->fd = g_iso_output.rd;

	memset(&ev, 0, sizeof(ev));
	ev.events = EPOLLIN;
	ev.data.ptr = cc;
	if (cix_epoll_ctl(g_epfd, EPOLL_CTL_ADD, cc->fd, &ev) != 0) {
		perror("epoll_ctl ADD iso output fd");
		abort();
	}
}

/*
 * Drained incrementally, exactly like the bootroot one and for the
 * same reason: grub-mkrescue and mksquashfs are chatty enough to fill
 * a 64K pipe, and a full pipe blocks the child forever rather than
 * failing it -- which would turn a diagnostic aid into a hang.
 */
static void handle_iso_output_event(struct conn *cc)
{
	if (child_output_readable(&g_iso_output)) {
		cix_epoll_ctl(g_epfd, EPOLL_CTL_DEL, cc->fd, NULL);
		child_output_close(&g_iso_output);
		free(cc);
	}
}

/* Same shape as register_pkg_fetch_pidfd(), for the mkbootroot child
 * spawn_cix_bootroot_assembly() below just forked -- tracks only
 * its exit; its captured stdout/stderr is a separate, directly-
 * registered conn (register_bootroot_output()/g_bootroot_output.rd
 * above, ADR-0087), not this one. */
static void register_bootroot_assemble_pidfd(pid_t pid, int pidfd)
{
	struct conn *cc;
	struct cix_epoll_event ev;

	cc = calloc(1, sizeof(*cc));
	if (cc == NULL) {
		perror("malloc (bootroot assemble reactor conn)");
		abort();
	}
	cc->kind = CONN_BOOTROOT_ASSEMBLE;
	cc->fd = pidfd;
	cc->pkg_fetch_pid = pid;

	memset(&ev, 0, sizeof(ev));
	ev.events = EPOLLIN;
	ev.data.ptr = cc;
	if (cix_epoll_ctl(g_epfd, EPOLL_CTL_ADD, cc->fd, &ev) != 0) {
		perror("epoll_ctl ADD bootroot assemble pidfd");
		abort();
	}
}

/*
 * ADR-0078: the well-known name of the shared "host tools" image --
 * cp/rm/sha256sum/gzip (coreutils.recipe/gzip.recipe) plus openssl/
 * curl/tar/bzip2/xz/squashfs-tools/e2fsprogs, one real `pkg install
 * --image=cix-hosttools` per recipe -- an operator builds this
 * exactly like "cix-builder"/"iso-builder" (docs/guides/building-cix.md),
 * no special-cased creation path. spawn_cix_bootroot_assembly()
 * below passes its rootfs to mkbootroot.c's own host_tools_dir
 * argument when present, purely additive: a box that never built this
 * image keeps today's dev-host-sourced behavior (mkbootroot.c's own
 * "" fallback), never a hard failure.
 */
#define HOST_TOOLS_IMAGE "cix-hosttools"

/*
 * #30, extending ADR-0029: the well-known name of the image holding
 * device firmware, resolved and staged the same way HOST_TOOLS_IMAGE
 * above is -- an operator builds it with ordinary `pkg install
 * --image=cix-firmware` calls, no special-cased creation path, and a
 * box that never built one keeps today's behaviour through
 * mkbootroot.c's own "" fallback.
 *
 * Firmware has to live in the control-plane root specifically, and
 * that is ADR-0029's original argument rather than a new one:
 * request_firmware() is answered by the kernel out of the HOST root,
 * during driver probe, before any container exists to hold anything.
 * A firmware blob in a container is a blob the kernel will never see.
 *
 * The image's own lib/firmware is the root that gets staged, not the
 * image rootfs itself, because that is where its packages install --
 * rtw88-firmware writes lib/firmware/rtw88/rtw8822b_fw.bin and
 * wireless-regdb writes lib/firmware/regulatory.db. Handing mkbootroot
 * that subdirectory means its contents already mirror /lib/firmware
 * exactly, which is the shape it documents wanting, and it needs to
 * know nothing about which packages or drivers exist.
 */
#define FIRMWARE_IMAGE "cix-firmware"

/*
 * #347: the well-known name of the image holding the module tools --
 * modprobe/depmod/insmod/lsmod/modinfo/rmmod, all six symlinks to one
 * real kmod binary (recipes/package/kmod). Resolved and staged exactly
 * like FIRMWARE_IMAGE above, built with an ordinary `pkg install
 * --image=cix-kmod kmod`, and absent on a box that never built one.
 *
 * Its own image rather than a few more files inside cix-hosttools,
 * because mkbootroot stages THIS directory with the flat copy
 * (copy_dir_files(): every file in it, into usr/bin), not the
 * named-absolute-path copy hosttools gets. cix-hosttools' own usr/bin
 * carries curl, tar, perl and bash among others, so pointing the flat
 * copy at it would put a shell in the control-plane root -- a property
 * this platform deliberately does not have. A one-package image's
 * usr/bin holds exactly the seven files kmod installs, and nothing
 * else.
 */
#define KMOD_IMAGE "cix-kmod"

/*
 * ADR-0057: when a hostbuild job named "cix" completes, assembles a
 * fresh control-plane squashfs from its own just-harvested artifacts
 * by forking+exec'ing the real, unmodified build/mkbootroot binary --
 * server-side, entirely within the daemon, never CLI-invoked (the
 * API-First Mandate rules out the CLI shelling out to a build tool
 * directly). Mirrors start_fetch_for()'s own "daemon already forks
 * subprocesses for curl" precedent -- this is the same class of
 * capability, not a new one. Uses THIS SAME hostbuild round's own
 * freshly built mkbootroot (cix.recipe now stages one alongside
 * cixd/cixctl/web/) rather than assuming some earlier round's
 * copy is still present anywhere -- self-contained, no bootstrap-order
 * dependency. Failure here (missing mkbootroot, fork failure) is
 * logged, never fatal to the daemon -- the hostbuild itself already
 * succeeded and its own artifacts are still there for a later retry.
 */
static void artifact_push_pump(void);
/*
 * The kind is defined HERE, not next to the export machinery it belongs
 * to, because the declaration below names it and C has no forward
 * declaration for an enum the way it has for a struct: an undefined
 * enum tag in a parameter list is an incomplete type, and a call
 * through it is not valid C.
 *
 * GCC accepts it, and so did tcc 0.9.27, which is why this sat here
 * for five releases. tcc 0.9.28rc does not, and it is right --
 * `daemon/src/main.c:9648: error: cast to incomplete type` on the
 * first hostbuild after the compiler upgrade (#216). The compiler got
 * stricter and found a real latent bug in this file.
 */
enum artifact_export_kind {
	ARTIFACT_EXPORT_KIND_IMAGE = 0,
	ARTIFACT_EXPORT_KIND_HOSTBUILD
};

/*
 * Issue #200 -- both defined lower down, next to the export machinery
 * they drive; declared here because pkg_completion_followup() runs
 * before either in this file.
 */
static int artifact_export_start(enum artifact_export_kind kind, const char *name,
                                 const char *dest_override, char *err_msg, size_t err_msg_size);
static void publish_hostbuild_artifact(const char *name);
static void spawn_cix_bootroot_assembly(const char *artifact_dir);

/* ADR-0207 phase 2: force the direct-rootfs container path with a COPY
 * instead of a snapshot, so the btrfs-incapable dev sandbox (ext4, no
 * loop devices) can exercise the whole direct machinery -- provisioning,
 * self-bind + pivot, persistence across restart, stopped-file access,
 * deletion -- everything except SNAP_CREATE_V2 itself, which only a
 * real btrfs host can prove. Same test-hook family as
 * --test-esp-entries-dir/--test-efivars-dir. */
static int g_test_direct_rootfs;
/*
 * #321: the userns twin of the flag above. cix_btrfs_is_backing() is false
 * on the test suite's own /tmp data dir, so the ADR-0207 phase 3 snapshot
 * presentation -- host-0-owned rootfs behind an id-mapped mount -- was
 * unreachable in every test this project has, and shipped a break that took
 * every workload on a btrfs host down. This makes the copy path present
 * itself the same way a snapshot does (host-0-owned, id-mapped) so the
 * branch is exercised on any filesystem; id-mapped mounts need no btrfs.
 */
static int g_test_userns_idmap;

/*
 * Where a stopped container's writable tree lives (ADR-0207 phase 2):
 * `<base>/rootfs` for a direct-rootfs container (its snapshot/copy is
 * the whole filesystem), `<base>/upper` for a classic overlay one. The
 * on-disk presence of rootfs IS the storage-mode marker -- no side
 * state to drift, the filesystem is the one source of truth, and a
 * container keeps its mode across restarts automatically.
 */
void container_writable_path(const char *container_root, const char *name,
                                     const char *rel_path, char *out, size_t out_size)
{
	struct stat wst;
	char wbase[PATH_MAX];

	snprintf(wbase, sizeof(wbase), "%s/%s/rootfs", container_root, name);
	if (!(stat(wbase, &wst) == 0 && S_ISDIR(wst.st_mode)))
		snprintf(wbase, sizeof(wbase), "%s/%s/upper", container_root, name);
	snprintf(out, out_size, "%s%s", wbase, rel_path);
}

/* Defined below, next to the disk-placement code it belongs with. */
void container_root_for(const char *disk_name, char *out, size_t out_size);

/*
 * #333: does this container run DIRECTLY out of a host-side tree?
 *
 * Two container shapes exist and they need opposite answers for a
 * write. An overlay container's root is assembled by the kernel inside
 * the container's own mount namespace, so the only coherent way in
 * from the host is /proc/<pid>/root -- writing into the upperdir of a
 * live overlay is not supported. A container with <base>/rootfs pivots
 * onto that directory itself (ADR-0207's btrfs snapshot) or onto an
 * id-mapped bind of it (ADR-0179's userns presentation), and in both
 * of those the host-side directory IS the container's tree.
 *
 * The distinction is not cosmetic: an open(O_CREAT) through
 * /proc/<pid>/root into a running USERNS container is refused with
 * EOVERFLOW ("Value too large for defined data type"), which is why
 * PUT .../files returned 500 for every container on a userns-by-default
 * host while GET on the same container worked.
 *
 * THE KERNEL-SIDE MECHANISM IS NOT ESTABLISHED, and it is worth saying
 * so rather than writing down a plausible one. The obvious explanation
 * -- crossing an id-mapped mount whose map does not admit the daemon's
 * fsuid -- does not survive its own check: jump's rootfs is owned by
 * 1345184, container_create() sets spec.userns_idmap only when that
 * owner is 0 (ADR-0179's two presentations), and src/container.c only
 * applies MOUNT_ATTR_IDMAP to the rootfs under that flag. So the tree
 * that failed is not id-mapped. What IS established is the axis and the
 * errno, and the fix depends on nothing more than those.
 *
 * Measured on 192.168.15.95 at v2.57.78 before this existed:
 *
 *   PUT /v1/containers/jump/files    userns=true,  running -> 500 EOVERFLOW
 *   PUT /v1/containers/cr-2/files    userns=true,  running -> 500 EOVERFLOW
 *   PUT /v1/containers/ntp-1/files   userns=false, running -> 204
 *   PUT /v1/containers/limtest/files userns=true,  stopped -> 204
 *
 * userns is the axis, not "every running container" as first reported
 * -- the stopped case already took the host-side path and always
 * worked.
 *
 * Returns 0 and fills out with the host-side root, or -1 when this
 * container has no such tree.
 */
static int container_direct_rootfs(const char *container_root, const char *name, char *out,
                                    size_t out_size)
{
	struct stat st;
	char base[PATH_MAX];

	snprintf(base, sizeof(base), "%s/%s/rootfs", container_root, name);
	if (stat(base, &st) != 0 || !S_ISDIR(st.st_mode))
		return -1;
	snprintf(out, out_size, "%s", base);
	return 0;
}


/*
 * Issue #162: where a container's tree lives when it has NO registry
 * entry -- which is what a cleanly stopped container is.
 *
 * POST /containers/{name}/stop kills the child and the async completion
 * then removes the registry entry, so the files API was a race against
 * that teardown and a hard 404 afterwards, even though the container
 * still exists: startable, definition persisted, on-disk state intact.
 * The asymmetry was the confusing part -- a container that exited ON
 * ITS OWN keeps its entry indefinitely, so ITS files stayed readable
 * while a deliberately stopped one's did not, and nothing said why.
 *
 * The disk comes from the persisted create body, which is the same
 * field a start would use to place it, so read and write resolve to
 * exactly the tree the next start will run from. Returns 0, or -1 when
 * there is genuinely no such container.
 */
static int container_root_from_def(const char *name, char *out, size_t out_size)
{
	struct container_def *def = containerdef_find(name);
	struct json_value *root;

	if (def == NULL)
		return -1;
	root = json_parse(def->body, def->body_len);
	/* container_root_for() copies into out before this frees the tree
	 * the disk string points into, and treats NULL as the default OS-disk
	 * placement -- which is exactly right for a body with no "disk". */
	container_root_for(root != NULL ? json_as_string(json_object_get(root, "disk")) : NULL,
	                   out, out_size);
	json_free(root);
	return 0;
}

/*
 * The work that follows a pkg build completing, wherever completion
 * came from: a real build container exiting, or an artifact/cache hit
 * that had no container to exit at all (#144).
 *
 * This exists because the cache-hit path first duplicated it and got it
 * incomplete -- it chained and pushed but never triggered the bootroot
 * assembly, so `pkg hostbuild cix --deploy` reported the package
 * installed and silently produced no image. The build succeeded, the
 * deploy did nothing, and the only visible sign was
 * bootroot_assembly_started_generation staying at 0. Two call sites
 * doing "the same thing" is exactly the shape that maxim warns about,
 * so there is one of them now.
 */
static void pkg_completion_followup(int chained, pid_t pkg_pid, int pkg_pidfd, int pkg_chain_idx,
                                     const char *hostbuild_done_name)
{
	if (chained)
		register_pkg_fetch_pidfd(pkg_pid, pkg_pidfd, pkg_chain_idx);
	else
		try_start_queued_pkg_rebuild();

	/*
	 * Issue #200: a hostbuild's output is a directory, so pkg.c's own
	 * post-build enqueue had no tarball for the pusher to upload and
	 * every push was skipped. Build one first; its completion queues
	 * the push. Before the pump, so the pump below still handles every
	 * other package that finished.
	 */
	publish_hostbuild_artifact(hostbuild_done_name);

	/* Issue #129: a build just finished, so there may be something to
	 * publish. Cheap no-op when the queue is empty or push is off. */
	artifact_push_pump();

	/*
	 * ADR-0057: "cix" is the one hostbuild name this daemon gives
	 * any further meaning to -- everything else pkg.c handles is
	 * completely generic. Deliberately a plain string match here in
	 * main.c, not a flag/callback registered in pkg.c itself: pkg.c
	 * stays fully agnostic to what any package *means*.
	 */
	if (hostbuild_done_name != NULL && hostbuild_done_name[0] != '\0' &&
	    strcmp(hostbuild_done_name, "cix") == 0) {
		char artifact_dir[PATH_MAX];

		snprintf(artifact_dir, sizeof(artifact_dir), "%s/%s", ARTIFACTS_DIR,
		         hostbuild_done_name);
		spawn_cix_bootroot_assembly(artifact_dir);
	}
}

/*
 * Where the kernel's module tree is, and where the module tools are.
 *
 * Two callers need the identical answers: the bootroot assembly, which
 * stages them onto the control-plane root, and the installer-ISO build,
 * which stages the NIC subset onto the media so cix-install can list a
 * real machine's built-in Ethernet at all (#429 follow-on). They were
 * resolved inline in the first, and a second copy in the second would
 * be two places that know where a kernel artifact keeps its modules --
 * free to drift, and drifting silently, since the failure is an empty
 * interface list rather than an error.
 *
 * Both leave out empty when the thing is not there, which every caller
 * treats as "stage nothing" rather than as a failure: a control plane
 * with no module tree still boots, and an ISO with none still installs
 * on virtio.
 */
static void resolve_kernel_modules_dir(char *out, size_t out_size)
{
	struct stat st;

	out[0] = '\0';
	/*
	 * ARTIFACTS_DIR/kernel is the kernel package's own hostbuild
	 * artifact directory, a sibling of the "cix" package's.
	 * kernel.recipe's pkg_install() runs modules_install followed by
	 * depmod -b, so this is a complete, dependency-indexed tree --
	 * modules.dep and its .bin indexes included -- rather than a bag
	 * of .ko files modprobe cannot resolve.
	 */
	if (snprintf(out, out_size, "%s/kernel/lib/modules", ARTIFACTS_DIR) >= (int)out_size)
		out[0] = '\0';
	else if (stat(out, &st) != 0 || !S_ISDIR(st.st_mode))
		out[0] = '\0';
}

static void resolve_kmod_bin_dir(char *out, size_t out_size)
{
	char kmod_version[IMAGE_VERSION_MAX];
	char kmod_root[PATH_MAX];
	struct stat st;

	out[0] = '\0';
	if (image_current_version(KMOD_IMAGE, kmod_version, sizeof(kmod_version)) != IMAGE_OK)
		return;
	image_version_rootfs_path(KMOD_IMAGE, kmod_version, kmod_root, sizeof(kmod_root));
	if (snprintf(out, out_size, "%s/usr/bin", kmod_root) >= (int)out_size)
		out[0] = '\0';
	else if (stat(out, &st) != 0 || !S_ISDIR(st.st_mode))
		out[0] = '\0';
}

static void spawn_cix_bootroot_assembly(const char *artifact_dir)
{
	char mkbootroot_bin[PATH_MAX];
	char cixd_bin[PATH_MAX];
	char cixctl_bin[PATH_MAX];
	char web_dir[PATH_MAX];
	char out_squashfs[PATH_MAX];
	char stage_dir[PATH_MAX];
	char host_tools_dir[PATH_MAX];
	char firmware_dir[PATH_MAX];
	char modules_dir[PATH_MAX];
	char kmod_bin_dir[PATH_MAX];
	struct stat host_tools_st;
	char *argv[11];
	pid_t pid;
	int pidfd;
	int output_pipe[2];

	snprintf(mkbootroot_bin, sizeof(mkbootroot_bin), "%s/mkbootroot", artifact_dir);
	snprintf(cixd_bin, sizeof(cixd_bin), "%s/cixd", artifact_dir);
	snprintf(cixctl_bin, sizeof(cixctl_bin), "%s/cixctl", artifact_dir);
	snprintf(web_dir, sizeof(web_dir), "%s/web", artifact_dir);
	/*
	 * BOOTROOT_DIR, not artifact_dir (#178). These are build OUTPUT:
	 * the artifact directory is tarred wholesale when the package is
	 * exported or published, so anything left here rode along -- a
	 * ~10 MB squashfs and a ~12 MB staging tree on top of ~1.5 MB of
	 * real package content. Every host pulling `cix` downloaded 22 MB
	 * to use 1.5 MB of it, and got a stale squashfs it would never
	 * read.
	 */
	snprintf(out_squashfs, sizeof(out_squashfs), "%s/cixd-root.squashfs", BOOTROOT_DIR);
	snprintf(stage_dir, sizeof(stage_dir), "%s/stage", BOOTROOT_DIR);

	/*
	 * ADR-0107/0108: resolved via HOST_TOOLS_IMAGE's own current
	 * version, not a flat "<IMAGES_DIR>/<name>/rootfs" path -- images
	 * are pure filesystem state, no registry lookup needed (image.h's
	 * own doc comment), but they DO now need a manifest.json lookup.
	 * stat() instead of assuming presence: most installs will never
	 * have built this optional image, and mkbootroot.c's own ""
	 * fallback already exists precisely for that case (also covers
	 * "exists but has no current version yet," though that's
	 * unreachable via image_create()'s own always-produces-one
	 * guarantee).
	 */
	host_tools_dir[0] = '\0';
	{
		char host_tools_version[IMAGE_VERSION_MAX];

		if (image_current_version(HOST_TOOLS_IMAGE, host_tools_version,
		                           sizeof(host_tools_version)) == IMAGE_OK) {
			image_version_rootfs_path(HOST_TOOLS_IMAGE, host_tools_version, host_tools_dir,
			                           sizeof(host_tools_dir));
			if (stat(host_tools_dir, &host_tools_st) != 0 || !S_ISDIR(host_tools_st.st_mode))
				host_tools_dir[0] = '\0';
		}
	}

	/*
	 * Same resolution as host_tools_dir above, one directory deeper:
	 * mkbootroot wants a firmware ROOT whose contents mirror
	 * /lib/firmware, and that is the image's own lib/firmware rather
	 * than its rootfs.
	 *
	 * This argument used to be a hardcoded "" with a comment saying a
	 * control-plane-only rebuild needs no firmware re-staging. That was
	 * true of nothing: mkbootroot assembles a FRESH root every time, so
	 * whatever it is not given, the resulting root does not have. The
	 * effect was that ADR-0029's firmware staging had no caller at all
	 * -- the capability existed in mkbootroot and no code path ever
	 * reached it -- which is why a wireless adapter needing
	 * rtw88/rtw8822b_fw.bin had nowhere for that file to come from.
	 */
	firmware_dir[0] = '\0';
	{
		char firmware_version[IMAGE_VERSION_MAX];
		char firmware_root[PATH_MAX];
		struct stat firmware_st;

		if (image_current_version(FIRMWARE_IMAGE, firmware_version, sizeof(firmware_version)) ==
		    IMAGE_OK) {
			image_version_rootfs_path(FIRMWARE_IMAGE, firmware_version, firmware_root,
			                           sizeof(firmware_root));
			if (snprintf(firmware_dir, sizeof(firmware_dir), "%s/lib/firmware", firmware_root) >=
			    (int)sizeof(firmware_dir))
				firmware_dir[0] = '\0';
			else if (stat(firmware_dir, &firmware_st) != 0 || !S_ISDIR(firmware_st.st_mode))
				firmware_dir[0] = '\0';
		}
		/*
		 * Logged as its own entry rather than left to mkbootroot's
		 * captured output, which is one long message the log store
		 * truncates -- so "did this assembly stage firmware?" was not
		 * answerable after the fact, and that question came up the
		 * first time a booted host was missing its firmware.
		 *
		 * Both branches say something. Silence on the absent path
		 * would leave the most likely cause of a firmware-less host
		 * looking identical to a host that was never meant to have
		 * any.
		 */
		if (firmware_dir[0] != '\0')
			logstore_write("cixd", "info", "cix bootroot assembly: staging firmware from %s",
			               firmware_dir);
		else
			logstore_write("cixd", "info",
			               "cix bootroot assembly: no firmware to stage -- image \"%s\" has no "
			               "current version, or no lib/firmware in it",
			               FIRMWARE_IMAGE);
	}

	/*
	 * #347: the kernel module tree, taken from the kernel package's own
	 * artifact directory -- ARTIFACTS_DIR/kernel, a SIBLING of the
	 * artifact_dir parameter above, which is the "cix" package's.
	 * kernel.recipe's own pkg_install() runs modules_install followed
	 * by depmod -b, so what is staged here is a complete,
	 * dependency-indexed tree (modules.dep and friends), not a bag of
	 * .ko files modprobe cannot resolve.
	 *
	 * This argument used to be a hardcoded "" whose comment said a
	 * control-plane-only rebuild touches no module tree. That is the
	 * same mistake firmware_dir above carried, for the same reason:
	 * mkbootroot assembles a FRESH root every time, so whatever it is
	 * not given, the resulting root does not have. The effect was that
	 * no kernel module could load on any Cix host ever assembled --
	 * GET /v1/system/kmod/e1000e answered "no such module
	 * (not built/available)" because there was no tree to find it in.
	 * A box whose drivers are all built in never notices; a bare-metal
	 * box, whose NIC driver is a module and which has no shell to
	 * repair itself with, is simply unreachable.
	 *
	 * The tree and the booting bzImage have to come from the same
	 * build, and nothing here enforces that because nothing needs to:
	 * modules are namespaced by kernel release (lib/modules/<release>)
	 * and modprobe selects by uname -r, so a mismatched release
	 * degrades to "module not found" -- exactly today's behaviour --
	 * while a matching release built from a different config is
	 * refused outright with "invalid module format". Neither failure
	 * is silent. It is still why a deploy should pass the kernel_path
	 * out of the same artifact this staged from.
	 */
	resolve_kernel_modules_dir(modules_dir, sizeof(modules_dir));
	{
		if (modules_dir[0] != '\0')
			logstore_write("cixd", "info", "cix bootroot assembly: staging kernel modules from %s",
			               modules_dir);
		else
			logstore_write("cixd", "info",
			               "cix bootroot assembly: no kernel modules to stage -- no module tree "
			               "at %s/kernel/lib/modules; nothing will be loadable on the assembled "
			               "host",
			               ARTIFACTS_DIR);
	}

	/*
	 * #347: the module tools, resolved exactly the way firmware_dir
	 * above is -- KMOD_IMAGE's own current version, one directory
	 * deeper, because mkbootroot wants the directory whose files land
	 * flat in usr/bin rather than the image rootfs.
	 *
	 * Staged even when modules_dir came back empty. They are two
	 * independent capabilities: an operator can load a module by hand
	 * from a tree this assembly did not produce, and "the tools are
	 * missing" and "the tree is missing" are different diagnoses that
	 * should not be collapsed into one silence.
	 */
	resolve_kmod_bin_dir(kmod_bin_dir, sizeof(kmod_bin_dir));
	{
		if (kmod_bin_dir[0] != '\0')
			logstore_write("cixd", "info", "cix bootroot assembly: staging module tools from %s",
			               kmod_bin_dir);
		else
			logstore_write("cixd", "info",
			               "cix bootroot assembly: no module tools to stage -- image \"%s\" has "
			               "no current version, or no usr/bin in it; modprobe will be absent from "
			               "the assembled host",
			               KMOD_IMAGE);
	}


	argv[0] = mkbootroot_bin;
	argv[1] = stage_dir;
	argv[2] = cixd_bin;
	argv[3] = cixctl_bin;
	argv[4] = web_dir;
	argv[5] = out_squashfs;
	argv[6] = firmware_dir;  /* "" if cix-firmware was never built on this box */
	argv[7] = modules_dir;   /* "" if this box has no kernel artifact to take a tree from */
	argv[8] = kmod_bin_dir;  /* "" if cix-kmod was never built on this box */
	argv[9] = host_tools_dir; /* "" if cix-hosttools was never built on this box */
	argv[10] = NULL;

	/*
	 * O_CLOEXEC on both ends, same reasoning as container_create()'s own
	 * diag pipe (include/container.h): the write end vanishes on its own
	 * at a successful execve() below, and the read end (kept open here
	 * past this fork) shouldn't leak into any later child this daemon
	 * spawns either. Not fatal on failure -- assembly still proceeds
	 * exactly as before this capture existed, just back to only the
	 * bare exit-status logging. O_NONBLOCK on the read end only (added
	 * for ADR-0087) -- the write end stays blocking since it becomes
	 * mkbootroot's own stdout/stderr.
	 */
	if (pipe2(output_pipe, O_CLOEXEC) != 0) {
		perror("pipe2 (bootroot assembly output capture)");
		logstore_write("cixd", "error",
		                "cix bootroot assembly: output capture pipe failed: %s",
		                strerror(errno));
		output_pipe[0] = output_pipe[1] = -1;
	} else if (fcntl(output_pipe[0], F_SETFL, O_NONBLOCK) != 0) {
		perror("fcntl O_NONBLOCK (bootroot assembly output capture)");
		close(output_pipe[0]);
		close(output_pipe[1]);
		output_pipe[0] = output_pipe[1] = -1;
	}

	pid = fork();
	if (pid < 0) {
		perror("fork (bootroot assembly)");
		logstore_write("cixd", "error", "cix bootroot assembly: fork failed: %s",
		                strerror(errno));
		if (output_pipe[0] >= 0) {
			close(output_pipe[0]);
			close(output_pipe[1]);
		}
		return;
	}
	if (pid == 0) {
		if (output_pipe[1] >= 0) {
			dup2(output_pipe[1], STDOUT_FILENO);
			dup2(output_pipe[1], STDERR_FILENO);
		}
		execve(mkbootroot_bin, argv, environ);
		perror("child: execve mkbootroot");
		_exit(127);
	}

	/*
	 * A real child now exists and is genuinely attempting this
	 * assembly -- bump the generation counter here, not any earlier
	 * (a failed fork() above never got a real attempt at all) and not
	 * any later (pidfd_open() failing below still means a real mkbootroot
	 * process was launched; it just couldn't be reaped normally, so
	 * task #737's own freshness tracking still needs to count this as
	 * "attempted, then failed" rather than silently never happening).
	 */
	g_bootroot_assembly_started++;
	g_bootroot_assembly_running = 1;

	if (output_pipe[1] >= 0)
		close(output_pipe[1]);

	pidfd = sys_pidfd_open(pid, 0);
	if (pidfd < 0) {
		perror("pidfd_open (bootroot assembly)");
		logstore_write("cixd", "error", "cix bootroot assembly: pidfd_open failed: %s",
		                strerror(errno));
		if (output_pipe[0] >= 0)
			close(output_pipe[0]);
		kill(pid, SIGKILL);
		waitpid(pid, NULL, 0);
		g_bootroot_assembly_running = 0;
		return;
	}
	g_bootroot_output.len = 0;
	g_bootroot_output.rd = output_pipe[0];
	register_bootroot_output();
	register_bootroot_assemble_pidfd(pid, pidfd);
}

/*
 * POST/GET /v1/system/iso (ADR-0064): closes the API-First Mandate gap
 * ADR-0063 deliberately left open -- image/src/mkinstalleriso.c was a
 * dev-machine-only tool an operator had to run by hand; this makes ISO
 * assembly a real, REST/CLI-reachable daemon capability, the same
 * fork+exec+pidfd-tracked, non-blocking shape spawn_cix_bootroot_
 * assembly() above already established for mkbootroot. Unlike that
 * mechanism (auto-triggered the moment a "cix" hostbuild completes),
 * ISO assembly is explicitly, separately triggered -- it has real
 * inputs of its own (the target's disk/ip/prefix/gateway/interface)
 * a hostbuild completion has no way to supply, and reuses whatever the
 * most recent "cix"/"kernel"/"isotools" hostbuild rounds already
 * harvested rather than forcing a fresh rebuild of any of them.
 *
 * Only one ISO build is ever in flight at a time (the same v1 single-
 * job constraint pkg.c's own install/hostbuild pipeline already has) --
 * g_iso_build_state is this mechanism's entire piece of state, never
 * persisted (an in-progress build that the daemon restarts through is
 * simply lost, exactly like an in-progress pkg install already is).
 */
enum iso_build_state { ISO_BUILD_NONE, ISO_BUILD_BUILDING, ISO_BUILD_READY, ISO_BUILD_FAILED };
static enum iso_build_state g_iso_build_state = ISO_BUILD_NONE;
static char g_iso_build_error[256];
/*
 * ADR-0220. Empty unless the finished ISO was actually signed, which
 * needs a release key installed -- an unsigned ISO is still a usable
 * ISO, so a missing key does not fail the build.
 */
static char g_iso_signature_path[PATH_MAX];

/*
 * The cixd version that built the current ISO, read back out of the
 * trusted comment inside its own signature.
 *
 * Deliberately taken from the artifact rather than from
 * CIX_BUILD_VERSION, because state is recovered from disk (#205) and a
 * surviving ISO may predate the running daemon. Reading it from the
 * signature means this describes the ISO, not whatever happens to be
 * running -- and the trusted comment is covered by the global
 * signature, so it is a signed claim rather than an editable label.
 */
static char g_iso_built_version[64];


/*
 * Issue #126: export an image's current version as a whole-rootfs
 * tarball, so compiled output can be pulled off one host and installed
 * on another instead of being rebuilt from source.
 *
 * The output filename is deliberately EXACTLY what the consuming side
 * already computes: ADR-0123's image-artifact fetch asks for
 * <base_url>/images/<name>-<hash>.tar.gz, where hash is the image
 * version (image_hash_manifest_string() over the sorted manifest). So
 * an exported file dropped behind any plain HTTP server is directly
 * consumable by a peer cixd's own image recipe -- no new protocol, no
 * translation step, and the existing checksum verification still gates
 * trust (the artifact server is never a trust boundary).
 *
 * Asynchronous with a status poll, like the ISO build above: tarring a
 * multi-gigabyte rootfs would freeze this daemon's single event loop
 * for minutes, which is exactly the wedge ADR-0180 exists to prevent.
 * One export at a time -- an operator exports a handful of images
 * deliberately, and a per-job identifier would be machinery with no
 * caller.
 */
enum artifact_export_state {
	ARTIFACT_EXPORT_NONE = 0,
	ARTIFACT_EXPORT_BUILDING,
	ARTIFACT_EXPORT_READY,
	ARTIFACT_EXPORT_FAILED
};

/*
 * Issue #129: what the running export is OF. The two subjects differ
 * only in where the bytes come from and what the resulting file is
 * called -- tarring, reaping, status and chunked download are
 * identical, so they share one state machine rather than growing a
 * second parallel one.
 *
 * A hostbuild artifact (ADR-0056) is the case that forced this: it
 * lives in a plain host directory that is deliberately never
 * container-visible, so GET /v1/containers/{n}/files cannot reach it
 * and it had no retrieval route at all -- the self-hosted kernel, the
 * single most expensive thing this project builds, existed only as
 * bytes on one box's disk.
 */

static enum artifact_export_state g_artifact_export_state;
static enum artifact_export_kind g_artifact_export_kind;
static char g_artifact_export_name[PKG_IMAGE_NAME_MAX];
static char g_artifact_export_version[IMAGE_VERSION_MAX];
static char g_artifact_export_path[PATH_MAX];
static char g_artifact_export_error[256];
/*
 * A publish that had to build its own tarball first: the export runs to
 * the cache path a push reads from, and the push is enqueued only once
 * the bytes are actually there. Empty when the export is an ordinary
 * operator-requested one.
 */
static char g_artifact_export_publish_name[PKG_NAME_MAX];

/*
 * Issue #200: make a hostbuild's output publishable.
 *
 * A hostbuild's artifact is a DIRECTORY this host assembled, never a
 * tarball it fetched, so pkg.c's post-build enqueue had nothing for the
 * pusher to upload and every push was skipped. The artifact cache's
 * newest `cix` sat at v2.2.0-rc30 while the box that built it ran rc35;
 * `kernel` and `isotools` were affected identically. Ordinary
 * source-built packages were fine only because their branch calls
 * pkg_cache_save() before enqueuing; a hostbuild's never did.
 *
 * Build the tarball from the installed tree first -- the same export
 * the manual publish endpoint uses, so there is one way to produce
 * these bytes rather than two -- and let its completion queue the push
 * through g_artifact_export_publish_name, exactly as that path does.
 *
 * Silent when there is nothing to do: not a hostbuild, or already
 * cached (a cache hit, which pkg.c does not enqueue anyway).
 */
static void publish_hostbuild_artifact(const char *name)
{
	char version[PKG_VERSION_MAX];
	int is_hostbuild = 0;
	char dest[PATH_MAX];
	char err[256];

	if (name == NULL || name[0] == '\0')
		return;
	if (pkg_artifact_publish_resolve(name, version, sizeof(version), &is_hostbuild) != PKG_OK)
		return;
	if (!is_hostbuild || pkg_artifact_cache_has(name, version))
		return;

	pkg_artifact_cache_path(name, version, dest, sizeof(dest));
	snprintf(g_artifact_export_publish_name, sizeof(g_artifact_export_publish_name), "%s", name);
	if (artifact_export_start(ARTIFACT_EXPORT_KIND_HOSTBUILD, name, dest, err, sizeof(err)) != 0) {
		g_artifact_export_publish_name[0] = '\0';
		/* Name the package and the reason: this whole class went
		 * unnoticed for five releases behind a message that asserted
		 * the wrong cause. */
		logstore_write("cixd", "warning",
		                "artifact publish: could not build a tarball for %s@%s, so it will "
		                "not be published: %s",
		                name, version, err);
	}
}
/* Read end of the tar child's stderr pipe -- -1 when no export is
 * running. Drained (bounded) at completion so a failure names its
 * actual cause instead of only an exit status; "tar failed (status
 * 0x200)" with the real complaint invisible is precisely the
 * diagnostic gap issue #125/#132 already document for other paths. */
static int g_artifact_export_errfd = -1;

static void register_artifact_export_pidfd(pid_t pid, int pidfd)
{
	struct conn *cc;
	struct cix_epoll_event ev;

	cc = calloc(1, sizeof(*cc));
	if (cc == NULL) {
		perror("malloc (image export reactor conn)");
		abort();
	}
	cc->kind = CONN_ARTIFACT_EXPORT;
	cc->fd = pidfd;
	cc->pkg_fetch_pid = pid;

	memset(&ev, 0, sizeof(ev));
	ev.events = EPOLLIN;
	ev.data.ptr = cc;
	if (cix_epoll_ctl(g_epfd, EPOLL_CTL_ADD, cc->fd, &ev) != 0) {
		perror("epoll_ctl ADD image export pidfd");
		abort();
	}
}

/*
 * Issue #129: drives pkg.c's artifact-push queue. pkg.c decides WHAT
 * to publish (only genuine fresh builds) and forks the uploader; the
 * event loop owns reaping it, exactly like every other long-running
 * child here. Called after anything that might have finished a build,
 * and again after each push completes so a queue drains.
 */
static void artifact_push_pump(void)
{
	pid_t pid;
	int pidfd;
	char desc[PKG_NAME_MAX + PKG_VERSION_MAX + 2];
	struct conn *cc;
	struct cix_epoll_event ev;

	if (pkg_artifact_push_try_start(&pid, &pidfd, desc, sizeof(desc)) != 1)
		return;

	cc = calloc(1, sizeof(*cc));
	if (cc == NULL) {
		perror("malloc (artifact push reactor conn)");
		abort();
	}
	cc->kind = CONN_ARTIFACT_PUSH;
	cc->fd = pidfd;
	cc->pkg_fetch_pid = pid;

	memset(&ev, 0, sizeof(ev));
	ev.events = EPOLLIN;
	ev.data.ptr = cc;
	if (cix_epoll_ctl(g_epfd, EPOLL_CTL_ADD, cc->fd, &ev) != 0) {
		perror("epoll_ctl ADD artifact push pidfd");
		abort();
	}
}

static void handle_artifact_push_event(struct conn *cc)
{
	int status = 0;

	cix_epoll_ctl(g_epfd, EPOLL_CTL_DEL, cc->fd, NULL);
	waitpid(cc->pkg_fetch_pid, &status, 0);
	close(cc->fd);
	free(cc);
	pkg_artifact_push_completed(status);
	/* Serialized queue -- one finishing is what lets the next start. */
	artifact_push_pump();
}

/* Reaps the tar child; the POST returned 202 long ago, so the result
 * only ever reaches the operator through GET .../export. */
static void handle_artifact_export_event(struct conn *cc)
{
	int status;

	char errbuf[192];
	ssize_t errn = 0;

	cix_epoll_ctl(g_epfd, EPOLL_CTL_DEL, cc->fd, NULL);
	if (waitpid(cc->pkg_fetch_pid, &status, 0) == cc->pkg_fetch_pid && WIFEXITED(status) &&
	    WEXITSTATUS(status) == 0) {
		g_artifact_export_state = ARTIFACT_EXPORT_READY;
		logstore_write("cixd", "info", "image export: %s@%s ready at %s", g_artifact_export_name,
		               g_artifact_export_version, g_artifact_export_path);
		/* The tarball exists now, which is the whole reason this
		 * export ran -- enqueue the push it was built for. */
		if (g_artifact_export_publish_name[0] != '\0') {
			enum pkg_error perr = pkg_artifact_publish(g_artifact_export_publish_name);

			if (perr == PKG_OK)
				artifact_push_pump();
			else
				logstore_write("cixd", "error",
				                "artifact publish: %s was exported for publishing but "
				                "could not be queued",
				                g_artifact_export_publish_name);
			g_artifact_export_publish_name[0] = '\0';
		}
	} else {
		/* The child has fully exited, so a bounded read of its whole
		 * stderr can't block past the pipe's own buffered content --
		 * O_NONBLOCK on this end guards the empty case. */
		if (g_artifact_export_errfd >= 0)
			errn = read(g_artifact_export_errfd, errbuf, sizeof(errbuf) - 1);
		if (errn < 0)
			errn = 0;
		errbuf[errn] = '\0';
		while (errn > 0 && (errbuf[errn - 1] == '\n' || errbuf[errn - 1] == '\r'))
			errbuf[--errn] = '\0';
		g_artifact_export_state = ARTIFACT_EXPORT_FAILED;
		snprintf(g_artifact_export_error, sizeof(g_artifact_export_error),
		         "tar failed (status 0x%x)%s%s", (unsigned)status, errn > 0 ? ": " : "",
		         errbuf);
		unlink(g_artifact_export_path);
		logstore_write("cixd", "error", "image export: %s failed -- %s", g_artifact_export_name,
		               g_artifact_export_error);
		if (g_artifact_export_publish_name[0] != '\0') {
			logstore_write("cixd", "error",
			                "artifact publish: %s not published -- could not build its "
			                "tarball from the installed tree",
			                g_artifact_export_publish_name);
			g_artifact_export_publish_name[0] = '\0';
		}
	}
	if (g_artifact_export_errfd >= 0) {
		close(g_artifact_export_errfd);
		g_artifact_export_errfd = -1;
	}
	close(cc->fd);
	free(cc);
}

/*
 * Starts the export. Returns 0 with the job running, -1 with err_msg
 * filled. The source tree is tarred from its own directory
 * (tar -C <src> . ) so the archive holds the tree's CONTENTS at top
 * level -- for an image that is exactly the shape ADR-0123's consumer
 * extracts straight into a new version's rootfs, and for a hostbuild
 * artifact it is the shape ADR-0122's package-artifact consumer
 * expects.
 *
 * The output filename is <name>-<version>.tar.gz for both kinds,
 * which is deliberately the exact name the artifact cache serves at
 * (ADR-0122 for packages, ADR-0123's images/ prefix for images) --
 * an export can be pushed to the cache verbatim, with no renaming
 * step that could drift from what a puller later asks for.
 */
static int artifact_export_start(enum artifact_export_kind kind, const char *name,
                                 const char *dest_override, char *err_msg, size_t err_msg_size)
{
	char version[IMAGE_VERSION_MAX];
	char src[PATH_MAX];
	char out_dir[PATH_MAX];
	pid_t pid;
	int pidfd;

	if (g_artifact_export_state == ARTIFACT_EXPORT_BUILDING) {
		snprintf(err_msg, err_msg_size, "an export of \"%s\" is already running",
		         g_artifact_export_name);
		return -1;
	}

	if (kind == ARTIFACT_EXPORT_KIND_IMAGE) {
		if (image_current_version(name, version, sizeof(version)) != IMAGE_OK) {
			snprintf(err_msg, err_msg_size, "no such image, or it has no current version");
			return -1;
		}
		image_version_rootfs_path(name, version, src, sizeof(src));
		snprintf(out_dir, sizeof(out_dir), "%s/images", ARTIFACTS_DIR);
	} else {
		enum pkg_error perr =
		    pkg_hostbuild_artifact_info(name, version, sizeof(version), src, sizeof(src));

		if (perr == PKG_ERR_NOT_FOUND) {
			snprintf(err_msg, err_msg_size, "no such hostbuild package");
			return -1;
		}
		if (perr != PKG_OK) {
			snprintf(err_msg, err_msg_size,
			         "hostbuild \"%s\" is not installed -- nothing to export", name);
			return -1;
		}
		snprintf(out_dir, sizeof(out_dir), "%s/exports", ARTIFACTS_DIR);
	}

	if (access(src, R_OK) != 0) {
		snprintf(err_msg, err_msg_size, "source tree is not readable: %s", src);
		return -1;
	}
	if (persist_mkdir_p(out_dir) != 0) {
		snprintf(err_msg, err_msg_size, "could not create %s: %s", out_dir, strerror(errno));
		return -1;
	}
	if (dest_override != NULL)
		snprintf(g_artifact_export_path, sizeof(g_artifact_export_path), "%s", dest_override);
	else
		snprintf(g_artifact_export_path, sizeof(g_artifact_export_path), "%s/%s-%s.tar.gz",
		         out_dir, name, version);
	unlink(g_artifact_export_path);

	/*
	 * Issue #164: the archive is built by targz_run() below, which
	 * pipes tar into gzip directly. Asking tar to spawn the compressor
	 * itself (--use-compress-program, issue #125's own fix for the
	 * bare-"gzip"-on-no-PATH problem) routes the spawn through
	 * /bin/sh, which the control-plane root deliberately does not have
	 * -- so every export on a real installed host died reporting
	 * "/usr/bin/gzip: Cannot exec" against a gzip that was present and
	 * working. The normalizing flags (ADR-0201/issue #129) travel with
	 * the tar invocation into targz.c; an export is named exactly what
	 * the artifact server serves it at, so two hosts exporting the same
	 * tree must still produce identical bytes -- and they do.
	 */

	{
		int errpipe[2];

		/* Nonblocking read end: the completion handler drains after
		 * exit; an empty pipe must return 0/EAGAIN, never block the
		 * event loop. Loss of the pipe is not fatal -- same posture
		 * as pkg.c's run_subprocess(). */
		if (pipe2(errpipe, O_CLOEXEC | O_NONBLOCK) != 0) {
			errpipe[0] = -1;
			errpipe[1] = -1;
		}
		pid = fork();
		if (pid < 0) {
			snprintf(err_msg, err_msg_size, "fork failed: %s", strerror(errno));
			if (errpipe[0] >= 0) {
				close(errpipe[0]);
				close(errpipe[1]);
			}
			return -1;
		}
		if (pid == 0) {
			if (errpipe[1] >= 0)
				dup2(errpipe[1], 2);
			_exit(targz_run(src, g_artifact_export_path));
		}
		if (errpipe[1] >= 0)
			close(errpipe[1]);
		if (g_artifact_export_errfd >= 0)
			close(g_artifact_export_errfd);
		g_artifact_export_errfd = errpipe[0];
	}
	pidfd = sys_pidfd_open(pid, 0);
	if (pidfd < 0) {
		snprintf(err_msg, err_msg_size, "pidfd_open failed: %s", strerror(errno));
		kill(pid, SIGKILL);
		waitpid(pid, NULL, 0);
		if (g_artifact_export_errfd >= 0) {
			close(g_artifact_export_errfd);
			g_artifact_export_errfd = -1;
		}
		return -1;
	}
	register_artifact_export_pidfd(pid, pidfd);
	g_artifact_export_kind = kind;
	snprintf(g_artifact_export_name, sizeof(g_artifact_export_name), "%s", name);
	snprintf(g_artifact_export_version, sizeof(g_artifact_export_version), "%s", version);
	g_artifact_export_error[0] = '\0';
	g_artifact_export_state = ARTIFACT_EXPORT_BUILDING;
	return 0;
}

/*
 * GET /v1/images/{name}/export/download?offset=N&length=M -- the bytes
 * of a ready export, in bounded chunks the caller loops over.
 *
 * Deliberately chunked rather than one streamed response. This daemon
 * is a single event loop (ADR-0007/0009): writing a multi-gigabyte body
 * inline would freeze the control plane for the whole transfer (ADR-0180's
 * own wedge), and the two obvious escapes are both worse here -- a forked
 * child cannot write to the parent's TLS session, and a real EPOLLOUT
 * streaming state machine is a large change to a load-bearing HTTP layer
 * for one endpoint. A bounded chunk costs one small allocation and a few
 * hundred milliseconds, and the caller reassembles; the existing
 * build-log endpoint already establishes that responses here are capped
 * rather than unbounded.
 *
 * The caller learns the total size from GET .../export's own size_bytes
 * (it must poll that for "ready" anyway), so no custom header is needed
 * here and the HTTP layer stays untouched.
 */
#define ARTIFACT_EXPORT_CHUNK_MAX (8 * 1024 * 1024)

static void handle_artifact_export_download(int fd, enum artifact_export_kind kind,
                                            const char *name, const char *full_path)
{
	long long offset = 0;
	long long length = ARTIFACT_EXPORT_CHUNK_MAX;
	struct stat st;
	int file_fd;
	char *buf;
	ssize_t got;

	if (g_artifact_export_state != ARTIFACT_EXPORT_READY || g_artifact_export_name[0] == '\0' ||
	    g_artifact_export_kind != kind || strcmp(g_artifact_export_name, name) != 0) {
		respond_error(fd, 404, "Not Found",
		              "no ready export for this subject -- POST .../export first");
		return;
	}
	{
		char v[64];

		if (url_query_param(full_path, "offset", v, sizeof(v)) == 0)
			offset = strtoll(v, NULL, 10);
		if (url_query_param(full_path, "length", v, sizeof(v)) == 0)
			length = strtoll(v, NULL, 10);
	}
	if (offset < 0 || length <= 0) {
		respond_error(fd, 400, "Bad Request", "offset must be >= 0 and length > 0");
		return;
	}
	if (length > ARTIFACT_EXPORT_CHUNK_MAX)
		length = ARTIFACT_EXPORT_CHUNK_MAX;

	file_fd = open(g_artifact_export_path, O_RDONLY);
	if (file_fd < 0) {
		respond_error(fd, 500, "Internal Server Error", "export artifact is no longer readable");
		return;
	}
	if (fstat(file_fd, &st) != 0) {
		close(file_fd);
		respond_error(fd, 500, "Internal Server Error", "stat failed");
		return;
	}
	if (offset >= (long long)st.st_size) {
		close(file_fd);
		respond_error(fd, 416, "Range Not Satisfiable", "offset is at or past the end of the artifact");
		return;
	}
	if (offset + length > (long long)st.st_size)
		length = (long long)st.st_size - offset;
	if (lseek(file_fd, (off_t)offset, SEEK_SET) == (off_t)-1) {
		close(file_fd);
		respond_error(fd, 500, "Internal Server Error", "seek failed");
		return;
	}
	buf = malloc((size_t)length);
	if (buf == NULL) {
		close(file_fd);
		respond_error(fd, 500, "Internal Server Error", "out of memory");
		return;
	}
	got = 0;
	while (got < length) {
		ssize_t n = read(file_fd, buf + got, (size_t)(length - got));

		if (n <= 0)
			break;
		got += n;
	}
	close(file_fd);

	http_set_blocking(fd);
	http_write_response(fd, 200, "OK", "application/octet-stream", buf, (size_t)got);
	free(buf);
}

/*
 * POST /v1/images/{name}/rename {"new_name": "..."} (issue #124).
 * Renames the image directory and every package row recorded against
 * it, together -- moving one without the other is precisely how the
 * orphaned rows in #111 came about.
 */
static void handle_image_rename(int fd, const char *name, const char *body, size_t body_len)
{
	struct json_value *root = NULL;
	const char *new_name;
	enum image_error err;

	if (body == NULL || body_len == 0 || (root = json_parse(body, body_len)) == NULL) {
		respond_error(fd, 400, "Bad Request", "body must be JSON");
		json_free(root);
		return;
	}
	new_name = json_as_string(json_object_get(root, "new_name"));
	if (new_name == NULL || new_name[0] == '\0') {
		respond_error(fd, 400, "Bad Request", "new_name is required");
		json_free(root);
		return;
	}
	err = image_rename(name, new_name);
	json_free(root);
	switch (err) {
	case IMAGE_OK:
		http_set_blocking(fd);
		http_write_response(fd, 204, "No Content", "application/json", "", 0);
		return;
	case IMAGE_ERR_INVALID_NAME:
		respond_error(fd, 400, "Bad Request", "invalid image name");
		return;
	case IMAGE_ERR_DUPLICATE:
		respond_error(fd, 409, "Conflict", "an image with that name already exists");
		return;
	case IMAGE_ERR_PROTECTED:
		respond_error(fd, 400, "Bad Request", "the default image cannot be renamed");
		return;
	case IMAGE_ERR_IN_USE:
		respond_error(fd, 409, "Conflict",
		              "a container is using this image -- a running container's overlay "
		              "lowerdir points at this directory by path");
		return;
	case IMAGE_ERR_NOT_FOUND:
		respond_error(fd, 404, "Not Found", "no such image");
		return;
	default:
		respond_error(fd, 500, "Internal Server Error", "rename failed");
		return;
	}
}

static void handle_artifact_export_post(int fd, enum artifact_export_kind kind, const char *name)
{
	char err_msg[256];

	if (artifact_export_start(kind, name, NULL, err_msg, sizeof(err_msg)) != 0) {
		int code = (strstr(err_msg, "already running") != NULL)  ? 409
		           : (strstr(err_msg, "no such") != NULL)        ? 404
		           : (strstr(err_msg, "is not installed") != NULL) ? 409
		                                                          : 500;

		respond_error(fd, code,
		              code == 409   ? "Conflict"
		              : code == 404 ? "Not Found"
		                            : "Internal Server Error",
		              err_msg);
		return;
	}
	http_set_blocking(fd);
	http_write_response(fd, 202, "Accepted", "application/json", "", 0);
}

static void handle_artifact_export_get(int fd, enum artifact_export_kind kind, const char *name)
{
	struct json_writer w;
	const char *state = "none";
	struct stat st;
	long long size = -1;

	if (g_artifact_export_name[0] != '\0' && g_artifact_export_kind == kind &&
	    strcmp(g_artifact_export_name, name) == 0) {
		switch (g_artifact_export_state) {
		case ARTIFACT_EXPORT_BUILDING: state = "building"; break;
		case ARTIFACT_EXPORT_READY: state = "ready"; break;
		case ARTIFACT_EXPORT_FAILED: state = "failed"; break;
		default: state = "none"; break;
		}
	}
	jw_init(&w);
	jw_obj_open(&w);
	jw_key(&w, kind == ARTIFACT_EXPORT_KIND_IMAGE ? "image" : "package");
	jw_str(&w, name);
	jw_key(&w, "state");
	jw_str(&w, state);
	if (strcmp(state, "none") != 0) {
		jw_key(&w, "version");
		jw_str(&w, g_artifact_export_version);
		jw_key(&w, "artifact_path");
		jw_str(&w, g_artifact_export_path);
		jw_key(&w, "artifact_name");
		{
			const char *base = strrchr(g_artifact_export_path, '/');

			jw_str(&w, base != NULL ? base + 1 : g_artifact_export_path);
		}
	}
	if (strcmp(state, "ready") == 0 && stat(g_artifact_export_path, &st) == 0)
		size = (long long)st.st_size;
	jw_key(&w, "size_bytes");
	jw_num(&w, (double)size);
	jw_key(&w, "error");
	jw_str(&w, g_artifact_export_error);
	jw_obj_close(&w);
	w.buf[w.len] = '\0';
	http_set_blocking(fd);
	http_write_response(fd, 200, "OK", "application/json", w.buf, w.len);
	jw_free(&w);
}

static void register_iso_assemble_pidfd(pid_t pid, int pidfd)
{
	struct conn *cc;
	struct cix_epoll_event ev;

	cc = calloc(1, sizeof(*cc));
	if (cc == NULL) {
		perror("malloc (iso assemble reactor conn)");
		abort();
	}
	cc->kind = CONN_ISO_ASSEMBLE;
	cc->fd = pidfd;
	cc->pkg_fetch_pid = pid;

	memset(&ev, 0, sizeof(ev));
	ev.events = EPOLLIN;
	ev.data.ptr = cc;
	if (cix_epoll_ctl(g_epfd, EPOLL_CTL_ADD, cc->fd, &ev) != 0) {
		perror("epoll_ctl ADD iso assemble pidfd");
		abort();
	}
}

/*
 * Validates every real precondition (the "cix"/"kernel" hostbuild
 * artifacts, the "isotools" hostbuild artifact, and the operator-
 * populated signing key pair at SIGNING_KEYS_DIR) up front, so a
 * missing one fails the POST itself with a specific, actionable
 * message -- never a background failure the caller has to poll for
 * to discover. Returns 0 and forks the real build (state -> BUILDING)
 * on success; -1 with err_msg filled otherwise. err_msg_size must be
 * at least 256. Caller (handle_system_iso_post()) is responsible for
 * the "already building" check -- kept there, not here, so it maps to
 * its own distinct 409 rather than this function's 400-shaped
 * "missing precondition" errors, mirroring respond_pkg_error()'s own
 * PKG_ERR_BUSY (409) vs. PKG_ERR_INVALID_TOOLCHAIN (400) split.
 */
static int iso_build_start(const char *disk, const char *ip, const char *prefix,
                            const char *gateway, const char *interface, char *err_msg,
                            size_t err_msg_size)
{
	char mkinstalleriso_bin[PATH_MAX];
	char cix_install_bin[PATH_MAX];
	char cix_recover_bin[PATH_MAX];
	char cix_boot_bin[PATH_MAX];
	char bzimage_path[PATH_MAX];
	char squashfs_path[PATH_MAX];
	char isotools_root[PATH_MAX];
	char seed_dir[PATH_MAX];
	char signing_key[PATH_MAX];
	char signing_cert_pem[PATH_MAX];
	char signing_cert_der[PATH_MAX];
	char stage_dir[PATH_MAX];
	char kernel_args[512];
	char iso_modules_dir[PATH_MAX];
	char iso_kmod_bin_dir[PATH_MAX];
	/*
	 * 17, for argv[0..15] and the NULL terminator. It was 15, which
	 * held exactly the previous 14 arguments and that NULL -- so the
	 * two added below would have written past the end of the array.
	 * That is not hypothetical: #415 was a real argv overflow on this
	 * same pattern, found in a crash rather than in review.
	 */
	char *argv[17];
	pid_t pid;
	int pidfd;
	int output_pipe[2];
	struct {
		const char *path;
		const char *what;
	} required[] = {
	    {mkinstalleriso_bin, "mkinstalleriso (from a \"cix\" hostbuild)"},
	    {cix_install_bin, "cix-install (from a \"cix\" hostbuild)"},
	    {cix_recover_bin, "cix-recover (from a \"cix\" hostbuild, ADR-0146)"},
	    {cix_boot_bin, "cix-boot.efi (from a \"cix\" hostbuild, ADR-0215)"},
	    {bzimage_path, "bzImage (from a \"kernel\" hostbuild)"},
	    {squashfs_path, "cixd-root.squashfs (assembled after a \"cix\" hostbuild)"},
	    {isotools_root, "isotools artifact directory (from an \"isotools\" hostbuild)"},
	    {signing_key, "signing key (operator-provided at SIGNING_KEYS_DIR)"},
	    {signing_cert_pem, "signing cert .crt (operator-provided at SIGNING_KEYS_DIR)"},
	    {signing_cert_der, "signing cert .cer (operator-provided at SIGNING_KEYS_DIR)"},
	};
	size_t i;

	snprintf(mkinstalleriso_bin, sizeof(mkinstalleriso_bin), "%s/cix/mkinstalleriso",
	         ARTIFACTS_DIR);
	snprintf(cix_install_bin, sizeof(cix_install_bin), "%s/cix/cix-install",
	         ARTIFACTS_DIR);
	snprintf(cix_recover_bin, sizeof(cix_recover_bin), "%s/cix/cix-recover",
	         ARTIFACTS_DIR);
	snprintf(cix_boot_bin, sizeof(cix_boot_bin), "%s/cix/cix-boot.efi", ARTIFACTS_DIR);
	snprintf(bzimage_path, sizeof(bzimage_path), "%s/kernel/bzImage", ARTIFACTS_DIR);
	snprintf(squashfs_path, sizeof(squashfs_path), "%s/cixd-root.squashfs", BOOTROOT_DIR);
	snprintf(isotools_root, sizeof(isotools_root), "%s/isotools", ARTIFACTS_DIR);
	snprintf(signing_key, sizeof(signing_key), "%s/cix-signing.key", SIGNING_KEYS_DIR);
	snprintf(signing_cert_pem, sizeof(signing_cert_pem), "%s/cix-signing.crt", SIGNING_KEYS_DIR);
	snprintf(signing_cert_der, sizeof(signing_cert_der), "%s/cix-signing.cer", SIGNING_KEYS_DIR);

	for (i = 0; i < sizeof(required) / sizeof(required[0]); i++) {
		if (access(required[i].path, R_OK) != 0) {
			snprintf(err_msg, err_msg_size, "missing %s: %s", required[i].what, required[i].path);
			return -1;
		}
	}

	/*
	 * Only pass what the caller actually specified (#271).
	 *
	 * Every unset field used to become the literal "CHANGEME", and the
	 * documented way to install was to edit the kernel command line at
	 * the GRUB menu with 'e' before booting -- typed blind, against
	 * placeholders, with no feedback until the installer refused to
	 * start. cix-install asks for anything it was not given now, listing
	 * the machine's own disks and NICs, so an ISO built with none of
	 * these is the smoothest one rather than a broken one.
	 *
	 * Supplying some and not others is still meaningful: a fixed disk
	 * with a prompted address, say, for a fleet of identical machines.
	 */
	kernel_args[0] = '\0';
	{
		size_t used = 0;
		const struct {
			const char *flag;
			const char *val;
		} opt[] = {
			{ "--disk=", disk },       { "--ip=", ip },
			{ "--prefix=", prefix },   { "--gateway=", gateway },
			{ "--interface=", interface },
		};
		size_t k;

		for (k = 0; k < sizeof(opt) / sizeof(opt[0]); k++) {
			if (opt[k].val == NULL || opt[k].val[0] == '\0')
				continue;
			used += (size_t)snprintf(kernel_args + used, sizeof(kernel_args) - used, "%s%s%s",
			                          used > 0 ? " " : "", opt[k].flag, opt[k].val);
			if (used >= sizeof(kernel_args))
				break;
		}
	}

	snprintf(stage_dir, sizeof(stage_dir), "%s/.stage", ISO_DIR);
	/* ISO_OUTPUT_PATH is set once at startup -- see its own note there. */

	argv[0] = mkinstalleriso_bin;
	argv[1] = stage_dir;
	argv[2] = cix_install_bin;
	argv[3] = cix_recover_bin;
	argv[4] = cix_boot_bin;
	argv[5] = bzimage_path;
	argv[6] = squashfs_path;
	argv[7] = signing_key;
	argv[8] = signing_cert_pem;
	argv[9] = signing_cert_der;
	argv[10] = ISO_OUTPUT_PATH;
	argv[11] = kernel_args;
	argv[12] = isotools_root;
	/*
	 * The kernel module tree and the module tools (#429 follow-on).
	 *
	 * mkinstalleriso stages the NIC drivers' dependency closure and
	 * modprobe onto the media, so cix-install can load them before it
	 * lists interfaces. Without this the installer could only ever show
	 * interfaces whose driver is built into the kernel -- virtio_net --
	 * and a real machine's built-in Ethernet was absent from the
	 * screen entirely, which blocked a bare-metal install on
	 * 2026-09-12.
	 *
	 * Both resolved through the same helpers the bootroot assembly
	 * uses, deliberately: one answer to "where does a kernel artifact
	 * keep its modules", not two. Either may come back "" and that is
	 * not a failure -- mkinstalleriso says so on its own output and
	 * builds media that still installs on virtio.
	 *
	 * argc is checked exactly on the callee (`argc != 16`), and this
	 * pair takes it from 14 to 16. See the seed_dir comment below for
	 * why that is worth being careful about: this call site once passed
	 * one argument fewer than mkinstalleriso required, and every
	 * POST /v1/system/iso on a real host answered with a fragment of
	 * mkinstalleriso's usage text -- an error message made of
	 * documentation.
	 */
	resolve_kernel_modules_dir(iso_modules_dir, sizeof(iso_modules_dir));
	resolve_kmod_bin_dir(iso_kmod_bin_dir, sizeof(iso_kmod_bin_dir));
	/*
	 * The package seed directory (#189 part 2), "" for none -- the same
	 * convention mkbootroot uses for an absent optional input.
	 *
	 * This argument existed on the callee and never on this caller:
	 * mkinstalleriso grew it, checks `argc != 14`, and this call site
	 * still passed 13 and a NULL. Every POST /v1/system/iso on a real
	 * host therefore printed mkinstalleriso's usage text and exited 2,
	 * surfacing as "mkinstalleriso failed (status 0x200)" followed by
	 * a fragment of that usage prose -- an error message made of
	 * documentation, which reads like anything except a wrong argument
	 * count. Found while verifying something unrelated (ADR-0217's
	 * libc-dev removal), which is the only reason it was found at all:
	 * the ISO endpoint had no test that ran the real binary.
	 *
	 * The product decision this once deferred is made (#135): the media
	 * carries a real seed. A fresh install otherwise cannot obtain a
	 * single recipe without a network it cannot name -- no recipes
	 * without a forge, no forge without DNS, no DNS without a recipe --
	 * and the only way through was hand-feeding it hundreds of recipes
	 * from a developer machine over literal IPs.
	 *
	 * Staged fresh on every build rather than kept: a seed is a
	 * snapshot of this host's recipes and artifacts at the moment the
	 * ISO is made, and a stale one would ship recipes that no longer
	 * match their artifacts.
	 *
	 * A staging failure fails the whole build. Media that claims a seed
	 * and cannot bring up DNS is worse than media carrying none,
	 * because nothing reveals it until the installed box is already
	 * standing there unable to resolve anything.
	 */
	snprintf(seed_dir, sizeof(seed_dir), "%s/.seed", ISO_DIR);
	cix_btrfs_subvol_delete_or_rmtree(seed_dir);
	{
		char seed_err[256];

		seed_err[0] = '\0';
		if (pkg_seed_stage(seed_dir, seed_err, sizeof(seed_err)) != PKG_OK) {
			snprintf(err_msg, err_msg_size, "could not stage the installer package seed: %s",
			         seed_err[0] != '\0' ? seed_err : "unknown");
			return -1;
		}
	}
	argv[13] = seed_dir;
	argv[14] = iso_modules_dir;
	argv[15] = iso_kmod_bin_dir;
	argv[16] = NULL;

	/*
	 * Capture the child's stdout and stderr. Not fatal if it fails --
	 * the build still runs exactly as it did before this existed, just
	 * back to bare exit-status reporting. O_NONBLOCK on the read end
	 * only; the write end becomes mkinstalleriso's own stdio and must
	 * stay blocking.
	 */
	if (pipe2(output_pipe, O_CLOEXEC) != 0) {
		perror("pipe2 (iso assembly output capture)");
		output_pipe[0] = output_pipe[1] = -1;
	} else if (fcntl(output_pipe[0], F_SETFL, O_NONBLOCK) != 0) {
		perror("fcntl O_NONBLOCK (iso assembly output capture)");
		close(output_pipe[0]);
		close(output_pipe[1]);
		output_pipe[0] = output_pipe[1] = -1;
	}

	pid = fork();
	if (pid < 0) {
		snprintf(err_msg, err_msg_size, "fork failed: %s", strerror(errno));
		if (output_pipe[0] >= 0) {
			close(output_pipe[0]);
			close(output_pipe[1]);
		}
		return -1;
	}
	if (pid == 0) {
		if (output_pipe[1] >= 0) {
			dup2(output_pipe[1], STDOUT_FILENO);
			dup2(output_pipe[1], STDERR_FILENO);
		}
		execve(mkinstalleriso_bin, argv, environ);
		perror("child: execve mkinstalleriso");
		_exit(127);
	}
	if (output_pipe[1] >= 0)
		close(output_pipe[1]);
	g_iso_output.len = 0;
	g_iso_output.rd = output_pipe[0];
	register_iso_output();

	pidfd = sys_pidfd_open(pid, 0);
	if (pidfd < 0) {
		snprintf(err_msg, err_msg_size, "pidfd_open failed: %s", strerror(errno));
		kill(pid, SIGKILL);
		waitpid(pid, NULL, 0);
		return -1;
	}
	register_iso_assemble_pidfd(pid, pidfd);
	g_iso_build_state = ISO_BUILD_BUILDING;
	g_iso_build_error[0] = '\0';
	return 0;
}

/* Reaps iso_build_start()'s own mkinstalleriso child, same shape as
/*
 * Reads the version out of a minisign signature's trusted comment.
 *
 * The file's third line is "trusted comment: cix installer iso, vX.Y.Z"
 * -- this project's own wording, written by sign_finished_iso(). A
 * signature that does not carry it (someone else's, or a future format
 * change) simply yields nothing rather than a guess.
 */
static void read_iso_signed_version(const char *sig_path, char *out, size_t out_size)
{
	FILE *f;
	char line[512];
	const char *marker = "trusted comment:";
	const char *prefix = "cix installer iso, ";

	out[0] = '\0';
	f = fopen(sig_path, "r");
	if (f == NULL)
		return;
	while (fgets(line, sizeof(line), f) != NULL) {
		char *p;

		if (strncmp(line, marker, strlen(marker)) != 0)
			continue;
		p = strstr(line, prefix);
		if (p == NULL)
			break;
		p += strlen(prefix);
		p[strcspn(p, "\r\n")] = '\0';
		snprintf(out, out_size, "%s", p);
		break;
	}
	fclose(f);
}

/*
 * Recovers ISO state from disk at startup (#205).
 *
 * An ISO is a file. Keeping the only record of it in memory meant a
 * restart reported "none" while the artifact sat there untouched, and
 * POST /system/iso/publish refused it with "no ISO has been built on
 * this host" -- a false statement about a file the daemon could see.
 * Any restart between building and publishing stranded a finished,
 * signed ISO with no route out but a full rebuild.
 *
 * Derived rather than persisted, deliberately: a stored claim about
 * the ISO would be a second source of truth able to disagree with the
 * filesystem, and the thing it describes is already on the filesystem.
 *
 * A recovered ISO may predate the running daemon, and that is reported
 * (built_version) rather than hidden. It is still a real, bootable,
 * correctly signed artifact -- refusing to admit it exists would not
 * make it any less publishable by hand, only harder to notice.
 */
static void iso_recover_state(void)
{
	char sig_path[PATH_MAX];
	struct stat st;

	if (stat(ISO_OUTPUT_PATH, &st) != 0 || !S_ISREG(st.st_mode))
		return;

	g_iso_build_state = ISO_BUILD_READY;
	snprintf(sig_path, sizeof(sig_path), "%s.minisig", ISO_OUTPUT_PATH);
	if (stat(sig_path, &st) == 0 && S_ISREG(st.st_mode)) {
		snprintf(g_iso_signature_path, sizeof(g_iso_signature_path), "%s", sig_path);
		read_iso_signed_version(sig_path, g_iso_built_version, sizeof(g_iso_built_version));
	}

	/*
	 * Said out loud at boot, because a recovered ISO is exactly the
	 * one an operator might publish without having built it in this
	 * session -- and if it came from an older cixd, that is worth
	 * knowing before it is published as current.
	 */
	if (g_iso_signature_path[0] == '\0')
		logstore_write("cixd", "info",
		               "iso: found an unsigned ISO from a previous run (%s) -- it cannot be "
		               "published until it is rebuilt with a release key installed",
		               ISO_OUTPUT_PATH);
	else if (g_iso_built_version[0] != '\0' && strcmp(g_iso_built_version, CIX_BUILD_VERSION) != 0)
		logstore_write("cixd", "info",
		               "iso: found a signed ISO from a previous run, built by %s (this daemon is "
		               "%s) -- rebuild it if the installer should carry the running version",
		               g_iso_built_version, CIX_BUILD_VERSION);
	else
		logstore_write("cixd", "info", "iso: found a signed ISO from a previous run (%s)",
		               ISO_OUTPUT_PATH);
}

/*
 * Signs the finished ISO (ADR-0220), if this host holds a release key.
 *
 * Deliberately does NOT fail the build when no key is installed: an
 * unsigned ISO still installs, and most hosts that can build one are
 * not the designated release host and should not hold signing material
 * at all. The signature's absence is reported honestly instead --
 * signature_path stays null -- rather than being inferred from a
 * successful build.
 *
 * A signing failure with a key present is different, and is logged as
 * an error: that means the key is there and did not work, which an
 * operator needs to see before shipping the ISO as signed.
 */
static void sign_finished_iso(void)
{
	char comment[256];
	enum releasekey_error rc;
	char sig_path[PATH_MAX];

	g_iso_signature_path[0] = '\0';
	g_iso_built_version[0] = '\0';
	if (!releasekey_is_set()) {
		logstore_write("cixd", "info",
		               "iso assembly: no release key installed -- ISO is unsigned");
		return;
	}
	if ((size_t)snprintf(sig_path, sizeof(sig_path), "%s.minisig", ISO_OUTPUT_PATH) >=
	    sizeof(sig_path)) {
		logstore_write("cixd", "error", "iso assembly: signature path too long");
		return;
	}
	/*
	 * The trusted comment is signed too, so it is a real claim about
	 * the artifact rather than a label anyone can rewrite: naming the
	 * build that produced it means a verifier learns which release
	 * these bytes are, not merely that Cix signed something.
	 */
	snprintf(comment, sizeof(comment), "cix installer iso, %s", CIX_BUILD_VERSION);
	rc = releasekey_sign_file(ISO_OUTPUT_PATH, sig_path, comment);
	if (rc != RELEASEKEY_OK) {
		logstore_write("cixd", "error", "iso assembly: signing failed: %s",
		               releasekey_strerror(rc));
		return;
	}
	snprintf(g_iso_signature_path, sizeof(g_iso_signature_path), "%s", sig_path);
	/* Read back from the signature just written, rather than assigned
	 * from CIX_BUILD_VERSION: one answer to "where does built_version
	 * come from", and it round-trips what was actually signed. */
	read_iso_signed_version(sig_path, g_iso_built_version, sizeof(g_iso_built_version));
	logstore_write("cixd", "info", "iso assembly: signed (%s)", g_iso_signature_path);
}

/*
 * ADR-0220: publishing the finished ISO to the artifact cache.
 *
 * Two uploads, in a required order: the signature first, then the ISO.
 * The cache refuses an ISO with no signature beside it, and that
 * refusal is correct -- an unsigned installer is precisely the
 * artifact that must not become downloadable. Doing it in this order
 * means a failure between the two leaves a signature with no ISO
 * (harmless, and overwritten by the next attempt) rather than a
 * bootable image nobody can verify.
 *
 * Deliberately not routed through pkg.c's package push queue: that
 * queue publishes freshly built packages keyed by name@version, and an
 * ISO has neither -- no recipe stands behind it and nothing resolves
 * it by version. The cache counts installers separately for the same
 * reason.
 */
enum iso_publish_step { ISO_PUBLISH_SIG, ISO_PUBLISH_IMAGE };

static enum { ISO_PUB_NONE, ISO_PUB_RUNNING, ISO_PUB_DONE, ISO_PUB_FAILED } g_iso_publish_state =
    ISO_PUB_NONE;
static enum iso_publish_step g_iso_publish_step;
static char g_iso_publish_name[256];   /* canonical .iso name in the cache */
static char g_iso_publish_error[256];
static char g_iso_publish_status_path[PATH_MAX];

static const char *iso_publish_state_str(void)
{
	switch (g_iso_publish_state) {
	case ISO_PUB_RUNNING:
		return "publishing";
	case ISO_PUB_DONE:
		return "published";
	case ISO_PUB_FAILED:
		return "failed";
	default:
		return "none";
	}
}

/*
 * The cache's canonical installer name:
 * cix-installer-<version>-<release>-<arch>.iso.
 *
 * The architecture is in the name because a checksum cannot tell an
 * aarch64 image from an x86_64 one -- only the name can. The version
 * is this build's own, with its leading "v" stripped: the cache splits
 * name/version/release itself, and "v2.4.0" would make the version
 * field disagree with every package already published from the same
 * tag.
 */
static void iso_publish_canonical_name(char *out, size_t out_size, const char *suffix)
{
	struct utsname uts;
	const char *arch = "unknown";
	const char *ver = CIX_BUILD_VERSION;

	if (uname(&uts) == 0 && uts.machine[0] != '\0')
		arch = uts.machine;
	if (ver[0] == 'v')
		ver++;
	snprintf(out, out_size, "cix-installer-%s-1-%s.iso%s", ver, arch, suffix);
}

static int start_iso_publish_upload(enum iso_publish_step step)
{
	char remote[256];
	char local[PATH_MAX];
	char url[PKGARTIFACT_URL_MAX + 320];
	char auth[512];
	pid_t pid;
	int pidfd;

	if (step == ISO_PUBLISH_SIG) {
		iso_publish_canonical_name(remote, sizeof(remote), ".minisig");
		snprintf(local, sizeof(local), "%s", g_iso_signature_path);
	} else {
		iso_publish_canonical_name(remote, sizeof(remote), "");
		snprintf(local, sizeof(local), "%s", ISO_OUTPUT_PATH);
	}
	if (pkg_artifact_push_request(remote, url, sizeof(url), auth, sizeof(auth)) != PKG_OK) {
		snprintf(g_iso_publish_error, sizeof(g_iso_publish_error),
		         "no artifact cache is configured");
		return -1;
	}

	snprintf(g_iso_publish_status_path, sizeof(g_iso_publish_status_path), "%s/.iso-publish-status",
	         ISO_DIR);
	unlink(g_iso_publish_status_path);

	pid = fork();
	if (pid < 0) {
		snprintf(g_iso_publish_error, sizeof(g_iso_publish_error), "fork failed: %s",
		         strerror(errno));
		return -1;
	}
	if (pid == 0) {
		char sha[65];
		char sha_header[96];

		/* Digest in the child. An ISO is hundreds of megabytes and
		 * hashing it on the event-loop thread would stall every other
		 * request for as long as the file is big -- the same reason
		 * the package pusher does it here too. */
		if (pkg_run_capture_sha256(local, sha, sizeof(sha)) != 0)
			_exit(90);
		snprintf(sha_header, sizeof(sha_header), "X-Cix-Sha256: %s", sha);
		{
			char *argv[] = { (char *)PKG_CURL_BIN,
				         (char *)"-s",
				         PKG_CURL_STALL_GUARD_ARGS,
				         (char *)"--upload-file",
				         local,
				         (char *)"-H",
				         auth,
				         (char *)"-H",
				         sha_header,
				         (char *)"--output",
				         (char *)"/dev/null",
				         (char *)"--write-out",
				         (char *)"%{http_code}",
				         url,
				         NULL };
			int sfd = open(g_iso_publish_status_path, O_WRONLY | O_CREAT | O_TRUNC, 0600);

			if (sfd >= 0) {
				dup2(sfd, STDOUT_FILENO);
				close(sfd);
			}
			execve(PKG_CURL_BIN, argv, environ);
		}
		_exit(127);
	}
	pidfd = sys_pidfd_open(pid, 0);
	if (pidfd < 0) {
		snprintf(g_iso_publish_error, sizeof(g_iso_publish_error), "pidfd_open failed: %s",
		         strerror(errno));
		kill(pid, SIGKILL);
		waitpid(pid, NULL, 0);
		return -1;
	}
	g_iso_publish_step = step;
	{
		struct conn *cc = calloc(1, sizeof(*cc));
		struct cix_epoll_event ev;

		if (cc == NULL) {
			perror("malloc (iso publish reactor conn)");
			abort();
		}
		cc->kind = CONN_ISO_PUBLISH;
		cc->fd = pidfd;
		cc->pkg_fetch_pid = pid;
		memset(&ev, 0, sizeof(ev));
		ev.events = EPOLLIN;
		ev.data.ptr = cc;
		if (cix_epoll_ctl(g_epfd, EPOLL_CTL_ADD, cc->fd, &ev) != 0) {
			perror("epoll_ctl ADD iso publish pidfd");
			abort();
		}
	}
	iso_publish_canonical_name(g_iso_publish_name, sizeof(g_iso_publish_name), "");
	logstore_write("cixd", "info", "iso publish: uploading %s", remote);
	return 0;
}

static void handle_iso_publish_event(struct conn *cc)
{
	int status;
	int http = 0;
	FILE *f;

	cix_epoll_ctl(g_epfd, EPOLL_CTL_DEL, cc->fd, NULL);
	waitpid(cc->pkg_fetch_pid, &status, 0);
	close(cc->fd);

	f = fopen(g_iso_publish_status_path, "r");
	if (f != NULL) {
		if (fscanf(f, "%d", &http) != 1)
			http = 0;
		fclose(f);
	}

	if (!WIFEXITED(status) || WEXITSTATUS(status) != 0 || http < 200 || http >= 300) {
		g_iso_publish_state = ISO_PUB_FAILED;
		/*
		 * Name the HTTP status, not just "failed". A 409 here means
		 * something specific and actionable -- the cache refused an
		 * ISO whose signature it does not have -- and collapsing it
		 * into a generic failure is exactly the diagnostic gap that
		 * made earlier publish failures unreadable.
		 */
		snprintf(g_iso_publish_error, sizeof(g_iso_publish_error),
		         "%s upload failed (exit 0x%x, HTTP %d)",
		         g_iso_publish_step == ISO_PUBLISH_SIG ? "signature" : "iso", (unsigned)status,
		         http);
		logstore_write("cixd", "error", "iso publish: %s", g_iso_publish_error);
		free(cc);
		return;
	}

	if (g_iso_publish_step == ISO_PUBLISH_SIG) {
		/* Signature is up; the ISO may now follow. */
		free(cc);
		if (start_iso_publish_upload(ISO_PUBLISH_IMAGE) != 0) {
			g_iso_publish_state = ISO_PUB_FAILED;
			logstore_write("cixd", "error", "iso publish: %s", g_iso_publish_error);
		}
		return;
	}

	g_iso_publish_state = ISO_PUB_DONE;
	g_iso_publish_error[0] = '\0';
	logstore_write("cixd", "info", "iso publish: published %s", g_iso_publish_name);
	free(cc);
}

/*
 * handle_bootroot_assemble_event() -- updates g_iso_build_state for
 * GET /v1/system/iso to report back, since no REST response is waiting
 * on this (the original POST already returned 202 long before this
 * fires). */
static void handle_iso_assemble_event(struct conn *cc)
{
	int status;
	char output[BOOTROOT_OUTPUT_CAPTURE_MAX + 1];
	int output_len;

	cix_epoll_ctl(g_epfd, EPOLL_CTL_DEL, cc->fd, NULL);
	/*
	 * One last non-blocking drain before reporting: the incremental
	 * CONN_ISO_OUTPUT reader may not have been scheduled between
	 * mkinstalleriso's final write() and its exit. By the time waitpid()
	 * confirms the exit the child's fds are gone, so this returns
	 * whatever is still buffered or immediate EOF -- it never blocks.
	 */
	child_output_readable(&g_iso_output);
	output_len = g_iso_output.len;
	memcpy(output, g_iso_output.buf, (size_t)output_len);
	output[output_len] = '\0';

	if (waitpid(cc->pkg_fetch_pid, &status, 0) == cc->pkg_fetch_pid && WIFEXITED(status) &&
	    WEXITSTATUS(status) == 0) {
		g_iso_build_state = ISO_BUILD_READY;
		fprintf(stderr, "iso assembly: succeeded (%s)\n", ISO_OUTPUT_PATH);
		logstore_write("cixd", "info", "iso assembly: succeeded (%s)", ISO_OUTPUT_PATH);
		sign_finished_iso();
		/* A successful run that still printed something is worth
		 * seeing -- ADR-0154's mksquashfs bug exited 0 and produced
		 * wrong output, and said so on stderr the whole time. */
		if (output_len > 0)
			logstore_write("cixd", "info", "iso assembly: output: %s", output);
	} else {
		g_iso_build_state = ISO_BUILD_FAILED;
		/*
		 * The child's own last words go into the error GET /system/iso
		 * reports, not just the log store: this is the field an
		 * operator actually reads, and "status 0x100" alone is what
		 * made this failure undiagnosable.
		 */
		if (output_len > 0) {
			/*
			 * Log the whole capture first: reducing it to one line
			 * is for the operator-facing error field, and the full
			 * output is exactly what the next investigation wants.
			 *
			 * "The last line" was wrong here, and wrong in a way that
			 * cost a diagnosis round. mkinstalleriso ends a failure
			 * with its own summary of which tool exited nonzero --
			 *   /var/.../isotools/bin/sbsign failed (status 0x100)
			 * -- one line below the reason sbsign itself printed:
			 *   Error reading file /usr/lib/systemd/boot/efi/
			 *   systemd-bootx64.efi: No such file or directory
			 * The summary names the tool and hides what it could not
			 * find. childdiag_reduce_to_error_line() prefers the line
			 * that opens a diagnostic, which is the same rule
			 * diskformat.c needed for the opposite reason (its last
			 * line is a documentation-URL footer).
			 */
			logstore_write("cixd", "error", "iso assembly: output: %s", output);
			childdiag_reduce_to_error_line(output);
			snprintf(g_iso_build_error, sizeof(g_iso_build_error),
			         "mkinstalleriso failed (status 0x%x): %s", (unsigned)status, output);
		} else {
			snprintf(g_iso_build_error, sizeof(g_iso_build_error),
			         "mkinstalleriso failed (status 0x%x)", (unsigned)status);
		}
		fprintf(stderr, "iso assembly: failed\n");
		logstore_write("cixd", "error", "iso assembly: %s", g_iso_build_error);
	}
	close(cc->fd);
	free(cc);
}

/*
 * POST /v1/pkg/bootstrap's own toolchain_url mode (ADR-0065): closes a
 * real gap ADR-0031's own "the operator transfers it onto the box
 * out-of-band (scp)" assumption turned out to rest on -- a real,
 * freshly-installed Cix box has no SSH server and no general shell
 * at all (deliberately, ADR-0034), so there was never actually a way
 * to get a multi-hundred-MB toolchain artifact onto one over the
 * network. Reuses the exact host-side curl-fetch primitive pkg.c's own
 * recipe pkg_source already relies on (a plain fork+execve of curl,
 * never the daemon's own hand-rolled HTTP server) rather than
 * inventing a second fetch mechanism -- the only new code is fetching
 * into a fixed scratch path and, once it lands, handing off to the
 * exact same pkg_bootstrap_from_toolchain() the toolchain_path mode
 * already uses for staging.
 */
enum bootstrap_fetch_state {
	BOOTSTRAP_FETCH_NONE,
	BOOTSTRAP_FETCH_FETCHING,
	BOOTSTRAP_FETCH_READY,
	BOOTSTRAP_FETCH_FAILED
};
static enum bootstrap_fetch_state g_bootstrap_fetch_state = BOOTSTRAP_FETCH_NONE;
static char g_bootstrap_fetch_error[256];
static char g_bootstrap_fetch_sha256_expected[PKG_SHA256_MAX];

static void register_bootstrap_fetch_pidfd(pid_t pid, int pidfd)
{
	struct conn *cc;
	struct cix_epoll_event ev;

	cc = calloc(1, sizeof(*cc));
	if (cc == NULL) {
		perror("malloc (bootstrap fetch reactor conn)");
		abort();
	}
	cc->kind = CONN_BOOTSTRAP_FETCH;
	cc->fd = pidfd;
	cc->pkg_fetch_pid = pid;

	memset(&ev, 0, sizeof(ev));
	ev.events = EPOLLIN;
	ev.data.ptr = cc;
	if (cix_epoll_ctl(g_epfd, EPOLL_CTL_ADD, cc->fd, &ev) != 0) {
		perror("epoll_ctl ADD bootstrap fetch pidfd");
		abort();
	}
}

/* ADR-0121: same shape as register_bootstrap_fetch_pidfd() immediately
 * above, one epoll-tracked conn per in-flight pkg_sync_start() curl
 * child. */
static void register_pkg_sync_fetch_pidfd(pid_t pid, int pidfd)
{
	struct conn *cc;
	struct cix_epoll_event ev;

	cc = calloc(1, sizeof(*cc));
	if (cc == NULL) {
		perror("malloc (pkg sync fetch reactor conn)");
		abort();
	}
	cc->kind = CONN_PKG_SYNC_FETCH;
	cc->fd = pidfd;
	cc->pkg_fetch_pid = pid;

	memset(&ev, 0, sizeof(ev));
	ev.events = EPOLLIN;
	ev.data.ptr = cc;
	if (cix_epoll_ctl(g_epfd, EPOLL_CTL_ADD, cc->fd, &ev) != 0) {
		perror("epoll_ctl ADD pkg sync fetch pidfd");
		abort();
	}
}

/* The extraction helper finished (ADR-0278). Its exit status is 0 when
 * pkg_sync_extract() succeeded; anything else means it did not, and the
 * distinction between "no directory" and "extraction failed" is carried
 * by that function's own return, which the child encodes as a non-zero
 * exit. Reported as a generic extraction failure here, which is what
 * the state field said before the split too. */
static void pkg_sync_extract_done(int exit_status, void *ctx)
{
	(void)ctx;
	pkg_sync_completed(exit_status == 0 ? 0 : -2);
}

/*
 * ADR-0278, corrected: the child does the extraction AND the merge.
 *
 * The first version forked only the extraction, on the assumption that
 * unpacking the archive was the expensive half. Measured after deploy:
 * a real sync still stalled the loop 4991 ms. The merge -- roughly 1300
 * recipe files read, parsed and written -- is where the time goes.
 */
static int pkg_sync_extract_work(void *arg)
{
	int rc;

	(void)arg;
	rc = pkg_sync_extract();
	if (rc != 0)
		return rc;
	return pkg_sync_merge();
}

/*
 * Reaps the curl child pkg_sync_start() spawned, then runs the archive
 * extraction in a HELPER PROCESS rather than on the loop (ADR-0278,
 * #367).
 *
 * This handler used to call pkg_sync_completed() straight through, and
 * that function extracted the whole recipe repository before merging
 * it. Measured on 192.168.15.95: 5062-6116 ms of frozen event loop at
 * 03:23, 09:23, 15:23 and 21:23, four days running -- every stall
 * carrying an empty `activity`, which is what identified it as
 * scheduled work rather than a request. During that window nothing is
 * served: no API, no dashboard, no console, no container lifecycle
 * event, on a pid-1 daemon whose loop is the only way in.
 *
 * The merge itself stays here. It calls pkg_recipe_add() and reads
 * g_sync_refetch_*, so a fork would update a copy and throw it away --
 * and it is the cheap half regardless.
 *
 * A failed fork is not a lost sync: the extraction runs inline, exactly
 * as it always did. That is worse for latency and correct for the
 * result, which is the right way round.
 */
static void handle_pkg_sync_fetch_event(struct conn *cc)
{
	int status;
	int exit_status;

	cix_epoll_ctl(g_epfd, EPOLL_CTL_DEL, cc->fd, NULL);
	if (waitpid(cc->pkg_fetch_pid, &status, 0) == cc->pkg_fetch_pid && WIFEXITED(status))
		exit_status = WEXITSTATUS(status);
	else
		exit_status = -1;
	close(cc->fd);
	free(cc);

	if (!pkg_sync_fetch_done(exit_status))
		return;
	if (helper_run(pkg_sync_extract_work, NULL, pkg_sync_extract_done, NULL,
	                "pkg.sync extract and recipe merge") != 0) {
		logstore_write("cixd", "warn",
		                "pkg.sync: could not fork the extraction helper (%s) -- extracting on "
		                "the event loop instead, which stalls it (#367)",
		                strerror(errno));
		pkg_sync_completed(pkg_sync_extract_work(NULL));
	}
}




/*
 * Returns 0 and forks the fetch (state -> FETCHING) on success; -1
 * with err_msg filled otherwise (both url and sha256 are required --
 * unlike a recipe's own pkg_source, there is no "trust whatever
 * shows up" mode for something that gets unsquashfs'd wholesale into
 * the build sandbox). err_msg_size must be at least 256. Caller is
 * responsible for the "already fetching" check, same split as
 * iso_build_start()'s own doc comment explains.
 */
static int bootstrap_fetch_start(const char *url, const char *sha256, char *err_msg,
                                  size_t err_msg_size)
{
	static char out_path[PATH_MAX];
	static char url_buf[PKG_URL_MAX];
	char *argv[16];
	pid_t pid;
	int pidfd;

	if (url == NULL || url[0] == '\0') {
		snprintf(err_msg, err_msg_size, "toolchain_url is required");
		return -1;
	}
	if (sha256 == NULL || strlen(sha256) != 64) {
		snprintf(err_msg, err_msg_size, "toolchain_sha256 is required and must be a 64-char hex sha256");
		return -1;
	}

	snprintf(out_path, sizeof(out_path), "%s", PKGBUILD_TOOLCHAIN_FETCH_PATH);
	snprintf(url_buf, sizeof(url_buf), "%s", url);

	/* #285. Asynchronous (pidfd), so an unbounded fetch would stall
	 * this job rather than the loop -- but a bootstrap that never
	 * finishes and never fails is still a job nothing can resolve.
	 * --retry stays at 8: this is a 1.4 GB toolchain over whatever
	 * link the operator has, and the speed guard is what makes the
	 * retries safe rather than a way to wait eight times forever. */
	argv[0] = (char *)PKG_CURL_BIN;
	argv[1] = "-fsSL";
	argv[2] = "--connect-timeout";
	argv[3] = PKG_CURL_CONNECT_TIMEOUT;
	argv[4] = "--speed-limit";
	argv[5] = PKG_CURL_SPEED_LIMIT;
	argv[6] = "--speed-time";
	argv[7] = PKG_CURL_SPEED_TIME;
	argv[8] = "--retry";
	argv[9] = "8";
	argv[10] = "-o";
	argv[11] = out_path;
	argv[12] = url_buf;
	argv[13] = NULL;

	pid = fork();
	if (pid < 0) {
		snprintf(err_msg, err_msg_size, "fork failed: %s", strerror(errno));
		return -1;
	}
	if (pid == 0) {
		execve(PKG_CURL_BIN, argv, environ);
		perror("child: execve curl (bootstrap fetch)");
		_exit(127);
	}

	pidfd = sys_pidfd_open(pid, 0);
	if (pidfd < 0) {
		snprintf(err_msg, err_msg_size, "pidfd_open failed: %s", strerror(errno));
		kill(pid, SIGKILL);
		waitpid(pid, NULL, 0);
		return -1;
	}
	register_bootstrap_fetch_pidfd(pid, pidfd);
	snprintf(g_bootstrap_fetch_sha256_expected, sizeof(g_bootstrap_fetch_sha256_expected), "%s", sha256);
	g_bootstrap_fetch_state = BOOTSTRAP_FETCH_FETCHING;
	g_bootstrap_fetch_error[0] = '\0';
	return 0;
}

static void handle_backup_config_get(int fd)
{
	struct json_writer w;

	jw_init(&w);
	jw_obj_open(&w);
	backupconfig_write_json(&w);
	jw_obj_close(&w);
	respond_json(fd, 200, "OK", &w);
	jw_free(&w);
}

/*
 * PUT /v1/system/backup-config -- mirrors PUT /v1/system/daemon-
 * config's own "only the fields given are changed" partial-update
 * convention (ADR-0141's own explicit design note): reads the three
 * current values back from backupconfig.c's own getters, overrides
 * whichever fields this request body actually supplied (disk's own
 * JSON_NULL is a real, meaningful "clear it" distinct from the field
 * being absent entirely, same distinction POST .../migrate's own body
 * already makes), then persists the merged triple as one unit --
 * backupconfig_set() itself has no partial-update concept of its own.
 * Does NOT itself arm/disarm the periodic timer as a side effect of
 * every unrelated field edit -- only re-arms when enabled/interval_
 * hours actually changed, so an operator flipping some future
 * unrelated field (none exist yet, but the check is here for when one
 * does) never silently resets an in-flight countdown.
 */
static void handle_backup_config_put(int fd, const char *body, size_t body_len)
{
	struct json_value *root;
	const struct json_value *jdisk, *jenabled;
	const char *disk_name;
	char disk_name_buf[64];
	int enabled;
	enum backupconfig_error err;

	root = json_parse(body, body_len);
	if (root == NULL) {
		respond_error(fd, 400, "Bad Request", "invalid JSON body");
		return;
	}

	disk_name = backupconfig_disk();
	if (disk_name != NULL)
		snprintf(disk_name_buf, sizeof(disk_name_buf), "%s", disk_name);
	else
		disk_name_buf[0] = '\0';
	enabled = backupconfig_enabled();

	jdisk = json_object_get(root, "disk");
	if (jdisk != NULL) {
		if (jdisk->type == JSON_NULL) {
			disk_name_buf[0] = '\0';
		} else if (jdisk->type == JSON_STRING && json_as_string(jdisk) != NULL) {
			snprintf(disk_name_buf, sizeof(disk_name_buf), "%s", json_as_string(jdisk));
		} else {
			json_free(root);
			respond_error(fd, 400, "Bad Request", "disk must be a string or null");
			return;
		}
	}
	jenabled = json_object_get(root, "enabled");
	if (jenabled != NULL) {
		if (jenabled->type != JSON_BOOL) {
			json_free(root);
			respond_error(fd, 400, "Bad Request", "enabled must be a boolean");
			return;
		}
		enabled = jenabled->u.boolean;
	}
	/*
	 * ADR-0257: interval_hours is gone from this resource. WHEN a
	 * backup runs is a schedule; this says only where it goes and
	 * whether it is on. Refused rather than ignored, so a client still
	 * sending it learns that its schedule is not being set.
	 */
	if (json_object_get(root, "interval_hours") != NULL) {
		json_free(root);
		respond_error(fd, 400, "Bad Request",
		               "interval_hours moved to /v1/schedules (ADR-0257) -- set a schedule "
		               "with action \"system.backup\" instead");
		return;
	}
	json_free(root);

	err = backupconfig_set(disk_name_buf[0] != '\0' ? disk_name_buf : NULL, enabled);
	if (err != BACKUPCONFIG_OK) {
		respond_error(fd, 500, "Internal Server Error", "could not persist backup config");
		return;
	}

	{
		struct json_writer w;

		jw_init(&w);
		jw_obj_open(&w);
		backupconfig_write_json(&w);
		jw_obj_close(&w);
		respond_json(fd, 200, "OK", &w);
		jw_free(&w);
	}
}

/* Wrapped so the scheduler action above needs neither volumebackup.h's
 * sweep signature nor api_volume.h's hooks accessor in scope. */
static int volumebackup_sweep_now(void)
{
	return volumebackup_sweep(time(NULL), api_volume_backup_hooks());
}

static void do_backup_snapshot_now(void)
{
	const char *disk_name = backupconfig_disk();
	struct discovered_disk disks[DISK_ENUM_MAX];
	int n, i;
	const struct discovered_disk *found = NULL;
	char target_path[PATH_MAX];
	struct json_writer w;

	if (disk_name == NULL) {
		backupconfig_record_attempt(0, "no backup disk configured");
		return;
	}

	n = disk_enumerate(disks, DISK_ENUM_MAX, CONTAINERS_DIR);
	for (i = 0; i < n; i++) {
		if (strcmp(disks[i].name, disk_name) == 0) {
			found = &disks[i];
			break;
		}
	}
	if (found == NULL) {
		backupconfig_record_attempt(0, "configured backup disk is not currently present");
		return;
	}
	{
		const char *role = diskrole_lookup(disk_name);

		if (role == NULL || strcmp(role, "backup") != 0) {
			backupconfig_record_attempt(0,
			                             "configured backup disk no longer carries the backup role");
			return;
		}
	}
	if (!found->mounted) {
		backupconfig_record_attempt(0, "configured backup disk is present but not currently mounted");
		return;
	}

	snprintf(target_path, sizeof(target_path), "%s/backup.json", found->mount_path);

	do_system_backup(&w);
	if (persist_atomic_write(target_path, w.buf, w.len) != 0) {
		jw_free(&w);
		backupconfig_record_attempt(0, "failed to write snapshot to disk");
		return;
	}
	jw_free(&w);
	backupconfig_record_attempt(1, NULL);
}

static void handle_backup_config_status_get(int fd)
{
	struct json_writer w;

	jw_init(&w);
	backupconfig_write_status_json(&w);
	respond_json(fd, 200, "OK", &w);
	jw_free(&w);
}

static void handle_backup_config_snapshot_now_post(int fd)
{
	do_backup_snapshot_now();

	{
		struct json_writer w;

		jw_init(&w);
		backupconfig_write_status_json(&w);
		respond_json(fd, 200, "OK", &w);
		jw_free(&w);
	}
}

static void handle_bootstrap_fetch_event(struct conn *cc)
{
	int status;
	char sha_out[PKG_SHA256_MAX];

	cix_epoll_ctl(g_epfd, EPOLL_CTL_DEL, cc->fd, NULL);
	if (waitpid(cc->pkg_fetch_pid, &status, 0) != cc->pkg_fetch_pid || !WIFEXITED(status) ||
	    WEXITSTATUS(status) != 0) {
		g_bootstrap_fetch_state = BOOTSTRAP_FETCH_FAILED;
		snprintf(g_bootstrap_fetch_error, sizeof(g_bootstrap_fetch_error), "curl fetch failed (status 0x%x)",
		         (unsigned)status);
		fprintf(stderr, "bootstrap fetch: curl failed\n");
		close(cc->fd);
		free(cc);
		return;
	}
	close(cc->fd);
	free(cc);

	if (pkg_run_capture_sha256(PKGBUILD_TOOLCHAIN_FETCH_PATH, sha_out, sizeof(sha_out)) != 0 ||
	    strcasecmp(sha_out, g_bootstrap_fetch_sha256_expected) != 0) {
		g_bootstrap_fetch_state = BOOTSTRAP_FETCH_FAILED;
		snprintf(g_bootstrap_fetch_error, sizeof(g_bootstrap_fetch_error), "checksum mismatch");
		fprintf(stderr, "bootstrap fetch: checksum mismatch\n");
		return;
	}

	{
		enum pkg_error perr = pkg_bootstrap_from_toolchain(PKGBUILD_TOOLCHAIN_FETCH_PATH);

		if (perr != PKG_OK) {
			g_bootstrap_fetch_state = BOOTSTRAP_FETCH_FAILED;
			snprintf(g_bootstrap_fetch_error, sizeof(g_bootstrap_fetch_error),
			         "fetched toolchain failed to stage (invalid squashfs?)");
			fprintf(stderr, "bootstrap fetch: staging failed\n");
			return;
		}
	}

	g_bootstrap_fetch_state = BOOTSTRAP_FETCH_READY;
	fprintf(stderr, "bootstrap fetch: succeeded, toolchain staged\n");
}

/*
 * Multi-disk management Phase C: registers the async format+mount job
 * diskformat_start() (daemon/src/diskformat.c) already forked -- that
 * module has no epoll/conn knowledge of its own (mirrors pkg.c's own
 * start_fetch_for() convention), so main.c does the actual reactor
 * registration, the same split every other async host job here uses.
 */
static void register_disk_format_pidfd(pid_t pid, int pidfd)
{
	struct conn *cc;
	struct cix_epoll_event ev;

	cc = calloc(1, sizeof(*cc));
	if (cc == NULL) {
		perror("malloc (disk format reactor conn)");
		abort();
	}
	cc->kind = CONN_DISK_FORMAT;
	cc->fd = pidfd;
	cc->pkg_fetch_pid = pid;

	memset(&ev, 0, sizeof(ev));
	ev.events = EPOLLIN;
	ev.data.ptr = cc;
	if (cix_epoll_ctl(g_epfd, EPOLL_CTL_ADD, cc->fd, &ev) != 0) {
		perror("epoll_ctl ADD disk format pidfd");
		abort();
	}
}

/* Reaps diskformat_start()'s own child, hands the exit status straight
 * to diskformat_completed() -- no REST response is waiting on this
 * (the original POST already returned 202 long before this fires),
 * same shape as handle_iso_assemble_event()/handle_bootstrap_fetch_
 * event() above. */
static void handle_disk_format_event(struct conn *cc)
{
	int status;
	int exit_status;

	cix_epoll_ctl(g_epfd, EPOLL_CTL_DEL, cc->fd, NULL);
	if (waitpid(cc->pkg_fetch_pid, &status, 0) == cc->pkg_fetch_pid && WIFEXITED(status))
		exit_status = WEXITSTATUS(status);
	else
		exit_status = -1;
	close(cc->fd);
	free(cc);

	diskformat_completed(exit_status);
	fprintf(stderr, "disk format: job finished (exit_status=%d)\n", exit_status);
}

/*
 * ADR-0141 Phase 2: registers the async bulk-copy job storagemigrate_
 * start() already forked, the same split every other async host job
 * uses (storagemigrate.c has no epoll/conn knowledge of its own).
 */
static void register_storage_migrate_pidfd(enum storage_kind kind, pid_t pid, int pidfd)
{
	struct conn *cc;
	struct cix_epoll_event ev;

	cc = calloc(1, sizeof(*cc));
	if (cc == NULL) {
		perror("malloc (storage migrate reactor conn)");
		abort();
	}
	cc->kind = CONN_STORAGE_MIGRATE;
	cc->fd = pidfd;
	cc->pkg_fetch_pid = pid;
	cc->storage_migrate_kind = kind;

	memset(&ev, 0, sizeof(ev));
	ev.events = EPOLLIN;
	ev.data.ptr = cc;
	if (cix_epoll_ctl(g_epfd, EPOLL_CTL_ADD, cc->fd, &ev) != 0) {
		perror("epoll_ctl ADD storage migrate pidfd");
		abort();
	}
}

/* ADR-0142 Section 4: same shape as register_storage_migrate_pidfd()
 * above, keyed by container name instead of storage kind. */
static void register_container_storage_migrate_pidfd(const char *name, pid_t pid, int pidfd)
{
	struct conn *cc;
	struct cix_epoll_event ev;

	cc = calloc(1, sizeof(*cc));
	if (cc == NULL) {
		perror("malloc (container storage migrate reactor conn)");
		abort();
	}
	cc->kind = CONN_CONTAINER_STORAGE_MIGRATE;
	cc->fd = pidfd;
	cc->pkg_fetch_pid = pid;
	snprintf(cc->container_storage_migrate_name, sizeof(cc->container_storage_migrate_name), "%s", name);

	memset(&ev, 0, sizeof(ev));
	ev.events = EPOLLIN;
	ev.data.ptr = cc;
	if (cix_epoll_ctl(g_epfd, EPOLL_CTL_ADD, cc->fd, &ev) != 0) {
		perror("epoll_ctl ADD container storage migrate pidfd");
		abort();
	}
}


/*
 * ADR-0141 Phase 3: log-storage's own finalize step -- simpler than
 * state-storage's (single consumer, no /etc/resolv.conf-style bind
 * mount to redo), but the same overall shape: second synchronous copy
 * pass, repoint (logstore_repoint(), which itself handles the
 * persistently-open segment fd -- see its own doc comment), persist
 * the new placement, remove the old location.
 */
static void finalize_log_storage_migration(void)
{
	const char *target_dir = storagemigrate_job_target_dir(STORAGE_KIND_LOG);
	const char *target_disk = storagemigrate_job_target_disk(STORAGE_KIND_LOG);
	char old_source_dir[PATH_MAX];
	char new_state_path[PATH_MAX];

	snprintf(old_source_dir, sizeof(old_source_dir), "%s", storagemigrate_job_source_dir(STORAGE_KIND_LOG));

	if (storagemigrate_finalize(STORAGE_KIND_LOG) != 0) {
		fprintf(stderr, "log-storage migration: final copy pass failed, migration aborted\n");
		return;
	}

	snprintf(LOG_DIR, sizeof(LOG_DIR), "%s", target_dir);
	snprintf(new_state_path, sizeof(new_state_path), "%s/state.json", LOG_DIR);
	snprintf(LOG_STATE_PATH, sizeof(LOG_STATE_PATH), "%s", new_state_path);
	logstore_repoint(LOG_DIR, LOG_STATE_PATH);

	storageplacement_set(STORAGE_KIND_LOG, target_disk[0] != '\0' ? target_disk : NULL);

	if (persist_remove_tree(old_source_dir) != 0)
		fprintf(stderr, "log-storage migration: could not remove old location %s: %s\n",
		        old_source_dir, strerror(errno));

	fprintf(stderr, "log-storage migration: complete, now active on %s\n",
	        target_disk[0] != '\0' ? target_disk : "(default OS-disk placement)");
}

/*
 * ADR-0141 Phase 4: rebuildable-storage's own finalize -- like state-
 * storage's, several distinct modules (image.c, pkg.c's own several
 * concerns) each need repointing, but unlike state-storage there's no
 * /etc/resolv.conf-style external bind mount, and unlike log-storage
 * there's no persistently-open file handle -- every consumer here was
 * confirmed (not assumed, per ADR-0141's own original review note) to
 * cache nothing but plain path strings.
 */
static void finalize_rebuildable_storage_migration(void)
{
	const char *target_dir = storagemigrate_job_target_dir(STORAGE_KIND_REBUILDABLE);
	const char *target_disk = storagemigrate_job_target_disk(STORAGE_KIND_REBUILDABLE);
	char old_source_dir[PATH_MAX];

	snprintf(old_source_dir, sizeof(old_source_dir), "%s",
	         storagemigrate_job_source_dir(STORAGE_KIND_REBUILDABLE));

	if (storagemigrate_finalize(STORAGE_KIND_REBUILDABLE) != 0) {
		fprintf(stderr, "rebuildable-storage migration: final copy pass failed, migration aborted\n");
		return;
	}

	snprintf(REBUILDABLE_DIR, sizeof(REBUILDABLE_DIR), "%s", target_dir);
	compute_rebuildable_dir_relative_paths();

	image_init(IMAGES_DIR);
	pkg_repoint(PKG_DIR, PKG_INSTALLED_STATE_PATH, IMAGES_DIR, ARTIFACTS_DIR);
	pkg_repo_repoint(PKG_REPO_CONFIG_PATH);
	pkg_cache_repoint(PKG_CACHE_DIR, PKG_CACHE_CONFIG_PATH);
	pkg_artifact_repoint(PKG_ARTIFACT_CONFIG_PATH);
	pkg_build_config_repoint(PKG_BUILD_CONFIG_PATH);

	storageplacement_set(STORAGE_KIND_REBUILDABLE, target_disk[0] != '\0' ? target_disk : NULL);

	if (persist_remove_tree(old_source_dir) != 0)
		fprintf(stderr, "rebuildable-storage migration: could not remove old location %s: %s\n",
		        old_source_dir, strerror(errno));

	fprintf(stderr, "rebuildable-storage migration: complete, now active on %s\n",
	        target_disk[0] != '\0' ? target_disk : "(default OS-disk placement)");
}

static void handle_storage_migrate_event(struct conn *cc)
{
	int status;
	int exit_status;
	enum storage_kind kind = cc->storage_migrate_kind;

	cix_epoll_ctl(g_epfd, EPOLL_CTL_DEL, cc->fd, NULL);
	if (waitpid(cc->pkg_fetch_pid, &status, 0) == cc->pkg_fetch_pid && WIFEXITED(status))
		exit_status = WEXITSTATUS(status);
	else
		exit_status = -1;
	close(cc->fd);
	free(cc);

	storagemigrate_completed(kind, exit_status);
	/*
	 * Issue #172: the outcome goes to the LOG STORE, not only to
	 * stderr and the polling endpoint.
	 *
	 * The original report was "fails after ~20 seconds and writes
	 * nothing whatsoever to the log store". Capturing the copy child's
	 * stderr fixed *what* the reason is, but it was still readable
	 * only by polling GET .../migrate -- and an operator working out
	 * what happened to a host hours later reads the log store, by
	 * which time nobody is polling anything. stderr does not help
	 * either: this daemon never mirrors stderr into the log store
	 * (only the reverse), so on a real installed box with no shell
	 * that line goes nowhere at all -- the same gap #125/#132 already
	 * document.
	 *
	 * Success is logged too, deliberately. "Did that migration ever
	 * actually finish?" is a question an operator asks about a job
	 * that moved 15 GB, and silence is a poor answer to it.
	 */
	{
		const char *kind_name = kind == STORAGE_KIND_REBUILDABLE ? "rebuildable"
		                        : kind == STORAGE_KIND_LOG       ? "log"
		                                                         : "unknown";

		if (exit_status == 0) {
			logstore_write("cixd", "info",
			               "storage migrate: %s-storage bulk copy finished successfully (%s -> %s)",
			               kind_name, storagemigrate_job_source_dir(kind),
			               storagemigrate_job_target_dir(kind));
		} else {
			const char *why = storagemigrate_job_error(kind);

			logstore_write("cixd", "error",
			               "storage migrate: %s-storage bulk copy failed (%s -> %s): %s", kind_name,
			               storagemigrate_job_source_dir(kind), storagemigrate_job_target_dir(kind),
			               (why != NULL && why[0] != '\0') ? why : "no reason reported");
		}
	}
	fprintf(stderr, "storage migrate: bulk copy job finished (kind=%d exit_status=%d)\n", (int)kind,
	        exit_status);
	if (exit_status == 0 && kind == STORAGE_KIND_LOG)
		finalize_log_storage_migration();
	else if (exit_status == 0 && kind == STORAGE_KIND_REBUILDABLE)
		finalize_rebuildable_storage_migration();
}

static const char *iso_build_state_str(enum iso_build_state s)
{
	switch (s) {
	case ISO_BUILD_BUILDING:
		return "building";
	case ISO_BUILD_READY:
		return "ready";
	case ISO_BUILD_FAILED:
		return "failed";
	case ISO_BUILD_NONE:
	default:
		return "none";
	}
}

static void write_iso_status(struct json_writer *w)
{
	jw_obj_open(w);
	jw_key(w, "state");
	jw_str(w, iso_build_state_str(g_iso_build_state));
	jw_key(w, "iso_path");
	if (g_iso_build_state == ISO_BUILD_READY)
		jw_str(w, ISO_OUTPUT_PATH);
	else
		jw_null(w);
	jw_key(w, "error");
	if (g_iso_build_state == ISO_BUILD_FAILED)
		jw_str(w, g_iso_build_error);
	else
		jw_null(w);
	jw_key(w, "signature_path");
	if (g_iso_build_state == ISO_BUILD_READY && g_iso_signature_path[0] != '\0')
		jw_str(w, g_iso_signature_path);
	else
		jw_null(w);
	jw_key(w, "publish_state");
	jw_str(w, iso_publish_state_str());
	jw_key(w, "published_name");
	if (g_iso_publish_state == ISO_PUB_DONE && g_iso_publish_name[0] != '\0')
		jw_str(w, g_iso_publish_name);
	else
		jw_null(w);
	jw_key(w, "publish_error");
	if (g_iso_publish_state == ISO_PUB_FAILED)
		jw_str(w, g_iso_publish_error);
	else
		jw_null(w);
	jw_key(w, "built_version");
	if (g_iso_build_state == ISO_BUILD_READY && g_iso_built_version[0] != '\0')
		jw_str(w, g_iso_built_version);
	else
		jw_null(w);
	/*
	 * How big the media actually is.
	 *
	 * This endpoint reported a path and nothing else, so the only way
	 * to learn an ISO's size was to publish it and read the cache
	 * back. That is how an installer grew from 71.7 MiB to 217.9 MiB
	 * across a release series with nobody counting: 69.9 MiB of it a
	 * seed shipped twice (#307), 46.8 MiB static archives with shared
	 * counterparts beside them, and 18.5 MiB of debug sections -- each
	 * fixed on its own, none of them visible here.
	 *
	 * Read from the filesystem on each request rather than recorded at
	 * build time: the file is the truth, and a stored number is one
	 * more thing that can disagree with it.
	 */
	jw_key(w, "iso_bytes");
	if (g_iso_build_state == ISO_BUILD_READY) {
		struct stat ist;

		if (stat(ISO_OUTPUT_PATH, &ist) == 0)
			jw_num(w, (double)ist.st_size);
		else
			jw_null(w);
	} else {
		jw_null(w);
	}
	jw_obj_close(w);
}

/* GET /v1/system/iso -- status/iso_path polling, the exact shape GET
 * /v1/pkg/hostbuild/{name} already established for its own async job. */
static void handle_system_iso_get(int fd)
{
	struct json_writer w;

	jw_init(&w);
	write_iso_status(&w);
	respond_json(fd, 200, "OK", &w);
	jw_free(&w);
}

/*
 * POST /v1/system/iso (ADR-0064) -- every field is optional; an empty
 * body reproduces this tool's original default (a generic, edit-at-
 * the-GRUB-menu ISO, kernel_args left as the "CHANGEME" placeholder
 * image/src/mkinstalleriso.c's own usage text has always documented).
 */
static void handle_system_iso_post(int fd, const char *body, size_t body_len)
{
	struct json_value *root = NULL;
	const char *disk = NULL;
	const char *ip = NULL;
	const char *prefix = NULL;
	const char *gateway = NULL;
	const char *interface = NULL;
	char err_msg[256];
	struct json_writer w;

	if (body != NULL && body_len > 0) {
		root = json_parse(body, body_len);
		if (root == NULL) {
			respond_error(fd, 400, "Bad Request", "invalid JSON body");
			return;
		}
		disk = json_as_string(json_object_get(root, "disk"));
		ip = json_as_string(json_object_get(root, "ip"));
		prefix = json_as_string(json_object_get(root, "prefix"));
		gateway = json_as_string(json_object_get(root, "gateway"));
		interface = json_as_string(json_object_get(root, "interface"));
	}

	if (g_iso_build_state == ISO_BUILD_BUILDING) {
		if (root != NULL)
			json_free(root);
		respond_error(fd, 409, "Conflict", "an ISO build is already in progress");
		return;
	}
	if (iso_build_start(disk, ip, prefix, gateway, interface, err_msg, sizeof(err_msg)) != 0) {
		if (root != NULL)
			json_free(root);
		respond_error(fd, 400, "Bad Request", err_msg);
		return;
	}
	if (root != NULL)
		json_free(root);

	jw_init(&w);
	write_iso_status(&w);
	respond_json(fd, 202, "Accepted", &w);
	jw_free(&w);
}

/*
 * A "networks" array entry is either a bare name (string, auto-
 * allocated IP -- unchanged v1 behavior) or an object
 * {"name":..., "ip":...} naming an explicit, operator-chosen address
 * instead. Returns 0 with name_out/*out_has_ip(/*out_ip_be) filled,
 * or -1 if item is neither shape, name is missing, or a present ip
 * doesn't parse as an IPv4 address.
 */
/*
 * ADR-0259: may an operator give a container's own interface this name?
 *
 * 15 characters is IFNAMSIZ - 1, the kernel's own ceiling rather than a
 * limit invented here. The charset is deliberately narrower than what
 * the kernel would accept: a name containing a space, a slash or a
 * colon parses perfectly well and then reads as two fields in every
 * tool that prints one interface per line.
 *
 * "eth<digits>" is refused outright rather than collision-checked,
 * because that is the namespace the platform hands out positionally to
 * unnamed attachments. Allowing an explicit "eth1" would mean reasoning
 * about whether it collides with the default the next attachment is
 * about to be given -- a matrix, where refusing the prefix is a rule
 * that fits in one sentence. Bare "eth" is not in that namespace and is
 * allowed.
 */
static int container_ifname_is_valid(const char *s)
{
	size_t i;
	size_t len;

	if (s == NULL)
		return 0;
	len = strlen(s);
	if (len == 0 || len > 15)
		return 0;
	if (strcmp(s, "lo") == 0 || strcmp(s, ".") == 0 || strcmp(s, "..") == 0)
		return 0;
	for (i = 0; i < len; i++) {
		char c = s[i];

		if (!((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') ||
		      (c >= '0' && c <= '9') || c == '-' || c == '_' || c == '.'))
			return 0;
	}
	if (len > 3 && strncmp(s, "eth", 3) == 0) {
		for (i = 3; i < len; i++)
			if (s[i] < '0' || s[i] > '9')
				break;
		if (i == len)
			return 0;
	}
	return 1;
}

/*
 * Returns 0, or -1 for a malformed entry -- and -2 specifically for an
 * "ifname" that is present but not a legal interface name, so the
 * caller can say which rule was broken instead of the generic "invalid
 * networks entry". Getting that wrong matters here: the alternative is
 * failing later at rtnl_link_rename(), which returns a bare -1 and
 * surfaces to the operator as "failed to create container".
 */
static int parse_network_entry(const struct json_value *item, char *name_out, size_t name_out_size,
                                uint32_t *out_ip_be, int *out_has_ip, char *ifname_out,
                                size_t ifname_out_size, char *bridge_out, size_t bridge_out_size)
{
	const char *n;
	const char *ip_str;
	const char *ifn;
	const char *brn;
	struct in_addr addr;

	*out_has_ip = 0;
	if (ifname_out != NULL && ifname_out_size > 0)
		ifname_out[0] = '\0';
	if (bridge_out != NULL && bridge_out_size > 0)
		bridge_out[0] = '\0';
	if (item->type == JSON_STRING) {
		n = json_as_string(item);
		if (n == NULL)
			return -1;
		snprintf(name_out, name_out_size, "%s", n);
		return 0;
	}
	if (item->type != JSON_OBJECT)
		return -1;
	n = json_as_string(json_object_get(item, "name"));
	if (n == NULL)
		return -1;
	snprintf(name_out, name_out_size, "%s", n);
	ip_str = json_as_string(json_object_get(item, "ip"));
	if (ip_str != NULL) {
		if (inet_pton(AF_INET, ip_str, &addr) != 1)
			return -1;
		*out_ip_be = addr.s_addr;
		*out_has_ip = 1;
	}
	ifn = json_as_string(json_object_get(item, "ifname"));
	if (ifn != NULL) {
		if (!container_ifname_is_valid(ifn))
			return -2;
		if (ifname_out != NULL && ifname_out_size > 0)
			snprintf(ifname_out, ifname_out_size, "%s", ifn);
	}
	/*
	 * ADR-0264: this attachment is a port of a bridge inside the
	 * container. Same name rules as ifname, and for the same reason --
	 * it becomes a real interface in the same namespace, so it cannot
	 * be "lo" and cannot collide with the eth<N> names this platform
	 * assigns to unnamed attachments. -3 rather than -2 so the caller
	 * can name the field the operator actually got wrong.
	 */
	brn = json_as_string(json_object_get(item, "container_bridge"));
	if (brn != NULL) {
		if (!container_ifname_is_valid(brn))
			return -3;
		if (bridge_out != NULL && bridge_out_size > 0)
			snprintf(bridge_out, bridge_out_size, "%s", brn);
	}
	return 0;
}

/*
 * Rejects a client-supplied container-relative path (POST /v1/containers'
 * own "files[].path") with any "." or ".." component, or an empty
 * component ("//" anywhere) -- the one place in the "files" feature
 * with real security weight, since a validated path becomes a real
 * host filesystem write target (see create_container_from_body()'s own
 * "files" staging). Caller has already checked path[0] == '/'.
 */
static int file_path_is_safe(const char *path)
{
	const char *p = path;

	while (*p == '/')
		p++;
	while (*p != '\0') {
		const char *start = p;
		size_t len;

		while (*p != '\0' && *p != '/')
			p++;
		len = (size_t)(p - start);
		if (len == 0 || (len == 1 && start[0] == '.') ||
		    (len == 2 && start[0] == '.' && start[1] == '.'))
			return 0;
		while (*p == '/')
			p++;
	}
	return 1;
}



/*
 * Deliberately restricted to the net.* sysctl tree (POST /v1/containers'
 * own "sysctls" object) -- most non-net.* sysctls (vm.*, fs.*, ...) are
 * not namespace-isolated at all in Linux, so allowing arbitrary keys
 * would make this a real host-wide write primitive from inside a
 * container, not a per-container knob. Requires "net." as the first
 * dot-separated component and every component non-empty and
 * [A-Za-z0-9_] only -- this also naturally rejects "net..foo" or
 * "net.ipv4.." (an empty component from what would otherwise become a
 * "/proc/sys/net/../.." traversal once '.' is translated to '/', see
 * container_net_apply_sysctl()).
 */
static int sysctl_key_is_safe(const char *key)
{
	const char *p = key;

	if (strncmp(p, "net.", 4) != 0)
		return 0;
	while (*p != '\0') {
		const char *start = p;

		while (*p != '\0' && *p != '.')
			p++;
		if (p == start)
			return 0;
		while (start < p) {
			if (!((*start >= 'a' && *start <= 'z') || (*start >= 'A' && *start <= 'Z') ||
			      (*start >= '0' && *start <= '9') || *start == '_'))
				return 0;
			start++;
		}
		if (*p == '.')
			p++;
	}
	return 1;
}

/*
 * POST /v1/containers' own "env" field's key validation -- POSIX
 * portable environment variable name rules (IEEE Std 1003.1-2017
 * 8.1): letters, digits, underscore, not starting with a digit. Real
 * enforcement, not cosmetic: a key containing '=' would make
 * daemon/src/registry.c's own spec->envp "KEY=VALUE" split (see
 * registry_create()) recover the wrong key/value boundary.
 */
static int env_key_is_safe(const char *key)
{
	const char *p = key;

	if (*p == '\0' || (*p >= '0' && *p <= '9'))
		return 0;
	for (; *p != '\0'; p++) {
		if (!((*p >= 'a' && *p <= 'z') || (*p >= 'A' && *p <= 'Z') ||
		      (*p >= '0' && *p <= '9') || *p == '_'))
			return 0;
	}
	return 1;
}

/*
 * Core of what POST /v1/containers does: parses+validates body,
 * builds a container_spec, calls registry_create(), calls
 * register_container_pidfd() on success (do NOT also call it at any
 * call site below -- double-registering the same pidfd with epoll is
 * a real bug, confirmed directly: it aborts the daemon), and runs the
 * requested dns_register/pki_issue side effects -- so replaying the
 * exact same body (boot autostart, crash restart, see
 * daemon/include/containerdef.h) gets the exact same result a fresh
 * POST would. Zero HTTP coupling. On success returns 0 and *out_entry
 * is the new registry entry; out_restart_policy/out_restart_delay_seconds/
 * out_depends_on(_count) are filled from the body's own "restart"/
 * "restart_delay_seconds"/"depends_on" fields regardless of outcome (a
 * caller deciding what to persist needs them either way, though only
 * a success is ever actually persisted). On
 * failure returns the same HTTP status code (400/409/500)
 * handle_create() has always returned for that condition, with
 * err_msg holding the exact same message text -- the REST wrapper
 * forwards both verbatim; boot/restart callers just log them.
 */
enum disk_resolve_result {
	DISK_RESOLVE_OK = 0,
	DISK_RESOLVE_NOT_FOUND,
	DISK_RESOLVE_NOT_MOUNTED,
	DISK_RESOLVE_NO_ROLE,
};

/*
 * Resolves disk_name (POST /v1/containers' own optional "disk" field,
 * task #638/ADR-0102) to the real host directory a container's own
 * overlay storage should live under, in place of the default
 * CONTAINERS_DIR: <the disk's own live mount_path>/containers.
 * Requires the disk to (a) actually exist, (b) currently be mounted
 * (ADR-0099's live /proc/mounts ground truth, not diskformat.c's own
 * ephemeral per-process job state), and (c) carry the
 * "container-storage" role (diskrole.c, Phase B) -- an arbitrary
 * mounted disk is not automatically a valid target. This is the one
 * thing that makes that role (assignable since Phase B but never
 * consumed by anything until now, per diskrole.h's own "Phase D"
 * comment) actually mean something, rather than being pure inert
 * metadata. Returns DISK_RESOLVE_OK and fills out_root, or the
 * specific reason it failed so the caller can give a precise 400.
 */
static int resolve_container_disk_root(const char *disk_name, char *out_root, size_t out_root_size)
{
	struct discovered_disk disks[DISK_ENUM_MAX];
	int count, i;

	count = disk_enumerate(disks, DISK_ENUM_MAX, CONTAINERS_DIR);
	for (i = 0; i < count; i++) {
		const char *role;

		if (strcmp(disks[i].name, disk_name) != 0)
			continue;
		if (!disks[i].mounted)
			return DISK_RESOLVE_NOT_MOUNTED;
		role = diskrole_lookup(disk_name);
		if (role == NULL || strcmp(role, "container-storage") != 0)
			return DISK_RESOLVE_NO_ROLE;
		snprintf(out_root, out_root_size, "%s/containers", disks[i].mount_path);
		return DISK_RESOLVE_OK;
	}
	return DISK_RESOLVE_NOT_FOUND;
}

/*
 * The read-side counterpart to resolve_container_disk_root() -- given
 * a disk_name (an already-created entry's own e->disk_name, or one
 * freshly reparsed from a containerdef's own stored body when no live
 * entry exists -- see handle_delete()'s crashed-container cleanup
 * branch), reconstructs the same root its own container_base was
 * computed under, for handle_container_file_read() and
 * handle_container_stats(). Takes the disk name directly rather than
 * a struct registry_entry * so callers with no live entry (a
 * restart:"always" definition currently between a crash and its next
 * restart timer) can still resolve the right root. Re-resolves the
 * disk's current mount_path fresh via disk_enumerate() rather than
 * caching it, matching this project's own "live /proc/mounts is the
 * one source of truth" precedent (ADR-0099) -- if the disk is no
 * longer mounted (a real, rare operational anomaly: it was unmounted
 * after a container was placed on it), falls back to CONTAINERS_DIR,
 * which fails the lookup cleanly (ENOENT) rather than crashing.
 */
void container_root_for(const char *disk_name, char *out, size_t out_size)
{
	struct discovered_disk disks[DISK_ENUM_MAX];
	int count, i;

	if (disk_name == NULL || disk_name[0] == '\0') {
		snprintf(out, out_size, "%s", CONTAINERS_DIR);
		return;
	}
	count = disk_enumerate(disks, DISK_ENUM_MAX, CONTAINERS_DIR);
	for (i = 0; i < count; i++) {
		if (strcmp(disks[i].name, disk_name) == 0 && disks[i].mounted) {
			snprintf(out, out_size, "%s/containers", disks[i].mount_path);
			return;
		}
	}
	snprintf(out, out_size, "%s", CONTAINERS_DIR);
}

/*
 * Issue #68: the strict-input half of the limits-visibility fix (#49 is
 * the read-back half). The create parser reads exactly the keys below
 * and always simply ignored everything else -- so a typo'd field name
 * ("cpuset" for "cpuset_cpus", the live-confirmed case) produced a
 * container silently missing its requested limits, with (pre-#49) no
 * way to even see the absence. HTTP-facing entry points (create, and
 * container-recipe add/apply) reject unknown keys with a 400 naming
 * the offender; the daemon-internal replay paths (autostart, rolling
 * restart, storage migration -- all replaying bodies this daemon
 * itself persisted) deliberately stay lenient so an upgrade can never
 * strand an existing definition.
 */
static const char *container_body_unknown_key(const struct json_value *root)
{
	static const char *const known[] = {
		"name", "image", "image_version", "services", "networks", "ip_forward", "ksm",
		"capture_output", "routes", "devices", "interfaces", "cap_add", "files",
		"sysctls", "env", "dns_servers", "dns_register", "pki_issue", "pki_cert_dir",
		/* ADR-0280/#397: deliver a pre-existing, unowned cert by name. */
		"pki_cert",
		"pki_days", "disk", "ldap_provision", "ldap_user", "ldap_group", "ldap_uid",
		"ldap_secret_dir", "restart", "restart_delay_seconds", "follow_rolling",
		"follow_rolling_jitter_seconds", "depends_on", "memory_max", "memory_swap_max",
		"cpu_max", "pids_max", "cpuset_cpus", "disk_quota_bytes", "ldap_client",
		"ldap_allow_groups",
		"userns",
		/* ADR-0262/#336: decline the virtualised /proc. */
		"procfuse",
		/* Issue #248: the consoles this container declares. */
		"consoles",
		/* Issue #88: persistent volumes. */
		"volumes",
		/*
		 * Issue #301: the server roles this container declares.
		 *
		 * These four were added to handle_create() without being
		 * added here, which made that code unreachable -- this
		 * allowlist runs first, so every create carrying one was
		 * refused with "unknown field" before the registration could
		 * run. Measured on 192.168.15.95 against v2.53.71:
		 * POST /v1/containers with a dns_server block returned
		 * {"error":"unknown field: dns_server"}, and container recipe
		 * add refused the same field, so the recipe could not carry
		 * it either. Nothing failed loudly; the feature simply never
		 * fired.
		 *
		 * One list serves both paths -- create_container_persisted()
		 * and the recipe's own add-time check both call this -- so a
		 * field is accepted in a recipe exactly when it is accepted
		 * in a create, which is the property that makes a recipe a
		 * faithful record of a container.
		 */
		"dns_server", "ntp_server", "syslog_target", "ldap_server",
	};
	size_t i, k;

	if (root == NULL || root->type != JSON_OBJECT)
		return NULL;
	for (i = 0; i < root->u.object.count; i++) {
		int found = 0;

		for (k = 0; k < sizeof(known) / sizeof(known[0]); k++) {
			if (strcmp(root->u.object.keys[i], known[k]) == 0) {
				found = 1;
				break;
			}
		}
		if (!found)
			return root->u.object.keys[i];
	}
	return NULL;
}

/*
 * Issue #66: stage one file directly into a container's upperdir, the
 * same open(O_CREAT|O_TRUNC)/write/optional-fchown sequence
 * create_container_from_body()'s own files[] loop already uses --
 * factored out so the ldap_client synthetic files below share exactly
 * that path (and its own already-audited safety: file_path_is_safe()
 * is enforced by the caller for user files; these synthetic paths are
 * fixed literals). Returns 0, or -1 with errno set. Records nothing in
 * file_paths[] itself -- the caller owns that array's indexing.
 */
/*
 * ADR-0179 phase 2c option (a): a userns container gets its OWN rootfs, a
 * copy of the image tree made here with `cp --reflink=auto -a` -- CoW (near
 * free) on a reflink-capable backing (btrfs/xfs), a real copy elsewhere. Its
 * own tree is what makes the container's rootfs directly writable+persistent
 * under an id-mapped mount, without the overlay-in-userns wall (ADR-0179).
 * Minimal fork/exec (no shell): argv is a fixed-arity vector, so no quoting/
 * injection surface. Returns 0 on a clean exit, -1 otherwise.
 */
static int run_cmd(const char *const argv[])
{
	pid_t p = fork();
	int status;

	if (p < 0)
		return -1;
	if (p == 0) {
		execv(argv[0], (char *const *)argv);
		_exit(127);
	}
	if (waitpid(p, &status, 0) < 0)
		return -1;
	return (WIFEXITED(status) && WEXITSTATUS(status) == 0) ? 0 : -1;
}

/*
 * ADR-0179 phase 2c option (a): recursively chown a userns container's own
 * rootfs copy to its subordinate base id, so its mapped root (host <base>)
 * genuinely OWNS every file -- id-mapped mounts proved too subtle to make the
 * child a writable owner, whereas plain ownership is unambiguous: the
 * container's userns maps <base> straight back to uid 0. Done once at first
 * create (a copy the container then keeps). nftw + lchown, no external binary;
 * single-threaded event loop makes the static target ids safe.
 */
static uid_t g_chown_uid;
static gid_t g_chown_gid;

static int chown_tree_cb(const char *path, const struct stat *sb, int typeflag, struct FTW *ftw)
{
	(void)sb;
	(void)typeflag;
	(void)ftw;
	if (lchown(path, g_chown_uid, g_chown_gid) != 0)
		return -1;
	return 0;
}

static int chown_tree(const char *path, uid_t uid, gid_t gid)
{
	g_chown_uid = uid;
	g_chown_gid = gid;
	return nftw(path, chown_tree_cb, 20, FTW_PHYS);
}

/*
 * Give every directory leading to a staged file to the container's own
 * root as well (#265). persist_mkdir_p() creates them as the daemon --
 * on-disk uid 0 -- and under the copy+chown presentation that is outside
 * the container's mapped range, so a freshly created /etc/pam.d would be
 * traversable but not writable by the container's root. Components that
 * already came from the image are chowned to the id they already carry,
 * so this is idempotent rather than a second source of truth.
 */
static void chown_staged_parents(const char *upperdir, const char *path, uid_t id_offset)
{
	char walk[PATH_MAX];
	size_t root_len = strlen(upperdir);
	char *slash;

	if (id_offset == 0)
		return;
	if ((size_t)snprintf(walk, sizeof(walk), "%s%s", upperdir, path) >= sizeof(walk))
		return;
	/* Walk from the deepest parent up to (but never past) upperdir. */
	while ((slash = strrchr(walk, '/')) != NULL && (size_t)(slash - walk) > root_len) {
		*slash = '\0';
		if (chown(walk, id_offset, (gid_t)id_offset) != 0 && errno != ENOENT)
			return;
	}
}

/*
 * Write one file into a container's rootfs before it starts, owned in the
 * CONTAINER's id space rather than the host's (#265, ADR-0239's family).
 *
 * This is the only place container files are staged. It used to be one of
 * three -- the files[] loop and the dns_servers resolv.conf writer each
 * carried their own copy of the same target/mkdir_p/open/write/fchown
 * sequence -- and that is exactly why this bug had more than one home. A
 * single implementation is the fix as much as the ownership rule is.
 *
 * id_offset is what makes the ownership correct. The caller reads it off
 * the rootfs being staged into -- a staged file is owned by whoever owns
 * the tree it lands in -- which covers all three presentations without
 * this function needing to know they exist:
 *
 *   - Non-userns upperdir: host-uid-0 owned, so 0. Unchanged.
 *   - userns, btrfs snapshot behind an id-mapped mount (ADR-0207 phase
 *     3): also host-uid-0 owned, so 0. On-disk 0 is ALREADY presented as
 *     the container's root there, and an offset would break it.
 *   - userns, copy+chown (ADR-0179 phase 2b): chown_tree() has given the
 *     whole rootfs to the container's subordinate base, which is what
 *     makes / and /etc read as 0 inside. A file staged afterwards as
 *     on-disk 0 falls outside the mapped range and reads as 65534,
 *     unreadable by the container's own root at mode 0600. That was the
 *     bug, and it is the presentation the live host runs.
 *
 * An unspecified owner means the container's root, not the host's, which
 * is why the offset applies even when the caller passes -1. An explicit
 * owner is an id in the container's own space -- a recipe asking for
 * owner 75 means the container's uid 75 -- so it is offset too. Before
 * this, such a recipe got on-disk uid 75, unmapped inside, which is not
 * what any author would expect it to mean.
 */
static int stage_container_bytes(const char *upperdir, const char *path, const void *content,
                                  size_t content_len, mode_t mode, uid_t owner, gid_t group,
                                  uid_t id_offset)
{
	char target[PATH_MAX];
	char target_dir[PATH_MAX];
	char *slash;
	uid_t eff_owner;
	gid_t eff_group;
	int fd;

	if (snprintf(target, sizeof(target), "%s%s", upperdir, path) >= (int)sizeof(target)) {
		errno = ENAMETOOLONG;
		return -1;
	}
	snprintf(target_dir, sizeof(target_dir), "%s", target);
	slash = strrchr(target_dir, '/');
	if (slash != NULL)
		*slash = '\0';
	if (persist_mkdir_p(target_dir) != 0)
		return -1;
	chown_staged_parents(upperdir, path, id_offset);
	fd = open(target, O_CREAT | O_TRUNC | O_WRONLY, mode);
	if (fd < 0)
		return -1;
	if (content_len > 0 && write(fd, content, content_len) != (ssize_t)content_len) {
		close(fd);
		return -1;
	}
	eff_owner = owner == (uid_t)-1 ? id_offset : owner + id_offset;
	eff_group = group == (gid_t)-1 ? (gid_t)id_offset : group + (gid_t)id_offset;
	/*
	 * With no offset and nothing asked for, do not chown at all -- that
	 * is the pre-existing behaviour for every non-userns container and
	 * there is no reason to start rewriting ownership it never had.
	 */
	if ((id_offset != 0 || owner != (uid_t)-1 || group != (gid_t)-1) &&
	    fchown(fd, eff_owner, eff_group) != 0) {
		close(fd);
		return -1;
	}
	close(fd);
	return 0;
}

static int stage_container_file(const char *upperdir, const char *path, const char *content,
                                 mode_t mode, uid_t owner, gid_t group, uid_t id_offset)
{
	return stage_container_bytes(upperdir, path, content, strlen(content), mode, owner, group,
	                             id_offset);
}





/*
 * Issue #66 (auto-derivation): the effective LDAP client URI list for
 * ldap_client -- the explicitly-configured client_uri if set, else one
 * built from the IPs of the containers an operator has already
 * registered as LDAP servers (ldap server register), so registering
 * the servers is the only step needed. Writes into out (returns 1) or
 * returns 0 if neither source yields anything. A registered server
 * whose container isn't currently running (no resolvable primary IP)
 * is skipped -- a best-effort list of the live ones, same posture DNS
 * server delivery already takes.
 */



/*
 * Issue #86: the workload cgroup every container and every build lives
 * under, carrying "the machine minus the control plane's reservation".
 *
 * Priority (nice -20, oom_score_adj -1000) is the cheap 80% of not
 * losing the box; this is the structurally sound part. Rather than
 * asking the scheduler to favour the daemon, everything that is not the
 * daemon is bounded, so what the control plane has left is a
 * kernel-enforced remainder rather than a hope.
 *
 * Derived from LIVE host totals on every apply, never stored: the same
 * "keep a tenth of the box" config has to keep meaning that when the
 * box is replaced by a bigger one, which is about to happen -- this
 * project's next install is real hardware, not the 2-CPU VM every
 * number here was first chosen against.
 *
 * Best-effort, deliberately: a sandbox where cgroup writes are not
 * permitted must still run containers. A safety margin that refuses to
 * start the system it protects is not one.
 */

static void workload_parent_ensure(void)
{
	const struct cpreserve_config *c = cpreserve_get();
	struct cgroup_limits lim;
	char cpu_max[64];
	long long mem_total, mem_free, mem_avail, mem_buffers, mem_cached, swap_total, swap_free;
	long cpus;

	memset(&lim, 0, sizeof(lim));
	lim.name = CGROUP_WORKLOAD_PARENT;
	/* -1 = leave memory.swap.max alone; 0 would forbid swapping
	 * entirely, which is not what "no swap limit configured" means.
	 * See struct cgroup_limits. */
	lim.memory_swap_max = -1;

	/*
	 * Disabled means an UNLIMITED parent, not a different shape: every
	 * container and build stays exactly where it is in the hierarchy
	 * either way, and only the ceiling appears or disappears. Moving
	 * the topology with the setting would make turning the reservation
	 * off a migration, and would leave existing containers accounted
	 * somewhere their successors are not.
	 */
	cpus = c->enabled ? sysconf(_SC_NPROCESSORS_ONLN) : 0;
	if (cpus > 0) {
		/* cgroup v2 cpu.max is "<quota> <period>" in microseconds, and
		 * 100000 is the conventional period, so one whole CPU is
		 * 100000. Truncation lands in the safe direction (marginally
		 * more reserved than asked), and the floor stops a very small
		 * box ending up with a workload ceiling of nothing. */
		long long quota = (long long)cpus * 100000LL * (100 - c->cpu_percent) / 100;

		if (quota < 10000)
			quota = 10000;
		snprintf(cpu_max, sizeof(cpu_max), "%lld 100000", quota);
		lim.cpu_max = cpu_max;
	}

	if (c->enabled) {
		read_meminfo(&mem_total, &mem_free, &mem_avail, &mem_buffers, &mem_cached, &swap_total,
		             &swap_free);
		/* Only when the reservation still leaves workloads the clear
		 * majority of RAM. On a box too small for that, a memory
		 * ceiling would do more harm than the starvation it guards
		 * against. */
		if (mem_total > c->memory_bytes * 2)
			lim.memory_max = mem_total - c->memory_bytes;
	}

	cgroup_create_parent(&lim);
}

/* Where a container's own cgroup leaf goes -- always under the workload
 * parent, whose ceiling is present or absent according to the
 * reservation. See workload_parent_ensure() for why the shape does not
 * move with the setting. */
static void workload_cgroup_path(const char *name, char *out, size_t out_size)
{
	workload_parent_ensure();
	snprintf(out, out_size, "%s/%s", CGROUP_WORKLOAD_PARENT, name);
}

/*
 * ADR-0277: which image version a container's own rootfs was seeded
 * from, recorded beside that rootfs.
 *
 * ADR-0207 gave a container its own writable rootfs -- a btrfs
 * snapshot of the image, or a copy where snapshots are not possible --
 * and decided the storage mode from one fact on disk: if
 * <base>/rootfs exists, keep it. The reasoning was sound and is
 * written in the branch below ("re-snapshotting would silently
 * discard every write it ever made"), and it had a consequence nobody
 * traced: the tree is seeded ONCE, on first start, and reused forever
 * regardless of which image version the container is later pinned to.
 *
 * That made follow_rolling (ADR-0124) inert for every container in
 * this mode -- which, since userns is the default (ADR-0179) and
 * btrfs is the substrate (ADR-0207), is every container on a real
 * host. apply_rolling_container_restarts() did its half correctly:
 * it patched the pin and restarted the container, which then came
 * back on the old tree. The API reported the new version, the
 * container ran the old one, and nothing anywhere disagreed out loud.
 * Measured on 192.168.15.95 (#401): a package installed into an
 * image, the container reporting the new version, a full stop+start,
 * and the old binary still in place -- while a container freshly
 * created from the same image and the same reported version had the
 * new one.
 *
 * So the rootfs needs to say what it was made from. One line, in a
 * file beside it rather than inside it: inside would be visible to
 * the container and would travel with a snapshot of it, and both are
 * wrong for a fact about provenance.
 */
#define ROOTFS_SEED_MARKER_REL "rootfs.version"

static void rootfs_seed_version_path(const char *container_base, char *out, size_t out_size)
{
	snprintf(out, out_size, "%s/%s", container_base, ROOTFS_SEED_MARKER_REL);
}

static int rootfs_seed_version_read(const char *container_base, char *out, size_t out_size)
{
	char path[PATH_MAX];
	char *buf = NULL;
	size_t len = 0;

	rootfs_seed_version_path(container_base, path, sizeof(path));
	if (persist_read_file(path, &buf, &len) != 0 || buf == NULL)
		return -1;
	while (len > 0 && (buf[len - 1] == '\n' || buf[len - 1] == '\r'))
		len--;
	if (len == 0 || len >= out_size) {
		free(buf);
		return -1;
	}
	memcpy(out, buf, len);
	out[len] = '\0';
	free(buf);
	return 0;
}

static int rootfs_seed_version_write(const char *container_base, const char *version)
{
	char path[PATH_MAX];

	rootfs_seed_version_path(container_base, path, sizeof(path));
	return persist_atomic_write(path, version, strlen(version));
}

/*
 * 1 when an existing <base>/rootfs was seeded from a different image
 * version than `want`, i.e. the caller must discard it and seed again.
 * 0 means keep what is there.
 *
 * A rootfs with no marker predates the marker, and its real origin
 * cannot be recovered. It is ADOPTED at the version it is pinned to
 * rather than rebuilt: a silent mass re-seed of every container on the
 * first boot after this lands would be a far worse surprise than one
 * more cycle of a staleness that already exists. A container that had
 * already drifted stays drifted until its image version next moves, at
 * which point it rebuilds correctly like any other. From the adoption
 * on, the marker is real and every later change is caught.
 */
static int rootfs_needs_reseed(const char *name, const char *container_base, const char *want)
{
	char seeded[IMAGE_VERSION_MAX];

	if (rootfs_seed_version_read(container_base, seeded, sizeof(seeded)) != 0) {
		if (rootfs_seed_version_write(container_base, want) != 0)
			logstore_write("cixd", "warn",
			                "%s: could not record which image version its rootfs was seeded "
			                "from (%s) -- it will be adopted again on the next start",
			                name, strerror(errno));
		else
			logstore_write("cixd", "info",
			                "%s: adopted its existing rootfs as image version %s -- it "
			                "predates the seed marker, so its real origin is unknown",
			                name, want);
		return 0;
	}
	if (strcmp(seeded, want) == 0)
		return 0;
	logstore_write("cixd", "info",
	                "%s: rootfs was seeded from image version %s and this container is now "
	                "pinned to %s -- rebuilding it from the new version",
	                name, seeded, want);
	return 1;
}

/*
 * Format the "this name is taken" rejection (#417, and #148's lesson
 * applied to the name rather than the address).
 *
 * Container deletion is asynchronous (ADR-0180): DELETE returns once
 * the teardown is under way, so recreating under the same name
 * immediately afterwards legitimately races the entry on its way out.
 * The flat "already exists" reads as "something else took this name"
 * and sends the reader looking for a container that `container ls`
 * does not show. registry_ip_holder() already draws exactly this
 * distinction for a held address; the name had been left behind.
 */
static void name_conflict_msg(const char *name, char *err_msg, size_t err_msg_size)
{
	const struct registry_entry *e = registry_find(name);

	if (e != NULL && e->teardown_kind != REGISTRY_TEARDOWN_NONE)
		snprintf(err_msg, err_msg_size,
		          "a container with this name is still shutting down -- retry shortly");
	else
		snprintf(err_msg, err_msg_size, "a container with this name already exists");
}

static int create_container_from_body(const char *body, size_t body_len,
                                       struct registry_entry **out_entry,
                                       char out_restart_policy[16], int *out_restart_delay_seconds,
                                       char out_depends_on[][REGISTRY_NAME_MAX],
                                       int *out_depends_on_count, int *out_follow_rolling,
                                       int *out_has_follow_rolling_jitter,
                                       int *out_follow_rolling_jitter_seconds, char *err_msg,
                                       size_t err_msg_size)
{
	struct json_value *root;
	const struct json_value *jname, *jimage, *jimage_version, *jservices, *jmem, *jswapmax, *jpids, *jcpu, *jcpuset,
	    *jnetworks, *jip_forward, *jksm, *jroutes;
	const struct json_value *jdisk_quota;
	long long disk_quota_bytes;
	int quota_enforced_early = 0; /* #266: the userns snapshot applied it itself */
	const struct json_value *jdevices;
	const struct json_value *jinterfaces;
	const struct json_value *jcap_add;
	const struct json_value *jfiles, *jsysctls, *jenv;
	const struct json_value *jrestart, *jrestart_delay, *jdepends_on;
	const struct json_value *jfollow_rolling, *jfollow_rolling_jitter;
	const char *restart_str;
	long restart_delay, follow_rolling_jitter;
	const char *name, *image;
	char name_copy[REGISTRY_NAME_MAX];
	char lowerdir[PATH_MAX];
	char resolved_image_version[IMAGE_VERSION_MAX];
	char container_base[PATH_MAX];
	char upperdir[PATH_MAX], workdir[PATH_MAX], merged[PATH_MAX];
	char container_cgroup_path[PATH_MAX]; /* issue #86 -- under the workload parent */
	char userns_rootfs[PATH_MAX]; /* ADR-0179 phase 2c option (a) */
	const char *stage_dir;        /* where container files are staged: upper, or the userns rootfs */
	/*
	 * The id every staged file is owned by, in the container's own space
	 * (#265). Non-zero only for the copy+chown userns presentation -- see
	 * stage_container_file() for why the id-mapped one must stay 0.
	 */
	uid_t stage_id_offset = 0;
	char direct_rootfs_dir[PATH_MAX]; /* ADR-0207: <base>/rootfs when direct_mode */
	int direct_mode = 0;          /* ADR-0207 phase 2: snapshot/copy rootfs, no overlay */
	struct stat st;
	struct container_spec spec;
	struct registry_entry *entry;
	enum registry_error rerr;
	int create_errno;
	struct cixinit_table init_table;
	struct init_transport init_tp;
	char env_buf[CONTAINER_MAX_ENV][CONTAINER_ENV_ENTRY_MAX];
	char *envp_ptrs[CONTAINER_MAX_ENV + 1];
	int env_count = 0;
	size_t i;
	struct registry_network_attachment net_attachments[CONTAINER_MAX_NETWORKS];
	char chosen_ifname[16]; /* ADR-0259: this attachment's operator-chosen name, "" if none */
	char chosen_bridge[16]; /* ADR-0264: in-container bridge this attachment joins, "" if none */
	int net_count = 0;
	int ip_forward = 0;
	int ksm = 0;
	const struct json_value *jcapture_output;
	const struct json_value *jconsoles;
	struct registry_console consoles[REGISTRY_MAX_CONSOLES];
	int console_count = 0;
	int capture_output = 0;
	const struct json_value *juserns; /* ADR-0179 #29 phase 2 opt-in */
	int userns = 0;
	int no_procfuse = 0;
	int ldap_client = 0; /* issue #66 */
	/*
	 * Issue #76: which LDAP groups may log in here. Empty means no
	 * restriction -- any valid account in the directory, which is what
	 * an ldap_client container has always done. Naming groups turns
	 * that into "these groups only", enforced by nslcd itself rather
	 * than by anything this daemon has to be running to check.
	 */
	const struct json_value *jallow_groups = NULL;
	int output_pipe[2] = { -1, -1 };
	int stdio_write_fd = -1;
	struct route_spec route_specs[CONTAINER_MAX_ROUTES];
	int route_count = 0;
	struct registry_device_attachment device_attachments[CONTAINER_MAX_DEVICES];
	struct device_spec device_specs[CONTAINER_MAX_DEVICES];
	int device_count = 0;
	/* ADR-0161 Phase B: raw id/devicemap-name references from an
	 * "optional": true devices[] entry that didn't resolve at creation
	 * time -- handed to registry_set_pending_devices() once entry is
	 * known valid, below. */
	char pending_device_refs[CONTAINER_MAX_DEVICES][96];
	int pending_device_count = 0;
	char interface_names[CONTAINER_MAX_INTERFACES][CONTAINER_IFNAME_MAX];
	int interface_count = 0;
	char cap_add_names[CONTAINER_MAX_CAP_ADD][CONTAINER_CAP_NAME_MAX];
	int cap_add_count = 0;
	char file_paths[CONTAINER_MAX_FILES][CONTAINER_FILE_PATH_MAX];
	int file_count = 0;
	struct container_sysctl sysctl_specs[CONTAINER_MAX_SYSCTLS];
	int sysctl_count = 0;
	const struct json_value *jdns_servers;
	char dns_server_ips[RESOLV_MAX_NAMESERVERS][RESOLV_IP_STRLEN];
	int dns_server_count = 0;
	const struct json_value *jdns_register;
	int dns_register = 0;
	const struct json_value *jpki_issue, *jpki_cert_dir, *jpki_days, *jpki_cert;
	int pki_issue = 0;
	char pki_cert_dir_buf[PATH_MAX];
	char pki_cert_buf[DNS_NAME_MAX];
	int pki_days = 365;
	const struct json_value *jldap_provision, *jldap_user, *jldap_group, *jldap_uid,
	    *jldap_secret_dir;
	int ldap_provision = 0;
	char ldap_user_buf[LDAP_USER_NAME_MAX];
	char ldap_group_buf[LDAP_GROUP_NAME_MAX];
	int ldap_uid = 0;
	char ldap_secret_dir_buf[PATH_MAX];
	const struct json_value *jdisk;
	const char *disk_name;
	char container_root[PATH_MAX];

	snprintf(out_restart_policy, 16, "no");
	*out_restart_delay_seconds = CONTAINERDEF_DEFAULT_RESTART_DELAY_SECONDS;
	*out_depends_on_count = 0;
	*out_follow_rolling = 0;
	*out_has_follow_rolling_jitter = 0;
	*out_follow_rolling_jitter_seconds = 0;

	root = json_parse(body, body_len);
	if (root == NULL) {
		snprintf(err_msg, err_msg_size, "invalid JSON body");
		return 400;
	}

	jname = json_object_get(root, "name");
	jimage = json_object_get(root, "image");
	jimage_version = json_object_get(root, "image_version");
	jservices = json_object_get(root, "services");
	jnetworks = json_object_get(root, "networks");
	jip_forward = json_object_get(root, "ip_forward");
	jksm = json_object_get(root, "ksm");
	jcapture_output = json_object_get(root, "capture_output");
	jconsoles = json_object_get(root, "consoles");
	juserns = json_object_get(root, "userns");
	{
		const struct json_value *jprocfuse = json_object_get(root, "procfuse");

		/*
		 * Absent means on. ADR-0262: a virtualised /proc that has to be
		 * remembered is useless, because nobody knows they need it
		 * until something has already sized itself wrong.
		 */
		if (jprocfuse != NULL) {
			if (jprocfuse->type != JSON_BOOL) {
				json_free(root);
				snprintf(err_msg, err_msg_size, "procfuse must be a boolean");
				return 400;
			}
			no_procfuse = !jprocfuse->u.boolean;
		}
	}
	jroutes = json_object_get(root, "routes");
	jdevices = json_object_get(root, "devices");
	jinterfaces = json_object_get(root, "interfaces");
	jcap_add = json_object_get(root, "cap_add");
	jfiles = json_object_get(root, "files");
	jsysctls = json_object_get(root, "sysctls");
	jenv = json_object_get(root, "env");
	jdns_servers = json_object_get(root, "dns_servers");
	jdns_register = json_object_get(root, "dns_register");
	{
		const struct json_value *jll = json_object_get(root, "ldap_client");

		ldap_client = (jll != NULL && jll->type == JSON_BOOL && jll->u.boolean);
	}
	jallow_groups = json_object_get(root, "ldap_allow_groups");
	jpki_issue = json_object_get(root, "pki_issue");
	jpki_cert_dir = json_object_get(root, "pki_cert_dir");
	jpki_days = json_object_get(root, "pki_days");
	jpki_cert = json_object_get(root, "pki_cert");
	jdisk = json_object_get(root, "disk");
	name = json_as_string(jname);
	image = json_as_string(jimage);
	disk_name = json_as_string(jdisk);
	ip_forward = (jip_forward != NULL && jip_forward->type == JSON_BOOL && jip_forward->u.boolean);
	ksm = (jksm != NULL && jksm->type == JSON_BOOL && jksm->u.boolean);
	capture_output = (jcapture_output != NULL && jcapture_output->type == JSON_BOOL &&
	                   jcapture_output->u.boolean);
	/*
	 * ADR-0207 phase 3, secure by default: an ABSENT "userns" field
	 * takes the platform default (daemon_config, fresh installs: on);
	 * an explicit true/false always wins, in both directions -- that
	 * explicit false is the opt-out the whole posture rests on, used
	 * by operators for workloads that genuinely need init-userns and
	 * by the platform for its own build containers.
	 */
	if (juserns != NULL)
		userns = (juserns->type == JSON_BOOL && juserns->u.boolean);
	else
		userns = daemon_config_userns_default();
	dns_register = (jdns_register != NULL && jdns_register->type == JSON_BOOL &&
	                jdns_register->u.boolean);
	pki_issue = (jpki_issue != NULL && jpki_issue->type == JSON_BOOL && jpki_issue->u.boolean);
	snprintf(pki_cert_dir_buf, sizeof(pki_cert_dir_buf), "%s",
	         json_as_string(jpki_cert_dir) != NULL ? json_as_string(jpki_cert_dir) :
	                                                  PKI_CONTAINER_CERT_DIR);
	if (jpki_days != NULL)
		pki_days = (int)json_as_number(jpki_days);
	/*
	 * Qualified here, once, so the existence check below and the delivery
	 * further down cannot disagree about which cert was meant.
	 *
	 * siteconfig_qualify() (ADR-0052) is what POST /v1/pki/certs applies
	 * to the name it creates, so a lookup that skipped it would resolve a
	 * bare name to a cert that path never created: on an install with a
	 * site name set, creating "jump-ssh" yields "jump-ssh.<site>.<suffix>"
	 * and a literal lookup would 400. Same inconsistency ADR-0092 fixed
	 * for dns_register, and the same fix -- a deployment recipe says
	 * "jump-ssh" and stays portable across installs rather than hardcoding
	 * one site's domain. Measured on 192.168.15.95, 2026-09-12: site_name
	 * is "" there, so qualification is a no-op and the cert really is
	 * named "jump-ssh" -- which is exactly why this would have gone
	 * unnoticed until the first install that set one.
	 */
	if (json_as_string(jpki_cert) != NULL)
		siteconfig_qualify(json_as_string(jpki_cert), pki_cert_buf, sizeof(pki_cert_buf));
	else
		pki_cert_buf[0] = '\0';

	/* Task #727: auto-provisioning hook. ldap_user_buf left empty
	 * (rather than defaulted here) when omitted -- the firing block
	 * below defaults it to entry->name, a stable post-json_free()
	 * buffer, not the raw `name` pointer into root this parse
	 * function must not still be holding onto by then. */
	jldap_provision = json_object_get(root, "ldap_provision");
	jldap_user = json_object_get(root, "ldap_user");
	jldap_group = json_object_get(root, "ldap_group");
	jldap_uid = json_object_get(root, "ldap_uid");
	jldap_secret_dir = json_object_get(root, "ldap_secret_dir");
	ldap_provision = (jldap_provision != NULL && jldap_provision->type == JSON_BOOL &&
	                   jldap_provision->u.boolean);
	ldap_user_buf[0] = '\0';
	if (json_as_string(jldap_user) != NULL)
		snprintf(ldap_user_buf, sizeof(ldap_user_buf), "%s", json_as_string(jldap_user));
	ldap_group_buf[0] = '\0';
	if (json_as_string(jldap_group) != NULL)
		snprintf(ldap_group_buf, sizeof(ldap_group_buf), "%s", json_as_string(jldap_group));
	if (jldap_uid != NULL)
		ldap_uid = (int)json_as_number(jldap_uid);
	snprintf(ldap_secret_dir_buf, sizeof(ldap_secret_dir_buf), "%s",
	         json_as_string(jldap_secret_dir) != NULL ? json_as_string(jldap_secret_dir) :
	                                                     "/etc/cix-ldap");

	jrestart = json_object_get(root, "restart");
	restart_str = json_as_string(jrestart);
	if (restart_str != NULL && strcmp(restart_str, "always") != 0 &&
	    strcmp(restart_str, "on-failure") != 0 && strcmp(restart_str, "unless-stopped") != 0 &&
	    strcmp(restart_str, "no") != 0) {
		json_free(root);
		snprintf(err_msg, err_msg_size,
		         "restart must be \"always\", \"on-failure\", \"unless-stopped\", or \"no\"");
		return 400;
	}
	snprintf(out_restart_policy, 16, "%s", restart_str != NULL ? restart_str : "no");

	/*
	 * Given with restart:"no", ignored rather than rejected -- mirrors
	 * depends_on's own existing "ignored, not an error" precedent
	 * (nothing to persist, so no future restart to delay).
	 */
	jrestart_delay = json_object_get(root, "restart_delay_seconds");
	if (jrestart_delay != NULL) {
		restart_delay = (long)json_as_number(jrestart_delay);
		if (restart_delay < 1 || restart_delay > 300) {
			json_free(root);
			snprintf(err_msg, err_msg_size, "restart_delay_seconds must be 1-300");
			return 400;
		}
		*out_restart_delay_seconds = (int)restart_delay;
	}

	/*
	 * Part 5 (ADR-0124): same "ignored, not an error" precedent
	 * restart_delay_seconds already established just above. Since ADR-0181
	 * every container -- restart:"no" included -- has a persisted
	 * definition, so follow_rolling IS stored for it; it is simply never
	 * acted on, because apply_rolling_container_restarts() deliberately
	 * skips restart:"no" defs ("never auto-restart" includes "never
	 * auto-recreated by a rolling update"). Parsed-and-stored-but-inert,
	 * not rejected.
	 */
	jfollow_rolling = json_object_get(root, "follow_rolling");
	*out_follow_rolling =
	    (jfollow_rolling != NULL && jfollow_rolling->type == JSON_BOOL && jfollow_rolling->u.boolean);

	/*
	 * Part 5 follow-up: an optional per-container override of the
	 * daemon-wide rolling-restart jitter window -- same "ignored, not
	 * an error" precedent as follow_rolling itself just above when
	 * this container never actually follows rolling updates, or when
	 * restart is "no" (ADR-0181: persisted like any other, but its
	 * rolling-follow is inert -- see the follow_rolling note above).
	 * Range-validated the same 0-CONTAINERDEF_JITTER_MAX_
	 * SECONDS bound PUT /v1/system/rolling-config already enforces for
	 * the daemon-wide default, so a container-level override can never
	 * exceed what the daemon itself would ever accept.
	 */
	jfollow_rolling_jitter = json_object_get(root, "follow_rolling_jitter_seconds");
	if (jfollow_rolling_jitter != NULL) {
		follow_rolling_jitter = (long)json_as_number(jfollow_rolling_jitter);
		if (follow_rolling_jitter < 0 || follow_rolling_jitter > CONTAINERDEF_JITTER_MAX_SECONDS) {
			json_free(root);
			snprintf(err_msg, err_msg_size, "follow_rolling_jitter_seconds must be 0-%d",
			         CONTAINERDEF_JITTER_MAX_SECONDS);
			return 400;
		}
		*out_has_follow_rolling_jitter = 1;
		*out_follow_rolling_jitter_seconds = (int)follow_rolling_jitter;
	}

	jdepends_on = json_object_get(root, "depends_on");
	if (jdepends_on != NULL) {
		if (jdepends_on->type != JSON_ARRAY ||
		    jdepends_on->u.array.count > CONTAINERDEF_MAX_DEPENDS) {
			json_free(root);
			snprintf(err_msg, err_msg_size, "depends_on must be an array of at most %d entries",
			         CONTAINERDEF_MAX_DEPENDS);
			return 400;
		}
		*out_depends_on_count = (int)jdepends_on->u.array.count;
		for (i = 0; i < (size_t)*out_depends_on_count; i++) {
			const char *dep = json_as_string(jdepends_on->u.array.items[i]);

			if (dep == NULL || !name_is_valid(dep)) {
				json_free(root);
				snprintf(err_msg, err_msg_size, "invalid depends_on entry");
				return 400;
			}
			snprintf(out_depends_on[i], REGISTRY_NAME_MAX, "%s", dep);
		}
	}


	if (!name_is_valid(name) || image == NULL || image[0] == '\0' || jservices == NULL) {
		json_free(root);
		snprintf(err_msg, err_msg_size, "name/image/services missing or invalid");
		return 400;
	}
	if (jnetworks != NULL) {
		/* ADR-0259: each attachment's resolved interface name, kept so
		 * two of them cannot claim the same one. */
		char seen_ifnames[CONTAINER_MAX_NETWORKS][16];
		char chosen_bridge[16];

		memset(seen_ifnames, 0, sizeof(seen_ifnames));
		if (jnetworks->type != JSON_ARRAY || jnetworks->u.array.count == 0 ||
		    jnetworks->u.array.count > CONTAINER_MAX_NETWORKS) {
			json_free(root);
			snprintf(err_msg, err_msg_size, "networks must be a non-empty array of at most 64 entries");
			return 400;
		}
		for (i = 0; i < jnetworks->u.array.count; i++) {
			char n[NETWORK_NAME_MAX];
			uint32_t ip_be;
			int has_ip;
			int prc;
			size_t j;

			prc = parse_network_entry(jnetworks->u.array.items[i], n, sizeof(n), &ip_be,
			                           &has_ip, seen_ifnames[i], sizeof(seen_ifnames[i]),
			                           chosen_bridge, sizeof(chosen_bridge));
			if (prc == -3) {
				json_free(root);
				snprintf(err_msg, err_msg_size,
				         "networks[%d].container_bridge must be 1-15 characters of "
				         "[A-Za-z0-9._-], and may not be \"lo\" or an \"eth<N>\" name "
				         "(it becomes a real interface in the same namespace)",
				         (int)i);
				return 400;
			}
			if (prc == -2) {
				json_free(root);
				snprintf(err_msg, err_msg_size,
				         "networks[%d].ifname must be 1-15 characters of "
				         "[A-Za-z0-9._-], and may not be \"lo\" or an \"eth<N>\" name "
				         "(those are what this platform assigns to unnamed attachments)",
				         (int)i);
				return 400;
			}
			if (prc != 0) {
				json_free(root);
				snprintf(err_msg, err_msg_size, "invalid networks entry");
				return 400;
			}
			/*
			 * ADR-0259: two attachments cannot share a name. Only
			 * explicit names can collide -- an explicit "eth<N>" is
			 * already refused above, so a chosen name can never equal
			 * another attachment's positional default.
			 */
			for (j = 0; j < i; j++) {
				if (seen_ifnames[i][0] != '\0' &&
				    strcmp(seen_ifnames[i], seen_ifnames[j]) == 0) {
					json_free(root);
					snprintf(err_msg, err_msg_size,
					         "networks[%d].ifname \"%s\" is already used by "
					         "networks[%d] -- each interface needs its own name",
					         (int)i, seen_ifnames[i], (int)j);
					return 400;
				}
			}
			if (network_find(n) == NULL) {
				json_free(root);
				snprintf(err_msg, err_msg_size, "unknown network");
				return 400;
			}
			if (has_ip) {
				enum network_error ip_err = network_ip_available(n, ip_be);

				if (ip_err != NETWORK_OK) {
					const char *ip_msg;
					int ip_status = network_error_to_status(ip_err, &ip_msg);

					/*
					 * Issue #148: say WHICH container holds the
					 * address, and whether it is on its way out.
					 *
					 * Container deletion is asynchronous -- DELETE
					 * returns once teardown is under way -- so
					 * recreating at the same address immediately after
					 * a delete legitimately races the previous holder.
					 * The old message said "assigned to a running
					 * container" when nothing was running and nothing
					 * appeared in `container ls`, which reads as
					 * "something else grabbed it" and sends an
					 * operator looking for a conflict that does not
					 * exist. Naming the holder, and distinguishing
					 * "shutting down" from a genuine clash, is the
					 * difference between "retry in a moment" and "go
					 * find what is using this".
					 */
					if (ip_err == NETWORK_ERR_IP_TAKEN) {
						char holder[REGISTRY_NAME_MAX];
						int tearing = 0;

						holder[0] = '\0';
						if (registry_ip_holder(ip_be, holder, sizeof(holder), &tearing))
							snprintf(err_msg, err_msg_size,
							          "ip is held by container \"%s\"%s", holder,
							          tearing ? ", which is still shutting down -- retry "
							                     "shortly"
							                  : "");
						else
							snprintf(err_msg, err_msg_size, "%s", ip_msg);
					} else {
						snprintf(err_msg, err_msg_size, "%s", ip_msg);
					}
					json_free(root);
					return ip_status;
				}
			}
		}
	}
	if (dns_register && jnetworks == NULL) {
		json_free(root);
		snprintf(err_msg, err_msg_size, "dns_register requires networks");
		return 400;
	}
	if (pki_issue && !pki_ca_bootstrapped()) {
		json_free(root);
		snprintf(err_msg, err_msg_size, "pki_issue requires the CA to be bootstrapped -- POST /v1/pki/ca first");
		return 400;
	}
	/*
	 * ADR-0280/#397. pki_cert names an ALREADY-EXISTING cert to deliver;
	 * pki_issue creates a fresh one owned by this container. Both write
	 * tls.crt/tls.key into the same pki_cert_dir, so declaring both is a
	 * genuine conflict with no sane resolution -- refuse it rather than
	 * let whichever block runs second silently win.
	 *
	 * Existence is checked here rather than left to the staging step, so a
	 * typo'd cert name is a 400 that NAMES the missing certificate rather
	 * than a 500 about staging. Both refuse to create the container --
	 * since #414 a container that asked for a TLS identity and did not
	 * get one does not start at all -- but only this one can say what is
	 * actually wrong.
	 */
	if (pki_cert_buf[0] != '\0') {
		if (pki_issue) {
			json_free(root);
			snprintf(err_msg, err_msg_size,
			         "pki_cert and pki_issue are mutually exclusive -- both deliver tls.crt/tls.key into pki_cert_dir");
			return 400;
		}
		if (!pki_ca_bootstrapped()) {
			json_free(root);
			snprintf(err_msg, err_msg_size,
			         "pki_cert requires the CA to be bootstrapped -- POST /v1/pki/ca first");
			return 400;
		}
		if (!pki_cert_exists(pki_cert_buf)) {
			json_free(root);
			snprintf(err_msg, err_msg_size,
			         "pki_cert names no existing certificate \"%s\" -- create it first with POST /v1/pki/certs",
			         pki_cert_buf);
			return 400;
		}
	}
	if (ldap_provision) {
		/* Group must exist -- ldap_user_create() would reject an
		 * unresolvable primarygroup anyway, but checking here (before
		 * the container itself is created) matches pki_issue's own
		 * "fail fast on an obviously-unsatisfiable request" pattern,
		 * and reads by ldap.c's own in-memory table (no root pointer
		 * involved), so it's safe this early. Auto-creating the group
		 * is deliberately not done -- an operator's own group naming/
		 * gid-numbering choices shouldn't be second-guessed here. */
		if (ldap_group_buf[0] == '\0' || ldap_group_find(ldap_group_buf) == NULL) {
			json_free(root);
			snprintf(err_msg, err_msg_size,
			         "ldap_provision requires ldap_group to name an existing LDAP group");
			return 400;
		}
		/* An explicit ldap_user must already be a valid LDAP username
		 * (default-to-container-name happens later, post-json_free(),
		 * and is validated there too -- container names allow a wider
		 * charset than LDAP usernames do). */
		if (ldap_user_buf[0] != '\0' && !ldap_username_is_valid(ldap_user_buf)) {
			json_free(root);
			snprintf(err_msg, err_msg_size, "ldap_user is not a valid LDAP username");
			return 400;
		}
	}
	/*
	 * Issue #76: an allow-list only means anything to nslcd, so naming
	 * one without ldap_client is a request that cannot do what it says
	 * -- refused rather than silently ignored, which would read as a
	 * restriction that is in force when it is not.
	 */
	if (jallow_groups != NULL && !ldap_client) {
		json_free(root);
		snprintf(err_msg, err_msg_size,
		         "ldap_allow_groups requires ldap_client -- there is nothing to restrict without it");
		return 400;
	}
	if (jallow_groups != NULL && jallow_groups->type != JSON_ARRAY) {
		json_free(root);
		snprintf(err_msg, err_msg_size, "ldap_allow_groups must be an array of group names");
		return 400;
	}
	if (jroutes != NULL) {
		if (jroutes->type != JSON_ARRAY || jroutes->u.array.count > CONTAINER_MAX_ROUTES) {
			json_free(root);
			snprintf(err_msg, err_msg_size, "routes must be an array of at most 8 entries");
			return 400;
		}
		route_count = (int)jroutes->u.array.count;
		for (i = 0; i < (size_t)route_count; i++) {
			const struct json_value *item = jroutes->u.array.items[i];
			const char *dest = json_as_string(json_object_get(item, "dest"));
			const char *via = json_as_string(json_object_get(item, "via"));
			const struct json_value *jprefix = json_object_get(item, "prefix_len");
			struct in_addr dest_addr, via_addr;
			long prefix_len;

			if (dest == NULL || via == NULL || jprefix == NULL ||
			    inet_pton(AF_INET, dest, &dest_addr) != 1 ||
			    inet_pton(AF_INET, via, &via_addr) != 1) {
				json_free(root);
				snprintf(err_msg, err_msg_size, "invalid routes entry");
				return 400;
			}
			prefix_len = (long)json_as_number(jprefix);
			if (prefix_len < 0 || prefix_len > 32) {
				json_free(root);
				snprintf(err_msg, err_msg_size, "routes prefix_len must be 0-32");
				return 400;
			}
			route_specs[i].dest_be = dest_addr.s_addr;
			route_specs[i].dest_prefix_len = (int)prefix_len;
			route_specs[i].gateway_be = via_addr.s_addr;
		}
	}
	if (jdevices != NULL) {
		if (jdevices->type != JSON_ARRAY || jdevices->u.array.count > CONTAINER_MAX_DEVICES) {
			json_free(root);
			snprintf(err_msg, err_msg_size, "devices must be an array of at most 16 entries");
			return 400;
		}
		/*
		 * device_count is the WRITE index here, decoupled from the
		 * request array's own read index i -- a single grouped id
		 * (e.g. "gpu:0", ADR-0028) can expand into several grants via
		 * device_find_group(), so one requested entry doesn't
		 * necessarily mean one device_specs slot. The array-length
		 * check above is only a coarse upfront guard (an array literally
		 * longer than the cap can never fit even unexpanded); the real
		 * bound is enforced incrementally below as groups expand.
		 */
		for (i = 0; i < jdevices->u.array.count; i++) {
			const struct json_value *item = jdevices->u.array.items[i];
			const char *id;
			int optional = 0;
			int shared = 0;
			const struct discovered_device *matches[CONTAINER_MAX_DEVICES];
			int n, j;

			/*
			 * ADR-0161 Phase B: a bare string (every pre-existing
			 * caller's exact shape, zero opt-in required) or
			 * {"id": "...", "optional": true} -- "id" shorthand,
			 * "optional" defaults false, so an object entry with
			 * "optional" omitted behaves identically to the bare-
			 * string form too.
			 */
			if (item->type == JSON_STRING) {
				id = json_as_string(item);
			} else if (item->type == JSON_OBJECT) {
				const struct json_value *joptional = json_object_get(item, "optional");
				const struct json_value *jshared = json_object_get(item, "shared");

				id = json_as_string(json_object_get(item, "id"));
				if (joptional != NULL) {
					if (joptional->type != JSON_BOOL) {
						json_free(root);
						snprintf(err_msg, err_msg_size, "devices[].optional must be a boolean");
						return 400;
					}
					optional = joptional->u.boolean;
				}
				if (jshared != NULL) {
					if (jshared->type != JSON_BOOL) {
						json_free(root);
						snprintf(err_msg, err_msg_size, "devices[].shared must be a boolean");
						return 400;
					}
					shared = jshared->u.boolean;
				}
			} else {
				id = NULL;
			}

			if (id == NULL) {
				json_free(root);
				snprintf(err_msg, err_msg_size,
				         "devices entries must be a string, or {\"id\":..., \"optional\":..., "
				         "\"shared\":...}");
				return 400;
			}
			/*
			 * A persisted device mapping name (ADR-0048) takes priority
			 * over the raw device.h id namespace -- mapping names are
			 * validated with simple_name_is_valid() at creation time,
			 * which forbids ':', so they can never collide with a real
			 * id (every real id's own bus prefix always contains one).
			 * devicemap_resolve() returns -1 (not 0) when id doesn't
			 * name any mapping at all, which is what falls through to
			 * the existing raw-id path below -- a mapping that DOES
			 * exist but currently resolves to nothing (its device is
			 * unplugged) is a real error here, UNLESS optional is true
			 * (ADR-0161 Phase B): the container is then still created,
			 * without this grant, and id is remembered in pending_
			 * device_refs[] for Phase C/D's later hotplug matching.
			 */
			n = devicemap_resolve(id, CONTAINERS_DIR, matches,
			                       CONTAINER_MAX_DEVICES - device_count);
			if (n < 0)
				n = device_find_group(id, CONTAINERS_DIR, matches,
				                       CONTAINER_MAX_DEVICES - device_count);
			if (n <= 0) {
				if (optional) {
					if (pending_device_count < CONTAINER_MAX_DEVICES) {
						snprintf(pending_device_refs[pending_device_count],
						         sizeof(pending_device_refs[0]), "%s", id);
						pending_device_count++;
					}
					continue;
				}
				json_free(root);
				snprintf(err_msg, err_msg_size, "unknown, unassignable, or not-currently-present device");
				return 400;
			}
			if (device_count + n > CONTAINER_MAX_DEVICES) {
				json_free(root);
				snprintf(err_msg, err_msg_size,
				         "too many devices requested (a grouped id can expand into "
				         "more than one grant)");
				return 400;
			}
			for (j = 0; j < n; j++) {
				const struct discovered_device *dd = matches[j];
				char holder[REGISTRY_NAME_MAX];

				/*
				 * #356: a device already held by a running container
				 * is refused unless both sides said "shared".
				 *
				 * Checked per RESOLVED device rather than per requested
				 * entry, because one entry can expand into several --
				 * a vendor_model mapping matching two identical drives,
				 * or a gpu:N group. One of those being contended must
				 * refuse that device rather than the whole entry
				 * silently granting the rest.
				 *
				 * Before this, nothing refused a second grant at all:
				 * both containers got their own BPF_CGROUP_DEVICE rule
				 * for the same major/minor, which is ordinary
				 * multi-tenant compute for a GPU and data corruption
				 * for a serial adapter or a raw disk. Now it is a
				 * decision someone has to make in writing.
				 */
				if (registry_device_grant_conflict(dd->id, shared, holder, sizeof(holder))) {
					json_free(root);
					snprintf(err_msg, err_msg_size,
					         "device %s is already held by container \"%s\" -- both grants must "
					         "set \"shared\": true to share it",
					         dd->id, holder);
					return 409;
				}

				/* dev_path/major/minor always come from the daemon's
				 * own current sysfs snapshot (dd), never trusted from
				 * the request body -- a client only ever names a
				 * device by id. */
				memset(&device_specs[device_count], 0, sizeof(device_specs[device_count]));
				device_specs[device_count].type = dd->type;
				device_specs[device_count].major = dd->major;
				device_specs[device_count].minor = dd->minor;
				snprintf(device_specs[device_count].dev_path,
				         sizeof(device_specs[device_count].dev_path), "%s", dd->dev_path);
				memset(&device_attachments[device_count], 0,
				       sizeof(device_attachments[device_count]));
				snprintf(device_attachments[device_count].id,
				         sizeof(device_attachments[device_count].id), "%s", dd->id);
				snprintf(device_attachments[device_count].dev_path,
				         sizeof(device_attachments[device_count].dev_path), "%s",
				         dd->dev_path);
				device_attachments[device_count].type = dd->type;
				device_attachments[device_count].major = dd->major;
				device_attachments[device_count].minor = dd->minor;
				device_attachments[device_count].shared = shared;
				/* .live stays 0 (memset above) -- a create-time grant,
				 * never independently detachable (ADR-0161 Phase D). */
				device_count++;
			}
		}
	}
	if (jinterfaces != NULL) {
		if (jinterfaces->type != JSON_ARRAY || jinterfaces->u.array.count > CONTAINER_MAX_INTERFACES) {
			json_free(root);
			snprintf(err_msg, err_msg_size, "interfaces must be an array of at most 16 entries");
			return 400;
		}
		interface_count = (int)jinterfaces->u.array.count;
		for (i = 0; i < (size_t)interface_count; i++) {
			const char *ifname = json_as_string(jinterfaces->u.array.items[i]);
			char dev_id[96];
			const struct discovered_device *dd;

			if (ifname == NULL) {
				json_free(root);
				snprintf(err_msg, err_msg_size, "interfaces entries must be strings");
				return 400;
			}
			/* GET /v1/devices is the one source of truth for which real
			 * interfaces exist and are currently assignable -- an
			 * interface already moved into another running container's
			 * netns simply doesn't appear there at all anymore, so
			 * there is no separate "already claimed" check needed here
			 * beyond this same lookup every other device grant uses. */
			snprintf(dev_id, sizeof(dev_id), "net:%s", ifname);
			dd = device_find(dev_id, CONTAINERS_DIR);
			if (dd == NULL || !dd->assignable) {
				json_free(root);
				snprintf(err_msg, err_msg_size, "unknown or unassignable interface");
				return 400;
			}
			snprintf(interface_names[i], sizeof(interface_names[i]), "%s", ifname);
		}
	}
	if (jcap_add != NULL) {
		if (jcap_add->type != JSON_ARRAY || jcap_add->u.array.count > CONTAINER_MAX_CAP_ADD) {
			json_free(root);
			snprintf(err_msg, err_msg_size, "cap_add must be an array of at most 8 entries");
			return 400;
		}
		cap_add_count = (int)jcap_add->u.array.count;
		for (i = 0; i < (size_t)cap_add_count; i++) {
			const char *cap_name = json_as_string(jcap_add->u.array.items[i]);

			if (cap_name == NULL || !container_cap_name_valid(cap_name)) {
				json_free(root);
				snprintf(err_msg, err_msg_size,
				         "cap_add entries must be a recognized capability name "
				         "that's actually on the default deny-list (e.g. \"CAP_SYS_TIME\")");
				return 400;
			}
			snprintf(cap_add_names[i], sizeof(cap_add_names[i]), "%s", cap_name);
		}
	}
	/*
	 * Issue #248: the consoles this container declares.
	 *
	 * Validated in full here, before anything is created, so a bad
	 * declaration is a 400 naming what is wrong rather than a
	 * container that exists and then refuses to attach.
	 */
	memset(consoles, 0, sizeof(consoles));
	if (jconsoles != NULL) {
		if (jconsoles->type != JSON_ARRAY ||
		    jconsoles->u.array.count > REGISTRY_MAX_CONSOLES) {
			json_free(root);
			snprintf(err_msg, err_msg_size,
			         "consoles must be an array of at most %d entries",
			         REGISTRY_MAX_CONSOLES);
			return 400;
		}
		for (i = 0; i < jconsoles->u.array.count; i++) {
			const struct json_value *item = jconsoles->u.array.items[i];
			const char *cname;
			const struct json_value *jcmd;
			size_t a;
			int dup;

			cname = json_as_string(json_object_get(item, "name"));
			jcmd = json_object_get(item, "cmd");
			if (cname == NULL || cname[0] == '\0' ||
			    strlen(cname) >= REGISTRY_CONSOLE_NAME_MAX) {
				json_free(root);
				snprintf(err_msg, err_msg_size,
				         "each console needs a name of 1 to %d characters",
				         REGISTRY_CONSOLE_NAME_MAX - 1);
				return 400;
			}
			/*
			 * The name is how a console is selected in a URL and
			 * shown in a list, so keep it to characters that need
			 * no escaping in either.
			 */
			for (a = 0; cname[a] != '\0'; a++) {
				if (!isalnum((unsigned char)cname[a]) && cname[a] != '_' &&
				    cname[a] != '-') {
					/* Message before the free: cname points into root (#421). */
					snprintf(err_msg, err_msg_size,
					         "console name '%s' may use only letters, digits, - and _",
					         cname);
					json_free(root);
					return 400;
				}
			}
			/*
			 * Duplicate names would make selection ambiguous, and
			 * silently picking the first is exactly the kind of
			 * arbitrary choice this whole field exists to remove.
			 */
			for (dup = 0; dup < console_count; dup++) {
				if (strcmp(consoles[dup].name, cname) == 0) {
					/* Message before the free: cname points into root (#421). */
					snprintf(err_msg, err_msg_size,
					         "console name '%s' is declared more than once", cname);
					json_free(root);
					return 400;
				}
			}
			if (jcmd == NULL || jcmd->type != JSON_ARRAY || jcmd->u.array.count < 1 ||
			    jcmd->u.array.count > REGISTRY_CONSOLE_ARGC_MAX) {
				/* Message before the free: cname points into root (#421). */
				snprintf(err_msg, err_msg_size,
				         "console '%s' needs a cmd array of 1 to %d strings", cname,
				         REGISTRY_CONSOLE_ARGC_MAX);
				json_free(root);
				return 400;
			}
			snprintf(consoles[console_count].name, sizeof(consoles[console_count].name),
			         "%s", cname);
			for (a = 0; a < jcmd->u.array.count; a++) {
				const char *arg = json_as_string(jcmd->u.array.items[a]);

				if (arg == NULL || strlen(arg) >= REGISTRY_CONSOLE_ARG_MAX) {
					/* Message before the free: cname points into root (#421). */
					snprintf(err_msg, err_msg_size,
					         "console '%s' argv[%d] must be a string under %d bytes",
					         cname, (int)a, REGISTRY_CONSOLE_ARG_MAX);
					json_free(root);
					return 400;
				}
				snprintf(consoles[console_count].argv[a],
				         sizeof(consoles[console_count].argv[a]), "%s", arg);
			}
			/*
			 * argv[0] is exec'd by path, never resolved through a
			 * PATH lookup -- there is no shell in this path. A bare
			 * name would fail at exec time with a confusing ENOENT
			 * against a binary that exists, so refuse it here where
			 * the message can say why.
			 */
			if (consoles[console_count].argv[0][0] != '/') {
				/* Message before the free: cname points into root (#421). */
				snprintf(err_msg, err_msg_size,
				         "console '%s' argv[0] must be an absolute path -- it is exec'd "
				         "directly, with no shell to resolve a bare name",
				         cname);
				json_free(root);
				return 400;
			}
			consoles[console_count].argc = (int)jcmd->u.array.count;
			console_count++;
		}
	}
	if (jfiles != NULL) {
		if (jfiles->type != JSON_ARRAY || jfiles->u.array.count > CONTAINER_MAX_FILES) {
			json_free(root);
			snprintf(err_msg, err_msg_size, "files must be an array of at most 16 entries");
			return 400;
		}
		for (i = 0; i < jfiles->u.array.count; i++) {
			const struct json_value *item = jfiles->u.array.items[i];
			const char *path = json_as_string(json_object_get(item, "path"));
			const char *content = json_as_string(json_object_get(item, "content"));
			const char *mode_str = json_as_string(json_object_get(item, "mode"));
			const struct json_value *jowner = json_object_get(item, "owner");
			const struct json_value *jgroup = json_object_get(item, "group");
			long mode;

			if (path == NULL || content == NULL || path[0] != '/' ||
			    strlen(path) >= CONTAINER_FILE_PATH_MAX ||
			    strlen(content) > CONTAINER_FILE_CONTENT_MAX || !file_path_is_safe(path)) {
				json_free(root);
				snprintf(err_msg, err_msg_size, "invalid files entry");
				return 400;
			}
			/*
			 * Issue #142: /run is a fresh tmpfs mounted at every
			 * container start (src/mountns.c, deliberately -- a
			 * daemon finding its own stale pidfile there is a real
			 * failure this project has hit). files[] are written into
			 * the container's upperdir at CREATION time, so anything
			 * staged under /run is masked by that mount on every
			 * single start and can never be read by anything.
			 *
			 * Refused rather than silently discarded, because there is
			 * no arrangement in which it works: the file is written,
			 * the request succeeds, the container starts, and the
			 * content is simply not there. That is the same shape as
			 * the artifact that lost its exec bit and the config file
			 * holding a literal {{SECRET:X}} -- valid by every check
			 * the platform makes, wrong in the one way that matters.
			 */
			if (strcmp(path, "/run") == 0 || strncmp(path, "/run/", 5) == 0) {
				/* Message BEFORE the free: `path` points into the
				 * parsed JSON, so formatting it afterwards prints
				 * freed memory. */
				snprintf(err_msg, err_msg_size,
				          "files entry \"%s\": /run is a fresh tmpfs at every container "
				          "start, so staged content there is never visible -- use another "
				          "path (/etc is the usual home for config)",
				          path);
				json_free(root);
				return 400;
			}
			mode = mode_str != NULL ? strtol(mode_str, NULL, 8) : 0644;
			if (mode < 0 || mode > 0777) {
				json_free(root);
				snprintf(err_msg, err_msg_size, "files mode must be 0-0777 octal");
				return 400;
			}
			/*
			 * owner/group (ADR-0144): a real, numeric uid/gid this
			 * exact file lands owned as, staged before the container's
			 * own process ever execve()s (same pre-clone3() write this
			 * whole block already does) -- no NSS lookup involved, no
			 * ordering dependency on some OTHER staged file (e.g.
			 * /etc/passwd) being written first. Omitted means root:root
			 * (this daemon's own real euid/egid, unchanged from before
			 * this field existed). Real need: a file only a specific
			 * non-root container user should be able to read (e.g. a
			 * bind credential an AuthorizedKeysCommand script -- never
			 * root -- must read but nothing else on the box should).
			 */
			if (jowner != NULL && (jowner->type != JSON_NUMBER || json_as_number(jowner) < 0)) {
				json_free(root);
				snprintf(err_msg, err_msg_size, "files owner must be a non-negative uid");
				return 400;
			}
			if (jgroup != NULL && (jgroup->type != JSON_NUMBER || json_as_number(jgroup) < 0)) {
				json_free(root);
				snprintf(err_msg, err_msg_size, "files group must be a non-negative gid");
				return 400;
			}
			if (jdns_servers != NULL && strcmp(path, "/etc/resolv.conf") == 0) {
				json_free(root);
				snprintf(err_msg, err_msg_size,
				         "cannot combine dns_servers with an explicit files[] entry for "
				         "/etc/resolv.conf -- pick one");
				return 400;
			}
		}
	}
	/*
	 * Issue #66: ldap_client stages the two identity-resolution files
	 * that would otherwise hand-carry the daemon's own LDAP client
	 * config -- /etc/nsswitch.conf (passwd/group/shadow: files ldap)
	 * and /etc/nslcd.conf (uri/base/binddn/bindpw from
	 * ldap_config_get()). The container still owns its own service
	 * wiring (PAM, sshd, the startup script that actually runs nslcd)
	 * and its own baseline /etc/passwd -- this flag is only about the
	 * client config values that are properly the daemon's, not the
	 * container's, to know. A container needing a *custom* nslcd.conf
	 * uses the {{LDAP:*}} recipe tokens instead and leaves this unset;
	 * both paths coexist. Refused with a clear error when the daemon
	 * has no client URI/base configured (there would be nothing useful
	 * to render), and budget-checked against CONTAINER_MAX_FILES up
	 * front so a create can't half-stage and then 500.
	 */
	if (ldap_client) {
		const struct ldap_config *lc = ldap_config_get();
		int user_files = (jfiles != NULL) ? (int)jfiles->u.array.count : 0;
		char probe_uri[600];

		if (lc->base_dn[0] == '\0' || !ldap_effective_client_uri(probe_uri, sizeof(probe_uri))) {
			json_free(root);
			snprintf(err_msg, err_msg_size,
			         "ldap_client requires base_dn (PUT /ldap/config) and either client_uri "
			         "or at least one running registered LDAP server");
			return 400;
		}
		if (user_files + 2 > CONTAINER_MAX_FILES) {
			json_free(root);
			snprintf(err_msg, err_msg_size,
			         "ldap_client needs 2 file slots; too many files[] entries already");
			return 400;
		}
	}

	/*
	 * ADR-0143: optional real /etc/resolv.conf staged into the
	 * container's own upperdir, same shape files[] already uses --
	 * deliberately explicit (no auto-wiring to any registered internal
	 * DNS server), same posture ADR-0076 already established for the
	 * host's own equivalent PUT /system/resolv. RESOLV_MAX_NAMESERVERS
	 * is resolv.c's own cap (matches glibc's real resolv.conf MAXNS),
	 * reused here rather than a second invented limit.
	 */
	if (jdns_servers != NULL) {
		if (jdns_servers->type != JSON_ARRAY || jdns_servers->u.array.count > RESOLV_MAX_NAMESERVERS) {
			json_free(root);
			snprintf(err_msg, err_msg_size, "dns_servers must be an array of at most %d entries",
			         RESOLV_MAX_NAMESERVERS);
			return 400;
		}
		for (i = 0; i < jdns_servers->u.array.count; i++) {
			const char *ip = json_as_string(jdns_servers->u.array.items[i]);
			struct in_addr addr;

			if (ip == NULL || inet_pton(AF_INET, ip, &addr) != 1) {
				json_free(root);
				snprintf(err_msg, err_msg_size, "dns_servers entries must be valid IPv4 addresses");
				return 400;
			}
			snprintf(dns_server_ips[i], sizeof(dns_server_ips[i]), "%s", ip);
		}
		dns_server_count = (int)jdns_servers->u.array.count;
	}
	if (jsysctls != NULL) {
		if (jsysctls->type != JSON_OBJECT || jsysctls->u.object.count > CONTAINER_MAX_SYSCTLS) {
			json_free(root);
			snprintf(err_msg, err_msg_size, "sysctls must be an object of at most 32 entries");
			return 400;
		}
		sysctl_count = (int)jsysctls->u.object.count;
		for (i = 0; i < (size_t)sysctl_count; i++) {
			const char *key = jsysctls->u.object.keys[i];
			const char *value = json_as_string(jsysctls->u.object.values[i]);

			if (value == NULL || strlen(key) >= CONTAINER_SYSCTL_KEY_MAX ||
			    strlen(value) >= CONTAINER_SYSCTL_VALUE_MAX || !sysctl_key_is_safe(key)) {
				json_free(root);
				snprintf(err_msg, err_msg_size, "invalid sysctls entry");
				return 400;
			}
			snprintf(sysctl_specs[i].key, sizeof(sysctl_specs[i].key), "%s", key);
			snprintf(sysctl_specs[i].value, sizeof(sysctl_specs[i].value), "%s", value);
		}
	}
	if (jenv != NULL) {
		if (jenv->type != JSON_OBJECT || jenv->u.object.count > CONTAINER_MAX_ENV) {
			json_free(root);
			snprintf(err_msg, err_msg_size, "env must be an object of at most 32 entries");
			return 400;
		}
		env_count = (int)jenv->u.object.count;
		for (i = 0; i < (size_t)env_count; i++) {
			const char *key = jenv->u.object.keys[i];
			const char *value = json_as_string(jenv->u.object.values[i]);

			if (value == NULL || strlen(key) >= CONTAINER_ENV_KEY_MAX ||
			    strlen(value) >= CONTAINER_ENV_VALUE_MAX || !env_key_is_safe(key)) {
				json_free(root);
				snprintf(err_msg, err_msg_size, "invalid env entry");
				return 400;
			}
			snprintf(env_buf[i], sizeof(env_buf[i]), "%s=%s", key, value);
			envp_ptrs[i] = env_buf[i];
		}
	}

	/*
	 * ADR-0260: what the container runs is its services[], translated
	 * once into cix-init's table. A tcp probe connects to the
	 * container's own first address.
	 */
	if (cixinit_table_from_json(jservices, net_count > 0 ? net_attachments[0].ip_be : 0, &init_table,
	                            err_msg, err_msg_size) != 0) {
		json_free(root);
		return 400;
	}
	envp_ptrs[env_count] = NULL;

	/*
	 * ADR-0107/0108: an image's own rootfs is now one of potentially
	 * many immutable per-version directories, not one fixed path --
	 * "image_version" in the request body (present only on a
	 * daemon-restart/`.../start` replay of a create request this
	 * daemon already persisted once, spliced in by handle_container_create()
	 * below -- see its own comment) pins this container to the EXACT
	 * version it was originally created against, so a `pkg install`
	 * against the same image name in between never silently changes
	 * what a replayed/restarted container resolves to. A fresh, real
	 * client request never sets this field, so it resolves the
	 * image's own current version fresh, exactly as before.
	 */
	{
		const char *requested_version = json_as_string(jimage_version);

		if (requested_version != NULL && requested_version[0] != '\0') {
			snprintf(resolved_image_version, sizeof(resolved_image_version), "%s",
			         requested_version);
		} else if (image_current_version(image, resolved_image_version,
		                                  sizeof(resolved_image_version)) != IMAGE_OK) {
			json_free(root);
			snprintf(err_msg, err_msg_size, "image rootfs does not exist");
			return 400;
		}
	}
	image_version_rootfs_path(image, resolved_image_version, lowerdir, sizeof(lowerdir));
	if (stat(lowerdir, &st) != 0) {
		json_free(root);
		snprintf(err_msg, err_msg_size, "image rootfs does not exist");
		return 400;
	}

	/*
	 * An image with no C library cannot run anything, and used not to
	 * be possible: image creation copied the loader and libc straight
	 * off the build host into every image (ADR-0209's "glibc floor").
	 * It borrows nothing now -- a C library arrives as a package, the
	 * same way everything else does -- so an image nobody installed one
	 * into is a real, reachable state.
	 *
	 * Said plainly here rather than left to surface as the container
	 * exiting 127 with "execve failed", which describes the symptom and
	 * names nothing. Checked by looking for the loader itself, not for
	 * a package called glibc: the requirement is a working runtime, and
	 * whichever package provides it is the catalogue's business.
	 */
	{
		char loader[PATH_MAX];

		snprintf(loader, sizeof(loader), "%s/%s", lowerdir, PKG_IMAGE_LOADER_REL);
		if (stat(loader, &st) != 0) {
			/* Formatted BEFORE the tree is freed: `image` points into
			 * that JSON, so reading it afterwards prints whatever the
			 * allocator has since put there. Caught on a real box --
			 * the message named the image as a few bytes of garbage,
			 * which is exactly the sort of diagnostic this guard
			 * exists to avoid producing. */
			snprintf(err_msg, err_msg_size,
			         "image \"%s\" has no C library -- install a libc package (glibc) "
			         "into it before running a container from it",
			         image);
			json_free(root);
			return 400;
		}
	}

	if (registry_find(name) != NULL) {
		/*
		 * Message BEFORE the free, not after (#421). `name` is
		 * json_as_string(jname), pointing into root's own string
		 * storage -- the same use-after-free the create path's other
		 * 409 site documents at length and solves with name_copy.
		 * v2.57.122 put name_conflict_msg() after json_free(), so its
		 * registry_find() compared against freed heap, found nothing,
		 * and reported "already exists" for a container the daemon
		 * knew was tearing down.
		 *
		 * Measured on 192.168.15.95 in a build container, 2026-09-12
		 * (recipes/package/probe-delete-409/2): 92 of 100 racing
		 * delete+recreate rounds answered "a container with this name
		 * already exists" while GET on that same container reported
		 * "status":"deleting" -- one field, two answers, because only
		 * one of the two reads was looking at live memory.
		 */
		name_conflict_msg(name, err_msg, err_msg_size);
		json_free(root);
		return 409;
	}

	if (jnetworks != NULL) {
		net_count = (int)jnetworks->u.array.count;
		for (i = 0; i < (size_t)net_count; i++) {
			char n[NETWORK_NAME_MAX];
			uint32_t ip_be;
			int has_ip;

			/* Already validated above (name exists; a given ip is
			 * in-range and free) -- re-parsed only to recover the
			 * values, no new failure mode expected here. */
			parse_network_entry(jnetworks->u.array.items[i], n, sizeof(n), &ip_be, &has_ip,
			                     chosen_ifname, sizeof(chosen_ifname), chosen_bridge,
			                     sizeof(chosen_bridge));
			if (!has_ip) {
				int arc = network_alloc_ip(n, &ip_be);

				if (arc == -2) {
					/* Issue #137: a deliberate refusal, not an
					 * exhausted range -- so it is a 409 naming the two
					 * safe ways forward, never a bare 500. */
					json_free(root);
					snprintf(err_msg, err_msg_size,
					         "network \"%s\" is bridged to a physical interface and has no "
					         "declared allocation pool, so auto-allocating an address could "
					         "collide with equipment on that LAN. Either give this container "
					         "an explicit ip, or declare the pool this platform may use "
					         "(network create --alloc-start=/--alloc-end=).",
					         n);
					return 409;
				}
				if (arc != 0) {
					json_free(root);
					snprintf(err_msg, err_msg_size, "no free IP addresses");
					return 500;
				}
			}
			memset(&net_attachments[i], 0, sizeof(net_attachments[i]));
			strncpy(net_attachments[i].name, n, sizeof(net_attachments[i].name) - 1);
			net_attachments[i].ip_be = ip_be;
			/*
			 * ADR-0259: the operator's name when one was given, the
			 * positional default otherwise. Validated in the pass
			 * above, so nothing here can fail.
			 */
			snprintf(net_attachments[i].container_bridge,
			         sizeof(net_attachments[i].container_bridge), "%s", chosen_bridge);
			if (chosen_ifname[0] != '\0')
				snprintf(net_attachments[i].ifname, sizeof(net_attachments[i].ifname), "%s",
				         chosen_ifname);
			else
				snprintf(net_attachments[i].ifname, sizeof(net_attachments[i].ifname), "eth%d",
				         (int)i);
			/* veth_host stays empty -- only a live attachment (task #861)
			 * ever needs a standalone detach path; see its own comment
			 * in registry.h. */
		}
	}

	if (disk_name != NULL && disk_name[0] != '\0') {
		int drc = resolve_container_disk_root(disk_name, container_root, sizeof(container_root));

		if (drc != DISK_RESOLVE_OK) {
			json_free(root);
			snprintf(err_msg, err_msg_size, "%s",
			         drc == DISK_RESOLVE_NOT_FOUND
			             ? "no such disk"
			             : drc == DISK_RESOLVE_NOT_MOUNTED
			                   ? "disk is not mounted"
			                   : "disk has no container-storage role assigned");
			return 400;
		}
	} else {
		snprintf(container_root, sizeof(container_root), "%s", CONTAINERS_DIR);
	}

	snprintf(container_base, sizeof(container_base), "%s/%s", container_root, name);
	if (persist_mkdir_p(container_base) != 0) {
		json_free(root);
		snprintf(err_msg, err_msg_size, "failed to create container directory");
		return 500;
	}
	snprintf(upperdir, sizeof(upperdir), "%s/upper", container_base);
	snprintf(workdir, sizeof(workdir), "%s/work", container_base);
	snprintf(merged, sizeof(merged), "%s/merged", container_base);
	userns_rootfs[0] = '\0';
	stage_dir = upperdir;

	/*
	 * #266: spec is zeroed HERE, before the rootfs provisioning below
	 * touches it -- not further down where the rest of it is filled in.
	 *
	 * It used to be memset AFTER that block, which silently undid
	 * everything the block set: spec.userns_idmap was assigned while
	 * provisioning and then cleared before container_create() ever read
	 * it, so ADR-0207 phase 3's id-mapped presentation never reached the
	 * runtime. That is not cosmetic -- the same flag is what id-maps a
	 * userns container's VOLUMES, and without it every volume was owned
	 * by the overflow uid inside and rejected every write. Measured on a
	 * real container before the fix: /vol owned 65534:65534, `touch`
	 * denied, with jump's own /home among the casualties.
	 *
	 * The same block also READ spec.ov.quota_bytes, which at that point
	 * was uninitialised stack memory -- the real value is parsed much
	 * further down. So the btrfs qgroup call it guards fired, or did
	 * not, on garbage. disk_quota_bytes is therefore parsed here too,
	 * where the block can use the real number.
	 */
	memset(&spec, 0, sizeof(spec));
	jdisk_quota = json_object_get(root, "disk_quota_bytes");
	disk_quota_bytes = jdisk_quota != NULL ? (long long)json_as_number(jdisk_quota) : 0;

	/*
	 * ADR-0179 phase 2c option (a): a userns container does not use an
	 * overlay -- it gets its own per-container rootfs (a CoW copy of the
	 * image), which container_create() id-maps and pivots into directly.
	 * Create that copy here (host-side), the merged mountpoint the child
	 * pivots onto, and stage the container's own files straight into the
	 * rootfs instead of an overlay upperdir. The copy is made only on first
	 * create (reused on restart, so writes persist).
	 */
	if (userns) {
		struct stat rst;

		snprintf(userns_rootfs, sizeof(userns_rootfs), "%s/rootfs", container_base);
		/*
		 * ADR-0277: an existing rootfs is kept only while it still
		 * matches the image version this container is pinned to.
		 * When the pin has moved the tree is discarded and seeded
		 * again below -- that is what makes follow_rolling actually
		 * apply. Safe here because a userns container can always be
		 * re-seeded: the snapshot path and the copy+chown fallback
		 * are both below.
		 */
		if (stat(userns_rootfs, &rst) == 0 &&
		    rootfs_needs_reseed(name, container_base, resolved_image_version)) {
			if (cix_btrfs_subvol_delete_or_rmtree(userns_rootfs) != 0) {
				json_free(root);
				snprintf(err_msg, err_msg_size,
				         "could not discard the rootfs seeded from the previous image "
				         "version");
				return 500;
			}
		}
		if (stat(userns_rootfs, &rst) == 0) {
			/*
			 * Revival: the rootfs IS this container's state; which
			 * PRESENTATION it needs is read off the filesystem itself,
			 * the same one-source-of-truth marker the direct-rootfs
			 * mode uses. A snapshot-provisioned rootfs is owned by
			 * host uid 0 (never chowned -- the id-mapped mount does
			 * the presenting); a phase-2b copy is owned by its
			 * subordinate base. No side state to drift.
			 */
			spec.userns_idmap = (rst.st_uid == 0);
		} else if (cix_btrfs_is_backing(container_base) &&
		           cix_btrfs_snapshot_or_copy(lowerdir, userns_rootfs) == 0) {
			/*
			 * ADR-0207 phase 3: on btrfs a userns container's rootfs
			 * is the SAME O(1) writable snapshot a non-userns one
			 * gets -- host-uid-0 owned, extent-sharing fully
			 * preserved -- presented to the container through an
			 * id-mapped mount instead of a per-inode chown (which
			 * would rewrite every inode's metadata and cost the
			 * sharing). One storage model, two presentations.
			 */
			spec.userns_idmap = 1;
			rootfs_seed_version_write(container_base, resolved_image_version);
			if (disk_quota_bytes > 0) {
				if (cix_btrfs_qgroup_limit_excl(userns_rootfs,
				                                 (unsigned long long)disk_quota_bytes) !=
				    0) {
					json_free(root);
					snprintf(err_msg, err_msg_size,
					         "failed to set the btrfs qgroup quota on the userns rootfs");
					return 500;
				}
				/* Enforced right here, on the snapshot itself. The
				 * general quota block below must not also assign a
				 * project id or hand a limit to overlay_create(),
				 * which never runs for this container. */
				quota_enforced_early = 1;
			}
		} else {
			/*
			 * Non-btrfs (including the dev sandbox and unmigrated ext4
			 * hosts): the ADR-0179 phase-2b copy+chown presentation,
			 * proven live on real hardware, unchanged.
			 */
			const char *cp_argv[] = { "/usr/bin/cp", "--reflink=auto", "-a",
			                          lowerdir, userns_rootfs, NULL };
			long long base = 0;

			if (run_cmd(cp_argv) != 0) {
				json_free(root);
				snprintf(err_msg, err_msg_size,
				         "failed to copy image rootfs for userns container");
				return 500;
			}
			rootfs_seed_version_write(container_base, resolved_image_version);
			if (g_test_userns_idmap) {
				/* Leave the copy host-0-owned and id-map it: that is
				 * byte-for-byte the presentation a btrfs snapshot gets,
				 * the only difference being how the tree was made. */
				spec.userns_idmap = 1;
			} else if (subid_lookup_or_assign(name, &base) != 0 ||
			           chown_tree(userns_rootfs, (uid_t)base, (gid_t)base) != 0) {
				/* chown the whole copy to the container's subordinate base
				 * id so its mapped root owns it (subid_lookup_or_assign is
				 * idempotent -- the spec block below re-derives the same
				 * base). */
				json_free(root);
				snprintf(err_msg, err_msg_size,
				         "failed to chown userns rootfs to its subordinate id");
				return 500;
			}
		}
		if (persist_mkdir_p(merged) != 0) {
			json_free(root);
			snprintf(err_msg, err_msg_size, "failed to create userns pivot mountpoint");
			return 500;
		}
		stage_dir = userns_rootfs;
	} else {
		/*
		 * ADR-0207 phase 2: the non-userns twin of the branch above --
		 * decide the storage mode HERE, before file staging, because
		 * files[] (and every synthetic file: nsswitch, nslcd, dhcp)
		 * are staged into stage_dir next, and a direct-mode container
		 * reads its files from its rootfs, not from an overlay
		 * upperdir it will never mount. The on-disk presence of
		 * <base>/rootfs is the mode marker: a revived container whose
		 * rootfs exists keeps it, PROVIDED it was seeded from the image
		 * version this container is still pinned to -- ADR-0277, which
		 * amended this rule after the unconditional form made
		 * follow_rolling inert (see rootfs_needs_reseed()). When the
		 * pin has moved the tree is discarded and seeded again, so the
		 * writes it carried are lost by design: a container's rootfs
		 * is derived from its image, and anything that must outlive an
		 * image version belongs on a volume. A fresh create on btrfs
		 * snapshots the image's subvolume (O(1), copy-on-write);
		 * anything else stays on the classic overlay path until phase 4. A failed snapshot (e.g. image store and
		 * container storage on different filesystems, which
		 * SNAP_CREATE_V2 cannot cross) falls back to overlay LOUDLY --
		 * the overlay-on-btrfs upperdir path (ADR-0103) is still fully
		 * functional, so the fallback is honest, not hidden.
		 */
		struct stat rst;
		/*
		 * ADR-0277: discard a rootfs whose image version has moved,
		 * so the seeding below runs again against the new one. Guarded
		 * by can_seed because, unlike the userns branch, this one has
		 * no copy fallback: discarding a tree we could not then
		 * replace would drop the container onto the overlay path with
		 * an empty upperdir, which is worse than the staleness.
		 */
		int can_seed = (g_test_direct_rootfs || cix_btrfs_is_backing(container_base));

		snprintf(direct_rootfs_dir, sizeof(direct_rootfs_dir), "%s/rootfs", container_base);
		if (can_seed && stat(direct_rootfs_dir, &rst) == 0 && S_ISDIR(rst.st_mode) &&
		    rootfs_needs_reseed(name, container_base, resolved_image_version) &&
		    cix_btrfs_subvol_delete_or_rmtree(direct_rootfs_dir) != 0) {
			json_free(root);
			snprintf(err_msg, err_msg_size,
			         "could not discard the rootfs seeded from the previous image version");
			return 500;
		}
		if (stat(direct_rootfs_dir, &rst) == 0 && S_ISDIR(rst.st_mode)) {
			direct_mode = 1;
		} else if (can_seed) {
			if (cix_btrfs_snapshot_or_copy(lowerdir, direct_rootfs_dir) == 0) {
				direct_mode = 1;
				rootfs_seed_version_write(container_base, resolved_image_version);
			} else {
				logstore_write("cixd", "warn",
				                "container %s: could not snapshot the image rootfs (%s) -- "
				                "falling back to the overlay path",
				                name, strerror(errno));
			}
		}
		if (direct_mode) {
			snprintf(merged, sizeof(merged), "%s", direct_rootfs_dir);
			stage_dir = direct_rootfs_dir;
		}
	}

	/*
	 * Written directly into the container's own upperdir, entirely on
	 * this (daemon/host) process, before registry_create()/clone3() is
	 * ever called -- overlay_create() (child-side, post-clone3())
	 * mkdir()s upperdir EEXIST-tolerant and mounts it unchanged, so
	 * these files are simply already there the moment the container's
	 * own process execve()s, unlike a post-hoc write into an already-
	 * running container's filesystem (ADR-0013's /proc/<pid>/root/
	 * pattern), which needs a live pid this early creation path doesn't
	 * have yet. Already fully validated above (path safety, content/
	 * mode bounds) -- this pass only does I/O.
	 */
	/*
	 * #265: a staged file is owned by whoever owns the rootfs it is
	 * staged into.
	 *
	 * Read off the tree itself rather than reasoned about, because the
	 * id depends on how this container's rootfs is PRESENTED and there
	 * are three presentations that disagree: a non-userns upperdir and
	 * a btrfs snapshot behind an id-mapped mount are both host-uid-0
	 * owned, while the ADR-0179 phase-2b copy has been chown_tree()d to
	 * the container's subordinate base -- which is exactly what makes /
	 * and /etc read as 0 inside it. A file staged as on-disk 0 into that
	 * last one falls outside the container's mapped range and reads as
	 * 65534, unreadable by the container's own root at mode 0600.
	 *
	 * Deliberately NOT branched on spec.userns_idmap, which was the
	 * first attempt and does not work: that field is assigned while the
	 * rootfs is provisioned and then cleared by the memset(&spec) below,
	 * so it is always 0 by the time anything reads it (#266). The rootfs
	 * owner is the same fact without the ordering hazard -- it is the
	 * one-source-of-truth marker the revival path above already reads
	 * for precisely this reason.
	 */
	{
		struct stat rootfs_st;

		if (stat(stage_dir, &rootfs_st) == 0)
			stage_id_offset = rootfs_st.st_uid;
	}

	if (jfiles != NULL) {
		/*
		 * #419: if this container declares itself an LDAP server, the
		 * managed listener values are applied to its config's staged
		 * TEXT, here, before clone3(). Not afterwards: glauth binds
		 * its listeners at startup and its config watcher reloads only
		 * the record datastore, so a listener written into a live
		 * config is never adopted -- and every path that brings a
		 * container up replays this same body, so a restart would
		 * otherwise re-stage the recipe's own value over the managed
		 * one and glauth would read that. Measured on 192.168.15.95,
		 * v2.57.114, before this existed: both live configs read
		 * `[ldap] enabled = true` while 3893 stayed refused, and a
		 * real stop/start of ldap-1 did not change it.
		 *
		 * Same ordering fix pki_cert_deliver() needed in #414, for the
		 * same reason: a service reads its identity once, at startup.
		 */
		const struct json_value *jldapsrv = json_object_get(root, "ldap_server");
		const char *ldap_cfg_path =
		    (jldapsrv != NULL && jldapsrv->type == JSON_OBJECT) ?
		        json_as_string(json_object_get(jldapsrv, "config_path")) :
		        NULL;

		for (i = 0; i < jfiles->u.array.count; i++) {
			const struct json_value *item = jfiles->u.array.items[i];
			const char *path = json_as_string(json_object_get(item, "path"));
			const char *content = json_as_string(json_object_get(item, "content"));
			const char *mode_str = json_as_string(json_object_get(item, "mode"));
			const struct json_value *jowner = json_object_get(item, "owner");
			const struct json_value *jgroup = json_object_get(item, "group");
			long mode = mode_str != NULL ? strtol(mode_str, NULL, 8) : 0644;
			uid_t owner = jowner != NULL ? (uid_t)json_as_number(jowner) : (uid_t)-1;
			gid_t group = jgroup != NULL ? (gid_t)json_as_number(jgroup) : (gid_t)-1;
			char *rendered = NULL;
			size_t rendered_len = 0;
			int staged;

			if (ldap_cfg_path != NULL && path != NULL && content != NULL &&
			    strcmp(path, ldap_cfg_path) == 0 &&
			    ldap_render_listeners(content, strlen(content), &rendered, &rendered_len) ==
			        1) {
				/* stage_container_file() takes a NUL-terminated
				 * string; the render returns a length, so terminate a
				 * copy rather than assuming. */
				char *z = malloc(rendered_len + 1);

				if (z == NULL) {
					free(rendered);
					json_free(root);
					snprintf(err_msg, err_msg_size, "failed to stage files");
					return 500;
				}
				memcpy(z, rendered, rendered_len);
				z[rendered_len] = '\0';
				free(rendered);
				staged = stage_container_file(stage_dir, path, z, (mode_t)mode, owner, group,
				                               stage_id_offset);
				free(z);
			} else {
				free(rendered);
				staged = stage_container_file(stage_dir, path, content, (mode_t)mode, owner,
				                               group, stage_id_offset);
			}
			if (staged != 0) {
				json_free(root);
				snprintf(err_msg, err_msg_size, "failed to stage files");
				return 500;
			}
			snprintf(file_paths[i], sizeof(file_paths[i]), "%s", path);
		}
		file_count = (int)jfiles->u.array.count;
	}
	if (ldap_client) {
		/* Rendered from the daemon's own LDAP client config (validated
		 * present above). nslcd.conf holds the bind credential -> 0600.
		 * nsswitch.conf is the standard "files then ldap" resolution
		 * order. `pam_authc_ppolicy no` matches this project's own
		 * glauth deployment (jump's own working recipe), which doesn't
		 * implement the ppolicy control nslcd probes for by default. */
		const struct ldap_config *lc;
		char nslcd[1024];
		char effective_uri[600];

		/*
		 * Issue #80: make sure the nslcd service/bind account this
		 * container is about to be handed actually exists, before we
		 * render its bind_dn/bind_password. Idempotent -- a no-op once
		 * provisioned, or if the operator configured a custom bind. This
		 * is the right moment: a client container is being created, so
		 * the registered glauth servers are up to receive the account.
		 */
		ldap_ensure_service_bind_account();
		lc = ldap_config_get();

		ldap_effective_client_uri(effective_uri, sizeof(effective_uri));

		if (stage_container_file(stage_dir, "/etc/nsswitch.conf",
		                          "passwd:         files ldap\n"
		                          "group:          files ldap\n"
		                          "shadow:         files ldap\n",
		                          0644, (uid_t)-1, (gid_t)-1, stage_id_offset) != 0) {
			json_free(root);
			snprintf(err_msg, err_msg_size, "failed to stage ldap_client nsswitch.conf");
			return 500;
		}
		snprintf(file_paths[file_count], sizeof(file_paths[file_count]), "%s",
		         "/etc/nsswitch.conf");
		file_count++;

		{
			/*
			 * Issue #76: host-scoped authorisation.
			 *
			 * Without ldap_allow_groups this file carries no
			 * pam_authz_search at all and any valid account in the
			 * directory may log in -- what an ldap_client container has
			 * always done. With it, nslcd runs the search below after
			 * authenticating and refuses the login if it matches
			 * nothing, so "which users" is enforced by the same daemon
			 * that resolves them rather than by anything of ours that
			 * has to still be running.
			 *
			 * Group membership is the mechanism, and it is what this
			 * directory actually supports: verified live against the
			 * deployed glauth that a user entry carries memberOf DNs of
			 * the form "ou=<group>,ou=groups,<base>" for BOTH its
			 * primary and its secondary groups, that filtering on them
			 * matches a member and returns nothing for a non-member.
			 * (The `host` attribute this issue originally suggested
			 * would need custom-attribute support this glauth's config
			 * backend does not expose; groups are a first-class concept
			 * here already, and a user can be in many, which is exactly
			 * what "may log into several hosts" needs.)
			 */
			char authz[512] = "";

			if (jallow_groups != NULL && jallow_groups->type == JSON_ARRAY &&
			    jallow_groups->u.array.count > 0) {
				size_t gi;
				size_t off = 0;

				off += (size_t)snprintf(authz + off, sizeof(authz) - off,
				                         "pam_authz_search "
				                         "(&(objectClass=posixAccount)(uid=$username)(|");
				for (gi = 0; gi < jallow_groups->u.array.count; gi++) {
					const char *g = json_as_string(jallow_groups->u.array.items[gi]);

					/*
					 * Refused, never escaped: this string is written
					 * into a file nslcd parses as an LDAP filter, and a
					 * group name is already constrained to a safe set
					 * elsewhere in this daemon -- anything outside it is
					 * a mistake worth reporting, not something to encode
					 * around.
					 */
					if (g == NULL || !simple_name_is_valid(g, LDAP_GROUP_NAME_MAX)) {
						json_free(root);
						snprintf(err_msg, err_msg_size,
						         "ldap_allow_groups entries must be plain group names");
						return 400;
					}
					if (ldap_group_find(g) == NULL) {
						/*
						 * The message is built BEFORE the tree is freed:
						 * g points into it.
						 */
						snprintf(err_msg, err_msg_size,
						         "ldap_allow_groups names group \"%s\", which does not exist -- "
						         "create it first, so a typo cannot silently lock everyone out",
						         g);
						json_free(root);
						return 400;
					}
					off += (size_t)snprintf(authz + off, sizeof(authz) - off,
					                         "(memberOf=ou=%s,ou=groups,%s)", g, lc->base_dn);
					if (off >= sizeof(authz)) {
						json_free(root);
						snprintf(err_msg, err_msg_size, "too many ldap_allow_groups entries");
						return 400;
					}
				}
				snprintf(authz + off, sizeof(authz) - off, "))\n");
			}

			/*
			 * #414: with TLS on, nslcd needs a trust anchor. It
			 * already runs tls_reqcert demand (nslcd's own default,
			 * visible in its debug output), so without a CA file it
			 * refuses every connection rather than falling back --
			 * the safe failure, and an opaque one.
			 *
			 * The path is the bundle pkg_seed_image_baseline()
			 * stages into every image (ADR-0051), not something this
			 * container has to carry: it is already there, in every
			 * image, before any of this runs. Emitted only when TLS
			 * is on, so a plaintext deployment's nslcd.conf is
			 * byte-identical to what it was.
			 */
			snprintf(nslcd, sizeof(nslcd),
			         "uri %s\nbase %s\nbinddn %s\nbindpw %s\npam_authc_ppolicy no\n%s%s",
			         effective_uri, lc->base_dn, lc->bind_dn, lc->bind_password,
			         lc->client_tls ? "tls_cacertfile " PKG_IMAGE_CA_BUNDLE_PATH "\n" : "",
			         authz);
		}
		if (stage_container_file(stage_dir, "/etc/nslcd.conf", nslcd, 0600, (uid_t)-1,
		                          (gid_t)-1, stage_id_offset) != 0) {
			json_free(root);
			snprintf(err_msg, err_msg_size, "failed to stage ldap_client nslcd.conf");
			return 500;
		}
		snprintf(file_paths[file_count], sizeof(file_paths[file_count]), "%s", "/etc/nslcd.conf");
		file_count++;
	}
	/*
	 * ADR-0197: a container that is already a registered DNS server is
	 * also a DHCP server, so it gets its own rendered DHCP files staged
	 * HERE, before its process starts.
	 *
	 * That timing is the whole point, and it was found the hard way on
	 * the real box: dnsmasq reads its conf file only at startup, and a
	 * restart re-stages the container's own creation-time files[] --
	 * so a conf written into the running container was overwritten by
	 * the empty placeholder on the very next restart, and the range
	 * silently never took effect. Staging it as part of creation means
	 * the file dnsmasq opens is the rendered one, every time.
	 *
	 * Staged after the caller's own files[] deliberately, so the
	 * rendered content wins over the placeholder an operator staged to
	 * let dnsmasq start the first time.
	 */
	if (dhcp_server_is_registered(name)) {
		char conf[4096];
		char hosts[8192];

		if (dhcp_render_conf(name, conf, sizeof(conf)) >= 0 &&
		    dhcp_render_hosts(hosts, sizeof(hosts)) >= 0) {
			if (stage_container_file(stage_dir, DHCP_CONF_PATH, conf, 0644, (uid_t)-1,
			                          (gid_t)-1, stage_id_offset) == 0 &&
			    file_count < CONTAINER_MAX_FILES) {
				snprintf(file_paths[file_count], sizeof(file_paths[file_count]), "%s",
				         DHCP_CONF_PATH);
				file_count++;
			}
			if (stage_container_file(stage_dir, DHCP_HOSTS_PATH, hosts, 0644, (uid_t)-1,
			                          (gid_t)-1, stage_id_offset) == 0 &&
			    file_count < CONTAINER_MAX_FILES) {
				snprintf(file_paths[file_count], sizeof(file_paths[file_count]), "%s",
				         DHCP_HOSTS_PATH);
				file_count++;
			}
		}
	}
	if (dns_server_count > 0) {
		char content[RESOLV_MAX_NAMESERVERS * (RESOLV_IP_STRLEN + 16)];
		size_t content_len = 0;

		content[0] = '\0';
		for (i = 0; i < (size_t)dns_server_count; i++)
			content_len += (size_t)snprintf(content + content_len, sizeof(content) - content_len,
			                                 "nameserver %s\n", dns_server_ips[i]);

		if (stage_container_file(stage_dir, "/etc/resolv.conf", content, 0644, (uid_t)-1,
		                          (gid_t)-1, stage_id_offset) != 0) {
			json_free(root);
			snprintf(err_msg, err_msg_size, "failed to stage dns_servers");
			return 500;
		}
	}

	/*
	 * The container's TLS identity, staged before clone3() rather than
	 * pushed in after the container is already running (#414).
	 *
	 * It used to be delivered from the post-pidfd block below, which
	 * created a startup race the daemon then expected every image to
	 * work around: the container's own services start while
	 * pki_cert_create() is still running three openssl subprocesses, so
	 * a service that reads its key at startup can find nothing there.
	 * jump papered over that with a `waitkey` oneshot spinning on the
	 * file, and ldap-1/ldap-2 could not: the ldap image is glibc plus
	 * glauth with no shell in it at all, so there was nothing to spin
	 * with. `execve(/usr/bin/bash) failed, errno 2`, measured on
	 * 192.168.15.95 on 2026-09-12.
	 *
	 * The race did not need to exist. pki_cert_deliver() stopped using
	 * a pid at #269, when it moved to writing through the container's
	 * host-side tree -- from then on the parameter was vestigial and
	 * nothing about delivery actually required a running container. So
	 * the cert is now staged exactly like every other file the daemon
	 * writes for a container, and is simply already there when the
	 * container's first process execve()s.
	 *
	 * Deliberately AFTER the files[] loop above: a daemon-delivered
	 * cert wins over a body-declared file at the same path, which is
	 * what the post-pidfd write did by being last, and silently
	 * reversing that would be a regression.
	 */
	if (pki_issue || pki_cert_buf[0] != '\0') {
		const char *cert_name = pki_cert_buf[0] != '\0' ? pki_cert_buf : name;
		char *key_pem = NULL, *chain_pem = NULL;
		enum pki_error perr = PKI_OK;
		int created_here = 0;

		if (pki_issue) {
			const char *pki_sans[PKI_MAX_SANS];
			char pki_san_ips[PKI_MAX_SANS][INET_ADDRSTRLEN];
			int pki_san_count = 0;
			int ni;
			struct json_writer scratch;

			/*
			 * The container's own name, plus every address it is
			 * actually reachable at (#414). A TLS client verifies the
			 * name it DIALLED, and this platform hands LDAP clients
			 * the registered servers' live IPs
			 * (ldap_effective_client_uri()), so a cert carrying only
			 * the container name cannot verify however correct it
			 * looks.
			 *
			 * From net_attachments[], which is populated well before
			 * this point -- spec.nets[] is not filled in until after
			 * clone3() is prepared, further down. Read from the
			 * container's own declared networks rather than left for
			 * an operator to type into a POST /v1/pki/certs call: the
			 * address is declared once, and a second hand-written copy
			 * is what drifts the first time a container moves.
			 *
			 * Known limit, recorded rather than solved: a container
			 * whose address later changes hits PKI_ERR_DUPLICATE and
			 * keeps the cert it has, stale IP SAN included. Deleting
			 * the cert (or the container) reissues it.
			 */
			pki_sans[pki_san_count++] = name;
			for (ni = 0; ni < net_count && pki_san_count < PKI_MAX_SANS; ni++) {
				struct in_addr a4;

				if (net_attachments[ni].ip_be == 0)
					continue;
				a4.s_addr = net_attachments[ni].ip_be;
				if (inet_ntop(AF_INET, &a4, pki_san_ips[pki_san_count],
				              sizeof(pki_san_ips[pki_san_count])) == NULL)
					continue;
				pki_sans[pki_san_count] = pki_san_ips[pki_san_count];
				pki_san_count++;
			}
			jw_init(&scratch);
			perr = pki_cert_create(name, pki_sans, pki_san_count, pki_days, name, &scratch);
			jw_free(&scratch);

			/* DUPLICATE means a cert for this name already exists --
			 * expected on every restart-always respawn after the first,
			 * and on any recreate of a same-named container. Harmless:
			 * the existing one is what gets staged. Any other error has
			 * no cert to fall back on. */
			if (perr == PKI_OK)
				created_here = 1;
			else if (perr != PKI_ERR_DUPLICATE)
				logstore_write("pki", "err",
				               "%s: pki_issue requested but cert issuance failed (err=%d)",
				               name, (int)perr);
		}

		if (perr == PKI_OK || perr == PKI_ERR_DUPLICATE) {
			enum pki_error rerr = pki_cert_read_pem(cert_name, &key_pem, &chain_pem);

			if (rerr != PKI_OK) {
				logstore_write("pki", "err",
				               "%s: could not read certificate \"%s\" to stage it (err=%d)",
				               name, cert_name, (int)rerr);
			} else {
				char crt_path[PATH_MAX], key_path[PATH_MAX];
				int staged;

				snprintf(crt_path, sizeof(crt_path), "%s/tls.crt", pki_cert_dir_buf);
				snprintf(key_path, sizeof(key_path), "%s/tls.key", pki_cert_dir_buf);
				staged = stage_container_file(stage_dir, crt_path, chain_pem, 0644,
				                               (uid_t)-1, (gid_t)-1, stage_id_offset) == 0 &&
				          stage_container_file(stage_dir, key_path, key_pem, 0600,
				                               (uid_t)-1, (gid_t)-1, stage_id_offset) == 0;
				free(key_pem);
				free(chain_pem);
				if (!staged) {
					/*
					 * A container that asked for a TLS identity and did
					 * not get one is not a container that should start:
					 * whatever it runs would either fail opaquely or,
					 * worse, serve without the identity it was told it
					 * had. Fail the create, and drop a cert this call
					 * issued so a retry is not met with DUPLICATE --
					 * only one this call issued, since shredding a
					 * pre-existing cert here would destroy the very
					 * identity pki_cert exists to keep (#397).
					 */
					if (created_here)
						pki_cert_delete(cert_name);
					json_free(root);
					snprintf(err_msg, err_msg_size,
					         "failed to stage the TLS certificate into %s",
					         pki_cert_dir_buf);
					return 500;
				}
			}
		}
	}

	/*
	 * ADR-0274: /etc/os-release, staged into every container at
	 * creation and re-staged on every restart, from the DAEMON's own
	 * build version.
	 *
	 * pkg_seed_image_baseline() also writes this, and that copy is not
	 * enough on its own for two reasons found by deploying it.
	 *
	 * It only lands when an image produces a NEW VERSION. Every image
	 * that already existed when os-release shipped therefore has none,
	 * and gets none until something changes its package manifest --
	 * and by ADR-0155 reinstalling a package at the same version
	 * reproduces the same manifest hash, dedups, and throws the
	 * re-seeded tree away. Measured on the box: `jump` answered
	 * `{"error":"no such file"}` after a host running the feature had
	 * been deployed and rebooted.
	 *
	 * And BUILD_ID would freeze. An image seeded once carries that
	 * build's version for the rest of its life, so a host upgrading
	 * past it would disagree with its own containers about what they
	 * are -- the exact drift ADR-0274 exists to prevent, reintroduced
	 * by the mechanism meant to prevent it.
	 *
	 * A container is the right owner because BUILD_ID is a fact about
	 * the HOST the container is running on, and that is knowable only
	 * here. Same reasoning that made /etc/passwd container-instance
	 * content rather than image baseline.
	 *
	 * Deliberately NOT recorded in file_paths[]. That array is the
	 * caller's own files[] -- it is echoed back in the create response
	 * and replayed on restart -- and putting a platform file in it
	 * would be wrong twice. It would change what every create response
	 * reports for every container (test_container_files asserts the
	 * echo is exactly what was sent, and caught this). And replay
	 * re-stages PERSISTED content, so an entry here would pin the
	 * BUILD_ID captured at creation rather than refresh it: the
	 * mechanism that looks like it keeps the file current is the one
	 * that would freeze it.
	 *
	 * So this writes the file and stops -- and that is enough, because
	 * this block is on the START path, not just the create path. A
	 * restart replays the stored definition through here, so the file
	 * is re-rendered from the RUNNING daemon's CIX_BUILD_VERSION every
	 * time the container comes up, over whatever rootfs it already has.
	 *
	 * This paragraph used to claim the opposite -- that a container
	 * reports the build it was created under and goes stale if the host
	 * upgrades beneath it (#393) -- while the top of this same comment
	 * said "re-staged on every restart". One comment, two contradictory
	 * claims, and the pessimistic one was the one that got filed as an
	 * issue. Measured on 192.168.15.95: `jump` was created under
	 * v2.57.61, the host was upgraded to v2.57.63 and rebooted, the
	 * container's rootfs was ADOPTED rather than rebuilt (ADR-0277
	 * logs it by name), and its /etc/os-release then read
	 * BUILD_ID="v2.57.63". The re-render survives a reused rootfs,
	 * which is the whole question.
	 */
	{
		char osr[OSRELEASE_MAX];

		if (osrelease_render(osr, sizeof(osr), CIX_BUILD_VERSION) == 0)
			(void)stage_container_file(stage_dir, "/etc/os-release", osr, 0644, (uid_t)-1,
			                            (gid_t)-1, stage_id_offset);
	}

	/* spec was zeroed before the rootfs provisioning above, which sets
	 * fields on it -- zeroing it again here is what broke #266. */
	{
		/* fd sentinels: 0 is a valid fd, so "no idmapped volume tree"
		 * must be -1, not the memset's zero (ADR-0207 phase 3). */
		int vfi;

		for (vfi = 0; vfi < CONTAINER_MAX_VOLUMES; vfi++)
			spec.volume_idmap_fds[vfi] = -1;
	}
	spec.ns.clone_flags = CLONE_NEWPID | CLONE_NEWNS | CLONE_NEWUTS | CLONE_NEWNET |
	                       CLONE_NEWCGROUP | CLONE_INTO_CGROUP;
	/*
	 * Issue #88: persistent volumes. Resolved here, at create time, from
	 * names to real host paths -- the container runtime is handed paths,
	 * never names, so it never needs to know the volume registry exists.
	 * A named volume that does not exist is a hard 400 rather than an
	 * implicit create: a typo silently producing a brand-new empty
	 * volume is precisely how someone loses data and then concludes
	 * persistence "didn't work".
	 *
	 * Placed deliberately AFTER spec's own memset below -- populating
	 * it any earlier is silently undone, which is exactly what happened
	 * on the first attempt (the container came up with no /home at all
	 * and no error, because volume_count had been zeroed back to 0).
	 */
	{
		const struct json_value *jvolumes = json_object_get(root, "volumes");

		if (jvolumes != NULL && jvolumes->type == JSON_ARRAY) {
			size_t vi;

			if (jvolumes->u.array.count > CONTAINER_MAX_VOLUMES) {
				json_free(root);
				snprintf(err_msg, err_msg_size, "too many volumes (max %d)",
				         CONTAINER_MAX_VOLUMES);
				return 400;
			}
			for (vi = 0; vi < jvolumes->u.array.count; vi++) {
				const struct json_value *item = jvolumes->u.array.items[vi];
				const char *vname = json_as_string(json_object_get(item, "name"));
				const char *vpath = json_as_string(json_object_get(item, "path"));
				const struct json_value *jro = json_object_get(item, "read_only");
				struct volume *vol;
				char hostpath[PATH_MAX];

				if (vname == NULL || vpath == NULL || vpath[0] != '/' ||
				    !file_path_is_safe(vpath)) {
					json_free(root);
					snprintf(err_msg, err_msg_size,
					         "each volume needs a name and an absolute path with no '..'");
					return 400;
				}
				vol = volume_find(vname);
				if (vol == NULL) {
					/* Formatted before the free: vname points into the
					 * JSON tree, so naming it afterwards prints
					 * whatever the allocator has since put there.
					 * Same defect as the C-library guard above, found
					 * by looking for the pattern once that one had
					 * been seen printing garbage on a real box. */
					snprintf(err_msg, err_msg_size, "no such volume: %s", vname);
					json_free(root);
					return 400;
				}
				if (volume_host_path(vol, hostpath, sizeof(hostpath)) != 0) {
					snprintf(err_msg, err_msg_size, "could not resolve volume %s", vname);
					json_free(root);
					return 500;
				}
				snprintf(spec.volumes[spec.volume_count].host_path,
				         sizeof(spec.volumes[spec.volume_count].host_path), "%s", hostpath);
				snprintf(spec.volumes[spec.volume_count].mount_path,
				         sizeof(spec.volumes[spec.volume_count].mount_path), "%s", vpath);
				spec.volumes[spec.volume_count].read_only =
				    (jro != NULL && jro->type == JSON_BOOL && jro->u.boolean);
				spec.volume_count++;
			}
		}
	}

	/*
	 * ADR-0179 (issue #29) phase 2 opt-in: "userns":true gives this
	 * container its own user namespace, its root mapped onto a dedicated
	 * host subordinate-ID range. Keyed on the container name for now (the
	 * ADR's own host-auth-off fallback key) -- preferring the caller's
	 * resolved uidnumber is a later refinement; both share the same
	 * allocator. Opt-in during verification specifically so the platform's
	 * existing running containers are untouched until this path is proven
	 * on real hardware, after which the ADR flips it to default-on.
	 */
	if (userns) {
		long long base;

		if (subid_lookup_or_assign(name, &base) != 0) {
			json_free(root);
			snprintf(err_msg, err_msg_size, "failed to allocate a userns subordinate-ID range");
			return 500;
		}
		spec.ns.clone_flags |= CLONE_NEWUSER;
		spec.userns_enabled = 1;
		spec.userns_uid_base = base;
		spec.userns_gid_base = base;
		spec.userns_len = SUBID_RANGE_LEN;
	}
	spec.ns.hostname = name;
	/* Issue #86: leaves live under the workload parent, so their
	 * COLLECTIVE demand is bounded and the control plane keeps a real
	 * reservation rather than whatever happens to be left over. */
	workload_cgroup_path(name, container_cgroup_path, sizeof(container_cgroup_path));
	spec.cg.name = container_cgroup_path;
	jmem = json_object_get(root, "memory_max");
	spec.cg.memory_max = jmem != NULL ? (long long)json_as_number(jmem) : 0;
	jswapmax = json_object_get(root, "memory_swap_max");
	/*
	 * Issue #52: absent is -1 (leave the kernel's own "max" alone), not
	 * 0 -- 0 is the operator asking for a container that may not swap
	 * at all, and the two must not collapse into one another.
	 */
	spec.cg.memory_swap_max = jswapmax != NULL ? (long long)json_as_number(jswapmax) : -1;
	if (jswapmax != NULL && spec.cg.memory_swap_max < 0) {
		json_free(root);
		snprintf(err_msg, err_msg_size,
		         "memory_swap_max must be a non-negative byte count -- 0 means this container "
		         "may not swap at all; omit the field to leave swap unlimited");
		return 400;
	}
	jpids = json_object_get(root, "pids_max");
	spec.cg.pids_max = jpids != NULL ? (long long)json_as_number(jpids) : 0;
	jcpu = json_object_get(root, "cpu_max");
	spec.cg.cpu_max = json_as_string(jcpu);
	jcpuset = json_object_get(root, "cpuset_cpus");
	spec.cg.cpuset_cpus = json_as_string(jcpuset);
	/* Parsed above, before the rootfs provisioning that needs it (#266). */
	if (disk_quota_bytes > 0 && !quota_enforced_early) {
		/*
		 * btrfs has no quotactl(2) project-quota support at all
		 * (ADR-0103) -- overlay_create() enforces the limit itself
		 * there, via a qgroup set on the upperdir subvolume it
		 * creates, so there is no project id to assign and no
		 * quotactl(2) call to make up front here. ext4 (and any other
		 * quotactl-capable filesystem) keeps the existing Part 4/
		 * ADR-0062 flow completely unchanged.
		 */
		if (overlay_backing_is_btrfs(container_base)) {
			spec.ov.quota_bytes = disk_quota_bytes;
		} else {
			uint32_t projid;

			if (quotamap_get_or_assign(name, &projid) != 0) {
				json_free(root);
				snprintf(err_msg, err_msg_size, "failed to assign a disk-quota project id");
				return 500;
			}
			/*
			 * Set before the container (and its overlay_create()'s own
			 * FS_IOC_FSSETXATTR tagging) is created -- order-agnostic per
			 * this call's own comment, but doing it first means the limit
			 * is already in force by the moment any file could possibly
			 * be tagged with this project id.
			 */
			if (quotamap_apply(container_base, projid, disk_quota_bytes) != 0) {
				json_free(root);
				snprintf(err_msg, err_msg_size,
				         "failed to set disk quota (backing filesystem may not have "
				         "project-quota support enabled)");
				return 500;
			}
			spec.ov.project_id = projid;
		}
	}
	if (direct_mode) {
		spec.ov.direct_rootfs = 1;
		if (spec.ov.quota_bytes > 0) {
			/*
			 * EXCLUSIVE bytes, not referenced (ADR-0207): a snapshot
			 * references the whole image from the first instant, and
			 * the quota owed here is "your own divergence" -- exactly
			 * what the overlay upperdir quota meant. See btrfs.h.
			 */
			if (cix_btrfs_qgroup_limit_excl(direct_rootfs_dir,
			                                 (unsigned long long)spec.ov.quota_bytes) != 0) {
				json_free(root);
				snprintf(err_msg, err_msg_size,
				         "failed to set the btrfs qgroup quota on the container rootfs");
				return 500;
			}
			spec.ov.quota_bytes = 0; /* enforced here; overlay_create will not run */
		}
	}
	spec.ov.lowerdir = lowerdir;
	spec.ov.upperdir = upperdir;
	spec.ov.workdir = workdir;
	spec.ov.merged = merged;
	spec.ov.userns_rootfs = userns ? userns_rootfs : NULL;
	spec.mnt.put_old_rel = ".old_root";
	/*
	 * ADR-0262/#336. Default ON: a virtualised /proc a recipe has to
	 * remember to ask for is useless, because nobody knows they need it
	 * until something has already sized itself wrong -- which is
	 * #278/#279 exactly. `procfuse: false` on the create declines it.
	 *
	 * procfuse_mount_path() is NULL when the server is not running (no
	 * /dev/fuse, a kernel without FUSE, a refused mount), and that
	 * silently means "bind nothing" rather than failing the create: a
	 * container reading the host's real /proc is what every container
	 * did before this existed.
	 */
	if (!no_procfuse) {
		static const struct procfuse_file procfuse_names[] = PROCFUSE_FILES;

		spec.mnt.procfuse_dir = procfuse_mount_path();
		spec.mnt.procfuse_files = procfuse_names;
		spec.mnt.procfuse_file_count = PROCFUSE_FILE_COUNT;
		/*
		 * Logged, because the first attempt at this bound nothing and
		 * there was no way to tell which half had failed. The bind
		 * itself happens in the container child, whose perror() goes
		 * to stderr -- and stderr is never mirrored into the log store
		 * (CLAUDE.md records this exactly), so a NON-FATAL failure
		 * there is invisible. This line at least says whether the
		 * daemon had a path to offer, which splits that question in
		 * two.
		 */
		logstore_write("cixd", "info", "container %s: procfuse dir=%s", name,
		                spec.mnt.procfuse_dir != NULL ? spec.mnt.procfuse_dir : "(server not running)");
	}
	spec.net_count = net_count;
	for (i = 0; i < (size_t)net_count; i++) {
		struct network_def *net = network_find(net_attachments[i].name);

		spec.nets[i].bridge = net->name;
		spec.nets[i].container_ip_be = net_attachments[i].ip_be;
		spec.nets[i].has_address = net->has_address;
		spec.nets[i].address_ip_be = net->address_be;
		spec.nets[i].prefix_len = net->prefix_len;
		snprintf(spec.nets[i].ifname, sizeof(spec.nets[i].ifname), "%s",
		         net_attachments[i].ifname);
		snprintf(spec.nets[i].container_bridge, sizeof(spec.nets[i].container_bridge), "%s",
		         net_attachments[i].container_bridge);
	}
	spec.ip_forward = ip_forward;
	spec.ksm = ksm;
	spec.sysctl_count = sysctl_count;
	for (i = 0; i < (size_t)sysctl_count; i++)
		spec.sysctls[i] = sysctl_specs[i];
	spec.route_count = route_count;
	for (i = 0; i < (size_t)route_count; i++)
		spec.routes[i] = route_specs[i];
	spec.device_count = device_count;
	for (i = 0; i < (size_t)device_count; i++)
		spec.devices[i] = device_specs[i];
	spec.interface_count = interface_count;
	for (i = 0; i < (size_t)interface_count; i++)
		snprintf(spec.interfaces[i], sizeof(spec.interfaces[i]), "%s", interface_names[i]);
	spec.cap_add_count = cap_add_count;
	for (i = 0; i < (size_t)cap_add_count; i++)
		snprintf(spec.cap_add[i], sizeof(spec.cap_add[i]), "%s", cap_add_names[i]);
	spec.envp = envp_ptrs;
	/*
	 * ADR-0260: pid 1 is cix-init. Its transport is opened and its
	 * table written now, its binary staged into the tree, and its argv
	 * -- the fd numbers -- becomes the container's.
	 */
	if (init_transport_open(&init_tp, &init_table, -1, &spec, err_msg, err_msg_size) != 0) {
		json_free(root);
		return 500;
	}
	if (stage_cix_init(stage_dir, stage_id_offset, err_msg, err_msg_size) != 0) {
		init_transport_close_all(&init_tp);
		json_free(root);
		return 500;
	}

	/*
	 * Always-on stdout/stderr capture for an ordinary, operator-created
	 * container -- the same pipe2()/O_NONBLOCK-on-the-read-end pattern
	 * pkg_build_start() already established for build containers
	 * (pkg.c). Unconditional (every container, not gated behind the
	 * client's own "capture_output" request) since transparent
	 * container-log capture landed: every line gets forwarded to
	 * logstore.c regardless, so a container that crash-loops with no
	 * other REST-visible diagnostic (e.g. sshd's -D -e exiting 1 on a
	 * config problem) always has its real stderr discoverable via
	 * GET /v1/system/logs?source=container. The client's own
	 * "capture_output" boolean (the `capture_output` local variable
	 * here) now controls only whether the SAME bytes are ALSO mirrored
	 * into this container's own GET /v1/containers/{name} "captured_output"
	 * tail (see register_container_output()'s call site below,
	 * entry->capture_requested) -- a separate, still-opt-in feature. A
	 * pipe2()/fcntl() failure here is treated as "capture unavailable"
	 * rather than a hard container-create failure -- the container
	 * still gets created, it just runs without capture, exactly like
	 * pkg.c's own build path degrades.
	 */
	if (pipe2(output_pipe, O_CLOEXEC) == 0) {
		if (fcntl(output_pipe[0], F_SETFL, O_NONBLOCK) == 0) {
			spec.capture_output = 1;
			spec.stdout_fd = output_pipe[1];
			spec.stderr_fd = output_pipe[1];
			stdio_write_fd = output_pipe[1];
		} else {
			close(output_pipe[0]);
			close(output_pipe[1]);
			output_pipe[0] = -1;
			output_pipe[1] = -1;
		}
	} else {
		output_pipe[0] = -1;
		output_pipe[1] = -1;
	}

	rerr = registry_create(name, image, resolved_image_version, &spec, net_attachments, net_count,
	                        ip_forward,
	                        device_attachments, device_count, file_paths, file_count, disk_name,
	                        dns_server_ips, dns_server_count, &entry);
	/* Observability for the ADR-0207 default flip: which isolation mode
	 * this container actually got is a fact operators and tests need
	 * readable back, not inferred. */
	if (rerr == REGISTRY_OK && entry != NULL)
		entry->userns_enabled = spec.userns_enabled;
	/* Issue #49: mirror the requested quota for read-back (see
	 * registry.h's own field comment for why this one isn't read live
	 * from the kernel like the cgroup limits are). */
	if (rerr == REGISTRY_OK && entry != NULL)
		entry->disk_quota_bytes = disk_quota_bytes;
	/* Issue #248: what this container offers as a console. Recorded
	 * even when empty -- zero declared consoles is a real answer that
	 * the attach path and both clients act on, not a missing value. */
	if (rerr == REGISTRY_OK && entry != NULL)
		registry_set_consoles(name, consoles, console_count);
	/*
	 * Captured immediately, before json_free() below -- container_create()
	 * (via registry_create()) always preserves errno across every one of
	 * its own failure paths (each does `errno = saved_errno;` right
	 * before returning -1), but free()'s own internal bookkeeping isn't
	 * guaranteed to leave errno alone, so this is the last safe point to
	 * read it. This closes a real, previously-silent gap: every
	 * REGISTRY_ERR_CREATE_FAILED used to collapse into one generic
	 * "failed to create container" regardless of cause (a missing image,
	 * a cgroup controller the kernel never delegated -- see ADR-0079 --
	 * or anything else container_create() itself might fail on), giving
	 * an operator nothing to act on beyond a bare 500.
	 */
	create_errno = errno;
	/* ADR-0260: the child's ends of cix-init's transport are the child's
	 * now -- or there is no child, and then nothing keeps ours either. */
	init_transport_close_child_ends(&init_tp);
	if (rerr != REGISTRY_OK)
		init_transport_close_all(&init_tp);
	/*
	 * The parent's own copy of the pipe's write end must be closed
	 * explicitly here, win or lose -- clone3() (no CLONE_FILES) gave
	 * the child an independent copy of the fd table, not a shared one,
	 * so this process's own copy of output_pipe[1] keeps the pipe
	 * "held open" from the read end's perspective (no EOF, ever) until
	 * it's closed, regardless of what the child itself does with its
	 * copy. Same discipline as handle_pkg_fetch_event()'s own
	 * `if (stdio_write_fd >= 0) close(stdio_write_fd);`.
	 */
	if (stdio_write_fd >= 0)
		close(stdio_write_fd);
	/*
	 * A real copy, not just the `name` pointer -- `name` is
	 * json_as_string(jname), pointing straight into `root`'s own
	 * string storage, which json_free() below invalidates. Confirmed
	 * live as a real use-after-free, not a hypothetical one: the log
	 * store's own "container %s: failed to create: ..." line (below)
	 * showed garbled bytes instead of the real container name in the
	 * web dashboard's log view. The success path already sidesteps
	 * this exact hazard by using entry->name instead of `name` (see
	 * its own comment a little further down) -- this was the one
	 * spot that still used the dangling pointer directly.
	 */
	snprintf(name_copy, sizeof(name_copy), "%s", name != NULL ? name : "");
	/*
	 * Safe to free the JSON tree now even though spec.ns.hostname,
	 * spec.cg.name and spec.argv[] point into it: registry_create()
	 * has already returned, meaning container_create()'s clone3() has
	 * already happened. From that point on the child is a fully
	 * independent process with its own copy-on-write view of this
	 * memory -- nothing this process does to it afterward (including
	 * freeing it) is visible to the child, by the basic guarantee of
	 * copy-on-write.
	 */
	json_free(root);

	if (rerr == REGISTRY_ERR_DUPLICATE) {
		if (output_pipe[0] >= 0)
			close(output_pipe[0]);
		/* name_copy, not `name`: json_free(root) above invalidated
		 * the latter -- see its own comment. */
		name_conflict_msg(name_copy, err_msg, err_msg_size);
		return 409;
	}
	if (rerr == REGISTRY_ERR_FULL) {
		if (output_pipe[0] >= 0)
			close(output_pipe[0]);
		snprintf(err_msg, err_msg_size, "container table full");
		return 500;
	}
	if (rerr == REGISTRY_ERR_CREATE_FAILED) {
		if (output_pipe[0] >= 0)
			close(output_pipe[0]);
		snprintf(err_msg, err_msg_size, "failed to create container: %s (%s)",
		         strerror(create_errno), container_create_last_error_step());
		logstore_write("cixd", "error", "container %s: failed to create: %s (%s)", name_copy,
		                strerror(create_errno), container_create_last_error_step());
		return 500;
	}

	register_container_pidfd(entry);

	/* ADR-0260: the daemon's ends of cix-init's transport, and one
	 * reactor conn per service output pipe. */
	{
		int k;
		int out_read[CIXINIT_MAX_SERVICES];

		for (k = 0; k < init_tp.count; k++)
			out_read[k] = init_tp.out[k][0];
		registry_set_services(entry, &init_table, out_read, init_tp.ctl[0], init_tp.rep[0]);
		register_container_init(entry);
		for (k = 0; k < init_tp.count; k++)
			register_container_output_fd(entry, init_tp.out[k][0], k);
	}

	/* ADR-0161 Phase B: live-run-only bookkeeping (see registry.h's own
	 * comment) -- a restart-capable container's own persisted body
	 * already carries these refs for free via replay; this call is
	 * what makes them visible to Phase C's hotplug listener for the
	 * rest of THIS daemon process's life, restart-capable or not. */
	if (pending_device_count > 0)
		registry_set_pending_devices(entry, pending_device_refs, pending_device_count);

	if (output_pipe[0] >= 0) {
		entry->output_fd = output_pipe[0];
		/* The pipe/forwarding-to-logstore is now unconditional (see
		 * this function's own comment above output_pipe's setup) --
		 * capture_requested (the client's own "capture_output" opt-in)
		 * controls only whether captured_output itself gets populated. */
		entry->capture_requested = capture_output;
		register_container_output(entry);
	}

	if (dns_register) {
		/* entry->name, not the local `name`, which pointed into
		 * root and is no longer valid after json_free() above.
		 *
		 * siteconfig_qualify() (ADR-0052) applies the site's default
		 * suffix the same way the manual POST /v1/dns/records path
		 * already does -- this call was missing entirely until now
		 * (ADR-0092), leaving every auto-registered container record
		 * (e.g. dns-1/dns-2's own names) bare while every manually-
		 * created one got the suffix, a real, user-reported
		 * inconsistency with no reason behind it.
		 */
		char qualified_name[DNS_NAME_MAX];
		struct dns_record *rec;
		enum dns_error derr;

		siteconfig_qualify(entry->name, qualified_name, sizeof(qualified_name));
		derr = dns_record_create(qualified_name, spec.nets[0].container_ip_be, entry->name, &rec);

		if (derr != DNS_OK)
			fprintf(stderr,
			        "%s: dns_register requested but auto-registration failed (err=%d)\n",
			        entry->name, (int)derr);
	}

	/*
	 * pki_issue / pki_cert are handled at STAGING time, well above --
	 * the certificate is written into the container's tree before
	 * clone3(), not pushed into it once it is already running (#414).
	 * Nothing remains to do here, and that is the point: the block that
	 * used to live at this spot is what created the startup race every
	 * image was then expected to work around.
	 */
	if (ldap_provision) {
		/* task #727: a service/bind identity for this container itself --
		 * NOT a human login account (those are created directly via
		 * POST /v1/ldap/users, task #726). Mirrors pki_issue's own
		 * shape closely: pid-dependent (secret delivery needs a live
		 * container root), so it fires in this same post-pidfd block,
		 * and tolerates its own "already exists" case the identical
		 * way pki_issue tolerates PKI_ERR_DUPLICATE -- a respawn under
		 * restart-always gets a fresh pid and needs its secret
		 * delivered again even though the account itself already
		 * exists. The plaintext secret is never persisted anywhere
		 * (see ldap_generate_secret()'s own comment) -- a fresh one is
		 * generated and re-hashed into the account on every single
		 * fire of this block, respawn or not, and only this one
		 * delivery ever sees the plaintext. */
		const struct ldap_group *g = ldap_group_find(ldap_group_buf); /* validated non-empty above */
		const char *ldap_user_name = ldap_user_buf[0] != '\0' ? ldap_user_buf : entry->name;
		int uid = ldap_uid != 0 ? ldap_uid : ldap_uid_alloc();
		char secret[LDAP_PROVISION_SECRET_LEN + 1];
		struct ldap_user *u = NULL;
		enum ldap_record_error lerr = LDAP_RECORD_ERR_NOT_FOUND;

		if (!ldap_username_is_valid(ldap_user_name)) {
			fprintf(stderr,
			        "%s: ldap_provision requested but the container name isn't a valid "
			        "LDAP username -- pass ldap_user= explicitly\n",
			        entry->name);
		} else if (g == NULL || ldap_generate_secret(secret) != 0) {
			fprintf(stderr, "%s: ldap_provision requested but the group vanished or "
			                "/dev/urandom couldn't be read\n",
			        entry->name);
		} else {
			lerr = ldap_user_create(ldap_user_name, uid, g->gidnumber, NULL, 0, NULL, NULL, NULL,
			                         NULL, NULL, secret, 0, entry->name, 1, NULL, &u);
			if (lerr == LDAP_RECORD_ERR_DUPLICATE) {
				/* Respawn under restart-always: the account already
				 * exists (from this container's own first start) --
				 * re-hash the freshly generated secret into it so
				 * this respawn's own delivery below is valid. */
				u = ldap_user_find(ldap_user_name);
				if (u != NULL)
					lerr = ldap_user_update(ldap_user_name, NULL, uid, g->gidnumber,
					                         u->secondary_groups, u->secondary_group_count,
					                         u->givenname, u->sn, u->mail, u->loginshell,
					                         u->homedirectory, secret, u->disabled,
					                         u->ssh_public_key, u->can_search, &u);
			}
			if (lerr != LDAP_RECORD_OK || u == NULL) {
				fprintf(stderr,
				        "%s: ldap_provision requested but the account create/update failed "
				        "(err=%d)\n",
				        entry->name, (int)lerr);
			} else {
				char parent[PATH_MAX + 32], dst[PATH_MAX + 32];

				/* Host-side tree (#269) -- see containerpath.h. */
				container_file_host_path(entry->name, entry->disk_name,
				                          ldap_secret_dir_buf, parent, sizeof(parent));
				if (parent[0] == '\0' ||
				    snprintf(dst, sizeof(dst), "%s/bind.secret", parent) >= (int)sizeof(dst) ||
				    persist_mkdir_p(parent) != 0 ||
				    persist_atomic_write(dst, secret, strlen(secret)) != 0) {
					fprintf(stderr,
					        "%s: ldap_provision account ready but delivering its secret "
					        "into the container failed\n",
					        entry->name);
				} else {
					chmod(dst, 0600);
				}
			}
		}
	}

	/*
	 * Re-apply anything this daemon PROJECTS into a container, now that
	 * it is running (#253).
	 *
	 * A registered DNS server's /etc/dnsmasq-hosts and
	 * /etc/dnsmasq-servers are derived from state the daemon already
	 * holds; they are not the container's own data. Nothing re-applied
	 * them on start, and the definition's files[] ARE re-staged on every
	 * start -- with the recipe's content, which for the servers file is
	 * empty. So a restart actively reset it rather than merely failing
	 * to refresh, and dnsmasq came back forwarding nowhere.
	 *
	 * That is not a restart quirk: the host's own resolv.conf points at
	 * these containers, so every lookup on the box failed while the
	 * container read "running", the binding was present, and GET
	 * /v1/dns/forwarders returned the right values. It was reached
	 * twice from different directions -- a storage migration's own
	 * stop-and-replay, and a plain recreate.
	 *
	 * This is the one place worth doing it: every path that brings a
	 * container up replays this same body (fresh POST, boot autostart,
	 * crash restart, migration replay), which is exactly why it exists.
	 * Both syncs skip containers that are not running and are no-ops
	 * with no bindings, so this is cheap and idempotent for every
	 * container that is not a DNS server.
	 *
	 * The general rule, since this class keeps recurring: a file the
	 * daemon derives from its own state is re-derived, never assumed to
	 * have survived.
	 */
	dns_server_sync_all();
	dns_forwarders_sync_all();

	*out_entry = entry;
	return 0;
}

/*
 * Creating a container from a request body, without responding.
 *
 * Split out so that anything else needing to create a container uses
 * this same implementation rather than a second copy of it, or -- worse
 * -- an HTTP client talking back to this daemon. POST /v1/dns/provision
 * is the first such caller. Returns 0 on success, otherwise an HTTP
 * status with err_msg filled in; *out_entry is set only on success.
 */
/*
 * Re-push the config this daemon manages for a container that has just
 * come back (#270).
 *
 * A DNS server's hosts file, an LDAP server's user and group list and a
 * DHCP server's leases are written INTO the container by the daemon,
 * not staged by its definition. So a container that is recreated,
 * started, or restarted comes back serving whatever its definition
 * stages -- an empty hosts file, a config with no users -- and stays
 * that way until the next unrelated write or the next reboot.
 *
 * Boot was already covered: containerdef_autostart_all() is followed by
 * the same syncs. Nothing covered a single container coming back while
 * the daemon keeps running, which is every `container start`, every
 * crash restart, every rolling restart and every recreate. Migrating
 * the fleet to btrfs surfaced it repeatedly -- each migrate-storage
 * needed a throwaway `ldap group add` afterwards to make the service
 * work again, and that workaround is what this removes.
 *
 * Every sync here iterates all bindings and is idempotent, so calling
 * them wholesale is correct rather than merely convenient; a
 * per-container variant would be an optimisation, not a fix. They also
 * skip a server that is not up, so calling this when the container that
 * came back is not one of them costs a few loop iterations and writes
 * nothing.
 *
 * NTP and syslog deliberately absent: their bindings are registrations,
 * with no daemon-written config inside the container, so they have no
 * equivalent gap. Checked rather than assumed.
 */
static void resync_managed_services(void)
{
	dns_server_sync_all();
	dns_forwarders_sync_all();
	ldap_record_sync_all();
	dhcp_sync_all(NULL, 0, NULL);
}

static int create_container_persisted(const char *body, size_t body_len,
                                       struct registry_entry **out_entry, char *err_msg,
                                       size_t err_msg_size)
{
	int body_has_userns = 0;
	struct registry_entry *entry;
	char restart_policy[16];
	int restart_delay_seconds;
	char depends_on[CONTAINERDEF_MAX_DEPENDS][REGISTRY_NAME_MAX];
	int depends_on_count;
	int follow_rolling;
	int has_follow_rolling_jitter, follow_rolling_jitter_seconds;
	int status;

	/* Issue #68: HTTP creates are strict about unknown keys -- see
	 * container_body_unknown_key()'s own comment. Parsed once extra
	 * here (create_container_from_body() re-parses); negligible cost
	 * against a container creation, and keeps the shared parser's
	 * replay callers lenient without a signature change across its
	 * five call sites. */
	{
		struct json_value *root = json_parse(body, body_len);
		const char *bad = container_body_unknown_key(root);

		if (bad != NULL) {
			snprintf(err_msg, err_msg_size, "unknown field: %s", bad);
			json_free(root);
			return 400;
		}
		/* Checked on the parsed tree, not with strstr -- "userns" can
		 * legitimately appear inside a files[] content string. */
		body_has_userns = json_object_get(root, "userns") != NULL;
		json_free(root);
	}

	status = create_container_from_body(body, body_len, &entry, restart_policy,
	                                     &restart_delay_seconds, depends_on, &depends_on_count,
	                                     &follow_rolling,
	                                     &has_follow_rolling_jitter, &follow_rolling_jitter_seconds,
	                                     err_msg, err_msg_size);
	if (status != 0)
		return status;

	/*
	 * ADR-0181 (issue #73), superseding ADR-0027: persist EVERY container's
	 * definition, regardless of restart policy. `restart` now governs only
	 * auto-restart (on exit/boot/rolling); it no longer decides whether the
	 * container exists after it stops. So `stop` always keeps the container
	 * (startable), and only `delete` removes it -- stop is stop, delete is
	 * delete. `restart:"no"` means "persisted, never auto-restarted."
	 */
	{
		/*
		 * ADR-0107/0108: splice "image_version" onto the raw request
		 * body before persisting it -- containerdef_add() stores this
		 * exact byte string, replayed verbatim (never re-parsed
		 * against fresh state) by handle_start()/
		 * handle_restart_timer_event()/containerdef_autostart_all() on
		 * every future revival of this definition. Without this, a
		 * replay would call image_current_version() fresh and
		 * silently re-pin a restarted container to whatever the
		 * image's current version has become by then -- exactly the
		 * bug this whole epic exists to close, just moved from "pkg
		 * install" to "daemon restart" as the trigger. Raw string
		 * surgery (find the body's own trailing '}', splice one more
		 * key in front of it) rather than a full JSON re-serialize --
		 * the body was already validated as a well-formed JSON object
		 * by create_container_from_body()'s own json_parse() above,
		 * so its last non-whitespace byte is guaranteed to be '}'.
		 */
		char *persisted_body = NULL;
		size_t persisted_len = body_len;
		const char *persist_src = body;

		if (entry->image_version[0] != '\0' || !body_has_userns) {
			size_t trim = body_len;

			while (trim > 0 && (body[trim - 1] == ' ' || body[trim - 1] == '\t' ||
			                     body[trim - 1] == '\n' || body[trim - 1] == '\r'))
				trim--;
			if (trim > 0 && body[trim - 1] == '}') {
				persisted_body = malloc(trim + 192);
				if (persisted_body != NULL) {
					int n = 0;

					memcpy(persisted_body, body, trim - 1);
					if (entry->image_version[0] != '\0')
						n += snprintf(persisted_body + (trim - 1) + n, 96,
						              ",\"image_version\":\"%s\"", entry->image_version);
					/*
					 * ADR-0207 phase 3: pin the RESOLVED isolation mode
					 * into the persisted definition when the caller left
					 * it to the default, exactly as image_version is
					 * pinned above and for the same reason -- a revival
					 * replays this body, and consulting the CURRENT
					 * default then would silently flip a container's
					 * isolation mode (and with it its whole storage
					 * layout) on some future restart after an operator
					 * changes the platform default. A container's mode
					 * is decided once, at creation, visibly.
					 */
					if (!body_has_userns)
						n += snprintf(persisted_body + (trim - 1) + n, 32,
						              ",\"userns\":%s",
						              entry->userns_enabled ? "true" : "false");
					persisted_body[(trim - 1) + n] = '}';
					persisted_len = (trim - 1) + (size_t)n + 1;
					persist_src = persisted_body;
				}
			}
		}

		if (containerdef_add(entry->name, persist_src, persisted_len, depends_on, depends_on_count,
		                      restart_policy, restart_delay_seconds, follow_rolling,
		                      has_follow_rolling_jitter, follow_rolling_jitter_seconds) != 0) {
			fprintf(stderr,
			        "%s: persisting its definition failed -- it will not survive a daemon "
			        "restart and `start` after a stop will not find it (restart:\"%s\")\n",
			        entry->name, restart_policy);
		}
		free(persisted_body);
	}

	/*
	 * A recreate is the case this was found in: the container comes
	 * back with whatever its definition stages, and nothing had
	 * re-pushed what the daemon manages for it (#270).
	 *
	 * This runs BEFORE register_declared_server_roles(), which is the
	 * caller's next step -- so it cannot cover a role the container
	 * declares in its own definition: the binding does not exist yet
	 * when this iterates them, and a delete-and-recreate forgot the
	 * old one. That gap was #418, and the fix is that each register
	 * renders its own server (dns_server_register() always did;
	 * ldap_server_register() now does too), not a second sync bolted
	 * on after registration here.
	 */
	resync_managed_services();

	*out_entry = entry;
	return 0;
}

/*
 * Registers the server roles a container's own definition declares
 * (#301).
 *
 * A DNS, NTP, syslog or LDAP server is two pieces of state: the
 * container, and a binding telling this daemon to keep it fed --
 * writing the record set into its hosts file, re-sending SIGHUP, and so
 * on. Deleting a container deliberately forgets the binding
 * (dns_server_forget() and friends in handle_delete), because a gone
 * container must not leave a dangling one.
 *
 * The consequence was that recreating a container from its recipe --
 * the documented recovery path -- brought back a container that served
 * nothing. Measured on 192.168.15.95: after deleting and re-applying
 * dns-1 and dns-2, both were "running", GET /v1/dns/servers returned an
 * empty list, dnsmasq answered for nothing, and the host could not
 * resolve at all. Every individual thing an operator would check looked
 * right, and no error was logged anywhere.
 *
 * So the role is declared in the container's own definition, which is
 * what a recipe renders to. Forget-on-delete stays correct, and apply
 * restores the whole server rather than half of it.
 *
 * Returns 0, or -1 with err filled. A declared role that cannot be
 * registered is an error rather than a warning: a server that is
 * running and unregistered is exactly the silent state this exists to
 * end.
 */
static int register_declared_server_roles(const char *body, size_t body_len,
                                           struct registry_entry *entry, char *err, size_t err_size)
{
	struct json_value *root = json_parse(body, body_len);
	const struct json_value *v;
	int rc = 0;

	if (root == NULL)
		return 0; /* create_container_persisted() already parsed it */

	v = json_object_get(root, "dns_server");
	if (v != NULL && v->type == JSON_OBJECT) {
		const char *hosts_path = json_as_string(json_object_get(v, "hosts_path"));

		if (hosts_path == NULL || hosts_path[0] != '/') {
			snprintf(err, err_size, "dns_server.hosts_path must be an absolute path");
			rc = -1;
		} else if (dns_server_register(entry->name, entry->handle.pid, entry->handle.pidfd,
		                                hosts_path) != DNS_SERVER_OK) {
			snprintf(err, err_size, "container created, but registering it as a DNS server failed");
			rc = -1;
		}
	}
	if (rc == 0) {
		v = json_object_get(root, "ntp_server");
		if (v != NULL && v->type == JSON_BOOL && v->u.boolean &&
		    ntp_server_register(entry->name) != NTP_OK) {
			snprintf(err, err_size, "container created, but registering it as an NTP server failed");
			rc = -1;
		}
	}
	if (rc == 0) {
		v = json_object_get(root, "syslog_target");
		if (v != NULL && v->type == JSON_BOOL && v->u.boolean &&
		    syslogfwd_target_register(entry->name) != SYSLOGFWD_OK) {
			snprintf(err, err_size,
			          "container created, but registering it as a syslog target failed");
			rc = -1;
		}
	}
	if (rc == 0) {
		v = json_object_get(root, "ldap_server");
		if (v != NULL && v->type == JSON_OBJECT) {
			const char *config_path = json_as_string(json_object_get(v, "config_path"));

			if (config_path == NULL || config_path[0] != '/') {
				snprintf(err, err_size, "ldap_server.config_path must be an absolute path");
				rc = -1;
			} else if (ldap_server_register(entry->name, config_path) != LDAP_SERVER_OK) {
				snprintf(err, err_size,
				          "container created, but registering it as an LDAP server failed");
				rc = -1;
			}
		}
	}
	json_free(root);
	return rc;
}

static void handle_create(int fd, const char *body, size_t body_len)
{
	struct registry_entry *entry = NULL;
	char err_msg[256];
	int status;
	struct json_writer w;

	status = create_container_persisted(body, body_len, &entry, err_msg, sizeof(err_msg));
	if (status != 0) {
		respond_error(fd, status, http_status_text(status), err_msg);
		return;
	}

	if (register_declared_server_roles(body, body_len, entry, err_msg, sizeof(err_msg)) != 0) {
		logstore_write("cixd", "error", "container %s: %s", entry->name, err_msg);
		respond_error(fd, 500, "Internal Server Error", err_msg);
		return;
	}

	jw_init(&w);
	registry_write_json_one(entry, &w);
	respond_json(fd, 201, "Created", &w);
	jw_free(&w);
}

static void handle_delete(int fd, const char *name)
{
	struct registry_entry *e = registry_find(name);
	struct container_def *def = containerdef_find(name);
	struct conn *cc;
	char disk_name[DISKROLE_DISK_NAME_MAX];

	/*
	 * A restart:"always" definition that has never once managed to
	 * autostart (a cycle, an unknown dependency, an image that no
	 * longer exists, ...) has no live registry entry at all -- without
	 * this check, DELETE could never reach it, permanently stranding a
	 * broken definition with no way to remove it short of hand-editing
	 * container_defs.json on disk. Found directly: test_container_restart.c's
	 * own cleanup of exactly this case (a container skipped for a
	 * circular/unknown dependency) silently 404'd, leaking its
	 * definition into every subsequently-run test on this host.
	 */
	if (e == NULL && def == NULL) {
		respond_error(fd, 404, "Not Found", "no such container");
		return;
	}

	/*
	 * ADR-0180 (issue #67): a RUNNING container is never killed-and-
	 * waited-for synchronously here anymore -- that wait
	 * (registry_remove()'s own waitid()) is unbounded in principle (a
	 * task stuck in uninterruptible D-state only ever *pends* SIGKILL),
	 * and because this daemon is one epoll loop, it froze the entire
	 * control plane twice in real production before this existed.
	 * Instead: every piece of durable intent is written NOW (service-
	 * ownership forgets + containerdef removal below -- so no daemon
	 * restart in the window can resurrect the container), the SIGKILL
	 * is sent without waiting (registry_begin_kill()), and the entry's
	 * own already-registered pidfd epoll watch -- the exact machinery
	 * that detects ordinary crashes -- completes the teardown
	 * (registry slot release + disk cleanup) from
	 * handle_container_event() when the process actually dies. Until
	 * then the entry reports status "deleting", and a same-name create
	 * 409s off the still-in-use registry slot, exactly as it would
	 * against any live container.
	 */
	if (e != NULL && e->running && e->teardown_kind == REGISTRY_TEARDOWN_NONE) {
		dns_server_forget(name);
		dhcp_server_forget(name);
		dns_record_forget_owner(name);
		ldap_server_forget(name);
		ldap_user_forget_owner(name);
		pki_cert_forget_owner(name);
		ntp_server_forget(name);
		syslogfwd_target_forget(name);
		serverhealth_forget(name); /* issue #81 -- no health record for a gone container */
		containerdef_remove(name);
		begin_container_stop(e, REGISTRY_TEARDOWN_DELETE);
		http_set_blocking(fd);
		http_write_response(fd, 204, "No Content", "application/json", "", 0);
		return;
	}
	/* A repeat DELETE while a prior one's teardown is still mid-flight:
	 * idempotent -- the intent is already fully recorded. A DELETE
	 * landing while a STOP's teardown is in flight upgrades the intent
	 * in place (records delete's own durable half now; the one pending
	 * pidfd event completes whichever kind it finds recorded). */
	if (e != NULL && e->running && e->teardown_kind != REGISTRY_TEARDOWN_NONE) {
		if (e->teardown_kind == REGISTRY_TEARDOWN_STOP) {
			dns_server_forget(name);
			dns_record_forget_owner(name);
			ldap_server_forget(name);
			ldap_user_forget_owner(name);
			pki_cert_forget_owner(name);
			ntp_server_forget(name);
			syslogfwd_target_forget(name);
			serverhealth_forget(name); /* issue #81 */
			containerdef_remove(name);
			e->teardown_kind = REGISTRY_TEARDOWN_DELETE;
		}
		http_set_blocking(fd);
		http_write_response(fd, 204, "No Content", "application/json", "", 0);
		return;
	}

	disk_name[0] = '\0';

	if (e != NULL) {
		if (e->reactor_conn != NULL) {
			cc = e->reactor_conn;
			cix_epoll_ctl(g_epfd, EPOLL_CTL_DEL, cc->fd, NULL);
			free(cc);
			e->reactor_conn = NULL;
		}

		snprintf(disk_name, sizeof(disk_name), "%s", e->disk_name);

		/*
		 * registry_remove() SIGKILLs the process first (thawing it if
		 * paused, so the signal can actually be delivered) -- the disk
		 * cleanup below must run AFTER this, never before: overlay_create()
		 * mounted this container's own overlay (container_base/merged)
		 * directly in the daemon's own root mount namespace (the mount(2)
		 * call happens in create_container_from_body(), before clone3()
		 * ever forks the container's own separate namespace), and that
		 * mount is never explicitly torn down anywhere else in this
		 * codebase -- confirmed by grep, the only umount2() calls that
		 * exist at all are mountns_pivot()'s own old-root cleanup, which
		 * runs inside the container's own child process, a completely
		 * separate mount namespace. Running persist_remove_tree() while
		 * that mount is still live would be a real correctness hazard,
		 * not just an ordering nicety: nftw() without FTW_MOUNT freely
		 * crosses into a mounted subdirectory, so it would walk straight
		 * into the still-live overlay view and start unlinking through
		 * it -- silently mutating (or, on a still-alive process, actively
		 * corrupting) the upperdir via the overlay itself, then failing
		 * on the mountpoint's own rmdir() (EBUSY) partway through, an
		 * even worse outcome than doing nothing.
		 */
		registry_remove(name);
	} else {
		/*
		 * task #759 follow-up: e == NULL here does NOT mean "never
		 * autostarted, nothing on disk" -- it also covers a
		 * restart:"always" container that DID create successfully at
		 * least once and is simply between a crash and its next
		 * handle_restart_timer_event() retry (registry_remove() runs
		 * on every exit, live or crashed, long before this handler is
		 * ever reached). The previous version of this function skipped
		 * disk cleanup entirely for this case, based on the (false)
		 * assumption below it. Confirmed the hard way, live on
		 * 192.168.15.95: a jump box container crash-looped forever
		 * with "Unable to load host key: bad permissions" because its
		 * very first-ever creation left a 0644 host-key file in its
		 * upperdir, and every subsequent DELETE + recreate under the
		 * SAME name silently reused that same never-cleaned upperdir
		 * (files[] staging's own open(O_CREAT|O_TRUNC) never chmod()s
		 * an already-existing file to the newly requested mode) --
		 * repeating the identical crash forever, surviving any number
		 * of "delete and recreate" cycles. The overlay mount is still
		 * live too (nothing unmounts it on a plain crash, same
		 * reasoning as the e != NULL branch above), so this is exactly
		 * as safe to clean up here, not a special case.
		 *
		 * disk_name is re-derived from the persisted definition's own
		 * stored body (the same "disk" field create_container_from_body()
		 * itself reads), since there's no live registry entry to read
		 * e->disk_name from.
		 */
		struct json_value *defroot = json_parse(def->body, def->body_len);

		if (defroot != NULL) {
			const char *d = json_as_string(json_object_get(defroot, "disk"));

			if (d != NULL)
				snprintf(disk_name, sizeof(disk_name), "%s", d);
			json_free(defroot);
		}
	}

	/*
	 * task #738 (extended by the task #759 follow-up above to also
	 * cover the e == NULL/crashed case): DELETE never removed a
	 * container's own on-disk upper/work/merged directories -- a real,
	 * pre-existing disk-space leak for every deleted container
	 * (confirmed: no code anywhere in this codebase ever called
	 * anything equivalent to this in a container-teardown context; the
	 * quotamap.h doc comment that used to justify this as deliberate
	 * cited "ADR-0054's pre-existing backup/restore design" --
	 * ADR-0054 is entirely about host-side stats and says nothing
	 * about backup/restore at all; ADR-0033, the *real* backup/restore
	 * ADR, explicitly scopes workload data as "each container's own
	 * concern, not this endpoint's" and reconstructs a restored
	 * container via a fresh containerdef replay, never by resurrecting
	 * old upperdir content -- so no real design anywhere actually
	 * depended on this retention; it was a stale, incorrect citation
	 * for a genuine oversight). container_root_for() resolves the same
	 * root the container was actually created under (ADR-0102 -- the
	 * default CONTAINERS_DIR, or an operator-chosen disk). Best-effort
	 * throughout -- a failure here is logged, never blocks the delete
	 * itself from completing (the registry/containerdef state is the
	 * one source of truth for whether a container exists; leftover
	 * disk state after a failed cleanup is a nit, not a reason to
	 * leave the container definition half-deleted).
	 */
	{
		char container_root[PATH_MAX];
		char container_base[PATH_MAX];
		char merged[PATH_MAX];

		container_root_for(disk_name, container_root, sizeof(container_root));
		snprintf(container_base, sizeof(container_base), "%s/%s", container_root, name);
		snprintf(merged, sizeof(merged), "%s/merged", container_base);
		if (umount2(merged, MNT_DETACH) != 0 && errno != EINVAL && errno != ENOENT)
			fprintf(stderr, "DELETE %s: umount2(%s) failed: %s\n", name, merged,
			        strerror(errno));
		{
			/* ADR-0207: a direct-mode container's rootfs is a btrfs
			 * subvolume persist_remove_tree cannot remove -- destroy it
			 * first; a no-op (ENOENT) for overlay-mode containers. */
			char droot[PATH_MAX];

			snprintf(droot, sizeof(droot), "%s/rootfs", container_base);
			cix_btrfs_subvol_delete_or_rmtree(droot);
		}
		if (persist_remove_tree(container_base) != 0)
			fprintf(stderr, "DELETE %s: failed to remove %s: %s\n", name, container_base,
			        strerror(errno));
	}

	/*
	 * Unconditional, matching the disk cleanup above -- a crashed-but-
	 * still-defined container releasing its own DNS/LDAP/PKI/NTP/SSH/
	 * syslog-target ownership on DELETE is exactly as correct as a live one
	 * doing so; there is no reason a still-registered DNS record or
	 * LDAP SSH-target sync should outlive a definition that's being
	 * permanently removed just because the container happened to be
	 * mid-crash at the moment of the DELETE call.
	 */
	dns_server_forget(name);
	dhcp_server_forget(name);
	dns_record_forget_owner(name);
	ldap_server_forget(name);
	ldap_user_forget_owner(name);
	pki_cert_forget_owner(name);
	ntp_server_forget(name);
	syslogfwd_target_forget(name);
	serverhealth_forget(name); /* issue #81 */

	/*
	 * Unconditional, a no-op if this name never had a restart:"always"
	 * definition. DELETE always means gone for good: not on this
	 * crash-restart timer (none pending, since this path never goes
	 * through handle_container_event()) and not on the next daemon
	 * restart.
	 */
	containerdef_remove(name);
	http_set_blocking(fd);
	http_write_response(fd, 204, "No Content", "application/json", "", 0);
}

/*
 * ADR-0142 Section 4: real cutover for a container-storage migration,
 * run synchronously once containerstoragemigrate_completed()'s own
 * bulk async copy pass has already succeeded -- mirrors finalize_
 * state_storage_migration()'s own overall shape (save the old source
 * dir first, run the second synchronous copy pass, only then commit),
 * but with the one real difference ADR-0142 calls out: a container's
 * own overlay is actively read/written by its own live process, so
 * unlike a daemon-wide singleton this needs a real stop before the
 * final copy pass can see a quiescent, fully consistent tree, and a
 * real restart afterward. Uses the exact same registry_remove()-plus-
 * reactor-conn-teardown primitive handle_stop()/handle_rolling_restart_
 * timer_event() already use, and the exact same create_container_
 * from_body() replay handle_rolling_restart_timer_event() already
 * uses to bring it back -- one source of truth for "how a container
 * stops" and "how a definition becomes live" respectively, not a third
 * bespoke version of either just for this. A container with no
 * persisted definition can never reach here (the POST handler below
 * rejects it before ever starting a job), so the replay always has a
 * real body to work from.
 *
 * On any failure after the container has already been stopped (final
 * copy pass fails, or the replay itself fails), the container is
 * restarted from its ORIGINAL location rather than left down -- the
 * migration is treated as a whole, all-or-nothing operation from the
 * caller's point of view, matching every other storage-placement
 * migration's own "don't guess, surface it, never leave things half
 * done" posture.
 */
static void container_storage_migration_after_stop(const char *name);

/*
 * ADR-0285 (#448): the stop half.
 *
 * This function used to stop the container itself, with
 * registry_remove()'s SIGKILL-and-blocking-waitid() and no running
 * check of any kind -- the same unbounded wait on the reactor that took
 * a live box out through the rolling-restart path. A running container
 * is now asked to stop the ordinary way and this returns; the kernel's
 * pidfd event resumes the job in
 * container_storage_migration_after_stop() below, which is the rest of
 * what this function used to be, unchanged.
 *
 * The reactor_conn is KEPT for a running container: it is the pidfd
 * registration, and freeing it would mean never learning the container
 * had stopped -- a migration that hangs after the stop rather than a
 * control plane that hangs during it.
 */
static void finalize_container_storage_migration(const char *name)
{
	struct registry_entry *live = registry_find(name);

	if (live != NULL && live->running) {
		begin_container_stop(live, REGISTRY_TEARDOWN_MIGRATE);
		return;
	}
	if (live != NULL) {
		/* Exited but still registered: no stop needed, just the slot. */
		if (live->reactor_conn != NULL) {
			struct conn *rc = live->reactor_conn;

			cix_epoll_ctl(g_epfd, EPOLL_CTL_DEL, rc->fd, NULL);
			free(rc);
			live->reactor_conn = NULL;
		}
		if (registry_remove(name) != 0) {
			logstore_write("cixd", "error",
			                "%s: container-storage migration could not release the registry "
			                "slot (%s) -- aborting the migration",
			                name, strerror(errno));
			return;
		}
	}
	container_storage_migration_after_stop(name);
}

/*
 * The half that needs the container's tree to be quiescent: the final
 * copy pass, the disk re-pointing, the replay, and the abort path that
 * restarts from the original location. Reached either directly (the
 * container was already down) or from container_exit_finalize() when a
 * REGISTRY_TEARDOWN_MIGRATE stop completes.
 */
static void container_storage_migration_after_stop(const char *name)
{
	char old_source_dir[PATH_MAX];
	char target_dir[PATH_MAX];
	char target_disk[DISKROLE_DISK_NAME_MAX];
	char merged[PATH_MAX];
	struct container_def *def;

	snprintf(old_source_dir, sizeof(old_source_dir), "%s",
	         containerstoragemigrate_job_source_dir(name));
	snprintf(target_dir, sizeof(target_dir), "%s", containerstoragemigrate_job_target_dir(name));
	snprintf(target_disk, sizeof(target_disk), "%s", containerstoragemigrate_job_target_disk(name));

	/* Best-effort, same tolerant errno handling as DELETE's own crashed-
	 * container cleanup (handle_delete() above) -- see that function's
	 * comment for why this can legitimately be a no-op. */
	snprintf(merged, sizeof(merged), "%s/merged", old_source_dir);
	if (umount2(merged, MNT_DETACH) != 0 && errno != EINVAL && errno != ENOENT)
		fprintf(stderr, "%s: container-storage migration: umount2(%s) failed: %s\n", name, merged,
		        strerror(errno));

	if (containerstoragemigrate_finalize(name) != 0) {
		fprintf(stderr,
		        "%s: container-storage migration: final copy pass failed, restarting from the "
		        "original location\n",
		        name);
		def = containerdef_find(name);
		if (def != NULL) {
			struct registry_entry *entry;
			char restart_policy[16];
			int restart_delay_seconds, depends_on_count;
			int follow_rolling, has_follow_rolling_jitter;
			int follow_rolling_jitter_seconds;
			char depends_on[CONTAINERDEF_MAX_DEPENDS][REGISTRY_NAME_MAX];
			char err_msg[256];

			if (create_container_from_body(def->body, def->body_len, &entry, restart_policy,
			                                &restart_delay_seconds, depends_on, &depends_on_count,
			                                &follow_rolling,
			                                &has_follow_rolling_jitter,
			                                &follow_rolling_jitter_seconds, err_msg,
			                                sizeof(err_msg)) != 0)
				fprintf(stderr, "%s: container-storage migration: restart after abort failed: %s\n",
				        name, err_msg);
		}
		return;
	}

	if (containerdef_patch_disk(name, target_disk[0] != '\0' ? target_disk : NULL) != 0)
		fprintf(stderr,
		        "%s: container-storage migration: failed to persist the new disk placement -- a "
		        "future daemon restart would replay the OLD location\n",
		        name);

	def = containerdef_find(name);
	if (def != NULL) {
		struct registry_entry *entry;
		char restart_policy[16];
		int restart_delay_seconds, depends_on_count;
		int follow_rolling, has_follow_rolling_jitter;
		int follow_rolling_jitter_seconds;
		char depends_on[CONTAINERDEF_MAX_DEPENDS][REGISTRY_NAME_MAX];
		char err_msg[256];

		if (create_container_from_body(def->body, def->body_len, &entry, restart_policy,
		                                &restart_delay_seconds, depends_on, &depends_on_count,
		                                &follow_rolling,
		                                &has_follow_rolling_jitter, &follow_rolling_jitter_seconds,
		                                err_msg, sizeof(err_msg)) != 0) {
			containerstoragemigrate_mark_failed(name, err_msg);
			fprintf(stderr, "%s: container-storage migration: cutover restart failed: %s\n", name,
			        err_msg);
			return;
		}
	}

	if (persist_remove_tree(old_source_dir) != 0)
		fprintf(stderr, "%s: container-storage migration: could not remove old location %s: %s\n",
		        name, old_source_dir, strerror(errno));

	fprintf(stderr, "%s: container-storage migration: complete, now active on %s\n", name,
	        target_disk[0] != '\0' ? target_disk : "(default OS-disk placement)");
}

static void handle_container_storage_migrate_event(struct conn *cc)
{
	int status;
	int exit_status;
	char name[REGISTRY_NAME_MAX];

	snprintf(name, sizeof(name), "%s", cc->container_storage_migrate_name);

	cix_epoll_ctl(g_epfd, EPOLL_CTL_DEL, cc->fd, NULL);
	if (waitpid(cc->pkg_fetch_pid, &status, 0) == cc->pkg_fetch_pid && WIFEXITED(status))
		exit_status = WEXITSTATUS(status);
	else
		exit_status = -1;
	close(cc->fd);
	free(cc);

	containerstoragemigrate_completed(name, exit_status);
	fprintf(stderr, "%s: container-storage migrate: bulk copy job finished (exit_status=%d)\n", name,
	        exit_status);
	if (exit_status == 0)
		finalize_container_storage_migration(name);
}

/*
 * POST /v1/containers/{name}/start (ADR-0045) -- the counterpart to
 * .../stop: brings a stopped-but-still-defined container back to life
 * without a daemon restart, closing the gap .../stop's own comment
 * above alludes to (what "stopped" means going forward was previously
 * "wait for containerdef_autostart_all() at the next daemon restart,"
 * and only for restart:"always"/"on-failure" -- "unless-stopped" or
 * "no" had no way back at all short of DELETE + a fresh POST, which
 * itself 409s on a name that already has a persisted definition).
 *
 * Idempotent like .../stop: already-live is a plain 200, not an
 * error. A name with no persisted definition at all is 404 -- this
 * endpoint only ever replays an existing definition, it does not
 * accept a body and create a new one (that's POST /v1/containers).
 * Reuses create_container_from_body() verbatim on the definition's own
 * stored body -- the exact same replay containerdef_autostart_all()
 * already does at boot (main(), ~line 4841) -- one source of truth for
 * "how a definition becomes a live container," not a second bespoke
 * path. Unlike autostart, this endpoint is explicit and manual, so it
 * intentionally ignores restart_policy/"unless-stopped" gating
 * entirely: an operator asking to start a container by name always
 * means start it, regardless of what a *crash* would have done.
 */
static void handle_start(int fd, const char *name)
{
	struct registry_entry *entry;
	struct container_def *def;
	char restart_policy[16];
	int restart_delay_seconds;
	char depends_on[CONTAINERDEF_MAX_DEPENDS][REGISTRY_NAME_MAX];
	int depends_on_count;
	int follow_rolling;
	int has_follow_rolling_jitter, follow_rolling_jitter_seconds;
	char err_msg[256];
	int status;
	struct json_writer w;

	entry = registry_find(name);
	/*
	 * A container mid-stop is still running=1 until its kill completes,
	 * and the idempotent-200 below would ack it as alive -- so a
	 * stop-then-start sequence could get a 200 for the DYING
	 * incarnation, start nothing, and end with the container down while
	 * the caller believes it started. Found reproducibly by a test
	 * driving stop-then-start at 200ms; every restart script has the
	 * same window. An in-flight teardown is a retryable conflict, never
	 * a success.
	 */
	if (entry != NULL && entry->running && entry->teardown_kind != REGISTRY_TEARDOWN_NONE) {
		respond_error(fd, 409, "Conflict",
		               "this container is being stopped -- retry once the stop completes");
		return;
	}
	if (entry != NULL && entry->running) {
		/* Genuinely live (or paused, which is still running=1) --
		 * start is idempotent, so this is a plain 200, not an error. */
		jw_init(&w);
		registry_write_json_one(entry, &w);
		respond_json(fd, 200, "OK", &w);
		jw_free(&w);
		return;
	}
	if (entry != NULL) {
		/*
		 * ADR-0181 (#73): a NOT-running entry here is a container that
		 * exited on its own and was deliberately retained as its own
		 * "exited" record (real exit code preserved). Starting it must
		 * actually bring it back, not silently 200 the stale exited
		 * entry -- so drop that record first, then replay the persisted
		 * definition below exactly as a stopped-but-defined container's
		 * own start already does.
		 *
		 * ADR-0285: registry_remove() no longer kills anything, and the
		 * guard above means this entry is already not-running, so its
		 * refusal branch cannot be reached from here. The return is
		 * checked anyway -- an unchecked call whose safety rests on an
		 * argument in a comment is the exact shape that produced #448,
		 * and if that argument ever stops holding the operator should
		 * be told why rather than shown a name collision from the
		 * create below.
		 */
		if (registry_remove(name) != 0) {
			respond_error(fd, 409, "Conflict",
			              "could not release this container's registry slot -- see the log "
			              "store for why");
			return;
		}
	}

	def = containerdef_find(name);
	if (def == NULL) {
		respond_error(fd, 404, "Not Found", "no such container");
		return;
	}

	status = create_container_from_body(def->body, def->body_len, &entry, restart_policy,
	                                     &restart_delay_seconds, depends_on, &depends_on_count,
	                                     &follow_rolling,
	                                     &has_follow_rolling_jitter, &follow_rolling_jitter_seconds,
	                                     err_msg, sizeof(err_msg));
	if (status != 0) {
		respond_error(fd, status, http_status_text(status), err_msg);
		return;
	}

	containerdef_set_stopped(name, 0);
	resync_managed_services();

	jw_init(&w);
	registry_write_json_one(entry, &w);
	respond_json(fd, 200, "OK", &w);
	jw_free(&w);
}

/*
 * POST /v1/containers/{name}/pause and .../unpause (ADR-0045): real
 * cgroup v2 freezer control, not SIGSTOP -- freezing stops every task
 * in the cgroup at the kernel level, uninterceptable/unignorable by
 * the frozen process, unlike SIGSTOP which a process can catch or
 * handle. Both require an already-live registry entry (404 otherwise
 * -- pausing a stopped-but-defined or nonexistent container makes no
 * sense, unlike start/stop which are meaningfully defined over
 * persisted definitions too). Unlike start/stop's idempotent-200
 * double-call tolerance, a double-pause or double-unpause is a 409:
 * "is this container already paused" is state a caller should already
 * know from its last GET, and silently no-opping it could mask a real
 * caller bug (e.g. two racing pause requests) that stop/start's own
 * idempotency never has to worry about hiding.
 */
static void handle_pause(int fd, const char *name)
{
	struct registry_entry *e = registry_find(name);
	struct json_writer w;

	if (e == NULL) {
		respond_error(fd, 404, "Not Found", "no such running container");
		return;
	}
	if (e->paused) {
		respond_error(fd, 409, "Conflict", "already paused");
		return;
	}
	if (registry_set_paused(e, 1) != 0) {
		respond_error(fd, 500, "Internal Server Error", "cgroup freeze failed");
		return;
	}

	jw_init(&w);
	registry_write_json_one(e, &w);
	respond_json(fd, 200, "OK", &w);
	jw_free(&w);
}

static void handle_unpause(int fd, const char *name)
{
	struct registry_entry *e = registry_find(name);
	struct json_writer w;

	if (e == NULL) {
		respond_error(fd, 404, "Not Found", "no such running container");
		return;
	}
	if (!e->paused) {
		respond_error(fd, 409, "Conflict", "not paused");
		return;
	}
	if (registry_set_paused(e, 0) != 0) {
		respond_error(fd, 500, "Internal Server Error", "cgroup thaw failed");
		return;
	}

	jw_init(&w);
	registry_write_json_one(e, &w);
	respond_json(fd, 200, "OK", &w);
	jw_free(&w);
}

/*
 * Issue #92: attach/detach a volume on an EXISTING container.
 *
 * Deliberately the opposite posture to POST .../networks, which is live
 * and ephemeral (ADR-0156): these edit the container's own persisted
 * definition and take effect on its NEXT start. A bind mount has to
 * land inside the container's own mount namespace, which only exists
 * between clone3() and pivot_root (ADR-0183) -- attaching to an
 * already-running container needs a primitive to enter another
 * namespace from outside that this daemon does not have. Rather than
 * pretend otherwise, the durable half ships now and says so plainly;
 * the live half stays tracked on #92.
 *
 * Editing the definition body is the whole mechanism -- no second
 * store of "which volumes does this container have", so nothing can
 * disagree with the definition that a restart actually replays.
 */
static void respond_container_volumes(int fd, int status, const char *status_text,
                                       const char *name, const struct json_value *body_root,
                                       const char *applies)
{
	struct json_writer w;

	jw_init(&w);
	jw_obj_open(&w);
	jw_key(&w, "name");
	jw_str(&w, name);
	containerdef_write_json_volumes(body_root, &w);
	jw_key(&w, "applies");
	/* Said explicitly rather than left for the caller to discover.
	 * "now" means the mount is already live in the running container;
	 * "on next start" means the definition is updated and the container
	 * will pick it up when it next starts. */
	jw_str(&w, applies);
	jw_obj_close(&w);
	respond_json(fd, status, status_text, &w);
	jw_free(&w);
}


/*
 * PATCH /v1/containers/{name} (issue #11) -- edit a container's stored
 * definition in place, instead of the delete-and-recreate that was the
 * only way to change a cmd, an env var or a file.
 *
 * Applies at the container's next start, and the response says so
 * rather than leaving the caller to guess. That is not a limitation
 * being papered over: a running process's argv cannot be changed
 * without re-exec'ing it, so "change cmd on a running container" is
 * `restart` by another name, and pretending otherwise would be the
 * kind of half-truth this API is supposed to avoid. What genuinely
 * CAN change live already does, through its own endpoints -- volumes
 * (issue #92) and network attach (ADR-0156).
 *
 * Merge semantics: a key present in the patch replaces that key; a key
 * set to null removes it; everything else is untouched. Top-level only
 * -- a deep merge would make "how do I clear one entry of files[]"
 * unanswerable.
 *
 * The four index fields (restart, depends_on, readiness,
 * follow_rolling) are deliberately refused with a 400 naming them.
 * They feed containerdef's cached index, whose one parser lives in the
 * create path; a second parser here for the same fields is exactly the
 * parallel implementation this project forbids. Lifting that needs
 * that parser extracted first -- a real follow-up, tracked, not a
 * placeholder left in the code.
 */
static void handle_container_patch(int fd, const char *name, const char *body, size_t body_len)
{
	static const char *const index_fields[] = { "restart", "restart_delay_seconds", "depends_on",
		                                        "follow_rolling",
		                                        "follow_rolling_jitter_seconds" };
	struct container_def *def = containerdef_find(name);
	struct registry_entry *e = registry_find(name);
	struct json_value *patch, *current;
	struct json_writer w;
	size_t i, k;
	int rc;

	if (def == NULL) {
		respond_error(fd, 404, "Not Found",
		              "no such container definition -- only a container this daemon has a "
		              "persisted definition for can be edited");
		return;
	}
	patch = json_parse(body, body_len);
	if (patch == NULL || patch->type != JSON_OBJECT) {
		json_free(patch);
		respond_error(fd, 400, "Bad Request", "body must be a JSON object of fields to change");
		return;
	}
	for (i = 0; i < patch->u.object.count; i++) {
		if (strcmp(patch->u.object.keys[i], "name") == 0) {
			json_free(patch);
			respond_error(fd, 400, "Bad Request",
			              "a container's name is its identity -- create a new one instead");
			return;
		}
		for (k = 0; k < sizeof(index_fields) / sizeof(index_fields[0]); k++) {
			if (strcmp(patch->u.object.keys[i], index_fields[k]) != 0)
				continue;
			json_free(patch);
			{
				char msg[256];

				snprintf(msg, sizeof(msg),
				         "'%s' cannot be edited in place yet -- it feeds the definition index, "
				         "whose only parser is the create path; recreate the container to change "
				         "it",
				         index_fields[k]);
				respond_error(fd, 400, "Bad Request", msg);
			}
			return;
		}
	}

	current = json_parse(def->body, def->body_len);
	if (current == NULL || current->type != JSON_OBJECT) {
		json_free(patch);
		json_free(current);
		respond_error(fd, 500, "Internal Server Error",
		              "this container's stored definition could not be parsed");
		return;
	}

	jw_init(&w);
	jw_obj_open(&w);
	for (i = 0; i < current->u.object.count; i++) {
		const struct json_value *replacement = json_object_get(patch, current->u.object.keys[i]);

		/* An explicit null removes the key; anything else replaces it. */
		if (replacement != NULL && replacement->type == JSON_NULL)
			continue;
		jw_key(&w, current->u.object.keys[i]);
		jw_value(&w, replacement != NULL ? replacement : current->u.object.values[i]);
	}
	for (i = 0; i < patch->u.object.count; i++) {
		if (json_object_get(current, patch->u.object.keys[i]) != NULL)
			continue; /* already written above, in the stored body's own order */
		if (patch->u.object.values[i]->type == JSON_NULL)
			continue;
		jw_key(&w, patch->u.object.keys[i]);
		jw_value(&w, patch->u.object.values[i]);
	}
	jw_obj_close(&w);

	if (w.buf == NULL) {
		jw_free(&w);
		json_free(patch);
		json_free(current);
		respond_error(fd, 500, "Internal Server Error", "could not build the updated definition");
		return;
	}
	rc = containerdef_set_body(name, w.buf, w.len);
	jw_free(&w);
	json_free(patch);
	json_free(current);
	if (rc != 0) {
		respond_error(fd, 500, "Internal Server Error", "could not persist the updated definition");
		return;
	}

	def = containerdef_find(name);
	jw_init(&w);
	jw_obj_open(&w);
	jw_key(&w, "name");
	jw_str(&w, name);
	jw_key(&w, "applies");
	jw_str(&w, "next-start");
	jw_key(&w, "restart_required");
	jw_bool(&w, e != NULL && e->running);
	jw_key(&w, "definition");
	{
		struct json_value *merged = json_parse(def->body, def->body_len);

		if (merged != NULL)
			jw_value(&w, merged);
		else
			jw_null(&w);
		json_free(merged);
	}
	jw_obj_close(&w);
	respond_json(fd, 200, "OK", &w);
	jw_free(&w);
}

/*
 * Rewrites def's stored body with `volumes` replaced by new_volumes
 * (which may be NULL to drop the key entirely). Every other field is
 * copied through the parsed tree verbatim.
 */
static int container_def_replace_volumes(struct container_def *def, const struct json_value *root,
                                          const struct json_value *const *new_volumes,
                                          size_t new_count)
{
	struct json_writer w;
	size_t i;
	int rc;

	jw_init(&w);
	jw_obj_open(&w);
	for (i = 0; i < root->u.object.count; i++) {
		if (strcmp(root->u.object.keys[i], "volumes") == 0)
			continue;
		jw_key(&w, root->u.object.keys[i]);
		jw_value(&w, root->u.object.values[i]);
	}
	if (new_count > 0) {
		jw_key(&w, "volumes");
		jw_arr_open(&w);
		for (i = 0; i < new_count; i++)
			jw_value(&w, new_volumes[i]);
		jw_arr_close(&w);
	}
	jw_obj_close(&w);
	if (w.buf == NULL) {
		jw_free(&w);
		return -1;
	}
	rc = containerdef_set_body(def->name, w.buf, w.len);
	jw_free(&w);
	return rc;
}

static void handle_container_volume_attach(int fd, const char *container_name, const char *body,
                                            size_t body_len)
{
	struct container_def *def = containerdef_find(container_name);
	struct json_value *req = NULL;
	struct json_value *root = NULL;
	const struct json_value *jvols;
	const struct json_value *existing[CONTAINER_MAX_VOLUMES + 1];
	size_t count = 0;
	const char *vname;
	const char *vpath;
	char vname_copy[VOLUME_NAME_MAX];
	char vpath_copy[VOLUME_MOUNT_PATH_MAX];
	int ro_copy = 0;
	size_t i;

	if (def == NULL) {
		respond_error(fd, 404, "Not Found", "no such container");
		return;
	}
	req = json_parse(body, body_len);
	if (req == NULL || req->type != JSON_OBJECT) {
		json_free(req);
		respond_error(fd, 400, "Bad Request", "invalid JSON body");
		return;
	}
	vname = json_as_string(json_object_get(req, "name"));
	vpath = json_as_string(json_object_get(req, "path"));
	if (vname == NULL || vpath == NULL || vpath[0] != '/' || !file_path_is_safe(vpath)) {
		json_free(req);
		respond_error(fd, 400, "Bad Request",
		              "name and an absolute path with no '..' are both required");
		return;
	}
	if (volume_find(vname) == NULL) {
		json_free(req);
		respond_error(fd, 404, "Not Found",
		              "no such volume -- create it first (POST /v1/volumes); a container is "
		              "never given a volume that does not already exist");
		return;
	}

	root = json_parse(def->body, def->body_len);
	if (root == NULL || root->type != JSON_OBJECT) {
		json_free(root);
		json_free(req);
		respond_error(fd, 500, "Internal Server Error",
		              "this container's stored definition could not be parsed");
		return;
	}
	jvols = json_object_get(root, "volumes");
	if (jvols != NULL && jvols->type == JSON_ARRAY) {
		for (i = 0; i < jvols->u.array.count && count < CONTAINER_MAX_VOLUMES; i++) {
			const struct json_value *item = jvols->u.array.items[i];
			const char *n = json_as_string(json_object_get(item, "name"));
			const char *pth = json_as_string(json_object_get(item, "path"));

			/* Two different volumes cannot share a mount path, and
			 * the same volume twice is a no-op the caller almost
			 * certainly did not mean -- both are 409 rather than a
			 * silently-ignored duplicate. */
			if (n != NULL && strcmp(n, vname) == 0) {
				json_free(root);
				json_free(req);
				respond_error(fd, 409, "Conflict",
				              "this container already mounts that volume");
				return;
			}
			if (pth != NULL && strcmp(pth, vpath) == 0) {
				json_free(root);
				json_free(req);
				respond_error(fd, 409, "Conflict",
				              "this container already mounts a volume at that path");
				return;
			}
			existing[count++] = item;
		}
	}
	if (count >= CONTAINER_MAX_VOLUMES) {
		json_free(root);
		json_free(req);
		respond_error(fd, 409, "Conflict", "this container already has the maximum volumes");
		return;
	}
	existing[count++] = req;

	/* Copied before the parsed body is freed: the live-attach step
	 * below still needs them, and they point into `req`. */
	{
		const struct json_value *jro2 = json_object_get(req, "read_only");

		snprintf(vname_copy, sizeof(vname_copy), "%s", vname);
		snprintf(vpath_copy, sizeof(vpath_copy), "%s", vpath);
		ro_copy = (jro2 != NULL && jro2->type == JSON_BOOL && jro2->u.boolean);
	}
	if (container_def_replace_volumes(def, root, existing, count) != 0) {
		json_free(root);
		json_free(req);
		respond_error(fd, 500, "Internal Server Error", "could not persist the definition");
		return;
	}
	json_free(root);
	json_free(req);

	/*
	 * Issue #92 part 2: if the container is running, apply it NOW as
	 * well, rather than only on its next start.
	 *
	 * Deliberately after the definition is persisted, not instead of
	 * it. A live-only attach would vanish on the next restart with
	 * nothing to say so, which is the sharp edge ADR-0156's own
	 * live/ephemeral network attach explicitly accepts and documents;
	 * here the durable record is the source of truth and the live mount
	 * is it taking effect early.
	 *
	 * A failure to mount live is reported but does NOT undo the
	 * definition: the volume genuinely is part of this container now,
	 * and it will be there on the next start. Rolling back a correct
	 * definition because one optional step failed would be the worse
	 * outcome.
	 */
	{
		struct registry_entry *e = registry_find(container_name);
		char hostpath[PATH_MAX];
		struct volume *vol = volume_find(vname_copy);
		int live = 0;

		if (e != NULL && e->running && !e->paused && vol != NULL &&
		    volume_host_path(vol, hostpath, sizeof(hostpath)) == 0)
			live = mountns_bind_into(e->handle.pid, hostpath, vpath_copy, ro_copy) == 0;

		def = containerdef_find(container_name);
		root = def != NULL ? json_parse(def->body, def->body_len) : NULL;
		respond_container_volumes(fd, 200, "OK", container_name, root,
		                           e != NULL && e->running ? (live ? "now" : "on next start")
		                                                   : "on next start");
		json_free(root);
	}
}

static void handle_container_volume_detach(int fd, const char *container_name,
                                            const char *volume_name)
{
	struct container_def *def = containerdef_find(container_name);
	struct json_value *root;
	const struct json_value *jvols;
	const struct json_value *kept[CONTAINER_MAX_VOLUMES];
	size_t count = 0;
	int found = 0;
	size_t i;

	if (def == NULL) {
		respond_error(fd, 404, "Not Found", "no such container");
		return;
	}
	root = json_parse(def->body, def->body_len);
	if (root == NULL || root->type != JSON_OBJECT) {
		json_free(root);
		respond_error(fd, 500, "Internal Server Error",
		              "this container's stored definition could not be parsed");
		return;
	}
	jvols = json_object_get(root, "volumes");
	if (jvols != NULL && jvols->type == JSON_ARRAY) {
		for (i = 0; i < jvols->u.array.count && count < CONTAINER_MAX_VOLUMES; i++) {
			const struct json_value *item = jvols->u.array.items[i];
			const char *n = json_as_string(json_object_get(item, "name"));

			if (n != NULL && strcmp(n, volume_name) == 0) {
				found = 1;
				continue;
			}
			kept[count++] = item;
		}
	}
	if (!found) {
		json_free(root);
		respond_error(fd, 404, "Not Found", "this container does not mount that volume");
		return;
	}
	if (container_def_replace_volumes(def, root, kept, count) != 0) {
		json_free(root);
		respond_error(fd, 500, "Internal Server Error", "could not persist the definition");
		return;
	}
	json_free(root);

	def = containerdef_find(container_name);
	root = def != NULL ? json_parse(def->body, def->body_len) : NULL;
	respond_container_volumes(fd, 200, "OK", container_name, root, "on next start");
	json_free(root);
}

/*
 * POST /v1/containers/{name}/networks (ADR-0156, task #861): attaches
 * one more network to an ALREADY-RUNNING container, live -- no
 * recreate. Deliberately LIVE and EPHEMERAL, the same posture ADR-0153
 * already established for PUT .../files: never touches the
 * container's own persisted create-request body, so a future restart
 * or recreate replays the original definition, this attachment gone.
 * If it needs to survive a recreate, the durable path is editing the
 * container's own definition (a container recipe, ADR-0151) and
 * re-applying it -- not this endpoint, same division of responsibility
 * ADR-0153 already drew for files.
 *
 * Body shape is deliberately identical to one entry of POST
 * /containers' own "networks" array (parse_network_entry(), reused
 * verbatim) -- a bare network-name string for an auto-allocated IP, or
 * {"name":..., "ip":...} for an operator-chosen one.
 */
static void handle_container_network_attach(int fd, const char *container_name, const char *body,
                                              size_t body_len)
{
	struct registry_entry *e;
	struct json_value *root;
	char net_name[NETWORK_NAME_MAX];
	uint32_t ip_be;
	int has_ip;
	struct network_def *net;
	struct registry_network_attachment att;
	char veth_host[16], veth_ctr[16], ifname[16];
	char chosen_ifname[16];
	char chosen_bridge[16];
	int prc;
	struct json_writer w;
	int i;

	e = registry_find(container_name);
	if (e == NULL || !e->running) {
		respond_error(fd, 404, "Not Found", "no such running container");
		return;
	}

	root = json_parse(body, body_len);
	if (root == NULL) {
		respond_error(fd, 400, "Bad Request", "invalid JSON body");
		return;
	}
	prc = parse_network_entry(root, net_name, sizeof(net_name), &ip_be, &has_ip, chosen_ifname,
	                           sizeof(chosen_ifname), chosen_bridge, sizeof(chosen_bridge));
	if (prc == -3) {
		json_free(root);
		respond_error(fd, 400, "Bad Request",
		              "container_bridge must be 1-15 characters of [A-Za-z0-9._-], and may "
		              "not be \"lo\" or an \"eth<N>\" name");
		return;
	}
	if (prc == 0 && chosen_bridge[0] != '\0') {
		/*
		 * ADR-0264 is a creation-time capability, and saying so is
		 * better than accepting the field and ignoring it. Building the
		 * bridge means acting inside the container's own netns, which
		 * this path cannot do -- it has no setns() primitive, the same
		 * reason route_spec is documented as create-time only.
		 */
		json_free(root);
		respond_error(fd, 400, "Bad Request",
		              "container_bridge can only be set when the container is created -- "
		              "attaching a network to a running container cannot build a bridge "
		              "inside its network namespace");
		return;
	}
	if (prc == -2) {
		json_free(root);
		respond_error(fd, 400, "Bad Request",
		              "ifname must be 1-15 characters of [A-Za-z0-9._-], and may not be "
		              "\"lo\" or an \"eth<N>\" name (those are what this platform assigns "
		              "to unnamed attachments)");
		return;
	}
	if (prc != 0) {
		json_free(root);
		respond_error(fd, 400, "Bad Request", "invalid network entry");
		return;
	}
	json_free(root);

	net = network_find(net_name);
	if (net == NULL) {
		respond_error(fd, 404, "Not Found", "no such network");
		return;
	}
	for (i = 0; i < e->net_count; i++) {
		if (strcmp(e->nets[i].name, net_name) == 0) {
			respond_error(fd, 409, "Conflict", "already attached to this network");
			return;
		}
	}
	if (e->net_count >= CONTAINER_MAX_NETWORKS) {
		respond_error(fd, 409, "Conflict", "container already has the maximum number of networks");
		return;
	}

	if (has_ip) {
		if (network_ip_available(net_name, ip_be) != NETWORK_OK) {
			respond_error(fd, 400, "Bad Request", "ip is not available on this network");
			return;
		}
	} else {
		int arc = network_alloc_ip(net_name, &ip_be);

		if (arc == -2) {
			/* Issue #137 -- see the container-create site for the reasoning. */
			respond_error(fd, 409, "Conflict",
			              "this network is bridged to a physical interface and has no declared "
			              "allocation pool, so auto-allocating an address could collide with "
			              "equipment on that LAN. Pass an explicit ip, or declare the pool "
			              "(network create --alloc-start=/--alloc-end=).");
			return;
		}
		if (arc != 0) {
			respond_error(fd, 500, "Internal Server Error", "no free IP addresses");
			return;
		}
	}

	/* Same vh<pid>-<idx>/vc<pid>-<idx> naming scheme
	 * container_net_host_setup() uses at create time -- "a<idx>" instead
	 * of a bare "<idx>" only to keep a live-attached veth's own name
	 * visibly distinct from a create-time one at a glance (both are
	 * already guaranteed collision-free by pid+idx alone). idx is this
	 * container's own net_count *before* this attachment, exactly like
	 * create-time attachments' own idx is their position in that same
	 * array -- collision-free against both earlier create-time and
	 * earlier live attachments. */
	snprintf(veth_host, sizeof(veth_host), "vh%d-a%d", (int)e->handle.pid, e->net_count);
	snprintf(veth_ctr, sizeof(veth_ctr), "vc%d-a%d", (int)e->handle.pid, e->net_count);
	/*
	 * ADR-0259: the operator's name if given, else the positional
	 * default. Uniqueness is checked against the attachments this
	 * container already has -- an explicit "eth<N>" is refused by
	 * container_ifname_is_valid(), so a chosen name can never collide
	 * with a default this container was given earlier.
	 */
	if (chosen_ifname[0] != '\0')
		snprintf(ifname, sizeof(ifname), "%s", chosen_ifname);
	else
		snprintf(ifname, sizeof(ifname), "eth%d", e->net_count);
	for (i = 0; i < e->net_count; i++) {
		if (strcmp(e->nets[i].ifname, ifname) == 0) {
			respond_error(fd, 409, "Conflict",
			              "this container already has an interface with that name");
			return;
		}
	}

	if (container_net_attach_running(net->name, ip_be, net->prefix_len, e->handle.pid, veth_host,
	                                  veth_ctr, ifname) != 0) {
		respond_error(fd, 500, "Internal Server Error", "failed to attach network");
		return;
	}

	memset(&att, 0, sizeof(att));
	strncpy(att.name, net_name, sizeof(att.name) - 1);
	att.ip_be = ip_be;
	strncpy(att.veth_host, veth_host, sizeof(att.veth_host) - 1);
	strncpy(att.ifname, ifname, sizeof(att.ifname) - 1);
	if (registry_network_attach(e, &att) != 0) {
		/* Shouldn't happen (bounds/dup already checked above) but the
		 * veth pair is already live at this point -- tear it back down
		 * rather than leaving an orphan the registry doesn't know
		 * about. */
		container_net_detach_running(veth_host);
		respond_error(fd, 500, "Internal Server Error", "failed to record network attachment");
		return;
	}

	jw_init(&w);
	registry_write_json_one(e, &w);
	respond_json(fd, 200, "OK", &w);
	jw_free(&w);
}

/*
 * DELETE /v1/containers/{name}/networks/{network} (ADR-0156, task #861):
 * the reverse of the above. Only ever removes a LIVE attachment (its
 * own veth_host is non-empty) -- a network attached the ordinary way,
 * at container creation, has no standalone detach path (same
 * reasoning ADR-0153 gives for why a create-time "files[]" entry isn't
 * independently removable either): tearing it down mid-life would
 * silently diverge the running container from its own persisted
 * definition in a way nothing else in this API does.
 */
static void handle_container_network_detach(int fd, const char *container_name,
                                              const char *network_name)
{
	struct registry_entry *e;
	struct registry_network_attachment removed;
	struct json_writer w;
	int i;
	int is_live = 0;

	e = registry_find(container_name);
	if (e == NULL || !e->running) {
		respond_error(fd, 404, "Not Found", "no such running container");
		return;
	}
	for (i = 0; i < e->net_count; i++) {
		if (strcmp(e->nets[i].name, network_name) == 0) {
			is_live = e->nets[i].veth_host[0] != '\0';
			break;
		}
	}
	if (i == e->net_count) {
		respond_error(fd, 404, "Not Found", "not attached to this network");
		return;
	}
	if (!is_live) {
		respond_error(fd, 409, "Conflict",
		              "this network was attached at container creation, not live -- recreate the "
		              "container to remove it");
		return;
	}

	if (registry_network_detach(e, network_name, &removed) != 0) {
		respond_error(fd, 500, "Internal Server Error", "failed to update registry");
		return;
	}
	if (container_net_detach_running(removed.veth_host) != 0) {
		/* Registry already updated (GET now correctly shows it gone) --
		 * a real, orphaned host-side veth left over from a failed
		 * delete is a rare kernel-level failure, not something worth
		 * re-adding the registry entry over (that would just make GET
		 * lie about the network being reachable, which it now isn't
		 * either way). */
		fprintf(stderr, "%s: failed to remove live veth %s for network %s\n", container_name,
		        removed.veth_host, network_name);
	}

	jw_init(&w);
	registry_write_json_one(e, &w);
	respond_json(fd, 200, "OK", &w);
	jw_free(&w);
}

/*
 * ADR-0161 Phase D: mknod()s dev's own node directly into an already-
 * running container's private /dev, reaching in via /proc/<pid>/root
 * -- the identical host-side mechanism ADR-0153's own live file write
 * (handle_container_file_write() above) already established and
 * proved correct, reused rather than re-invented for the mknod half
 * (container_dev_mknod() itself, src/container_dev.c, is CHILD-side
 * code -- it mknod()s at dev->dev_path directly, correct only when
 * already inside the target mount namespace post-pivot, which a
 * live-attach call from this daemon process never is). Real 0666
 * mode plus an explicit chmod() after mknod(), same reasoning
 * container_dev_mknod()'s own comment gives (this project's
 * containers run as full root with no user namespace, so the real
 * access gate is the BPF program, not these POSIX bits; mknod()'s
 * own requested mode is subject to this daemon's own umask).
 */
static int live_mknod_device(const struct registry_entry *e, const struct device_spec *dev)
{
	char full_path[PATH_MAX];
	char target_dir[PATH_MAX];
	char *slash;
	mode_t mode;

	/* Host-side tree, not the container's own id-mapped view (#269):
	 * a node created through that view never arrives. */
	container_file_host_path(e->name, e->disk_name, dev->dev_path, full_path, sizeof(full_path));
	snprintf(target_dir, sizeof(target_dir), "%s", full_path);
	slash = strrchr(target_dir, '/');
	if (slash != NULL && slash != target_dir) {
		*slash = '\0';
		if (persist_mkdir_p(target_dir) != 0)
			return -1;
	}

	mode = (mode_t)((dev->type == DEVICE_NODE_BLOCK ? S_IFBLK : S_IFCHR) | 0666);
	if (mknod(full_path, mode, makedev(dev->major, dev->minor)) != 0 && errno != EEXIST)
		return -1;
	if (chmod(full_path, mode & 07777) != 0)
		return -1;
	return 0;
}

static int live_unlink_device(const struct registry_entry *e, const char *dev_path)
{
	char full_path[PATH_MAX];

	container_file_host_path(e->name, e->disk_name, dev_path, full_path, sizeof(full_path));
	if (full_path[0] == '\0') {
		errno = ENAMETOOLONG;
		return -1;
	}
	if (unlink(full_path) != 0 && errno != ENOENT)
		return -1;
	return 0;
}

/*
 * ADR-0161 Phase D: live-grants one already-resolved device to an
 * already-running container -- the real work shared by both the
 * manual POST /v1/containers/{name}/devices handler below and Phase
 * C's hotplug listener (handle_uevent_add()), so hotplug automation
 * is just another caller of this same primitive, not a separate code
 * path (the same two-layer shape ADR-0156 already established for
 * networks). BPF grant first (registry_device_live_attach(), atomic
 * replace, empirically verified safe -- see the ADR's own "Phase D
 * verification"), mknod second; on a live_mknod_device() failure the
 * BPF grant is rolled back rather than left dangling (permission
 * granted with no node to open it through is inert but not something
 * this daemon's own bookkeeping should silently carry forward).
 * Returns 0 on success, -1 (errno set) otherwise.
 */
static int live_attach_one_device(struct registry_entry *e, const struct discovered_device *dd,
                                   int shared)
{
	struct device_spec dev;
	struct registry_device_attachment att;

	memset(&dev, 0, sizeof(dev));
	dev.type = dd->type;
	dev.major = dd->major;
	dev.minor = dd->minor;
	snprintf(dev.dev_path, sizeof(dev.dev_path), "%s", dd->dev_path);

	memset(&att, 0, sizeof(att));
	snprintf(att.id, sizeof(att.id), "%s", dd->id);
	snprintf(att.dev_path, sizeof(att.dev_path), "%s", dd->dev_path);
	att.type = dd->type;
	att.major = dd->major;
	att.minor = dd->minor;
	att.live = 1;
	att.shared = shared;

	if (registry_device_live_attach(e, &dev, &att) != 0)
		return -1;

	if (live_mknod_device(e, &dev) != 0) {
		int saved_errno = errno;
		struct registry_device_attachment removed;

		registry_device_live_detach(e, dd->id, &removed);
		errno = saved_errno;
		return -1;
	}
	return 0;
}

/*
 * POST /v1/containers/{name}/devices (ADR-0161 Phase D): attaches one
 * more device to an ALREADY-RUNNING container, live -- no recreate.
 * Deliberately LIVE and EPHEMERAL, the same posture ADR-0153/ADR-0156
 * already established for files/networks: never touches the
 * container's own persisted create-request body.
 *
 * Body shape matches one entry of POST /containers' own "devices"
 * array bare-string form -- id is resolved exactly like a creation-
 * time entry is (devicemap_resolve() first, device_find_group()
 * fallback), so a grouped id (e.g. "gpu:0") can still expand into
 * more than one grant in a single call.
 */
static void handle_container_device_attach(int fd, const char *container_name, const char *body,
                                             size_t body_len)
{
	struct registry_entry *e;
	struct json_value *root;
	const char *id;
	const struct discovered_device *matches[CONTAINER_MAX_DEVICES];
	int n, j, attached;
	int shared = 0;
	struct json_writer w;

	e = registry_find(container_name);
	if (e == NULL || !e->running) {
		respond_error(fd, 404, "Not Found", "no such running container");
		return;
	}

	root = json_parse(body, body_len);
	if (root == NULL) {
		respond_error(fd, 400, "Bad Request", "invalid JSON body");
		return;
	}
	id = json_as_string(json_object_get(root, "id"));
	if (id == NULL) {
		json_free(root);
		respond_error(fd, 400, "Bad Request", "id is required");
		return;
	}
	{
		const struct json_value *jshared = json_object_get(root, "shared");

		if (jshared != NULL) {
			if (jshared->type != JSON_BOOL) {
				json_free(root);
				respond_error(fd, 400, "Bad Request", "shared must be a boolean");
				return;
			}
			shared = jshared->u.boolean;
		}
	}

	n = devicemap_resolve(id, CONTAINERS_DIR, matches, CONTAINER_MAX_DEVICES - e->device_count);
	if (n < 0)
		n = device_find_group(id, CONTAINERS_DIR, matches,
		                       CONTAINER_MAX_DEVICES - e->device_count);
	if (n <= 0) {
		json_free(root);
		respond_error(fd, 404, "Not Found",
		              "unknown, unassignable, or not-currently-present device");
		return;
	}
	if (e->device_count + n > CONTAINER_MAX_DEVICES) {
		json_free(root);
		respond_error(fd, 409, "Conflict", "container already has the maximum number of devices");
		return;
	}
	for (j = 0; j < n; j++) {
		char holder[REGISTRY_NAME_MAX];

		if (!matches[j]->assignable) {
			json_free(root);
			respond_error(fd, 400, "Bad Request", "device is not currently assignable");
			return;
		}
		/*
		 * #356, the same rule the create path applies: already held by
		 * a running container means refused unless both grants say so.
		 * Checked before anything is attached, so a grouped id whose
		 * second member is contended does not leave the first granted.
		 */
		if (registry_device_grant_conflict(matches[j]->id, shared, holder, sizeof(holder))) {
			char msg[256];

			snprintf(msg, sizeof(msg),
			         "device %s is already held by container \"%s\" -- both grants must set "
			         "\"shared\": true to share it",
			         matches[j]->id, holder);
			json_free(root);
			respond_error(fd, 409, "Conflict", msg);
			return;
		}
	}
	json_free(root);

	for (attached = 0; attached < n; attached++) {
		if (live_attach_one_device(e, matches[attached], shared) != 0)
			break;
	}
	if (attached < n) {
		/* Partial group failure -- unwind exactly what this call itself
		 * just granted (never anything the container already had
		 * before this request), same "leave no half-applied state"
		 * posture live_attach_one_device() itself already has for a
		 * single grant's own BPF-vs-mknod half. */
		int k;
		struct registry_device_attachment removed;

		for (k = 0; k < attached; k++) {
			registry_device_live_detach(e, matches[k]->id, &removed);
			live_unlink_device(e, matches[k]->dev_path);
		}
		respond_error(fd, 500, "Internal Server Error", "failed to attach device");
		return;
	}

	jw_init(&w);
	registry_write_json_one(e, &w);
	respond_json(fd, 200, "OK", &w);
	jw_free(&w);
}

/*
 * DELETE /v1/containers/{name}/devices/{id} (ADR-0161 Phase D): the
 * reverse of the above. Refuses (409) a device that was granted at
 * container creation time (registry_device_live_detach()'s own -2)
 * -- no standalone detach path for one of those, the same rule
 * registry_network_detach() already enforces for networks.
 */
static void handle_container_device_detach(int fd, const char *container_name, const char *id)
{
	struct registry_entry *e;
	struct registry_device_attachment removed;
	int i;
	int is_live = 0;
	struct json_writer w;

	e = registry_find(container_name);
	if (e == NULL || !e->running) {
		respond_error(fd, 404, "Not Found", "no such running container");
		return;
	}
	for (i = 0; i < e->device_count; i++) {
		if (strcmp(e->devices[i].id, id) == 0) {
			is_live = e->devices[i].live;
			break;
		}
	}
	if (i == e->device_count) {
		respond_error(fd, 404, "Not Found", "not attached to this device");
		return;
	}
	if (!is_live) {
		respond_error(fd, 409, "Conflict",
		              "this device was attached at container creation, not live -- recreate the "
		              "container to remove it");
		return;
	}

	if (registry_device_live_detach(e, id, &removed) != 0) {
		respond_error(fd, 500, "Internal Server Error", "failed to update device grant");
		return;
	}
	if (live_unlink_device(e, removed.dev_path) != 0)
		fprintf(stderr, "%s: failed to remove live device node %s (id %s)\n", container_name,
		        removed.dev_path, id);

	jw_init(&w);
	registry_write_json_one(e, &w);
	respond_json(fd, 200, "OK", &w);
	jw_free(&w);
}

/*
 * GET /v1/containers/{name}/files?path=... (ADR-0055): the read-path
 * counterpart to the create-time "files[]" staging (which is write-
 * only, host->container, pre-clone3()) -- reads one file's raw bytes
 * back out of a container's rootfs, running or exited-but-not-removed.
 *
 * Path resolution branches on liveness, same reasoning ADR-0013's own
 * write path already established for a *running* container (a stale
 * registry_entry.handle.pid is never safe to trust once running==0 --
 * pids get reused -- so /proc/<pid>/root only applies while running==1):
 *   running   -> /proc/<pid>/root<path>  (kernel resolves through the
 *                container's own mount namespace/root, no setns()) --
 *                and, if that misses, the on-disk layers below too:
 *                running == 1 only means this daemon hasn't PROCESSED
 *                the exit yet, so /proc/<pid> can already be gone for a
 *                container that died the instant it started.
 *   !running  -> <CONTAINERS_DIR>/<name>/upper<path> first (the COW
 *                upper layer the container itself wrote to -- still a
 *                real host directory even after every process in the
 *                overlay's own mount namespace has exited), falling
 *                back to <IMAGES_DIR>/<image>/rootfs<path> (the shared,
 *                read-only lowerdir -- entry->image survives exit).
 *
 * Response is this daemon's first non-JSON body: raw bytes via
 * http_write_response(), same primitive/pattern staticfile.c's own
 * static_serve() already uses for the web dashboard's static assets.
 */
/*
 * Issue #61: list a directory inside a container.
 *
 * A path resolving to a directory was a 400 with no alternative, so
 * post-mortem navigation was blind path-guessing -- finding gcc's
 * include-fixed tree during the Part 201 investigation took several
 * probe recipes that one listing call would have replaced.
 *
 * A RUNNING container is listed through /proc/<pid>/root, which is the
 * kernel's own merged overlay view: correct by construction, whiteouts
 * and all.
 *
 * An EXITED one has no such view, so its two layers are merged here --
 * upper first, then lower for anything upper did not have. That needs
 * whiteouts handled properly rather than ignored: overlayfs marks a
 * deleted file with a character device of rdev 0 in the upper layer, so
 * listing naively would show a file the container had deleted, which is
 * a listing that lies. Those entries are skipped AND suppress the
 * lower-layer name behind them, which is what deletion means.
 *
 * Opaque directories (a directory replaced wholesale, marked with the
 * trusted.overlay.opaque xattr) are NOT handled -- reading xattrs adds
 * a dependency for a case this daemon never creates, and the failure
 * mode is showing a stale name rather than hiding a real one.
 */
static int dirent_is_whiteout(const char *dir, const char *name)
{
	char path[PATH_MAX];
	struct stat st;

	snprintf(path, sizeof(path), "%s/%s", dir, name);
	if (lstat(path, &st) != 0)
		return 0;
	return S_ISCHR(st.st_mode) && st.st_rdev == 0;
}

static void handle_container_dir_list(int fd, const char *name, const char *rel_path)
{
	struct registry_entry *e = registry_find(name);
	char dirs[2][PATH_MAX];
	int dir_count = 0;
	char seen[512][256];
	int seen_count = 0;
	struct json_writer w;
	struct stat st;
	int i;
	int any = 0;

	if (e == NULL) {
		respond_error(fd, 404, "Not Found", "no such container");
		return;
	}
	if (e->running) {
		snprintf(dirs[0], sizeof(dirs[0]), "/proc/%d/root%s", (int)e->handle.pid, rel_path);
		if (stat(dirs[0], &st) == 0 && S_ISDIR(st.st_mode))
			dir_count = 1;
	}
	if (dir_count == 0) {
		char container_root[PATH_MAX];

		container_root_for(e->disk_name, container_root, sizeof(container_root));
		container_writable_path(container_root, name, rel_path, dirs[0], sizeof(dirs[0]));
		if (stat(dirs[0], &st) == 0 && S_ISDIR(st.st_mode))
			dir_count = 1;
		if (e->lowerdir[0] != '\0') {
			snprintf(dirs[dir_count], sizeof(dirs[dir_count]), "%s%s", e->lowerdir, rel_path);
			if (stat(dirs[dir_count], &st) == 0 && S_ISDIR(st.st_mode))
				dir_count++;
		}
	}
	if (dir_count == 0) {
		respond_error(fd, 404, "Not Found", "no such directory");
		return;
	}

	jw_init(&w);
	jw_obj_open(&w);
	jw_key(&w, "path");
	jw_str(&w, rel_path);
	jw_key(&w, "entries");
	jw_arr_open(&w);
	for (i = 0; i < dir_count; i++) {
		DIR *d = opendir(dirs[i]);
		struct dirent *de;

		if (d == NULL)
			continue;
		any = 1;
		while ((de = readdir(d)) != NULL && seen_count < 512) {
			char entry_path[PATH_MAX];
			struct stat est;
			int dup = 0;
			int k;

			if (strcmp(de->d_name, ".") == 0 || strcmp(de->d_name, "..") == 0)
				continue;
			for (k = 0; k < seen_count; k++) {
				if (strcmp(seen[k], de->d_name) == 0) {
					dup = 1;
					break;
				}
			}
			if (dup)
				continue;
			/* Record the name before deciding whether to emit it: a
			 * whiteout must also hide the lower layer's copy, which is
			 * the whole point of it. */
			snprintf(seen[seen_count], sizeof(seen[seen_count]), "%s", de->d_name);
			seen_count++;
			if (dirent_is_whiteout(dirs[i], de->d_name))
				continue;

			snprintf(entry_path, sizeof(entry_path), "%s/%s", dirs[i], de->d_name);
			jw_obj_open(&w);
			jw_key(&w, "name");
			jw_str(&w, de->d_name);
			jw_key(&w, "type");
			if (lstat(entry_path, &est) == 0)
				jw_str(&w, S_ISDIR(est.st_mode)    ? "dir"
				           : S_ISLNK(est.st_mode)  ? "symlink"
				           : S_ISREG(est.st_mode)  ? "file"
				                                   : "other");
			else
				jw_str(&w, "unknown");
			jw_key(&w, "size");
			jw_int(&w, (lstat(entry_path, &est) == 0 && S_ISREG(est.st_mode))
			               ? (long long)est.st_size
			               : 0);
			jw_obj_close(&w);
		}
		closedir(d);
	}
	jw_arr_close(&w);
	jw_key(&w, "truncated");
	/* Said rather than implied: a directory with more entries than the
	 * cap would otherwise look complete and short. */
	jw_bool(&w, seen_count >= 512);
	jw_obj_close(&w);
	if (!any) {
		jw_free(&w);
		respond_error(fd, 404, "Not Found", "no such directory");
		return;
	}
	respond_json(fd, 200, "OK", &w);
	jw_free(&w);
}

/*
 * Cap on a file whose stat() size is 0 (procfs/sysfs), read to EOF.
 * Generous next to the kilobytes these files actually hold, and finite
 * so a synthetic file that never ends cannot exhaust the daemon.
 */
#define FILE_STREAM_READ_MAX (4u * 1024u * 1024u)

static void handle_container_file_read(int fd, const char *name, const char *rel_path)
{
	struct registry_entry *e = registry_find(name);
	char container_root[PATH_MAX];
	int stopped = 0;
	const char *source; /* #394: which tree actually answered */
	char full_path[PATH_MAX];
	int file_fd;
	struct stat st;
	char *buf;
	size_t total;

	if (e == NULL) {
		/* Issue #162: no entry does not mean no container. */
		if (container_root_from_def(name, container_root, sizeof(container_root)) != 0) {
			respond_error(fd, 404, "Not Found", "no such container");
			return;
		}
		stopped = 1;
	}
	if (rel_path == NULL || rel_path[0] != '/' || strlen(rel_path) >= CONTAINER_FILE_PATH_MAX ||
	    !file_path_is_safe(rel_path)) {
		respond_error(fd, 400, "Bad Request", "invalid or missing path");
		return;
	}

	file_fd = -1;
	/*
	 * #394: WHICH tree answered. A 200 used to mean only "some tree the
	 * daemon can reach has these bytes", and the caller could not tell
	 * whether that was the tree the container is actually running from.
	 * That made the endpoint unusable for the question everyone asks it
	 * -- what does this container see -- and it was believed over a
	 * shell inside the container twice, because 2 MB of valid ELF looks
	 * like proof.
	 */
	source = "none";
	if (!stopped && e->running) {
		snprintf(full_path, sizeof(full_path), "/proc/%d/root%s", (int)e->handle.pid, rel_path);
		file_fd = open(full_path, O_RDONLY);
		if (file_fd >= 0)
			source = "container";
	}
	/*
	 * Fall through to the on-disk layers whenever the /proc path didn't
	 * produce the file -- not only when running == 0. running == 1 means
	 * "this daemon has not yet PROCESSED the exit", not "the process is
	 * definitely alive": a container whose own exec fails (or which exits
	 * the instant it starts) is genuinely dead while its pidfd event is
	 * still sitting unread in epoll, and /proc/<pid> is already gone by
	 * then. Without this fallback such a read 404s purely on event timing
	 * -- observed deterministically via a recipe-applied container running
	 * a cmd its image doesn't actually contain, where the staged file was
	 * sitting in the upper layer the whole time. Reading the layers is
	 * always safe here: they are this container's OWN directories, keyed
	 * by name, never a reused pid.
	 */
	if (file_fd < 0) {
		if (!stopped)
			container_root_for(e->disk_name, container_root, sizeof(container_root));
		container_writable_path(container_root, name, rel_path, full_path, sizeof(full_path));
		file_fd = open(full_path, O_RDONLY);
		if (file_fd >= 0)
			source = "writable";
		if (file_fd < 0 && !stopped) {
			/*
			 * Not in the upper layer -- fall back to the container's
			 * own read-only lowerdir, i.e. the exact tree its overlay
			 * was actually built on (entry->lowerdir, recorded verbatim
			 * at creation time). Issue #61: this used to RECONSTRUCT
			 * that path from image/image_version instead, which works
			 * only for an ordinary container. A build container
			 * ("__pkgbuild-N") is registered under the synthetic image
			 * name "pkgbuild" with an empty version, so both branches of
			 * that reconstruction missed and it fell through to an EMPTY
			 * prefix -- turning the read into a bare open() of rel_path
			 * on the HOST filesystem. That both failed to find real
			 * lowerdir content (the reported bug: /usr/bin/gcc 404ing on
			 * a preserved build container while /build/* worked) and, far
			 * worse, could serve the daemon host's OWN file at that path
			 * through a per-container endpoint. Using the recorded
			 * lowerdir fixes both at once and keeps ADR-0107/0108's
			 * guarantee intact -- for an ordinary container this IS the
			 * pinned image-version rootfs, byte-for-byte the same path
			 * the reconstruction produced, never the image's current
			 * version.
			 *
			 * This comment used to end "an empty lowerdir (userns
			 * containers, which have no overlay) correctly reads as no
			 * fallback". That is FALSE and it is what made this
			 * fallback invisible when reading the code: spec.ov.lowerdir
			 * is assigned unconditionally at container creation and
			 * recorded by registry.c, so a userns container has a
			 * perfectly good lowerdir and DOES fall through to it. That
			 * is the whole of #394 -- the endpoint answered 200 with the
			 * image's copy of a file the container did not have.
			 */
			if (e->lowerdir[0] != '\0') {
				snprintf(full_path, sizeof(full_path), "%s%s", e->lowerdir, rel_path);
				file_fd = open(full_path, O_RDONLY);
				if (file_fd >= 0)
					source = "image";
			}
		}
	}
	if (file_fd < 0) {
		respond_error(fd, 404, "Not Found", "no such file");
		return;
	}
	if (fstat(file_fd, &st) != 0) {
		close(file_fd);
		respond_error(fd, 500, "Internal Server Error", "stat failed");
		return;
	}
	if (S_ISDIR(st.st_mode)) {
		close(file_fd);
		respond_error(fd, 400, "Bad Request", "path is a directory, not a file");
		return;
	}

	/*
	 * Two different kinds of file reach this point, and only one of
	 * them can be read by its stat() size.
	 *
	 * An ordinary file reports a real st_size and is read to exactly
	 * that -- unchanged, and still the common case.
	 *
	 * A procfs or sysfs file reports st_size == 0 and yields its
	 * content only to a read that runs to EOF. The size-bounded loop
	 * below used to allocate nothing, read nothing, and answer 200
	 * with an EMPTY BODY -- a success carrying no data, which is the
	 * worst shape a failure can take: every caller believed it had
	 * read the file and simply found it empty. That cost real
	 * diagnostic work here, because /proc/self/mountinfo and
	 * /proc/meminfo are exactly how one asks a running container what
	 * it actually sees, and this endpoint silently answered "nothing"
	 * to both.
	 *
	 * Grow-until-EOF, capped: these files are kilobytes, and the cap
	 * exists so an endless synthetic file cannot exhaust the daemon.
	 */
	total = 0;
	if (st.st_size > 0) {
		buf = malloc((size_t)st.st_size);
		if (buf == NULL) {
			close(file_fd);
			respond_error(fd, 500, "Internal Server Error", "out of memory");
			return;
		}
		while (total < (size_t)st.st_size) {
			ssize_t n = read(file_fd, buf + total, (size_t)st.st_size - total);

			if (n <= 0)
				break;
			total += (size_t)n;
		}
	} else {
		size_t cap = 65536;

		buf = malloc(cap);
		if (buf == NULL) {
			close(file_fd);
			respond_error(fd, 500, "Internal Server Error", "out of memory");
			return;
		}
		for (;;) {
			ssize_t n;

			if (total == cap) {
				char *bigger;

				if (cap >= FILE_STREAM_READ_MAX)
					break;
				cap *= 2;
				bigger = realloc(buf, cap);
				if (bigger == NULL) {
					free(buf);
					close(file_fd);
					respond_error(fd, 500, "Internal Server Error", "out of memory");
					return;
				}
				buf = bigger;
			}
			n = read(file_fd, buf + total, cap - total);
			if (n <= 0)
				break;
			total += (size_t)n;
		}
	}
	close(file_fd);

	/*
	 * Issue #139: report the file's own metadata alongside its bytes.
	 *
	 * Without this the endpoint could not round-trip what it stores: a
	 * tool copying an installed tree got content and nothing else, so
	 * every binary it wrote came out 0644. That is not hypothetical --
	 * package artifacts built exactly that way installed dnsmasq
	 * non-executable, verified their checksums perfectly, and failed
	 * far away at execve with an error naming permissions rather than
	 * the artifact. Integrity was checked end to end; usability never
	 * was.
	 *
	 * st was already stat()ed above for the directory check, so this
	 * costs nothing. Headers, not a JSON envelope: the body stays the
	 * exact bytes it has always been, so every existing consumer is
	 * unaffected.
	 */
	{
		char meta[160];

		snprintf(meta, sizeof(meta),
		         "X-Cix-Mode: 0%o\r\n"
		         "X-Cix-Uid: %u\r\n"
		         "X-Cix-Gid: %u\r\n"
		         "X-Cix-Source: %s\r\n"
		         "X-Cix-Size: %lld\r\n",
		         (unsigned)(st.st_mode & 07777), (unsigned)st.st_uid, (unsigned)st.st_gid,
		         source, /* #394: container | writable | image */
		         /*
		          * The bytes actually served. For an ordinary file that
		          * is st_size; for a procfs file st_size is 0 and the
		          * only true size is what the read produced.
		          */
		         (long long)(st.st_size > 0 ? (long long)st.st_size : (long long)total));
		http_set_blocking(fd);
		http_write_response_hdrs(fd, 200, "OK", "application/octet-stream", meta, buf, total);
	}
	free(buf);
}

/*
 * PUT /v1/containers/{name}/files?path=... (ADR-0153, task #861): the
 * write-path counterpart to handle_container_file_read() immediately
 * above -- same running/!running path resolution (running:
 * /proc/<pid>/root<path>, kernel-resolved through the container's own
 * mount namespace, no setns() needed; !running: <containers-dir>/
 * <name>/upper<path> directly, the same real host directory overlay_
 * create() already mounts as the upper layer). Reuses the exact
 * write-then-chmod/chown sequence create-time files[] staging already
 * established (handle_create()'s own inline loop) rather than a
 * second copy.
 *
 * Deliberately LIVE and EPHEMERAL, not persisted into the container's
 * own definition -- this is a hotfix primitive (patch a running
 * container the way an operator would hand-edit a file over SSH),
 * not a way to durably change what a future restart/recreate produces.
 * A restart replays the persisted create-body unchanged, and this
 * write is never folded into it, on purpose: merging one file update
 * into an arbitrary already-persisted JSON files[] array is real,
 * separate complexity (matching an existing entry by path vs.
 * appending a new one, preserving every other field) that doesn't
 * belong bolted onto a same primitive that's supposed to stay simple
 * and immediate. The durable path for "this change should survive a
 * recreate" is a container recipe (ADR-0151): capture the updated
 * file content there and re-apply, the same reproducible path this
 * project already uses for exactly that. Both together (live patch
 * now, recipe update for later) intentionally mirror how `pkg
 * install` (live, immediate) and an image recipe's own package list
 * (declared intent for a future build) already relate.
 */
/*
 * DELETE /v1/containers/{name}/files?path=... -- the third side of the
 * same primitive GET and PUT already implement, resolving the path
 * exactly as they do (running: /proc/<pid>/root<path>, resolved by the
 * kernel through the container's own mount namespace; otherwise the
 * container's own writable layer).
 *
 * It exists because the pair without it is not a primitive an operator
 * can actually keep a container tidy with: a file could be created and
 * rewritten but never removed, so anything staged once was staged
 * forever. That surfaced the first time a staged path CHANGED --
 * cix-init moved to /sbin and every container built before that kept
 * an inert copy at the old path, with no way to remove it short of
 * destroying and rebuilding the container.
 *
 * Refuses a directory. Removing a tree is a different, more dangerous
 * operation than removing a file, and this endpoint has only ever
 * dealt in single files; rmdir(2) on an empty directory is a
 * reasonable thing to add later, deliberately, rather than to fall out
 * of unlink()'s error handling by accident.
 */
static void handle_container_file_delete(int fd, const char *name, const char *rel_path)
{
	struct registry_entry *e = registry_find(name);
	char container_root[PATH_MAX];
	char full_path[PATH_MAX];
	struct stat st;
	int stopped = 0;

	if (e == NULL) {
		if (container_root_from_def(name, container_root, sizeof(container_root)) != 0) {
			respond_error(fd, 404, "Not Found", "no such container");
			return;
		}
		stopped = 1;
	}
	if (rel_path == NULL || rel_path[0] != '/' || strlen(rel_path) >= CONTAINER_FILE_PATH_MAX ||
	    !file_path_is_safe(rel_path)) {
		respond_error(fd, 400, "Bad Request", "invalid or missing path");
		return;
	}
	{
		int use_proc = 0;

		if (!stopped && e->running) {
			char proc_root[64];

			snprintf(proc_root, sizeof(proc_root), "/proc/%d/root", (int)e->handle.pid);
			use_proc = (access(proc_root, F_OK) == 0);
		}
		if (use_proc) {
			snprintf(full_path, sizeof(full_path), "/proc/%d/root%s", (int)e->handle.pid,
			          rel_path);
		} else {
			if (!stopped)
				container_root_for(e->disk_name, container_root, sizeof(container_root));
			container_writable_path(container_root, name, rel_path, full_path,
			                         sizeof(full_path));
		}
	}

	if (lstat(full_path, &st) != 0) {
		respond_error(fd, 404, "Not Found", "no such file");
		return;
	}
	if (S_ISDIR(st.st_mode)) {
		respond_error(fd, 400, "Bad Request", "path is a directory, not a file");
		return;
	}
	if (unlink(full_path) != 0) {
		char errmsg[256];

		snprintf(errmsg, sizeof(errmsg), "unlink(%s) failed: %s", rel_path, strerror(errno));
		logstore_write_container(name, "error", "DELETE files: %s", errmsg);
		respond_error(fd, 500, "Internal Server Error", errmsg);
		return;
	}
	logstore_write_container(name, "info", "DELETE files: removed %s", rel_path);
	http_write_response(fd, 204, "No Content", "application/json", "", 0);
}

/*
 * #333: one file write, and which step of it failed.
 *
 * Four different syscalls used to share one error message, so "failed
 * to write file" was the whole of what an operator got -- for an open
 * that was refused, a short write, a chmod or a chown, with no errno
 * and no way to tell a read-only mount from a permission problem from
 * an id-mapping one. The endpoint was reported broken on every running
 * container and the report could not say why, which is most of why it
 * stayed open for three days; the fix took one measurement once it
 * could name EOVERFLOW.
 *
 * errno is captured immediately, before close() or anything else can
 * overwrite it. Factored out because the caller now attempts the write
 * at up to two different paths and both attempts must report
 * identically.
 */
struct file_write_result {
	const char *step;
	int err;
};

/* The directory component of a path, or "/" when there is none. */
static void path_parent(const char *path, char *out, size_t out_size)
{
	char *slash;

	snprintf(out, out_size, "%s", path);
	slash = strrchr(out, '/');
	if (slash == out)
		out[1] = '\0';
	else if (slash != NULL)
		*slash = '\0';
}

static int write_one_file(const char *full_path, const char *content, size_t content_len,
                           long mode, uid_t owner, gid_t group, struct file_write_result *res)
{
	char target_dir[PATH_MAX];
	char *slash;
	int file_fd;

	res->step = NULL;
	res->err = 0;

	snprintf(target_dir, sizeof(target_dir), "%s", full_path);
	slash = strrchr(target_dir, '/');
	if (slash != NULL)
		*slash = '\0';
	if (persist_mkdir_p(target_dir) != 0) {
		res->step = "mkdir";
		res->err = errno;
		return -1;
	}

	file_fd = open(full_path, O_CREAT | O_TRUNC | O_WRONLY, (mode_t)mode);
	if (file_fd < 0) {
		res->step = "open";
		res->err = errno;
		return -1;
	}
	if (content_len > 0 && write(file_fd, content, content_len) != (ssize_t)content_len) {
		res->step = "write";
		res->err = errno;
	} else if (fchmod(file_fd, (mode_t)mode) != 0) {
		res->step = "fchmod";
		res->err = errno;
	} else if ((owner != (uid_t)-1 || group != (gid_t)-1) &&
	           fchown(file_fd, owner, group) != 0) {
		res->step = "fchown";
		res->err = errno;
	}
	close(file_fd);
	return res->step != NULL ? -1 : 0;
}

static void file_write_fail(int fd, const char *name, const struct file_write_result *res,
                             const char *path, char *content)
{
	char errmsg[512];

	free(content);
	snprintf(errmsg, sizeof(errmsg), "%s(%s) failed: %s", res->step, path, strerror(res->err));
	logstore_write_container(name, "error", "PUT files: %s", errmsg);
	respond_error(fd, 500, "Internal Server Error", errmsg);
}

static void handle_container_file_write(int fd, const char *name, const char *rel_path,
                                         const char *body, size_t body_len)
{
	struct registry_entry *e = registry_find(name);
	struct json_value *root;
	const char *raw_content;
	char *content;
	const char *mode_str;
	const struct json_value *jowner, *jgroup;
	long mode;
	uid_t owner;
	gid_t group;
	size_t content_len;
	char container_root[PATH_MAX];
	int stopped = 0;
	char full_path[PATH_MAX];
	char rootfs_base[PATH_MAX];
	char proc_path[PATH_MAX];
	int have_rootfs_base = 0;
	int have_proc = 0;
	int wrote_through_proc = 0;
	struct file_write_result wr;

	if (e == NULL) {
		/*
		 * Issue #162: editing a file before a start is exactly the
		 * operation an operator wants on a container that is down, so
		 * write falls back to the persisted definition the same way
		 * read does.
		 */
		if (container_root_from_def(name, container_root, sizeof(container_root)) != 0) {
			respond_error(fd, 404, "Not Found", "no such container");
			return;
		}
		stopped = 1;
	}
	if (rel_path == NULL || rel_path[0] != '/' || strlen(rel_path) >= CONTAINER_FILE_PATH_MAX ||
	    !file_path_is_safe(rel_path)) {
		respond_error(fd, 400, "Bad Request", "invalid or missing path");
		return;
	}

	root = json_parse(body, body_len);
	if (root == NULL) {
		respond_error(fd, 400, "Bad Request", "invalid JSON body");
		return;
	}
	raw_content = json_as_string(json_object_get(root, "content"));
	if (raw_content == NULL) {
		json_free(root);
		respond_error(fd, 400, "Bad Request", "content is required");
		return;
	}
	/*
	 * A copy, not the json_value's own pointer -- content is used below
	 * in a real write(2) call, which must happen before root (and
	 * everything it owns, including raw_content) is freed. Freeing
	 * root first and using the string afterward was a real use-after-
	 * free caught live during this same feature's own verification
	 * pass (a real write produced garbage bytes, not the file's actual
	 * content) -- fixed here, not worked around.
	 */
	content = strdup(raw_content);
	if (content == NULL) {
		json_free(root);
		respond_error(fd, 500, "Internal Server Error", "out of memory");
		return;
	}
	mode_str = json_as_string(json_object_get(root, "mode"));
	mode = mode_str != NULL ? strtol(mode_str, NULL, 8) : 0644;
	jowner = json_object_get(root, "owner");
	jgroup = json_object_get(root, "group");
	owner = jowner != NULL ? (uid_t)json_as_number(jowner) : (uid_t)-1;
	group = jgroup != NULL ? (gid_t)json_as_number(jgroup) : (gid_t)-1;
	content_len = strlen(content);

	json_free(root);

	if (!stopped)
		container_root_for(e->disk_name, container_root, sizeof(container_root));
	have_rootfs_base = (container_direct_rootfs(container_root, name, rootfs_base,
	                                             sizeof(rootfs_base)) == 0);
	if (!stopped && e->running) {
		char proc_root[64];

		/*
		 * Same running-but-already-dead case the GET path above
		 * documents: running == 1 only means this daemon has not
		 * processed the exit yet, and a zombie's /proc/<pid>/root is a
		 * dangling link. Probing it is safe and unambiguous -- the
		 * daemon still holds the pidfd, so the pid cannot have been
		 * recycled by an unrelated process.
		 */
		snprintf(proc_root, sizeof(proc_root), "/proc/%d/root", (int)e->handle.pid);
		if (access(proc_root, F_OK) == 0) {
			have_proc = 1;
			snprintf(proc_path, sizeof(proc_path), "/proc/%d/root%s", (int)e->handle.pid,
			         rel_path);
		}
	}

	/*
	 * #333, first attempt: through the container's OWN view of its
	 * filesystem.
	 *
	 * This has to be tried first, and the reason is not the id-mapping
	 * this issue is about -- it is everything MOUNTED inside the
	 * container. /run is a tmpfs, and a volume is a bind mount; both
	 * shadow the corresponding directory in the host-side tree
	 * completely. A write that goes host-side for such a path lands on
	 * a directory nothing inside the container will ever look at, and
	 * reports 204 while doing it.
	 */
	if (have_proc) {
		if (write_one_file(proc_path, content, content_len, mode, owner, group, &wr) == 0) {
			wrote_through_proc = 1;
		} else if (wr.err != EOVERFLOW) {
			file_write_fail(fd, name, &wr, proc_path, content);
			return;
		}
		/*
		 * EOVERFLOW and only EOVERFLOW falls through. It is the
		 * measured signature of creating a file through a running
		 * userns container's /proc/<pid>/root -- see
		 * container_direct_rootfs() above, including why the obvious
		 * id-mapping explanation for it does not hold -- and it is not
		 * a signature anything else on this path produces, so falling
		 * through on it alone cannot mask a real failure.
		 */
	}

	if (!wrote_through_proc) {
		if (have_rootfs_base) {
			snprintf(full_path, sizeof(full_path), "%s%s", rootfs_base, rel_path);
			/*
			 * Who the new file must belong to, when the request did
			 * not say. The rootfs's OWN ownership is the answer, and
			 * it is the same one-source-of-truth marker
			 * container_create() reads to decide which presentation
			 * to give the container: a tree owned by host uid 0 is
			 * presented through an id-mapped mount, so a file the
			 * daemon creates as uid 0 already appears inside as root;
			 * a tree owned by a subordinate base is ADR-0179's
			 * phase-2b copy, where a uid-0 file would land on an id
			 * that does not map inside at all and read as nobody.
			 */
			if (owner == (uid_t)-1 && group == (gid_t)-1) {
				struct stat rst;

				if (stat(rootfs_base, &rst) == 0) {
					owner = rst.st_uid;
					group = rst.st_gid;
				}
			}
		} else {
			container_writable_path(container_root, name, rel_path, full_path,
			                         sizeof(full_path));
		}
		/*
		 * Before writing anything: would this land somewhere the
		 * container can SEE?
		 *
		 * Asked rather than assumed, because the honest answer is not
		 * always yes. A path under a tmpfs (/run) or a volume bind
		 * mount is shadowed inside the container, so the host-side
		 * tree is a DIFFERENT directory wearing the same path, and a
		 * write there reports 204 while being invisible to the only
		 * process that matters. That is the confident wrong answer
		 * this endpoint has already been burned by (#394).
		 *
		 * The test is direct: compare the parent directory's identity
		 * -- (st_dev, st_ino) -- in the container's own view against
		 * the host-side one. A bind or id-mapped mount of the same
		 * directory shares both, so the id-mapped rootfs this fallback
		 * exists for compares EQUAL and passes. Anything mounted over
		 * it is a different inode, a different superblock, or both.
		 *
		 * Checked BEFORE the write, never after: a write that has
		 * already happened cannot be taken back without destroying
		 * whatever the file held before it, and an overwrite of an
		 * existing file is exactly what this endpoint is for.
		 *
		 * Only meaningful for a RUNNING container. A stopped one has
		 * no view to compare against and its mounts do not exist yet
		 * -- the next start assembles them over a tree this write is
		 * genuinely part of. A parent that cannot be stat()ed on
		 * either side is not evidence of shadowing and does not
		 * refuse: mkdir below creates it, host-side, which is right
		 * for a directory the container does not have either.
		 */
		if (have_proc) {
			char proc_parent[PATH_MAX], host_parent[PATH_MAX];
			struct stat ps, hs;

			path_parent(proc_path, proc_parent, sizeof(proc_parent));
			path_parent(full_path, host_parent, sizeof(host_parent));
			if (stat(proc_parent, &ps) == 0 && stat(host_parent, &hs) == 0 &&
			    (ps.st_dev != hs.st_dev || ps.st_ino != hs.st_ino)) {
				char errmsg[640];

				free(content);
				snprintf(errmsg, sizeof(errmsg),
				         "%s is shadowed inside this container by a mount (a tmpfs such "
				         "as /run, or a volume), so a host-side write would not be "
				         "visible to it -- and a write through /proc/<pid>/root into this "
				         "container is refused with EOVERFLOW. Nothing was written. Use a "
				         "path in the container's own rootfs, or write to the volume "
				         "itself.",
				         rel_path);
				logstore_write_container(name, "error", "PUT files: %s", errmsg);
				respond_error(fd, 409, "Conflict", errmsg);
				return;
			}
		}
		if (write_one_file(full_path, content, content_len, mode, owner, group, &wr) != 0) {
			file_write_fail(fd, name, &wr, full_path, content);
			return;
		}
	}
	free(content);

	http_set_blocking(fd);
	http_write_response(fd, 204, "No Content", "application/json", "", 0);
}

/*
 * GET /v1/containers/{name}/stats (ADR-0054): real, host-side CPU/
 * memory/disk/network usage for one container, gathered entirely from
 * kernel interfaces the daemon already has open (cgroup_fd) or can
 * derive (the host-side veth name, network.c's own vh<pid>-<idx>
 * convention) -- no in-container agent. A raw, point-in-time snapshot
 * on every call, deliberately: no server-side history/ring buffer,
 * see ADR-0054 for why the daemon stays stateless for this feature.
 * Works for an exited-but-still-registered container too (cgroup
 * leaves are never rmdir()'d, see cgroup_create()'s own comment) --
 * only a fully-removed entry (DELETE'd, or never existed) is a 404.
 */
static void handle_container_stats(int fd, const char *name)
{
	struct registry_entry *e = registry_find(name);
	struct json_writer w;
	long long cpu_usage, cpu_user, cpu_system;
	long long mem_current, mem_peak, mem_max;
	/* Issue #52: a swap limit with no way to see swap use is half a
	 * feature -- the number an operator acts on is how close the
	 * container is to it. */
	long long swap_current = 0, swap_max = 0;
	int swap_max_unlimited = 1;
	int swap_current_unlimited = 0;
	int mem_max_unlimited;
	long long disk_bytes = 0;
	long long io_rbytes, io_wbytes, io_rios, io_wios;
	struct cgroup_pressure cpu_pressure, io_pressure, mem_pressure;
	int i;

	if (e == NULL) {
		respond_error(fd, 404, "Not Found", "no such container");
		return;
	}

	cgroup_read_stat_key(e->handle.cgroup_fd, "cpu.stat", "usage_usec", &cpu_usage);
	cgroup_read_stat_key(e->handle.cgroup_fd, "cpu.stat", "user_usec", &cpu_user);
	cgroup_read_stat_key(e->handle.cgroup_fd, "cpu.stat", "system_usec", &cpu_system);
	cgroup_read_single_value(e->handle.cgroup_fd, "memory.current", &mem_current, &mem_max_unlimited);
	cgroup_read_single_value(e->handle.cgroup_fd, "memory.peak", &mem_peak, &mem_max_unlimited);
	cgroup_read_single_value(e->handle.cgroup_fd, "memory.max", &mem_max, &mem_max_unlimited);
	if (cgroup_read_single_value(e->handle.cgroup_fd, "memory.swap.current", &swap_current,
	                              &swap_current_unlimited) != 0)
		swap_current = 0;
	if (cgroup_read_single_value(e->handle.cgroup_fd, "memory.swap.max", &swap_max,
	                              &swap_max_unlimited) != 0)
		swap_max_unlimited = 1;
	cgroup_read_io_totals(e->handle.cgroup_fd, &io_rbytes, &io_wbytes, &io_rios, &io_wios);
	cgroup_read_pressure(e->handle.cgroup_fd, "cpu.pressure", &cpu_pressure);
	cgroup_read_pressure(e->handle.cgroup_fd, "io.pressure", &io_pressure);
	cgroup_read_pressure(e->handle.cgroup_fd, "memory.pressure", &mem_pressure);

	{
		char container_root[PATH_MAX];
		char upperdir[PATH_MAX];

		container_root_for(e->disk_name, container_root, sizeof(container_root));
		container_writable_path(container_root, name, "", upperdir, sizeof(upperdir));
		overlay_upperdir_size(upperdir, &disk_bytes);
	}

	jw_init(&w);
	jw_obj_open(&w);
	jw_key(&w, "cpu");
	jw_obj_open(&w);
	jw_key(&w, "usage_usec");
	jw_int(&w, cpu_usage);
	jw_key(&w, "user_usec");
	jw_int(&w, cpu_user);
	jw_key(&w, "system_usec");
	jw_int(&w, cpu_system);
	jw_key(&w, "pressure");
	jw_obj_open(&w);
	write_pressure_json(&w, &cpu_pressure);
	jw_obj_close(&w);
	jw_obj_close(&w);
	jw_key(&w, "memory");
	jw_obj_open(&w);
	jw_key(&w, "current");
	jw_int(&w, mem_current);
	jw_key(&w, "peak");
	jw_int(&w, mem_peak);
	jw_key(&w, "max");
	if (mem_max_unlimited)
		jw_null(&w);
	else
		jw_int(&w, mem_max);
	jw_key(&w, "swap_current");
	jw_int(&w, swap_current);
	jw_key(&w, "swap_max");
	if (swap_max_unlimited)
		jw_null(&w);
	else
		jw_int(&w, swap_max);
	jw_key(&w, "pressure");
	jw_obj_open(&w);
	write_pressure_json(&w, &mem_pressure);
	jw_obj_close(&w);
	jw_obj_close(&w);
	jw_key(&w, "disk");
	jw_obj_open(&w);
	jw_key(&w, "upper_bytes");
	jw_int(&w, disk_bytes);
	jw_key(&w, "read_bytes");
	jw_int(&w, io_rbytes);
	jw_key(&w, "write_bytes");
	jw_int(&w, io_wbytes);
	jw_key(&w, "read_ios");
	jw_int(&w, io_rios);
	jw_key(&w, "write_ios");
	jw_int(&w, io_wios);
	jw_key(&w, "pressure");
	jw_obj_open(&w);
	write_pressure_json(&w, &io_pressure);
	jw_obj_close(&w);
	jw_obj_close(&w);
	jw_key(&w, "networks");
	jw_arr_open(&w);
	for (i = 0; i < e->net_count; i++) {
		char veth[32];

		container_veth_host_name(e, i, veth, sizeof(veth));
		jw_obj_open(&w);
		jw_key(&w, "name");
		jw_str(&w, e->nets[i].name);
		jw_key(&w, "rx_bytes");
		jw_int(&w, read_net_stat(veth, "rx_bytes"));
		jw_key(&w, "tx_bytes");
		jw_int(&w, read_net_stat(veth, "tx_bytes"));
		jw_key(&w, "rx_packets");
		jw_int(&w, read_net_stat(veth, "rx_packets"));
		jw_key(&w, "tx_packets");
		jw_int(&w, read_net_stat(veth, "tx_packets"));
		jw_obj_close(&w);
	}
	jw_arr_close(&w);
	jw_obj_close(&w);
	respond_json(fd, 200, "OK", &w);
	jw_free(&w);
}

/*
 * POST /v1/containers/{name}/stop (ADR-0027) -- kills a live container
 * right now, without removing its persisted definition (unlike
 * DELETE): no containerdef_remove(), and deliberately no dns_server_
 * forget()/dns_record_forget_owner()/pki_cert_forget_owner() either --
 * this name's DNS/PKI ownership survives a stop, unlike a delete.
 * Reuses registry_remove() verbatim (already does SIGKILL + a
 * synchronous reap) -- no new kill/reap primitive, no asymmetry with
 * DELETE's own semantics. Applies uniformly regardless of restart
 * policy (kills any live container). Since ADR-0181 every container has
 * a persisted definition, so a stop always leaves one behind -- the
 * container reappears as "stopped", never vanishing, which is the whole
 * point of that ADR ("stop is stop, delete is delete"). containerdef_
 * set_stopped() records the intent on that def (still a harmless no-op
 * for a genuinely def-less internal container like "__pkgbuild"); for a
 * restart:"no" def it sets the flag but changes no behavior, since "no"
 * is already never autostarted or crash-restarted. What stopped means
 * going forward is up to the two sites that consult it (containerdef_
 * autostart_all(), handle_restart_timer_event()), not this handler.
 * Idempotent: calling twice is both 200.
 *
 * A stop targeting PKG_BUILD_CONTAINER_NAME ("__pkgbuild") is a real,
 * previously-undiscovered special case: this path kills and reaps the
 * container directly via registry_remove() -- it never goes through
 * handle_container_event()'s own epoll-driven exit path (the pidfd is
 * explicitly pulled from epoll first, precisely so this synchronous
 * stop doesn't race a live event for the same fd), which is the ONLY
 * place pkg_build_completed() normally gets called. Without the check
 * below, manually stopping a stuck build left pkg.c's own
 * g_current_job_name lock permanently set (confirmed live: the
 * container was fully gone from the registry, but every subsequent
 * pkg install kept 409-ing "another package install is already in
 * progress" indefinitely) -- __pkgbuild was never expected to be
 * stopped this way before now. Fixed by calling pkg_build_completed()
 * here too, exactly like the normal exit path would have, using the
 * real exit_status registry_remove()'s own registry_mark_exited()
 * call just set on e (read after removal -- the slot is only flagged
 * not-in-use, not freed, so this is the same "read the entry once
 * more before something else can reuse it" pattern
 * handle_container_event() already relies on). A manually-killed
 * build's exit_status is never 0, so pkg_build_completed()'s own
 * success-only chaining logic correctly never triggers here.
 */
/*
 * Does an operator stop of this container survive a host reboot?
 *
 * Only "unless-stopped" carries the stopped flag through
 * containerdef_autostart_all(); "always" and "on-failure" are brought
 * back up unconditionally, and "no" never autostarts at all so the
 * question does not arise -- it stays down either way.
 *
 * Reported in the stop response (#348) because the answer is the one
 * thing an operator needs at that moment and could previously only
 * learn by rebooting and finding the container running.
 */
static int stop_survives_reboot(const char *name)
{
	struct container_def *d = containerdef_find(name);

	if (d == NULL)
		return 0;
	return strcmp(d->restart_policy, "unless-stopped") == 0 ||
	       strcmp(d->restart_policy, "no") == 0;
}

static void handle_stop(int fd, const char *name)
{
	struct registry_entry *e = registry_find(name);
	struct conn *cc;
	struct json_writer w;
	int was_pkgbuild = (pkg_build_container_chain_index(name) >= 0);

	if (e == NULL && containerdef_find(name) == NULL) {
		respond_error(fd, 404, "Not Found", "no such container");
		return;
	}

	/*
	 * ADR-0180 (issue #67): same asynchronous-teardown conversion as
	 * DELETE's own running branch (see handle_delete()'s comment for
	 * the full reasoning -- this handler shared the identical
	 * unbounded registry_remove() wait). The durable half of stop's
	 * intent (the stopped flag, which is what keeps a restart:"always"
	 * definition down across daemon restarts) is written NOW; the
	 * registry slot release -- and, for a pkgbuild container, the
	 * pkg_build_completed() bookkeeping that needs the real exit
	 * status -- completes from handle_container_event() when the
	 * process actually dies. Idempotent for a stop already in flight;
	 * a stop during a DELETE teardown changes nothing (delete's intent
	 * strictly supersedes).
	 *
	 * #348: this comment used to say the stopped flag "keeps a
	 * restart:\"always\" definition down across daemon restarts". It
	 * does not, and never did. containerdef_autostart_all() honours the
	 * flag only for restart:"unless-stopped" -- which is the documented
	 * contract and matches the convention the policy names are borrowed
	 * from, but is the opposite of what this comment promised. An
	 * operator stopped ar-1 precisely so it could not claim a radio
	 * during a boot-race test, the host rebooted, it came back up, took
	 * wlan0, and the experiment recorded a failure that never happened.
	 *
	 * The behaviour is right and stays. What was missing is that the
	 * consequence was invisible at the moment of acting: the response
	 * now says whether this stop survives a reboot, and says what to
	 * use if you wanted it to.
	 */
	if (e != NULL && e->running) {
		containerdef_set_stopped(name, 1);
		if (!stop_survives_reboot(name))
			logstore_write("cixd", "warn",
			                "%s: stopped, but restart policy is \"%s\" -- this stop lasts "
			                "only while this daemon runs; a reboot starts it again. Use "
			                "restart \"unless-stopped\" for a stop that persists (#348)",
			                name, containerdef_find(name) != NULL
			                          ? containerdef_find(name)->restart_policy
			                          : "?");
		if (e->teardown_kind == REGISTRY_TEARDOWN_NONE)
			begin_container_stop(e, REGISTRY_TEARDOWN_STOP);

		jw_init(&w);
		jw_obj_open(&w);
		jw_key(&w, "name");
		jw_str(&w, name);
		jw_key(&w, "status");
		jw_str(&w, "stopping");
		/* #348: whether this stop outlives a reboot, answered where the
		 * operator can act on it rather than discovered afterwards. */
		jw_key(&w, "survives_reboot");
		jw_bool(&w, stop_survives_reboot(name));
		jw_obj_close(&w);
		respond_json(fd, 200, "OK", &w);
		jw_free(&w);
		return;
	}

	if (e != NULL) {
		/* Exited-but-still-registered (a crashed entry, or a
		 * keep_on_failure-preserved build container): the original
		 * synchronous flow -- registry_remove()'s kill/wait branch is
		 * skipped for a non-running entry, so nothing here can block. */
		if (e->reactor_conn != NULL) {
			cc = e->reactor_conn;
			cix_epoll_ctl(g_epfd, EPOLL_CTL_DEL, cc->fd, NULL);
			free(cc);
			e->reactor_conn = NULL;
		}
		registry_remove(name);
		if (was_pkgbuild) {
			pid_t pkg_pid;
			int pkg_pidfd;
			int pkg_chain_idx;
			char hostbuild_done_name[PKG_NAME_MAX];
			/* An explicit operator stop always tears the container
			 * down (registry_remove() above already ran) regardless
			 * of keep_on_failure -- that flag is only ever about an
			 * unprompted build failure, never a deliberately-killed
			 * one. Discarded here for exactly that reason. */
			int kept_ignored;

			if (pkg_build_completed(name, e->exit_status, &pkg_pid, &pkg_pidfd,
			                         &pkg_chain_idx, hostbuild_done_name, &kept_ignored))
				register_pkg_fetch_pidfd(pkg_pid, pkg_pidfd, pkg_chain_idx);
			else
				try_start_queued_pkg_rebuild();
			artifact_push_pump(); /* issue #129 -- see the other call site */
		}
	}
	containerdef_set_stopped(name, 1);

	jw_init(&w);
	jw_obj_open(&w);
	jw_key(&w, "name");
	jw_str(&w, name);
	jw_key(&w, "status");
	jw_str(&w, "stopped");
	jw_key(&w, "survives_reboot"); /* #348, see the running branch above */
	jw_bool(&w, stop_survives_reboot(name));
	jw_obj_close(&w);
	respond_json(fd, 200, "OK", &w);
	jw_free(&w);
}

static void respond_container_storagemigrate_error(int fd, enum containerstoragemigrate_error err)
{
	switch (err) {
	case CONTAINERSTORAGEMIGRATE_ERR_BUSY:
		respond_error(fd, 409, "Conflict", "a storage migration for this container is already running");
		break;
	case CONTAINERSTORAGEMIGRATE_ERR_ALREADY_ACTIVE:
		respond_error(fd, 409, "Conflict", "this container's storage is already on that placement");
		break;
	case CONTAINERSTORAGEMIGRATE_ERR_TABLE_FULL:
		respond_error(fd, 500, "Internal Server Error",
		              "every container-storage migration job slot is in use -- try again shortly");
		break;
	case CONTAINERSTORAGEMIGRATE_ERR_SPAWN_FAILED:
	default:
		respond_error(fd, 500, "Internal Server Error", "could not start migration job");
		break;
	}
}

/*
 * POST /v1/containers/{name}/migrate-storage (ADR-0142 Section 4): the
 * exact same {"disk": "name"|null} contract every other storage-
 * placement migration endpoint already has, narrowed to one
 * container's own overlay directory. Requires a persisted definition to
 * exist -- the cutover this triggers always ends with a real stop-then-
 * replay, so a container with nothing to replay from can never safely
 * reach that point. Since ADR-0181 (issue #73) every container IS
 * persisted, restart:"no" included, so that check is now defence in
 * depth for a genuinely def-less internal container rather than the
 * routine restart-policy gate it originally was. disk_name
 * is validated via resolve_container_disk_root() -- the exact same
 * check POST /v1/containers itself already applies to a "disk" field
 * at creation time, reused rather than re-implemented (One Source of
 * Truth).
 */
static void handle_container_migrate_storage_post(int fd, const char *name, const char *body,
                                                    size_t body_len)
{
	struct json_value *root;
	const struct json_value *jdisk;
	const char *disk_name;
	char disk_name_buf[DISKROLE_DISK_NAME_MAX];
	char current_disk[DISKROLE_DISK_NAME_MAX];
	char source_root[PATH_MAX], target_root[PATH_MAX];
	char source_base[PATH_MAX], target_base[PATH_MAX];
	struct registry_entry *live = registry_find(name);
	struct container_def *def = containerdef_find(name);
	pid_t pid;
	int pidfd;
	enum containerstoragemigrate_error cerr;

	if (live == NULL && def == NULL) {
		respond_error(fd, 404, "Not Found", "no such container");
		return;
	}
	if (def == NULL) {
		respond_error(fd, 400, "Bad Request",
		              "this container has no persisted definition to restart from -- only a "
		              "restart_policy other than \"no\" supports storage migration");
		return;
	}

	root = json_parse(body, body_len);
	if (root == NULL) {
		respond_error(fd, 400, "Bad Request", "invalid JSON body");
		return;
	}
	jdisk = json_object_get(root, "disk");
	if (jdisk == NULL || (jdisk->type != JSON_NULL && jdisk->type != JSON_STRING)) {
		json_free(root);
		respond_error(fd, 400, "Bad Request",
		              "disk is required -- a disk name, or null for the default OS-disk placement");
		return;
	}
	if (jdisk->type == JSON_NULL) {
		disk_name = NULL;
	} else {
		disk_name = json_as_string(jdisk);
		if (disk_name == NULL || disk_name[0] == '\0' || strlen(disk_name) >= DISKROLE_DISK_NAME_MAX) {
			json_free(root);
			respond_error(fd, 400, "Bad Request", "invalid disk name");
			return;
		}
		snprintf(disk_name_buf, sizeof(disk_name_buf), "%s", disk_name);
		disk_name = disk_name_buf;
	}
	json_free(root);

	current_disk[0] = '\0';
	if (live != NULL) {
		snprintf(current_disk, sizeof(current_disk), "%s", live->disk_name);
	} else {
		struct json_value *defroot = json_parse(def->body, def->body_len);

		if (defroot != NULL) {
			const char *d = json_as_string(json_object_get(defroot, "disk"));

			if (d != NULL)
				snprintf(current_disk, sizeof(current_disk), "%s", d);
			json_free(defroot);
		}
	}

	if (strcmp(current_disk, disk_name != NULL ? disk_name : "") == 0) {
		respond_error(fd, 409, "Conflict", "this container's storage is already on that placement");
		return;
	}

	if (disk_name != NULL) {
		int drc = resolve_container_disk_root(disk_name, target_root, sizeof(target_root));

		if (drc != DISK_RESOLVE_OK) {
			respond_error(fd, 400, "Bad Request",
			              drc == DISK_RESOLVE_NOT_FOUND
			                  ? "no such disk"
			                  : drc == DISK_RESOLVE_NOT_MOUNTED
			                        ? "disk is not mounted"
			                        : "disk has no container-storage role assigned");
			return;
		}
	} else {
		snprintf(target_root, sizeof(target_root), "%s", CONTAINERS_DIR);
	}

	container_root_for(current_disk[0] != '\0' ? current_disk : NULL, source_root, sizeof(source_root));
	snprintf(source_base, sizeof(source_base), "%s/%s", source_root, name);
	snprintf(target_base, sizeof(target_base), "%s/%s", target_root, name);

	/*
	 * Snapshot containers (ADR-0207) migrate too, as of ADR-0234.
	 *
	 * This used to refuse them outright, and the refusal was right at
	 * the time: the copy child ran treecopy_recursive() over the whole
	 * container directory, which would have reproduced the rootfs
	 * subvolume as an ordinary directory -- every file present, and
	 * nothing that could be snapshotted or qgroup-limited afterwards.
	 * Refusing loudly beat corrupting quietly.
	 *
	 * The child now recognises the layout and reproduces the rootfs as
	 * a real subvolume on the target (cix_btrfs_subvol_copy()), so the
	 * reason to refuse is gone. What is NOT recovered is extent
	 * sharing: it does not cross filesystems, so a migrated container
	 * occupies its full size on the target disk. That is inherent, and
	 * the API documents it rather than surprising the operator with a
	 * disk that fills faster than expected.
	 */

	if (persist_mkdir_p(target_base) != 0) {
		respond_error(fd, 500, "Internal Server Error", "failed to create target container directory");
		return;
	}

	cerr = containerstoragemigrate_start(name, source_base, target_base, disk_name, &pid, &pidfd);
	if (cerr != CONTAINERSTORAGEMIGRATE_OK) {
		respond_container_storagemigrate_error(fd, cerr);
		return;
	}
	register_container_storage_migrate_pidfd(name, pid, pidfd);

	{
		struct json_writer w;

		jw_init(&w);
		containerstoragemigrate_write_status_json(&w, name);
		respond_json(fd, 202, "Accepted", &w);
		jw_free(&w);
	}
}

static void handle_container_migrate_storage_get(int fd, const char *name)
{
	struct json_writer w;

	if (registry_find(name) == NULL && containerdef_find(name) == NULL) {
		respond_error(fd, 404, "Not Found", "no such container");
		return;
	}

	jw_init(&w);
	containerstoragemigrate_write_status_json(&w, name);
	respond_json(fd, 200, "OK", &w);
	jw_free(&w);
}

static void handle_disk_format_post(int fd, const char *disk_name, const char *body, size_t body_len)
{
	struct json_value *root;
	const char *confirm;
	const char *fs_type_str;
	enum diskformat_fs_type fs_type;
	pid_t pid;
	int pidfd;
	enum diskformat_error derr;

	root = json_parse(body, body_len);
	if (root == NULL) {
		respond_error(fd, 400, "Bad Request", "invalid JSON body");
		return;
	}
	confirm = json_as_string(json_object_get(root, "confirm_disk_name"));
	if (confirm == NULL || strcmp(confirm, disk_name) != 0) {
		json_free(root);
		respond_error(fd, 400, "Bad Request",
		              "confirm_disk_name must be given and must match the disk name in the URL -- "
		              "this is a destructive operation");
		return;
	}
	if (is_active_storage_singleton_placement(disk_name)) {
		json_free(root);
		respond_error(fd, 409, "Conflict",
		              "this disk is the active state-storage, log-storage, or rebuildable-storage "
		              "placement, the configured backup-config disk, or the current swap placement "
		              "(issue #28) -- formatting it would destroy live data; migrate away first");
		return;
	}
	if (disk_has_container_in_use(disk_name)) {
		json_free(root);
		respond_error(fd, 409, "Conflict",
		              "one or more containers currently have their own storage on this disk -- "
		              "formatting it would destroy live data; migrate them away first "
		              "(POST /containers/{name}/migrate-storage)");
		return;
	}
	/*
	 * fs_type (ADR-0104, task #732): optional, defaults to "btrfs".
	 *
	 * It defaulted to ext4 for as long as ext4 was what this platform
	 * used. ADR-0207 made btrfs the sole substrate for the platform's
	 * own writable storage and put ext4 on a retirement path, which
	 * left this default pointing at the losing side: an operator
	 * formatting a data disk without saying otherwise got a filesystem
	 * that cannot snapshot, so any container placed on it gets a full
	 * copy of its image instead of a copy-on-write clone. Nobody chose
	 * that; the default simply outlived the decision.
	 *
	 * "btrfs" requires a real mkfs.btrfs to
	 * actually be staged on this box (btrfs-progs.recipe via a real
	 * cix-hosttools image, ADR-0103's own scope note) -- if it
	 * isn't, the job still starts (this daemon has no cheap way to
	 * probe for the binary's presence without also handling every
	 * other reason execve() could fail the same way) but fails fast
	 * with a clear DISKFORMAT_STATE_FAILED/"mkfs.btrfs failed" once
	 * the child actually tries to exec it and gets ENOENT -- consistent
	 * with mkfs.ext4's own existing failure-reporting shape, not a
	 * new failure mode this field introduces.
	 */
	fs_type_str = json_as_string(json_object_get(root, "fs_type"));
	if (fs_type_str == NULL || strcmp(fs_type_str, "btrfs") == 0) {
		fs_type = DISKFORMAT_FS_BTRFS;
	} else if (strcmp(fs_type_str, "ext4") == 0) {
		fs_type = DISKFORMAT_FS_EXT4;
	} else {
		json_free(root);
		respond_error(fd, 400, "Bad Request", "fs_type must be \"ext4\" or \"btrfs\"");
		return;
	}
	json_free(root);

	derr = diskformat_start(disk_name, CONTAINERS_DIR, DISKS_MOUNT_DIR, fs_type, &pid, &pidfd);
	if (derr != DISKFORMAT_OK) {
		respond_diskformat_error(fd, derr);
		return;
	}
	register_disk_format_pidfd(pid, pidfd);

	{
		struct json_writer w;

		jw_init(&w);
		diskformat_write_status_json(&w, disk_name);
		respond_json(fd, 202, "Accepted", &w);
		jw_free(&w);
	}
}

static const char *storage_kind_label(enum storage_kind kind)
{
	switch (kind) {
	case STORAGE_KIND_REBUILDABLE:
		return "rebuildable-storage";
	case STORAGE_KIND_LOG:
		return "log-storage";
	default:
		return "rebuildable-storage";
	}
}

static void handle_log_storage_get(int fd)
{
	struct json_writer w;

	jw_init(&w);
	jw_obj_open(&w);
	storageplacement_write_json(&w, STORAGE_KIND_LOG);
	/*
	 * #256: whether this placement is actually in effect. The
	 * daemon no longer refuses to start when its disk is missing,
	 * so "configured" and "in use" can now differ -- and if that
	 * were not reported, a degraded boot would be silent to every
	 * API client on a host with no shell.
	 */
	{
		const char *why = placement_degraded_reason(STORAGE_KIND_LOG);

		jw_key(&w, "degraded");
		jw_bool(&w, why != NULL);
		if (why != NULL) {
			jw_key(&w, "degraded_reason");
			jw_str(&w, why);
		}
	}
	jw_obj_close(&w);
	respond_json(fd, 200, "OK", &w);
	jw_free(&w);
}

static void respond_storagemigrate_error(int fd, enum storage_kind kind, enum storagemigrate_error err)
{
	char msg[192];

	switch (err) {
	case STORAGEMIGRATE_ERR_BUSY:
		snprintf(msg, sizeof(msg), "a %s migration is already running", storage_kind_label(kind));
		respond_error(fd, 409, "Conflict", msg);
		break;
	case STORAGEMIGRATE_ERR_NOT_FOUND:
		respond_error(fd, 404, "Not Found", "no such disk");
		break;
	case STORAGEMIGRATE_ERR_IS_OS_DISK:
		respond_error(fd, 400, "Bad Request",
		              "this disk holds the fixed OS layout -- it can never be a placement target");
		break;
	case STORAGEMIGRATE_ERR_WRONG_ROLE:
		snprintf(msg, sizeof(msg),
		         "this disk does not carry the %s role -- assign it via POST /v1/storage-roles first",
		         storage_kind_label(kind));
		respond_error(fd, 400, "Bad Request", msg);
		break;
	case STORAGEMIGRATE_ERR_NOT_MOUNTED:
		respond_error(fd, 400, "Bad Request", "this disk carries the role but isn't currently mounted");
		break;
	case STORAGEMIGRATE_ERR_ALREADY_ACTIVE:
		snprintf(msg, sizeof(msg), "this is already the active %s placement", storage_kind_label(kind));
		respond_error(fd, 409, "Conflict", msg);
		break;
	case STORAGEMIGRATE_ERR_SPAWN_FAILED:
	default:
		respond_error(fd, 500, "Internal Server Error", "could not start migration job");
		break;
	}
}

static void handle_log_storage_migrate_post(int fd, const char *body, size_t body_len)
{
	struct json_value *root;
	const struct json_value *jdisk;
	const char *disk_name;
	char disk_name_buf[DISKROLE_DISK_NAME_MAX];
	char target_dir[PATH_MAX];
	pid_t pid;
	int pidfd;
	enum storagemigrate_error merr;

	root = json_parse(body, body_len);
	if (root == NULL) {
		respond_error(fd, 400, "Bad Request", "invalid JSON body");
		return;
	}
	jdisk = json_object_get(root, "disk");
	if (jdisk == NULL || (jdisk->type != JSON_NULL && jdisk->type != JSON_STRING)) {
		json_free(root);
		respond_error(fd, 400, "Bad Request",
		              "disk is required -- a disk name, or null for the default OS-disk placement");
		return;
	}
	if (jdisk->type == JSON_NULL) {
		disk_name = NULL;
		snprintf(target_dir, sizeof(target_dir), "%s/logs", g_base_dir);
	} else {
		disk_name = json_as_string(jdisk);
		if (disk_name == NULL || disk_name[0] == '\0' ||
		    strlen(disk_name) >= DISKROLE_DISK_NAME_MAX) {
			json_free(root);
			respond_error(fd, 400, "Bad Request", "invalid disk name");
			return;
		}
		snprintf(disk_name_buf, sizeof(disk_name_buf), "%s", disk_name);
		disk_name = disk_name_buf;
		snprintf(target_dir, sizeof(target_dir), "%s/%s/logs", DISKS_MOUNT_DIR, disk_name);
	}
	json_free(root);

	merr = storagemigrate_start(STORAGE_KIND_LOG, LOG_DIR, target_dir, disk_name, CONTAINERS_DIR,
	                             &pid, &pidfd);
	if (merr != STORAGEMIGRATE_OK) {
		respond_storagemigrate_error(fd, STORAGE_KIND_LOG, merr);
		return;
	}
	register_storage_migrate_pidfd(STORAGE_KIND_LOG, pid, pidfd);

	{
		struct json_writer w;

		jw_init(&w);
		storagemigrate_write_status_json(&w, STORAGE_KIND_LOG);
		respond_json(fd, 202, "Accepted", &w);
		jw_free(&w);
	}
}

