/* GET /v1/schedules/{name} */
static void op_getSchedule(const struct api_ctx *ctx)
{
	const struct schedule *s = scheduler_find(ctx->p[0]);
	struct json_writer w;

	if (s == NULL) {
		respond_error(ctx->fd, 404, "Not Found", "no such schedule");
		return;
	}
	jw_init(&w);
	scheduler_write_json_one(s, &w);
	respond_json(ctx->fd, 200, "OK", &w);
	jw_free(&w);
}

/* PUT /v1/schedules/{name} */
static void op_setSchedule(const struct api_ctx *ctx)
{
	char err[320];
	enum schedule_error e;
	const struct schedule *s;
	struct json_writer w;

	e = scheduler_set_from_json(ctx->p[0], ctx->req->body, ctx->req->body_len, err, sizeof(err));
	if (e != SCHEDULE_OK) {
		respond_error(ctx->fd, 400, "Bad Request",
		               err[0] != '\0' ? err : schedule_strerror(e));
		return;
	}
	s = scheduler_find(ctx->p[0]);
	jw_init(&w);
	scheduler_write_json_one(s, &w);
	respond_json(ctx->fd, 200, "OK", &w);
	jw_free(&w);
}

/* DELETE /v1/schedules/{name} */
static void op_deleteSchedule(const struct api_ctx *ctx)
{
	enum schedule_error e = scheduler_delete(ctx->p[0]);

	if (e == SCHEDULE_ERR_NOT_FOUND) {
		respond_error(ctx->fd, 404, "Not Found", "no such schedule");
		return;
	}
	if (e != SCHEDULE_OK) {
		respond_error(ctx->fd, 500, "Internal Server Error", schedule_strerror(e));
		return;
	}
	http_write_response(ctx->fd, 204, "No Content", "application/json", "", 0);
}

/*
 * POST /v1/schedules/{name}/run
 *
 * The run's own outcome is reported in the returned schedule's
 * last_ok/last_reason rather than as an HTTP status: a job that ran and
 * failed is a successful request about a failed run, and collapsing
 * those into one number is how "did the call work" and "did the work
 * work" get confused.
 */
static void op_runSchedule(const struct api_ctx *ctx)
{
	const struct schedule *s;
	char err[320];
	struct json_writer w;

	if (scheduler_find(ctx->p[0]) == NULL) {
		respond_error(ctx->fd, 404, "Not Found", "no such schedule");
		return;
	}
	scheduler_run_now(ctx->p[0], err, sizeof(err));
	s = scheduler_find(ctx->p[0]);
	jw_init(&w);
	scheduler_write_json_one(s, &w);
	respond_json(ctx->fd, 200, "OK", &w);
	jw_free(&w);
}

/* GET /v1/pipeline (ADR-0256) -- the read-time join across the source
 * catalogue, the package job records and this host's own boot entry. */
static void op_getPipeline(const struct api_ctx *ctx)
{
	struct json_writer w;

	jw_init(&w);
	pipelineview_write_json(&w);
	respond_json(ctx->fd, 200, "OK", &w);
	jw_free(&w);
}

/*
 * GET /v1/pipeline/runs (ADR-0272) -- the same atoms, along the time
 * axis. Reads the run store and nothing else; the position an operator
 * sees in op_getPipeline() above is still derived live and is never
 * informed by this.
 */
static void op_getPipelineRuns(const struct api_ctx *ctx)
{
	struct json_writer w;
	char name[PKG_NAME_MAX] = "";
	char image[PKG_IMAGE_NAME_MAX] = "";
	char limit_s[16] = "";
	int limit = 0;

	(void)url_query_param(ctx->req->path, "name", name, sizeof(name));
	(void)url_query_param(ctx->req->path, "image", image, sizeof(image));
	if (url_query_param(ctx->req->path, "limit", limit_s, sizeof(limit_s)) == 0)
		limit = atoi(limit_s);

	jw_init(&w);
	pkg_runs_write_json(&w, name, image, limit);
	respond_json(ctx->fd, 200, "OK", &w);
	jw_free(&w);
}

static void pipeline_config_respond(int fd)
{
	struct json_writer w;

	jw_init(&w);
	jw_obj_open(&w);
	jw_key(&w, "run_retention");
	jw_int(&w, pkg_run_retention_get());
	/* ADR-0273. All three default false, and a host with them false
	 * behaves exactly as it did before they existed. */
	jw_key(&w, "gate_publish");
	jw_bool(&w, pkg_gate_enabled("publish"));
	jw_key(&w, "gate_roll");
	jw_bool(&w, pkg_gate_enabled("roll"));
	jw_key(&w, "gate_deploy");
	jw_bool(&w, pkg_gate_enabled("deploy"));
	jw_obj_close(&w);
	respond_json(fd, 200, "OK", &w);
	jw_free(&w);
}

/* GET /v1/system/pipeline-config (ADR-0272) */
static void op_getPipelineConfig(const struct api_ctx *ctx)
{
	pipeline_config_respond(ctx->fd);
}

/*
 * PUT /v1/system/pipeline-config (ADR-0272).
 *
 * Only the fields present are changed, and a value out of range changes
 * nothing at all -- a partial apply on a multi-field body would leave
 * the caller unable to say what the config now is without reading it
 * back, which is the kind of ambiguity this platform's own settings
 * endpoints avoid.
 */
static void op_setPipelineConfig(const struct api_ctx *ctx)
{
	struct json_value *root;
	const struct json_value *v;

	root = json_parse(ctx->req->body, ctx->req->body_len);
	if (root == NULL || root->type != JSON_OBJECT) {
		json_free(root);
		respond_error(ctx->fd, 400, "Bad Request", "invalid JSON body");
		return;
	}
	v = json_object_get(root, "run_retention");
	if (v != NULL) {
		int keep = (int)json_as_number(v);

		if (v->type != JSON_NUMBER || pkg_run_retention_set(keep) != 0) {
			json_free(root);
			respond_error(ctx->fd, 400, "Bad Request",
			              "run_retention must be a whole number from 1 to 2000");
			return;
		}
	}
	/* ADR-0273. Validated before any is applied, same rule as above:
	 * a partial apply leaves the caller unable to say what the config
	 * now is without reading it back. */
	{
		static const char *const keys[] = { "gate_publish", "gate_roll", "gate_deploy" };
		static const char *const gates[] = { "publish", "roll", "deploy" };
		size_t k;

		for (k = 0; k < sizeof(keys) / sizeof(keys[0]); k++) {
			const struct json_value *gv = json_object_get(root, keys[k]);

			if (gv != NULL && gv->type != JSON_BOOL) {
				json_free(root);
				respond_error(ctx->fd, 400, "Bad Request",
				              "gate_publish, gate_roll and gate_deploy are booleans");
				return;
			}
		}
		for (k = 0; k < sizeof(keys) / sizeof(keys[0]); k++) {
			const struct json_value *gv = json_object_get(root, keys[k]);

			if (gv != NULL)
				(void)pkg_gate_set(gates[k], gv->u.boolean);
		}
	}
	json_free(root);
	pipeline_config_respond(ctx->fd);
}

/* GET /v1/pipeline/approvals (ADR-0273) */
static void op_getPipelineApprovals(const struct api_ctx *ctx)
{
	struct json_writer w;

	jw_init(&w);
	pkg_approvals_write_json(&w);
	respond_json(ctx->fd, 200, "OK", &w);
	jw_free(&w);
}

/*
 * POST /v1/pipeline/approve (ADR-0273) -- let one held change through.
 *
 * The grant is consumed when that change actually goes through, so
 * approving does not turn the gate off. A target nothing is holding is
 * refused rather than remembered: a pre-approval is a standing
 * permission wearing the costume of a decision, and it would make the
 * audit line claim a person approved a specific change they never saw.
 */
static void op_approvePipeline(const struct api_ctx *ctx)
{
	struct json_value *root;
	const char *gate, *target;
	int rc;

	root = json_parse(ctx->req->body, ctx->req->body_len);
	if (root == NULL || root->type != JSON_OBJECT) {
		json_free(root);
		respond_error(ctx->fd, 400, "Bad Request", "invalid JSON body");
		return;
	}
	gate = json_as_string(json_object_get(root, "gate"));
	target = json_as_string(json_object_get(root, "target"));
	if (gate == NULL || target == NULL) {
		json_free(root);
		respond_error(ctx->fd, 400, "Bad Request", "gate and target are both required");
		return;
	}
	rc = pkg_approval_grant(gate, target, ctx->user);
	if (rc == PKG_APPROVE_OK) {
		/* ADR-0271: the record of WHO allowed a specific change out is
		 * the whole point of the pause. */
		logstore_write("audit", "info", "%s APPROVED gate %s for %s", audit_who(), gate, target);
	}
	json_free(root);
	switch (rc) {
	case PKG_APPROVE_OK:
		http_write_response(ctx->fd, 204, "No Content", "application/json", "", 0);
		return;
	case PKG_APPROVE_UNKNOWN_GATE:
		respond_error(ctx->fd, 400, "Bad Request",
		              "gate must be one of \"publish\", \"roll\" or \"deploy\", and target "
		              "must not be empty");
		return;
	case PKG_APPROVE_ALREADY:
		respond_error(ctx->fd, 409, "Conflict",
		              "that target is already approved and is waiting to go through");
		return;
	case PKG_APPROVE_FULL:
		respond_error(ctx->fd, 409, "Conflict", "too many approvals are outstanding");
		return;
	default:
		respond_error(ctx->fd, 409, "Conflict",
		              "nothing is holding that target -- either the gate is off, or it is not "
		              "queued. GET /v1/pipeline/approvals lists what is actually waiting");
		return;
	}
}

